import { byId, excerpt, flowPhases, focusSteps, hasSelection, parseModel, resolveEvidencePath, selectionEvidence } from "./lib/model.mjs";
import { DIFF_REFS, parseDiff, parseUntracked } from "./lib/changes.mjs";
import { buildIndicator, buildPane } from "./lib/views.mjs";
import { searchElements } from "./lib/impact.mjs";
import { escapeStep } from "./lib/escape.mjs";
import { REVIEW_FILE, checkReview, fingerprint, parseReview, pathKey } from "./lib/review.mjs";
import { BEHAVIOR_FILE, checkBehavior, citations, parseBehavior, sourceKey } from "./lib/behavior.mjs";
import { DATA_FILE, checkData, dataCitations, parseData } from "./lib/data.mjs";
import { AUTH_FILE, authCitations, checkAuth, opsAtStep, parseAuth } from "./lib/auth.mjs";
import { COVERAGE_FILE, checkCoverage, coverageCitations, coveragePaths, parseCoverage } from "./lib/coverage.mjs";
import { stepRef } from "./lib/lens.mjs";
import { modelBriefing, preflightPrompt, reviewPrompt } from "./lib/preflight.mjs";
import { EXPLORE_FILE, checkExplore, diffExploration, diffIsEmpty, explorationWindow, exploreEvidence, parseExplore } from "./lib/explore.mjs";
import { CELL_ASPECT, UNITS_PER_COLUMN, paneColumns, pictureSpec } from "./lib/pictures.mjs";
import { VIEWER_CONTEXT, VIEWER_MAX_LINES, evKey, viewerEvidence, viewerPage, viewerPlan } from "./lib/viewer.mjs";
import { authEvidence, dataEvidence } from "./lib/lens-entries.mjs";
import { evidenceRoot as resolveRoot, inspectRepositories, joinPath, parseWorkspace, readHead, revisionMatches } from "./lib/workspace.mjs";

const PANE_ID = "architecture";
const VIEWS = ["overview", "flow", "impact", "behavior", "explore", "data", "auth", "mermaid"];
const GIT_TIMEOUT_MS = 20000;
const RASTER_TIMEOUT_MS = 20000;
// Terminals that draw the Image element; tmux passes no graphics through.
const IMAGE_TERMINALS = ["ghostty", "wezterm", "iterm.app", "kitty"];
const PX_PER_COLUMN = 20;
const MAX_SVG_CHARS = 131000;
const MIN_IMAGE_COLUMNS = 80;

const state = {
  status: { kind: "loading" },
  cwd: "",
  cwdName: "project",
  isOpen: false,
  inBand: false,
  view: "overview",
  origin: "overview",
  flowId: null,
  focus: { phase: null, component: null },
  categories: [],
  impactDepth: 1,
  impactMode: "selection",
  diffRef: "working",
  changes: null,
  changeFile: null,
  changeMore: false,
  selection: null,
  excerpt: null,
  stack: [],
  building: false,
  notice: "",
  pickQuery: "",
  pickKind: "all",
  lastFocus: null,
  legendOpen: false,
  beforeLegend: null,
  anchor: null,
  spentOn: null,
  reviewing: false,
  reviewPath: "",
  reviewExcerpt: null,
  behavior: { variant: "default", origin: null, hop: null },
  data: { mode: "entities", entity: null, relation: null, lifecycle: null, transition: null, state: null, sequence: null, item: null },
  auth: { mode: "operations", phase: null, hop: null, operation: null, guard: null },
  coverageOpen: false,
  exploreAlt: null,
  explorePath: "",
  exploreAsk: "",
  exploreLean: null,
  exploreChange: null,
  exploring: false,
  pictureMode: "picture",
  overviewFocus: null,
  listOpen: false,
  pictureShown: false,
  zoom: null,
  showCarried: false,
};

// Rendering of diagrams: what this terminal can draw, and the PNGs already made.
const gfx = { detected: false, images: false, rasterizer: null, tmp: "/tmp", dir: "", dirReady: null, dirProblem: "", theme: "dark", ready: new Map(), pending: new Set(), failed: new Map() };

const propsOf = (e) => e.props ?? e;

async function loadStatus($) {
  const searched = [];
  try {
    state.cwd = await $.session.cwd();
    state.cwdName = state.cwd.split("/").filter(Boolean).pop() || "project";
    let fromEnv;
    try {
      fromEnv = await $.env.get("ARCHITECTURE_SIDECAR_MODEL");
    } catch {
      // An unreadable environment must not hide the project's own model file.
    }
    if (fromEnv) searched.push(joinPath(state.cwd, fromEnv));
    searched.push(`${state.cwd}/.architecture/model.json`);
    for (const path of searched) {
      if (!(await $.fs.exists(path))) continue;
      const text = await $.fs.read(path);
      const parsed = parseModel(text);
      if (!parsed.ok) return { kind: "invalid", errors: parsed.errors, searched, message: path };
      const workspace = parsed.model.project.repositories.length ? await loadWorkspace($, path, parsed.model) : undefined;
      const review = await loadReview($, parsed.model, fingerprint(text), workspace?.repos);
      const behavior = await loadBehavior($, parsed.model, workspace?.repos);
      const explore = await loadExplore($, parsed.model, fingerprint(text), workspace?.repos);
      const data = await loadLens($, parsed.model, workspace?.repos, DATA_LENS);
      const auth = await loadLens($, parsed.model, workspace?.repos, AUTH_LENS);
      const coverage = await loadLens($, parsed.model, workspace?.repos, COVERAGE_LENS, { auth: auth.kind === "ready" ? auth.auth : undefined, data: data.kind === "ready" ? data.data : undefined });
      return { kind: "ready", path, root: state.cwd, workspacePath: workspace?.path, model: parsed.model, warnings: [...parsed.warnings, ...(workspace?.warnings ?? [])], repos: workspace?.repos, review, behavior, explore, data, auth, coverage, searched };
    }
    return { kind: "missing", searched };
  } catch (err) {
    return { kind: "invalid", errors: [String(err?.message ?? err)], searched, message: "Reading the model failed." };
  }
}

async function loadWorkspace($, modelPath, model) {
  const warnings = [];
  const candidates = [];
  try {
    const fromEnv = await $.env.get("ARCHITECTURE_SIDECAR_WORKSPACE");
    if (fromEnv) candidates.push(joinPath(state.cwd, fromEnv));
  } catch {
    // An unreadable environment falls through to the project's own workspace file.
  }
  const modelDir = modelPath.replace(/\/[^/]*$/, "");
  if (model.project.workspace) candidates.push(joinPath(modelDir, model.project.workspace));
  candidates.push(`${state.cwd}/.architecture/workspace.json`);
  let workspace;
  let workspaceDir = state.cwd;
  let workspacePath;
  for (const path of candidates) {
    try {
      if (!(await $.fs.exists(path))) continue;
      workspacePath = path;
      const parsed = parseWorkspace(await $.fs.read(path));
      warnings.push(...parsed.warnings.map((w) => `${path}: ${w}`));
      if (!parsed.ok) {
        warnings.push(...parsed.errors.map((e) => `${path}: ${e}`));
        break;
      }
      workspace = parsed.workspace;
      workspaceDir = path.replace(/\/[^/]*$/, "");
      break;
    } catch (err) {
      warnings.push(`Could not read workspace file ${path}: ${String(err?.message ?? err)}`);
      break;
    }
  }
  if (!workspace) warnings.push(`No usable workspace file: repository evidence cannot be opened (looked for ${candidates.join(", ")})`);
  const repos = await inspectRepositories({ exists: (path) => $.fs.exists(path), read: (path) => $.fs.read(path) }, model, workspace, workspaceDir);
  for (const r of repos) if (r.state !== "ok") warnings.push(`Repository ${r.id}: ${r.state}. ${r.message}`);
  return { warnings, repos, path: workspacePath };
}

const evidenceRoot = (model, repos, repoId) => resolveRoot(model, repos, repoId, state.cwd);

async function loadReview($, model, modelFingerprint, repos) {
  const candidates = [];
  try {
    const fromEnv = await $.env.get("ARCHITECTURE_SIDECAR_REVIEW");
    if (fromEnv) candidates.push(joinPath(state.cwd, fromEnv));
  } catch {
    // An unreadable environment falls through to the project's own review file.
  }
  candidates.push(`${state.cwd}/${REVIEW_FILE}`);
  for (const path of candidates) {
    try {
      if (!(await $.fs.exists(path))) continue;
      const parsed = parseReview(await $.fs.read(path));
      if (!parsed.ok) return { kind: "invalid", path, errors: parsed.errors };
      const { review } = parsed;
      const lookup = async (file, onFile) => {
        const base = evidenceRoot(model, repos, file.repo);
        const abs = base.root && resolveEvidencePath(base.root, file.path);
        if (!abs) return undefined;
        try {
          return (await $.fs.exists(abs)) ? await onFile(abs) : null;
        } catch {
          return undefined;
        }
      };
      const planAbs = resolveEvidencePath(state.cwd, review.plan.path);
      const planText = planAbs && (await $.fs.exists(planAbs)) ? await $.fs.read(planAbs) : null;
      const plannedExists = new Map();
      for (const f of review.plannedFiles) {
        const found = await lookup(f, () => true);
        if (found !== undefined) plannedExists.set(pathKey(f), found === true);
      }
      const sourceLines = new Map();
      for (const ev of review.questions.flatMap((q) => q.evidence)) {
        const total = await lookup(ev, async (abs) => lineCount(await $.fs.read(abs)));
        if (total !== undefined) sourceLines.set(pathKey(ev), total);
      }
      const checkouts = new Map((repos ?? []).map((r) => [r.id, r]));
      const check = checkReview(model, review, { planText, modelFingerprint, plannedExists, sourceLines, checkouts });
      return { kind: "ready", path, review, issues: [...parsed.issues, ...check.issues], stale: check.stale, citationsChecked: check.citationsChecked, plannedExists };
    } catch (err) {
      return { kind: "invalid", path, errors: [String(err?.message ?? err)] };
    }
  }
  return { kind: "none", searched: candidates };
}

async function loadBehavior($, model, repos) {
  const candidates = [];
  try {
    const fromEnv = await $.env.get("ARCHITECTURE_SIDECAR_BEHAVIOR");
    if (fromEnv) candidates.push(joinPath(state.cwd, fromEnv));
  } catch {
    // An unreadable environment falls through to the project's own behavior file.
  }
  candidates.push(`${state.cwd}/${BEHAVIOR_FILE}`);
  for (const path of candidates) {
    try {
      if (!(await $.fs.exists(path))) continue;
      const parsed = parseBehavior(await $.fs.read(path));
      if (!parsed.ok) return { kind: "invalid", path, errors: parsed.errors };
      const { behavior } = parsed;
      const sources = new Map();
      for (const { ev } of citations(behavior)) {
        const key = sourceKey(ev);
        if (sources.has(key)) continue;
        const base = evidenceRoot(model, repos, ev.repo);
        const abs = base.root && resolveEvidencePath(base.root, ev.path);
        if (!abs) continue;
        try {
          sources.set(key, (await $.fs.exists(abs)) ? await $.fs.read(abs) : null);
        } catch {
          // A file the host refuses to read stays out of `sources`, which the check reports as unverified.
        }
      }
      const check = checkBehavior(model, behavior, { sources, checkouts: new Map((repos ?? []).map((r) => [r.id, r])) });
      return { kind: "ready", path, behavior, parseIssues: parsed.issues, issues: check.issues, stale: check.stale, checked: check.checked };
    } catch (err) {
      return { kind: "invalid", path, errors: [String(err?.message ?? err)] };
    }
  }
  return { kind: "none", searched: candidates };
}

// The data and authorization documents are read the same way: environment variable, else the project's own file.
const DATA_LENS = { file: DATA_FILE, parse: parseData, check: checkData, citations: dataCitations, key: "data" };

const AUTH_LENS = { file: AUTH_FILE, parse: parseAuth, check: checkAuth, citations: authCitations, key: "auth" };

// The coverage manifest is read like the other lens documents; it also tests that its declared source paths exist and is checked against the data and authorization documents when they load.
const COVERAGE_LENS = { file: COVERAGE_FILE, parse: parseCoverage, check: checkCoverage, citations: coverageCitations, paths: coveragePaths, key: "coverage" };

// The host lists the variables a module reads, so each is named literally where it is read.
async function lensEnv($, key) {
  try {
    if (key === "data") return await $.env.get("ARCHITECTURE_SIDECAR_DATA");
    if (key === "auth") return await $.env.get("ARCHITECTURE_SIDECAR_AUTH");
    if (key === "coverage") return await $.env.get("ARCHITECTURE_SIDECAR_COVERAGE");
  } catch {
    // An unreadable environment falls through to the project's own file.
  }
  return undefined;
}

async function loadLens($, model, repos, lens, docs) {
  const candidates = [];
  const fromEnv = await lensEnv($, lens.key);
  if (fromEnv) candidates.push(joinPath(state.cwd, fromEnv));
  candidates.push(`${state.cwd}/${lens.file}`);
  for (const path of candidates) {
    try {
      if (!(await $.fs.exists(path))) continue;
      const parsed = lens.parse(await $.fs.read(path));
      if (!parsed.ok) return { kind: "invalid", path, errors: parsed.errors };
      const doc = parsed[lens.key];
      const sources = new Map();
      for (const { evidence } of lens.citations(doc)) {
        for (const ev of evidence) {
          const key = sourceKey(ev);
          if (sources.has(key)) continue;
          const base = evidenceRoot(model, repos, ev.repo);
          const abs = base.root && resolveEvidencePath(base.root, ev.path);
          if (!abs) continue;
          try {
            sources.set(key, (await $.fs.exists(abs)) ? await $.fs.read(abs) : null);
          } catch {
            // A file the host refuses to read stays out of `sources`, which the check reports as unverified.
          }
        }
      }
      const paths = new Map();
      for (const { repo, path: rel } of lens.paths ? lens.paths(doc) : []) {
        const base = evidenceRoot(model, repos, repo);
        const abs = base.root && resolveEvidencePath(base.root, rel);
        if (!abs) continue;
        try {
          paths.set(`${repo ?? ""}:${rel}`, await $.fs.exists(abs));
        } catch {
          // A path the host refuses to test stays out of `paths`, which the check reports as unverified.
        }
      }
      const check = lens.check(model, doc, { sources, docs, paths, checkouts: new Map((repos ?? []).map((r) => [r.id, r])) });
      return { kind: "ready", path, [lens.key]: doc, parseIssues: parsed.issues, issues: check.issues, stale: check.stale, checked: check.checked };
    } catch (err) {
      return { kind: "invalid", path, errors: [String(err?.message ?? err)] };
    }
  }
  return { kind: "none", searched: candidates };
}

// Where an exploration is read from, and where Claude is asked to write one: $ARCHITECTURE_SIDECAR_EXPLORE, else the project's own file.
async function exploreTarget($) {
  try {
    const fromEnv = await $.env.get("ARCHITECTURE_SIDECAR_EXPLORE");
    if (fromEnv) return { abs: joinPath(state.cwd, fromEnv), shown: joinPath(state.cwd, fromEnv) };
  } catch {
    // An unreadable environment falls through to the project's own exploration file.
  }
  return { abs: `${state.cwd}/${EXPLORE_FILE}`, shown: EXPLORE_FILE };
}

async function loadExplore($, model, modelFingerprint, repos) {
  const target = await exploreTarget($);
  const path = target.abs;
  try {
    if (!(await $.fs.exists(path))) return { kind: "none", searched: [path], target: target.shown };
    const parsed = parseExplore(await $.fs.read(path));
    if (!parsed.ok) return { kind: "invalid", path, errors: parsed.errors, target: target.shown };
    const { exploration } = parsed;
    const specAbs = resolveEvidencePath(state.cwd, exploration.spec.path);
    let specText = null;
    try {
      specText = specAbs && (await $.fs.exists(specAbs)) ? await $.fs.read(specAbs) : null;
    } catch {
      // A specification the host refuses to read leaves its citations unchecked, which the check reports.
    }
    const sources = new Map();
    for (const ev of [...exploration.premises.flatMap((p) => p.evidence), ...exploration.unresolved.flatMap((u) => u.evidence)]) {
      const key = pathKey(ev);
      if (sources.has(key)) continue;
      const base = evidenceRoot(model, repos, ev.repo);
      const abs = base.root && resolveEvidencePath(base.root, ev.path);
      if (!abs) continue;
      try {
        sources.set(key, (await $.fs.exists(abs)) ? await $.fs.read(abs) : null);
      } catch {
        // A file the host refuses to read stays out of `sources`, which the check reports as unverified.
      }
    }
    let head;
    if (!model.project.repositories.length) {
      try {
        head = (await readHead({ exists: (p) => $.fs.exists(p), read: (p) => $.fs.read(p) }, state.cwd)) ?? undefined;
      } catch {
        // Without HEAD the source revision simply is not compared.
      }
    }
    const check = checkExplore(model, exploration, { specText, modelFingerprint, sources, head, checkouts: new Map((repos ?? []).map((r) => [r.id, r])) });
    return { kind: "ready", path, exploration, issues: [...parsed.issues, ...check.issues], stale: check.stale, failed: check.failed, unchecked: check.unchecked, checked: check.checked, target: target.shown };
  } catch (err) {
    return { kind: "invalid", path, errors: [String(err?.message ?? err)], target: target.shown };
  }
}

async function detectGraphics($) {
  const read = async (get) => {
    try {
      return (await get()) ?? "";
    } catch {
      return "";
    }
  };
  const forced = (await read(() => $.env.get("ARCHITECTURE_SIDECAR_GRAPHICS"))).toLowerCase();
  const program = (await read(() => $.env.get("TERM_PROGRAM"))).toLowerCase();
  const kitty = await read(() => $.env.get("KITTY_WINDOW_ID"));
  const tmux = await read(() => $.env.get("TMUX"));
  const tmp = (await read(() => $.env.get("TMPDIR"))) || "/tmp";
  gfx.images = forced === "off" ? false : forced === "on" || (!tmux && (IMAGE_TERMINALS.includes(program) || Boolean(kitty)));
  gfx.rasterizer = null;
  gfx.failed.clear();
  gfx.tmp = tmp.replace(/\/$/, "");
  gfx.dirReady = null;
  gfx.dir = "";
  if (gfx.images) await ensureDir($);
  if (gfx.images && gfx.dir) {
    try {
      const probe = await $.process.run(["rsvg-convert", "--version"], { timeoutMs: 5000 });
      if (probe.exitCode === 0) gfx.rasterizer = "rsvg-convert";
    } catch {
      // No rasterizer on PATH: the terminal falls back to the text views.
    }
  }
  try {
    const row = (await $.config.list()).find((r) => r.key === "theme");
    gfx.theme = /light/i.test(String(row?.value ?? "")) ? "light" : "dark";
  } catch {
    gfx.theme = "dark";
  }
  gfx.detected = true;
}

// The folder is made (and old files pruned) the first time something needs to be written, not at startup.
function ensureDir($) {
  gfx.dirReady ??= (async () => {
    await preparePrivateDir($, gfx.tmp);
    await pruneCache($);
  })();
  return gfx.dirReady.then(() => gfx.dir);
}

// Cached files hold diagrams and, for the browser view, excerpts of client source: the folder must be ours and ours alone.
async function preparePrivateDir($, tmp) {
  gfx.dirProblem = "";
  const run = async (argv) => {
    try {
      return await $.process.run(argv, { timeoutMs: 5000 });
    } catch (err) {
      return { exitCode: -1, stdout: "", stderr: String(err?.message ?? err) };
    }
  };
  const uid = (await run(["id", "-u"])).stdout.trim();
  if (!/^\d+$/.test(uid)) {
    gfx.dirProblem = "could not tell which user this is";
    return;
  }
  const mine = async (dir) => (await run(["find", dir, "-maxdepth", "0", "-type", "d", "-user", uid])).stdout.trim() === dir;
  // A path someone else made first (or a link) is not used. The next fixed names are tried so the folder is reused from
  // session to session; a fresh mktemp folder is the last resort.
  let dir = "";
  for (const name of [`architecture-sidecar-${uid}`, `architecture-sidecar-${uid}-2`, `architecture-sidecar-${uid}-3`]) {
    await run(["mkdir", "-m", "700", "-p", `${tmp}/${name}`]);
    if (await mine(`${tmp}/${name}`)) {
      dir = `${tmp}/${name}`;
      break;
    }
  }
  if (!dir) {
    const made = await run(["mktemp", "-d", `${tmp}/architecture-sidecar-XXXXXXXX`]);
    dir = made.exitCode === 0 ? made.stdout.trim() : "";
    if (!dir || !(await mine(dir))) {
      gfx.dirProblem = "no private temporary folder could be made";
      return;
    }
  }
  // The first version of this cache used a world-readable folder of this name; what it left is removed.
  const legacy = `${tmp}/architecture-sidecar-diagrams`;
  if ((await run(["find", legacy, "-maxdepth", "0", "-type", "d", "-user", uid])).stdout.trim() === legacy) {
    await run(["find", legacy, "-type", "f", "-delete"]);
    await run(["rmdir", legacy]);
  }
  await run(["chmod", "700", dir]);
  const mode = (await run(["find", dir, "-maxdepth", "0", "-perm", "700"])).stdout.trim();
  if (mode !== dir) {
    gfx.dirProblem = "the temporary folder could not be made private";
    return;
  }
  gfx.dir = dir;
}

// Pictures are dropped after two days, browser pages (which carry source excerpts) after one.
async function pruneCache($) {
  if (!gfx.dir) return;
  for (const argv of [["find", gfx.dir, "-type", "f", "-name", "view-*.html", "-mtime", "+0", "-delete"], ["find", gfx.dir, "-type", "f", "-mtime", "+1", "-delete"]]) {
    try {
      await $.process.run(argv, { timeoutMs: 5000 });
    } catch {
      // Nothing to trim, or no find: the cache just keeps its files.
    }
  }
  for (const [id, png] of [...gfx.ready]) {
    if (!(await $.fs.exists(png).catch(() => false))) gfx.ready.delete(id);
  }
}

const fileKey = (text) => fingerprint(text).replace(/[^A-Za-z0-9]/g, "").slice(0, 32);

async function rasterize($, spec, px) {
  const id = fileKey(`${spec.svg}|${px}`);
  if (gfx.ready.has(id) || gfx.pending.has(id) || gfx.failed.has(id)) return;
  gfx.pending.add(id);
  try {
    const svgPath = `${gfx.dir}/${id}.svg`;
    const pngPath = `${gfx.dir}/${id}.png`;
    await $.fs.write(svgPath, spec.svg);
    const r = await $.process.run([gfx.rasterizer, "-w", String(px), svgPath, "-o", pngPath], { timeoutMs: RASTER_TIMEOUT_MS });
    if (r.exitCode !== 0) throw new Error(r.stderr.trim().split("\n")[0] || `${gfx.rasterizer} exited with ${r.exitCode}`);
    gfx.ready.set(id, pngPath);
  } catch (err) {
    gfx.failed.set(id, String(err?.message ?? err));
  } finally {
    gfx.pending.delete(id);
    $.ui.invalidate("ui.render");
  }
}

const canDraw = (e, h, cols) => (e.surface === "terminal" ? Boolean(gfx.images && gfx.rasterizer && h.Image) && cols >= MIN_IMAGE_COLUMNS : Boolean(h.Svg));

function drawHint(e, h, cols) {
  if (canDraw(e, h, cols)) return "";
  if (e.surface !== "terminal") return "";
  if (gfx.images && gfx.rasterizer && h.Image) return "This pane is too narrow to draw the diagram legibly (about 84 columns needed). Press w to open it in your browser.";
  if (!gfx.images) return "Inline diagrams need Ghostty, kitty, WezTerm or iTerm2 outside tmux. Press w to open this diagram in your browser.";
  if (!gfx.dir) return `Inline diagrams are off: ${gfx.dirProblem || "no private temporary folder"}. Press w for the browser view.`;
  return "Inline diagrams need rsvg-convert (brew install librsvg). Press w to open this diagram in your browser.";
}

// The picture for the current view in the shape the views draw: { status, node } or undefined when there is none.
function pictureFor($, e, h, ctx, spec) {
  if (!spec || state.pictureMode !== "picture") return undefined;
  if (!canDraw(e, h, ctx.cols)) return undefined;
  if (e.surface !== "terminal") {
    if (spec.svg.length > MAX_SVG_CHARS) return undefined;
    return { status: "ready", node: h.Svg({ source: spec.svg, alt: spec.alt, isInteractive: true }) };
  }
  const columns = paneColumns(spec, ctx.cols, ctx.bodyRows);
  const rows = Math.max(4, Math.min(250, Math.round((columns * spec.height) / spec.width / CELL_ASPECT)));
  const px = Math.min(3200, columns * PX_PER_COLUMN);
  const id = fileKey(`${spec.svg}|${px}`);
  const failed = gfx.failed.get(id);
  if (failed) return { status: "error", message: failed };
  const png = gfx.ready.get(id);
  if (!png) {
    void rasterize($, spec, px);
    return { status: "pending" };
  }
  const small = spec.width / columns > UNITS_PER_COLUMN * 1.15;
  return { status: "ready", small, node: h.Image({ source: { file: png, format: "png" }, columns, rows, alt: `${spec.alt} This terminal is not drawing images: press v for the text view or w to open the diagram in your browser.` }) };
}

function currentFlow() {
  const flows = state.status.model?.flows ?? [];
  const ex = state.view === "explore" && state.status.explore?.kind === "ready" ? state.status.explore.exploration : null;
  return byId(flows, ex ? ex.question.flow : state.flowId) ?? flows[0];
}

function visibleSteps() {
  const ex = state.view === "explore" && state.status.explore?.kind === "ready" ? state.status.explore.exploration : null;
  if (ex) return explorationWindow(state.status.model, ex)?.steps ?? [];
  const flow = currentFlow();
  return flow ? focusSteps(flow, state.focus) : [];
}

function evidenceCount() {
  const model = state.status.model;
  return model ? selectionEvidence(model, state.selection).length : 0;
}

async function refresh($) {
  const keptEvidence = state.excerpt?.evIndex ?? 0;
  const before = state.status.explore?.kind === "ready" ? state.status.explore.exploration : null;
  state.status = await loadStatus($);
  const model = state.status.model;
  const after = state.status.explore?.kind === "ready" ? state.status.explore.exploration : null;
  if (before && after) {
    const diff = diffExploration(before, after);
    state.exploreChange = before.spec.path === after.spec.path && !diffIsEmpty(diff) ? diff : null;
  } else state.exploreChange = null;
  if (state.exploreAlt && !after?.alternatives.some((a) => a.id === state.exploreAlt)) state.exploreAlt = null;
  if (state.exploreLean?.alternative && !after?.alternatives.some((a) => a.id === state.exploreLean.alternative)) state.exploreLean = null;
  const flows = model?.flows ?? [];
  if (!flows.some((f) => f.id === state.flowId)) state.flowId = flows[0]?.id ?? null;
  const flow = currentFlow();
  if (state.focus.phase && !flowPhases(flow ?? { steps: [] }).some((p) => p.name === state.focus.phase)) state.focus.phase = null;
  if (state.focus.component && !model?.components.some((c) => c.id === state.focus.component)) state.focus.component = null;
  state.categories = model ? state.categories.filter((id) => model.relationships.some((r) => r.category === id)) : [];
  state.stack = [];
  state.excerpt = null;
  if (model && hasSelection(model, state.selection)) {
    $.ui.invalidate("ui.render");
    if (evidenceCount() > 0) await showEvidence($, Math.min(keptEvidence, evidenceCount() - 1));
    return;
  }
  state.selection = null;
  if (state.view === "inspect") state.view = state.origin;
  if (state.view !== "inspect" && !model) state.view = "overview";
  $.ui.invalidate("ui.render");
}

// A trailing newline ends the last line rather than starting an empty one.
const lineCount = (text) => text.split("\n").length - (text.endsWith("\n") ? 1 : 0);

// Lines around a cited range, read from the checkout that owns the file; failures come back as a message, never thrown.
async function readExcerpt($, model, ev, context = 1, maxLines = 14) {
  const base = evidenceRoot(model, state.status.repos, ev.repo);
  if (base.error) return { status: "error", message: base.error };
  const path = resolveEvidencePath(base.root, ev.path);
  if (!path) return { status: "error", message: `Refusing evidence path outside the repository: ${ev.path}` };
  try {
    if (!(await $.fs.exists(path))) return { status: "error", message: `File not found: ${ev.path}. The model may be stale.` };
    const text = await $.fs.read(path);
    const total = lineCount(text);
    if (ev.lines && ev.lines[1] > total) return { status: "error", message: `${ev.path} has only ${total} lines; evidence cites ${ev.lines[0]}-${ev.lines[1]}. The model may be stale.` };
    const ex = excerpt(text, ev.lines, context, maxLines);
    return { status: "ok", warning: base.warning, startLine: ex.startLine, source: ex.source, hidden: ex.hidden };
  } catch (err) {
    return { status: "error", message: `Could not read ${ev.path}: ${String(err?.message ?? err)}` };
  }
}

// The page carries only the lines a citation names (a little around them), never a whole file.
async function readViewerExcerpt($, model, ev) {
  if (!ev.lines) return { status: "whole" };
  return readExcerpt($, model, ev, VIEWER_CONTEXT, VIEWER_MAX_LINES);
}

async function openInBrowser($, e) {
  const model = state.status.model;
  if (!(await ensureDir($))) {
    state.notice = `The browser view is written to a private temporary folder, and none could be made (${gfx.dirProblem || "not checked yet"}). Nothing was written.`;
    $.ui.invalidate("ui.render");
    return;
  }
  const ctx = { model, status: state.status, view: state.view, flowId: state.flowId, focus: state.focus, categories: state.categories, impactDepth: state.impactDepth, impactMode: state.impactMode, selection: state.selection, behavior: state.behavior, data: state.data, auth: state.auth, overviewFocus: state.overviewFocus, exploreAlt: state.exploreAlt };
  const spec = pictureSpec(ctx, gfx.theme, { forViewer: true });
  if (!model || !spec) return;
  state.notice = "Preparing the browser view…";
  $.ui.invalidate("ui.render");
  try {
    const behavior = state.status.behavior?.kind === "ready" ? state.status.behavior.behavior : undefined;
    const vctx = { ...ctx, flowId: currentFlow()?.id };
    const plan = viewerPlan(model, vctx, spec, gfx.theme);
    const excerpts = new Map();
    const explore = ctx.view === "explore" && state.status.explore?.kind === "ready" ? state.status.explore : undefined;
    const dataDoc = ctx.view === "data" && state.status.data?.kind === "ready" ? state.status.data.data : undefined;
    const authDoc = ctx.view === "auth" && state.status.auth?.kind === "ready" ? state.status.auth.auth : undefined;
    const extra = [...(explore ? exploreEvidence(explore.exploration) : []), ...(dataDoc ? dataEvidence(model, dataDoc, plan.scope) : []), ...(authDoc ? authEvidence(model, authDoc, plan.scope) : [])];
    for (const ev of viewerEvidence(model, behavior, plan.scope, extra)) excerpts.set(evKey(ev), await readViewerExcerpt($, model, ev));
    const html = viewerPage(model, vctx, spec, { behavior, excerpts, theme: gfx.theme, plan, dataDoc, authDoc, explore: explore && { exploration: explore.exploration, alt: state.exploreAlt, failed: explore.failed, unchecked: explore.unchecked } });
    const file = `${gfx.dir}/view-${fileKey(html)}.html`;
    await $.fs.write(file, html);
    await $.process.run(["chmod", "600", file], { timeoutMs: 5000 });
    await pruneCache($);
    let opened = false;
    for (const opener of ["open", "xdg-open"]) {
      try {
        if ((await $.process.run([opener, file], { timeoutMs: 10000 })).exitCode === 0) {
          opened = true;
          break;
        }
      } catch {
        // This opener is not installed; the next one is tried.
      }
    }
    state.notice = opened ? `Opened the diagram in your browser (a local file, readable only by you, no server; removed after a day): ${file}` : `Could not start a browser. The diagram is at ${file}`;
  } catch (err) {
    state.notice = `Could not build the browser view: ${String(err?.message ?? err)}`;
  }
  $.ui.invalidate("ui.render");
}

async function showEvidence($, index) {
  const model = state.status.model;
  const ev = model && selectionEvidence(model, state.selection)[index];
  if (!ev) return;
  const fail = (message) => {
    state.excerpt = { evIndex: index, status: "error", message };
    $.ui.invalidate("ui.render");
  };
  const base = evidenceRoot(model, state.status.repos, ev.repo);
  if (base.error) return fail(base.error);
  const { root, warning } = base;
  const path = resolveEvidencePath(root, ev.path);
  if (!path) return fail(`Refusing evidence path outside the repository: ${ev.path}`);
  const where = ev.repo ? `[${ev.repo}] ${ev.path}` : ev.path;
  try {
    if (!(await $.fs.exists(path))) return fail(`File not found: ${where} (looked under ${root}). The model may be stale.`);
    const text = await $.fs.read(path);
    const total = lineCount(text);
    if (ev.lines && ev.lines[1] > total) return fail(`${where} has only ${total} lines; evidence cites ${ev.lines[0]}-${ev.lines[1]}. The model may be stale.`);
    const ex = excerpt(text, ev.lines, 1, 14);
    state.excerpt = { evIndex: index, status: "ok", repo: ev.repo, warning, path: ev.path, startLine: ex.startLine, source: ex.source, hidden: ex.hidden };
    $.ui.invalidate("ui.render");
  } catch (err) {
    fail(`Could not read ${where}: ${String(err?.message ?? err)}`);
  }
}

