const PREFLIGHT_USAGE = "Name the specification to preflight, for example /architecture preflight .specify/specs/012-feature/spec.md";

// A model that exists still may not describe this checkout; the briefing says so before Claude relies on it.
async function preflightBriefing($) {
  let head = null;
  try {
    head = await readHead({ exists: (path) => $.fs.exists(path), read: (path) => $.fs.read(path) }, state.cwd);
  } catch {
    // An unreadable checkout leaves freshness unchecked, which the briefing reports.
  }
  return modelBriefing(state.status, head);
}

// The file the pane loads first: the configured path, else the project's own.
async function reviewFilePath($) {
  try {
    const fromEnv = await $.env.get("ARCHITECTURE_SIDECAR_REVIEW");
    if (fromEnv) return joinPath(state.cwd, fromEnv);
  } catch {
    // An unreadable environment falls through to the project's own review file.
  }
  return `${state.cwd}/${REVIEW_FILE}`;
}

// A preflight may replace its own earlier output or a review of the same spec, never another plan's review or a file it cannot read.
async function replaceableReview($, file, specPath) {
  let text;
  try {
    if (!(await $.fs.exists(file))) return { ok: true, replaces: null };
    text = await $.fs.read(file);
  } catch (err) {
    return { ok: false, why: `could not be read (${String(err?.message ?? err)})` };
  }
  const parsed = parseReview(text);
  if (!parsed.ok) return { ok: false, why: "is not a valid plan review, so what it holds is unknown" };
  const { title, plan } = parsed.review;
  if (sameSpec(plan.path, specPath)) return { ok: true, replaces: null };
  if (/^Preflight:/.test(title)) return { ok: true, replaces: plan.path };
  return { ok: false, why: `is the plan review of ${plan.path}` };
}

async function requestPreflight($, path, briefing, reviewFile, replaces, { detached = false } = {}) {
