  state.notice = `Asked Claude to preflight ${path}.${briefing.usable ? ` Its evidence loads in Impact ▸ Plan review when the turn finishes${replaces ? `, replacing the preflight of ${replaces}` : ""}.` : ` ${briefing.state === "missing" ? "No model, so no evidence file." : "The model is unusable, so no evidence file."}`}`;
  $.ui.invalidate("ui.render");
