    $.ui.invalidate("ui.render");
  };
  const base = evidenceRoot(model, state.status.repos, src.repo);
  if (base.error) return fail(base.error);
  const path = resolveEvidencePath(base.root, src.path);
  if (!path) return fail(`Refusing path outside the repository: ${src.path}`);
  try {
    if (!(await $.fs.exists(path))) return fail(`File not found: ${src.path} (looked under ${base.root}). The plan or the checkout may have changed.`);
    const text = await $.fs.read(path);
    const total = lineCount(text);
    if (src.lines && src.lines[1] > total) return fail(`${src.path} has only ${total} lines; the citation names ${src.lines[0]}-${src.lines[1]}.`);
    const ex = excerpt(text, src.lines, 0, 16);
    state.reviewExcerpt = { key, status: "ok", warning: base.warning, path: src.path, quote: src.quote, startLine: ex.startLine, source: ex.source, hidden: ex.hidden };
