}

async function git($, root, args) {
  const r = await $.process.run(["git", "-c", "core.quotepath=off", ...args], { cwd: root, env: { GIT_OPTIONAL_LOCKS: "0" }, timeoutMs: GIT_TIMEOUT_MS });
  if (r.exitCode !== 0) throw new Error(r.stderr.trim().split("\n")[0] || `git exited with ${r.exitCode}`);
  if (r.isStdoutTruncated) throw new Error("git output was too large to read in full");
  return r.stdout;
}

async function scanRepository($, target, ref, model) {
  const scan = { id: target.id, status: "ok", message: "", files: [], basis: "unknown" };
  const found = target.found;
  const root = target.root ?? found?.root;
  if (!root) return { ...scan, status: "skipped", message: `no checkout configured (${found?.message || "no workspace"}); not scanned` };
  if (found && (found.state === "missing" || found.state === "unreadable")) return { ...scan, status: "skipped", message: `${found.message}; not scanned` };
  try {
    const diff = await git($, root, ["diff", "--unified=0", "--find-renames", "--no-color", "--no-ext-diff", "--no-textconv", ...ref.args]);
    scan.files = parseDiff(diff);
    if (ref.untracked) {
      const known = new Set(scan.files.map((f) => f.path));
      scan.files.push(...parseUntracked(await git($, root, ["ls-files", "--others", "--exclude-standard"])).filter((f) => !known.has(f.path)));
    }
    const recorded = target.id ? model.project.repositories.find((r) => r.id === target.id)?.revision : model.project.revision;
    const head = (await git($, root, ["rev-parse", "HEAD"]).catch(() => "")).trim() || found?.head;
    if (/^[0-9a-f]{7,40}$/i.test(recorded ?? "") && head) scan.basis = revisionMatches(recorded, head) ? "matches" : "stale";
    if (scan.basis === "stale") scan.note = "checkout is not at the model's revision; cited lines may have moved, so line matches are marked unclear";
    else if (scan.basis === "unknown") scan.note = "the model's revision cannot be compared with this checkout; cited lines may have moved, so line matches are marked unclear";
  } catch (err) {
    return { ...scan, status: "error", message: `git failed: ${String(err?.message ?? err)}` };
  }
  return scan;
}

async function scanChanges($) {
  const model = state.status.model;
  if (!model) return;
  const ref = DIFF_REFS[state.diffRef] ?? DIFF_REFS.working;
  const refId = state.diffRef;
  state.changes = { ref: refId, scanning: true, scans: [] };
  $.ui.invalidate("ui.render");
  const targets = model.project.repositories.length
    ? model.project.repositories.map((r) => ({ id: r.id, found: state.status.repos?.find((x) => x.id === r.id) }))
    : [{ id: undefined, root: state.cwd }];
  const scans = [];
  for (const target of targets) scans.push(await scanRepository($, target, ref, model));
  if (state.changes?.ref === refId) state.changes = { ref: refId, scanning: false, scans };
  $.ui.invalidate("ui.render");
}

async function revealStep($, block) {
  if (state.inBand || state.pictureShown) return;
  await $.clock.sleep(60);
  try {
    await $.ui.scroll({ to: { key: "prev" }, in: PANE_ID, block });
    await $.ui.focus({ requestId: PANE_ID, key: "prev" });
  } catch {
    // Scrolling is a convenience; the step is selected either way.
  }
}

async function returnToStep($, key) {
  if (state.inBand) return;
  await $.clock.sleep(60);
  try {
    await $.ui.scroll({ to: { key }, in: PANE_ID, block: "nearest" });
    await $.ui.focus({ requestId: PANE_ID, key });
    state.lastFocus = key;
  } catch {
    // Without a scroll or focus the pane still shows the restored Impact view.
  }
}

async function focusPicker($) {
  if (state.inBand || state.view !== "impact" || state.impactMode !== "selection" || ["component", "relationship"].includes(state.selection?.kind)) return;
  await $.clock.sleep(60);
  try {
    await $.ui.focus({ requestId: PANE_ID, key: "iq" });
    state.lastFocus = "iq";
  } catch {
    // The field stays unfocused; Tab reaches it.
  }
}

// The first of `keys` still drawn gets the ring; the Shortcuts button is always drawn, so it ends a list.
async function focusFirst($, keys) {
  for (const key of keys) {
    try {
      if (!(await $.ui.focus({ requestId: PANE_ID, key }))?.deny) return;
    } catch {
      // A refused move is handled like a denied one: the next key is tried.
    }
  }
}

// A refused close leaves the keyboard on the prompt, so the pane is reopened and the ring put back on `key`.
function reclaim($, key) {
  void (async () => {
    try {
      await $.clock.sleep(80);
      await $.ui.open({ id: PANE_ID, title: "Architecture", focus: true, closeOnEscape: true, rows: 30, columns: 100 });
      await focusFirst($, [key, "legend"]);
    } catch {
      // The pane stays open without keyboard focus; a click or Tab restores it.
    }
  })();
}

// Escape ends a transient interaction before it closes the pane; the second Escape on the same control closes.
function dismissTransient($) {
  const step = escapeStep(state);
  if (!step) return false;
  if (step.clearQuery) state.pickQuery = "";
  if (step.spend) state.spentOn = step.spend;
  if (step.closeLegend) state.legendOpen = false;
  state.lastFocus = step.focus;
  $.ui.invalidate("ui.render");
  reclaim($, step.focus);
  return true;
}

function makeActions($) {
  const redraw = () => $.ui.invalidate("ui.render");
  const frame = () => ({
    view: state.view,
    origin: state.origin,
    selection: state.selection,
    flowId: state.flowId,
    impactMode: state.impactMode,
    categories: [...state.categories],
    impactDepth: state.impactDepth,
    focus: { ...state.focus },
    pickQuery: state.pickQuery,
    pickKind: state.pickKind,
    anchor: state.anchor,
    behavior: { ...state.behavior },
    data: { ...state.data },
    auth: { ...state.auth },
    overviewFocus: state.overviewFocus,
    exploreAlt: state.exploreAlt,
  });
  const selectStep = async (flowId, n, block) => {
    state.flowId = flowId;
    state.selection = { kind: "step", id: `${flowId}#${n}` };
    state.excerpt = null;
    redraw();
    if (evidenceCount() > 0) await showEvidence($, 0);
    await revealStep($, block);
  };
  const openImpact = (kind, id, anchor) => {
    state.anchor = anchor ?? state.lastFocus;
    state.stack.push(frame());
    state.selection = { kind, id };
    state.excerpt = null;
    state.view = "impact";
    state.origin = "impact";
    state.impactMode = "selection";
    redraw();
    return evidenceCount() > 0 ? showEvidence($, 0) : undefined;
  };
  return {
    setView(view) {
      const keep = (view === "impact" && (state.selection?.kind === "component" || state.selection?.kind === "relationship")) || (view === "explore" && state.selection?.kind === "step");
      state.view = view;
      state.origin = view;
      if (!keep) {
        state.selection = null;
        state.pickQuery = "";
      }
      state.excerpt = null;
      state.stack = [];
      redraw();
      return focusPicker($);
    },
    openFlow(id) {
      state.flowId = id;
      state.focus = { phase: null, component: null };
      state.selection = null;
      state.excerpt = null;
      state.stack = [];
      state.view = "flow";
      state.origin = "flow";
      redraw();
    },
    toggleCategory(id) {
      state.categories = state.categories.includes(id) ? state.categories.filter((c) => c !== id) : [...state.categories, id];
      redraw();
    },
    clearCategories() {
      state.categories = [];
      redraw();
    },
    setPhase(name) {
      state.focus.phase = name;
      state.excerpt = null;
      if (state.selection?.kind === "step" && !visibleSteps().some((s) => `${currentFlow().id}#${s.n}` === state.selection.id)) state.selection = null;
      redraw();
    },
    setFocusComponent(id) {
      state.focus.component = id;
      state.excerpt = null;
      if (state.selection?.kind === "step" && !visibleSteps().some((s) => `${currentFlow().id}#${s.n}` === state.selection.id)) state.selection = null;
      redraw();
    },
    select(kind, id, anchor) {
      state.anchor = anchor ?? state.lastFocus;
      if (kind === "step") {
        const [flowId, n] = id.split("#");
        const entering = state.view !== "flow";
        if (entering) {
          state.stack.push(frame());
          state.focus = { phase: null, component: null };
          state.origin = "flow";
          state.view = "flow";
        }
        return selectStep(flowId, n, entering ? "start" : "nearest");
      }
      state.stack.push(frame());
      state.selection = { kind, id };
      state.excerpt = null;
      state.view = "inspect";
      redraw();
      return evidenceCount() > 0 ? showEvidence($, 0) : undefined;
    },
    openImpact,
    async setBehavior(patch) {
      state.behavior = { ...state.behavior, ...patch };
      if (patch.variant || patch.origin) state.reviewExcerpt = null;
      redraw();
      if (!patch.hop || state.inBand || state.pictureShown) return;
      await $.clock.sleep(60);
      try {
        await $.ui.scroll({ to: { key: "bxd" }, in: PANE_ID, block: "start" });
      } catch {
        // Scrolling is a convenience; the hop's claims are below the path.
      }
    },
    openBehavior(hopId) {
      state.stack.push(frame());
      state.behavior = { ...state.behavior, hop: hopId };
      state.selection = null;
      state.excerpt = null;
      state.view = "behavior";
      state.origin = "behavior";
      redraw();
    },
    setData(patch) {
      state.data = { ...state.data, ...patch };
      state.reviewExcerpt = null;
      redraw();
    },
    // `target` is a flow step reference, or `{ patch }` naming exactly what to select in the Data tab.
    openData(target) {
      const d = state.status.data?.kind === "ready" ? state.status.data.data : null;
      if (!d) return;
      const stepRef = typeof target === "string" ? target : undefined;
      state.anchor = state.lastFocus;
      state.stack.push(frame());
      const seq = d.sequences.find((s) => s.steps.includes(stepRef) && d.effects.some((e) => e.step === stepRef && e.op !== "read"));
      const life = d.lifecycles.find((l) => l.transitions.some((t) => t.step === stepRef));
      if (!stepRef) state.data = { ...state.data, ...target.patch };
      else if (seq) state.data = { ...state.data, mode: "operations", sequence: seq.id, item: stepRef };
      else if (life) state.data = { ...state.data, mode: "lifecycle", lifecycle: life.id, transition: life.transitions.find((t) => t.step === stepRef).id, state: null };
      else state.data = { ...state.data, mode: "entities", entity: d.effects.find((e) => e.step === stepRef && e.entity)?.entity ?? null, relation: null };
      state.selection = null;
      state.excerpt = null;
      state.reviewExcerpt = null;
      state.view = "data";
      state.origin = "data";
      redraw();
    },
    setAuth(patch) {
      state.auth = { ...state.auth, ...patch };
      state.reviewExcerpt = null;
      redraw();
    },
    // `target` is `{ step }`, `{ operation }` or `{ patch }` naming exactly what to select in the Auth tab.
    openAuth(target) {
      const a = state.status.auth?.kind === "ready" ? state.status.auth.auth : null;
      if (!a) return;
      state.anchor = state.lastFocus;
      state.stack.push(frame());
      if (target.patch) state.auth = { ...state.auth, ...target.patch };
      else if (target.step) {
        const op = opsAtStep(a, target.step)[0];
        const hop = a.hops.find((x) => x.step === target.step);
        const phase = stepRef(state.status.model, target.step)?.step.phase || null;
        state.auth = { ...state.auth, mode: "flow", phase, hop: hop?.id ?? null, operation: op?.id ?? state.auth.operation, guard: null };
      } else state.auth = { ...state.auth, mode: "operations", operation: target.operation, guard: null, hop: null };
      state.selection = null;
      state.excerpt = null;
      state.reviewExcerpt = null;
      state.view = "auth";
      state.origin = "auth";
      redraw();
    },
    setExploreAlt(id) {
      state.exploreAlt = id;
      redraw();
    },
    cycleExploreAlt() {
      const ids = [null, ...(loadedExploration()?.exploration.alternatives.map((a) => a.id) ?? [])];
      state.exploreAlt = ids[(ids.indexOf(state.exploreAlt) + 1) % ids.length];
      redraw();
    },
    exploreStep(flowId, n) {
      return selectStep(flowId, n, "nearest");
    },
    setExplorePath(value) {
      state.explorePath = value;
      redraw();
    },
    setExploreAsk(value) {
      state.exploreAsk = value;
      redraw();
    },
    async requestExplore(raw) {
      const target = await exploreSpec($, raw);
      if (target.error) {
        state.notice = target.error;
        return redraw();
      }
      const plan = await planExplore($, target.path, "");
      if (plan.open) return openExploration($, target.path);
      state.explorePath = target.path;
      state.exploreLean = null;
      await submitExplore($, plan.prompt, plan.notice);
    },
    requestFollowUp(text) {
      return requestFollowUp($, text);
    },
    leanDecision(choice) {
      state.exploreLean = choice;
      redraw();
    },
    async recordDecision() {
      const l = state.exploreLean;
      if (!l) return;
      const what = l.status === "selected" ? `the engineer chose alternative ${l.alternative}` : l.status === "deferred" ? "the engineer deferred the decision" : "the engineer wants the specification clarified before deciding";
      await requestFollowUp($, `Record this decision in the exploration: ${what}. Set only the "decision" field (status ${l.status}${l.alternative ? `, alternative ${l.alternative}` : ""}, by "engineer"); change nothing else.`);
      state.exploreLean = null;
    },
    openInBrowser() {
      return openInBrowser($);
    },
    setZoom(zoom) {
      state.zoom = zoom;
      redraw();
    },
    toggleCarried() {
      state.showCarried = !state.showCarried;
      redraw();
    },
    setOverviewFocus(id) {
      state.overviewFocus = id;
      redraw();
    },
    toggleList() {
      state.listOpen = !state.listOpen;
      redraw();
    },
    toggleCoverage() {
      state.coverageOpen = !state.coverageOpen;
      redraw();
    },
    openCoverage() {
      state.anchor = state.lastFocus;
      state.stack.push(frame());
      state.coverageOpen = true;
      state.selection = null;
      state.excerpt = null;
      state.reviewExcerpt = null;
      state.view = "overview";
      state.origin = "overview";
      redraw();
    },
    async toggleLegend() {
      state.legendOpen = !state.legendOpen;
      redraw();
      if (state.inBand) return;
      await $.clock.sleep(60);
      try {
        if (state.legendOpen) await $.ui.scroll({ to: { key: "shortcuts" }, in: PANE_ID, block: "nearest" });
        else await focusFirst($, [state.beforeLegend ?? "legend", "legend"]);
      } catch {
        // Scrolling and focusing are conveniences; the Shortcuts button reaches the list either way.
      }
    },
    setPictureMode(mode) {
      state.pictureMode = mode;
      redraw();
    },
    setPickQuery(value) {
      state.pickQuery = value;
      redraw();
    },
    setPickKind(kind) {
      state.pickKind = kind;
      redraw();
    },
    submitPick(value) {
      state.pickQuery = value;
      const model = state.status.model;
      const first = model && searchElements(model, value, state.pickKind)[0];
      if (first) return openImpact(first.kind, first.id);
      redraw();
    },
    setImpactMode(mode) {
      state.impactMode = mode;
      redraw();
      return focusPicker($);
    },
    setImpactDepth(depth) {
      state.impactDepth = depth;
      redraw();
    },
    setDiffRef(id) {
      state.diffRef = id;
      state.changes = null;
      redraw();
    },
    setChangeFile(key) {
      state.changeFile = key;
      redraw();
    },
    toggleChangeMore() {
      state.changeMore = !state.changeMore;
      redraw();
    },
    scanChanges() {
      return scanChanges($);
    },
    setReviewPath(value) {
      state.reviewPath = value;
      redraw();
    },
    async requestReview(raw) {
      const target = await reviewTarget($, raw);
      if (target.error) {
        state.notice = target.error;
        return redraw();
      }
      await requestReview($, target.path);
    },
    peek(key, src) {
      return peekSource($, key, src);
    },
    async jump(key) {
      if (state.inBand) return;
      try {
        await $.ui.scroll({ to: { key }, in: PANE_ID, block: "start" });
      } catch {
        // Scrolling is a convenience; the sections are in the same order below.
      }
    },
    stepBy(delta) {
      const flow = currentFlow();
      const visible = visibleSteps();
      if (!flow || !visible.length) return undefined;
      if (state.selection?.kind !== "step") return selectStep(flow.id, (delta < 0 ? visible[visible.length - 1] : visible[0]).n, "nearest");
      const at = visible.findIndex((s) => `${flow.id}#${s.n}` === state.selection.id);
      const next = visible[Math.min(visible.length - 1, Math.max(0, (at < 0 ? 0 : at) + delta))];
      return selectStep(flow.id, next.n, "nearest");
    },
    back() {
      const prev = state.stack.pop();
      const left = state.selection?.kind === "step" ? state.selection.id.split("#") : undefined;
      state.excerpt = null;
      if (prev) {
        Object.assign(state, prev);
      } else {
        state.view = state.origin;
        state.selection = null;
      }
      // A remounted Input starts empty whatever `value` says, so the filter is dropped to match the field.
      if (state.view === "impact" && !["component", "relationship"].includes(state.selection?.kind)) state.pickQuery = "";
      redraw();
      const back = left && state.view === "impact" && state.selection?.kind !== "step";
      // Returning to the plan review puts the reader back on the row they opened, not at the top.
      const returnKey = prev?.view === "impact" && (prev.impactMode === "review" || prev.impactMode === "changes") && prev.anchor ? prev.anchor : back ? `fs-${left[0]}-${left[1]}` : undefined;
      if (state.selection && evidenceCount() > 0) {
        const shown = showEvidence($, 0);
        return returnKey ? Promise.resolve(shown).then(() => returnToStep($, returnKey)) : shown;
      }
      return returnKey ? returnToStep($, returnKey) : focusPicker($);
    },
    evidence(i) {
      return showEvidence($, i);
    },
    reload() {
      return refresh($);
    },
    build(scope) {
      return requestBuild($, scope);
    },
    close() {
      state.isOpen = false;
      state.legendOpen = false;
      if (!state.inBand) $.ui.close({ id: PANE_ID });
      state.inBand = false;
      redraw();
    },
  };
}

function paneView($, e) {
  const p = propsOf(e);
  const cols = Math.max(24, (p.bodyColumns ?? e.viewport?.columns ?? 80) - 4);
  const ready = state.status.kind === "ready";
  const h = $.ui.resolve(e);
  const ctx = {
    status: state.status,
    model: ready ? state.status.model : null,
    cwdName: state.cwdName,
    cols,
    view: state.view,
    origin: state.origin,
    flowId: state.flowId,
    focus: state.focus,
    categories: state.categories,
    impactDepth: state.impactDepth,
    impactMode: state.impactMode,
    pickQuery: state.pickQuery,
    pickKind: state.pickKind,
    diffRef: state.diffRef,
    changes: state.changes,
    changeFile: state.changeFile,
    changeMore: state.changeMore,
    selection: state.selection,
    legendOpen: state.legendOpen,
    excerpt: state.excerpt,
    notice: state.notice,
    reviewPath: state.reviewPath,
    reviewExcerpt: state.reviewExcerpt,
    behavior: state.behavior,
    data: state.data,
    auth: state.auth,
    reviewing: state.reviewing,
    exploreAlt: state.exploreAlt,
    explorePath: state.explorePath,
    exploreAsk: state.exploreAsk,
    exploreLean: state.exploreLean,
    exploreChange: state.exploreChange,
    exploring: state.exploring,
    overviewFocus: state.overviewFocus,
    listOpen: state.listOpen,
    coverageOpen: state.coverageOpen,
    pictureMode: state.pictureMode,
    bodyRows: p.scroll?.bodyRows ?? 0,
    zoom: state.zoom,
    showCarried: state.showCarried,
    canBack: state.stack.length > 0,
    actions: makeActions($),
  };
  const spec = ready ? pictureSpec(ctx, gfx.theme) : null;
  ctx.hasDiagram = Boolean(spec);
  ctx.zoomable = Boolean(spec?.canZoom);
  ctx.windowed = spec?.zoom === "window";
  ctx.carriedTotal = spec?.carriedTotal ?? 0;
  ctx.canPicture = ready && canDraw(e, h, cols);
  ctx.hint = ctx.hasDiagram ? drawHint(e, h, cols) : "";
  ctx.picture = pictureFor($, e, h, ctx, spec);
  state.pictureShown = ctx.picture?.status === "ready";
  return buildPane(h, ctx);
}

async function openPane($, view, mode) {
  await refresh($);
  if (view) {
    state.view = view;
    state.origin = view;
    state.selection = null;
    state.excerpt = null;
  }
  if (mode) state.impactMode = mode;
  state.isOpen = true;
  state.inBand = false;
  state.legendOpen = false;
  state.lastFocus = null;
  state.spentOn = null;
  $.ui.invalidate("ui.render");
  // Gives the invalidated band a redraw (indicator gone) before the pane is placed.
  await $.clock.sleep(200);
  const placed = await $.ui.open({ id: PANE_ID, title: "Architecture", focus: true, closeOnEscape: true, rows: 30, columns: 100 });
  state.inBand = placed?.isPlaced === false;
  $.ui.invalidate("ui.render");
}

export function register(on) {
  on("session.start", async ($, e, next) => {
    const r = await next(e);
    await refresh($);
    await detectGraphics($);
    try {
      await $.command.register({ name: "architecture", description: "Interactive architecture views with file evidence; `build` asks Claude to write or refresh the model", argumentHint: "[overview|flow|impact|behavior|data|auth|mermaid|build [scope]|review [plan path]|preflight <spec path>|explore [spec path] [question]]" });
    } catch {
      // The pane still opens from the band indicator if registration is refused.
    }
    return r;
  });

  on("command.run", { command: "architecture" }, async ($, e) => {
    const words = String(e.args ?? "").trim().split(/\s+/).filter(Boolean);
    const head = (words[0] ?? "").toLowerCase();
    if (head === "build") {
      void requestBuild($, words.slice(1).join(" "), { detached: true }).catch(() => {
        state.building = false;
        state.notice = "Could not submit the build request; press g in the pane, or run the architecture-model skill.";
        $.ui.invalidate("ui.render");
      });
      return { text: "Architecture: asked Claude to build the model; run /architecture when the turn finishes." };
    }
    if (head === "review") {
      const target = words.slice(1).join(" ");
      if (!target) {
        await openPane($, "impact", "review");
        const r = state.status.review;
        return { text: r?.kind === "ready" ? `Architecture: plan review of ${r.review.plan.path}` : "Architecture: no plan review yet; run /architecture review <path to plan.md>." };
      }
      const checked = await reviewTarget($, target);
      if (checked.error) return { text: `Architecture: ${checked.error}` };
      state.view = "impact";
      state.origin = "impact";
      void requestReview($, checked.path, { detached: true }).catch(() => {
        state.reviewing = false;
        state.notice = "Could not submit the review request; run the architecture-review skill by hand.";
        $.ui.invalidate("ui.render");
      });
      return { text: `Architecture: asked Claude to review ${checked.path}; run /architecture review when the turn finishes.` };
    }
    if (head === "preflight") {
      const target = words.slice(1).join(" ");
      if (!target) return { text: `Architecture: ${PREFLIGHT_USAGE}` };
      const checked = await reviewTarget($, target);
      if (checked.error) return { text: `Architecture: ${checked.error}` };
      await refresh($);
      const briefing = await preflightBriefing($);
      const file = await reviewFilePath($);
      const shown = file === `${state.cwd}/${REVIEW_FILE}` ? REVIEW_FILE : file;
      let replaces = null;
      if (briefing.usable) {
        const existing = await replaceableReview($, file, checked.path);
        if (!existing.ok) return { text: `Architecture: did not preflight ${checked.path}: ${shown} ${existing.why}, and the preflight would overwrite it. Move or delete it, or point ARCHITECTURE_SIDECAR_REVIEW at another file, then run the command again.` };
        replaces = existing.replaces;
        state.view = "impact";
        state.origin = "impact";
      }
      void requestPreflight($, checked.path, briefing, shown, replaces, { detached: true }).catch(() => {
        state.reviewing = false;
        state.notice = "Could not submit the preflight request; run the architecture-preflight skill by hand.";
        $.ui.invalidate("ui.render");
      });
      const asked = `Architecture: asked Claude to preflight ${checked.path} (model: ${briefing.state}).`;
      if (briefing.usable) return { text: `${asked} The answer arrives in this session; /architecture review opens its evidence${shown === REVIEW_FILE ? "" : ` (${shown})`}.` };
      return { text: `${asked} There is no usable model, so no evidence file is written and /architecture review will show nothing from this run. The answer arrives in this session, from the spec and the source; /architecture build creates a model.` };
    }
    if (head === "explore" && words.length > 1) {
      // A first word ending in .md is the specification; anything else is a question about the loaded exploration.
      const looksLikePath = /\.md$/i.test(words[1]);
      const loaded = loadedExploration();
      const path = looksLikePath ? words[1] : loaded?.exploration.spec.path;
      const focus = (looksLikePath ? words.slice(2) : words.slice(1)).join(" ");
      if (!path) return { text: "Architecture: name the specification first, for example /architecture explore .specify/specs/012-feature/spec.md" };
      const checked = await exploreSpec($, path);
      if (checked.error) return { text: `Architecture: ${checked.error}` };
      const plan = await planExplore($, checked.path, focus);
      if (plan.open) {
        await openPane($, "explore");
        openExploration($, checked.path);
        return { text: `Architecture: exploration of ${checked.path}` };
      }
      state.view = "explore";
      state.origin = "explore";
      state.explorePath = checked.path;
      // Submitting from this hook would wait on the turn the hook holds, so the request follows once the command has returned.
      void submitExplore($, plan.prompt, plan.notice, { detached: true }).catch(() => {
        state.exploring = false;
        state.notice = "Could not submit the exploration request; run the architecture-explore skill by hand.";
      });
      return { text: `Architecture: asked Claude to ${plan.update ? "update" : "explore"} ${checked.path}; run /architecture explore when the turn finishes.` };
    }
    if (head === "explore") {
      await openPane($, "explore");
      const x = state.status.explore;
      return { text: x?.kind === "ready" ? `Architecture: exploration of ${x.exploration.spec.path}` : "Architecture: no exploration yet; run /architecture explore <path to spec.md>." };
    }
    await openPane($, VIEWS.includes(head) ? head : undefined);
    const s = state.status;
    return { text: s.kind === "ready" ? `Architecture: ${s.model.project.name}, ${s.model.components.length} components, ${s.model.flows.length} flows` : "Architecture: no usable model for this project (see the pane)." };
  });

  on("turn.complete", async ($, e, next) => {
    const r = await next(e);
    const reviewed = state.reviewing && !e.agentId;
    const explored = state.exploring && !e.agentId;
    if (state.building || reviewed || explored || state.isOpen) {
      const was = state.building;
      state.building = false;
      if (reviewed) state.reviewing = false;
      if (explored) state.exploring = false;
      await refresh($);
      if (was) state.notice = state.status.kind === "ready" ? "Model reloaded after Claude's turn." : "Claude's turn finished but no usable model was found; see below.";
      if (reviewed) state.notice = state.status.review?.kind === "ready" ? "Plan review loaded after Claude's turn." : "Claude's turn finished but no usable plan review was found; see Impact ▸ Plan review.";
      if (explored) state.notice = state.status.explore?.kind === "ready" ? "Exploration reloaded after Claude's turn; your selection was kept." : "Claude's turn finished but no usable exploration was found; see the Explore tab.";
      $.ui.invalidate("ui.render");
    }
    return r;
  });

  on("ui.render", { component: "AbovePrompt" }, ($, e, next) => {
    const p = propsOf(e);
    if (state.isOpen && state.inBand) return paneView($, e);
    if (state.isOpen || p.hasSurvey || state.status.kind === "loading") return next(e);
    const cols = p.bodyColumns ?? e.viewport?.columns ?? 80;
    return buildIndicator($.ui.resolve(e), state.status, state.cwdName, cols, () => openPane($));
  });

  on("ui.render", { component: "Pane" }, ($, e, next) => {
    if (e.requestId !== PANE_ID) return next(e);
    if (state.inBand) {
      // The host seated the pane (the terminal widened): the band must stop drawing a second copy.
      state.inBand = false;
      void Promise.resolve().then(() => $.ui.invalidate("ui.render"));
    }
    return paneView($, e);
  });

  on("ui.focus", { requestId: PANE_ID }, ($, e, next) => {
    state.lastFocus = e.element ?? null;
    if (state.lastFocus && !state.lastFocus.startsWith("legend")) state.beforeLegend = state.lastFocus;
    if (state.lastFocus !== state.spentOn) state.spentOn = null;
    return next(e);
  });

  on("ui.close", ($, e, next) => {
    if (e.id === PANE_ID && e.origin?.kind === "person" && state.isOpen && !state.inBand && dismissTransient($)) {
      return { deny: "Escape ended the open search or list; press it again to close the pane" };
    }
    if (e.id === PANE_ID) {
      state.isOpen = false;
      state.inBand = false;
      state.legendOpen = false;
      $.ui.invalidate("ui.render");
    }
    return next(e);
  });
}

