export const CONFIDENCE = ["observed", "inferred", "unknown"];
export const SCHEMA_VERSIONS = [1, 2];

/** Relationship kinds with a recognized meaning, grouped into the categories views can focus on; any other kind is "other". */
export const CATEGORIES = [
  { id: "runtime", label: "Runtime", tag: "run", kinds: ["runtime-call"] },
  { id: "contract", label: "API / schema contract", tag: "contract", kinds: ["schema-contract"] },
  { id: "build", label: "Build-time", tag: "build", kinds: ["build-time-composition", "code-generation"] },
  { id: "package", label: "Package dependency", tag: "pkg", kinds: ["package-dependency"] },
  { id: "event", label: "Event / asynchronous", tag: "event", kinds: ["event"] },
  { id: "deployment", label: "Deployment", tag: "deploy", kinds: ["deployment"] },
  { id: "implementation", label: "Implementation dependency", tag: "impl", kinds: ["implementation-dependency"] },
  { id: "other", label: "Other", tag: "other", kinds: [] },
];

export const categoryOf = (kind) => CATEGORIES.find((c) => c.kinds.includes(kind))?.id ?? "other";
export const categoryInfo = (id) => CATEGORIES.find((c) => c.id === id) ?? CATEGORIES[CATEGORIES.length - 1];

/** Fields each object may carry; [name, version] marks a field that needs that schemaVersion. */
const FIELDS = {
  model: ["schemaVersion", "project", "components", "relationships", "flows", "unknowns"],
  project: ["name", "summary", "revision", "generatedBy", ["repositories", 2], ["workspace", 2]],
  repository: ["id", "name", "url", "revision", "version"],
  component: ["id", "name", "kind", "responsibility", "confidence", "evidence", ["repo", 2]],
  relationship: ["id", "from", "to", "kind", "label", "confidence", "evidence", ["via", 2]],
  flow: ["id", "name", "summary", "steps", "unknowns"],
  step: ["n", "from", "to", "action", "phase", "confidence", "evidence", "stateChange", ["relationship", 2]],
  stateChange: ["store", "description", "verified"],
  evidence: ["path", "lines", "note", ["repo", 2]],
  unknown: ["text", "step"],
};

const REPO_ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

const asString = (v, max) => {
  const s = typeof v === "string" ? v.trim() : "";
  return max && s.length > max ? `${s.slice(0, max - 1)}…` : s;
};

const asConfidence = (v) => (CONFIDENCE.includes(v) ? v : "unknown");

/** Collects diagnostics about fields the parser cannot use, one line per kind of problem. */
function makeNotes(version) {
  const found = new Map();
  return {
    add(message, example) {
      const f = found.get(message) ?? { count: 0, example };
      f.count += 1;
      found.set(message, f);
    },
    fields(raw, kind, owner) {
      if (!raw || typeof raw !== "object" || Array.isArray(raw)) return;
      const allowed = FIELDS[kind];
      for (const key of Object.keys(raw)) {
        const entry = allowed.find((a) => (Array.isArray(a) ? a[0] : a) === key);
        if (!entry) this.add(`${kind} field "${key}" is not part of the model format and was ignored`, owner);
        else if (Array.isArray(entry) && version < entry[1]) this.add(`${kind} field "${key}" needs schemaVersion ${entry[1]} and was ignored`, owner);
      }
    },
    warnings() {
      return [...found].map(([message, f]) => {
        const where = [f.count > 1 ? `${f.count} times` : "", f.example ? `${f.count > 1 ? "e.g. " : ""}${f.example}` : ""].filter(Boolean).join(", ");
        return where ? `${message} (${where})` : message;
      });
    },
  };
}

function normEvidence(list, notes, ctx, owner) {
  if (!Array.isArray(list)) return [];
  const out = [];
  for (const ev of list) {
    notes.fields(ev, "evidence", owner);
    const path = asString(ev?.path);
    if (!path) continue;
    let lines;
    if (Array.isArray(ev.lines) && Number.isInteger(ev.lines[0]) && ev.lines[0] > 0) {
      const end = Number.isInteger(ev.lines[1]) && ev.lines[1] >= ev.lines[0] ? ev.lines[1] : ev.lines[0];
      lines = [ev.lines[0], end];
    }
    let repo = ctx.version >= 2 ? asString(ev.repo) || undefined : undefined;
    if (repo && !ctx.repoIds.has(repo)) notes.add("evidence names a repository the project does not declare", `${owner}: ${repo}`);
    if (!repo && ctx.repoIds.size > 0) {
      repo = ctx.defaultRepo ?? (ctx.repoIds.size === 1 ? [...ctx.repoIds][0] : undefined);
      if (!repo) notes.add("evidence names no repository although the project declares several", owner);
    }
    out.push({ repo, path, lines, note: asString(ev.note) });
  }
  return out;
}

function normRepositories(list, notes, warnings) {
  const out = [];
  for (const r of Array.isArray(list) ? list : []) {
    notes.fields(r, "repository", asString(r?.id));
    const id = asString(r?.id);
    if (!REPO_ID.test(id) || out.some((x) => x.id === id)) {
      warnings.push(`Skipped repository with ${id ? (REPO_ID.test(id) ? "duplicate" : "invalid") : "missing"} id${id ? ` "${id}"` : ""}`);
      continue;
    }
    out.push({ id, name: asString(r.name, 24) || id, url: asString(r.url), revision: asString(r.revision), version: asString(r.version) });
  }
  return out;
}

/** Parse and normalize a model file. Never throws; problems become `errors` (fatal) or `warnings`. */
export function parseModel(text) {
  const warnings = [];
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (err) {
    return { ok: false, errors: [`Not valid JSON: ${err.message}`], warnings };
  }
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return { ok: false, errors: ["Model must be a JSON object"], warnings };
  }
  if (!SCHEMA_VERSIONS.includes(raw.schemaVersion)) {
    return { ok: false, errors: [`Unsupported schemaVersion ${JSON.stringify(raw.schemaVersion)} (expected 1 or 2)`], warnings };
  }
  const version = raw.schemaVersion;
  const notes = makeNotes(version);
  notes.fields(raw, "model");

  const project = raw.project && typeof raw.project === "object" && !Array.isArray(raw.project) ? raw.project : {};
  notes.fields(project, "project");
  const repositories = version >= 2 ? normRepositories(project.repositories, notes, warnings) : [];
  const ctx = { version, repoIds: new Set(repositories.map((r) => r.id)) };

  const components = [];
  const ids = new Set();
  for (const c of Array.isArray(raw.components) ? raw.components : []) {
    const id = asString(c?.id);
    if (!id || ids.has(id)) {
      warnings.push(`Skipped component with ${id ? "duplicate" : "missing"} id${id ? ` "${id}"` : ""}`);
      continue;
    }
    ids.add(id);
    notes.fields(c, "component", id);
    let repo = version >= 2 ? asString(c.repo) || undefined : undefined;
    if (repo && !ctx.repoIds.has(repo)) {
      warnings.push(`Component ${id}: repository "${repo}" is not declared in project.repositories`);
    }
    components.push({
      id,
      name: asString(c.name, 24) || id,
      kind: asString(c.kind) || "component",
      repo,
      responsibility: asString(c.responsibility),
      confidence: asConfidence(c.confidence),
      evidence: normEvidence(c.evidence, notes, { ...ctx, defaultRepo: repo }, `component ${id}`),
    });
  }
  if (components.length === 0) {
    return { ok: false, errors: ["Model has no components"], warnings };
  }

  const relationships = [];
  const relIds = new Set();
  for (const r of Array.isArray(raw.relationships) ? raw.relationships : []) {
    const from = asString(r?.from);
    const to = asString(r?.to);
    if (!ids.has(from) || !ids.has(to)) {
      warnings.push(`Skipped relationship ${from || "?"} -> ${to || "?"}: unknown component`);
      continue;
    }
    let id = asString(r.id) || `${from}>${to}`;
    while (relIds.has(id)) id += "'";
    relIds.add(id);
    notes.fields(r, "relationship", id);
    let via = version >= 2 ? asString(r.via) || undefined : undefined;
    if (via && !ids.has(via)) {
      warnings.push(`Relationship ${id}: via "${via}" is not a component`);
      via = undefined;
    }
    const kind = asString(r.kind) || "depends-on";
    relationships.push({
      id,
      from,
      to,
      kind,
      category: categoryOf(kind),
      via,
      label: asString(r.label, 40),
      confidence: asConfidence(r.confidence),
      evidence: normEvidence(r.evidence, notes, ctx, `relationship ${id}`),
    });
  }

  const flows = [];
  for (const f of Array.isArray(raw.flows) ? raw.flows : []) {
    const id = asString(f?.id);
    if (!id) continue;
    notes.fields(f, "flow", id);
    const steps = [];
    for (const s of Array.isArray(f.steps) ? f.steps : []) {
      const from = asString(s?.from);
      const to = asString(s?.to);
      if (!ids.has(from) || !ids.has(to)) {
        warnings.push(`Flow ${id}: skipped step with unknown participant`);
        continue;
      }
      const n = steps.length + 1;
      notes.fields(s, "step", `${id} step ${n}`);
      let relationship = version >= 2 ? asString(s.relationship) || undefined : undefined;
      if (relationship) {
        const rel = relationships.find((x) => x.id === relationship);
        if (!rel) {
          warnings.push(`Flow ${id} step ${n}: relationship "${relationship}" does not exist`);
          relationship = undefined;
        } else if (!connects(rel, from, to)) {
          warnings.push(`Flow ${id} step ${n}: relationship "${relationship}" does not connect ${from} and ${to}`);
          relationship = undefined;
        }
      }
      const sc = s.stateChange;
      if (sc && typeof sc === "object") notes.fields(sc, "stateChange", `${id} step ${n}`);
      steps.push({
        n,
        from,
        to,
        action: asString(s.action, 40),
        phase: asString(s.phase, 24),
        confidence: asConfidence(s.confidence),
        relationship,
        evidence: normEvidence(s.evidence, notes, ctx, `flow ${id} step ${n}`),
        stateChange:
          sc && typeof sc === "object"
            ? { store: asString(sc.store), description: asString(sc.description), verified: sc.verified === true }
            : undefined,
      });
    }
    flows.push({
      id,
      name: asString(f.name) || id,
      summary: asString(f.summary),
      steps,
      unknowns: (Array.isArray(f.unknowns) ? f.unknowns : [])
        .map((u) => {
          notes.fields(u, "unknown", id);
          return { text: asString(u?.text), step: Number.isInteger(u?.step) ? u.step : undefined };
        })
        .filter((u) => u.text),
    });
  }

  let workspace = version >= 2 ? asString(project.workspace) || undefined : undefined;
  if (workspace && (workspace.startsWith("/") || workspace.split("/").includes(".."))) {
    warnings.push(`project.workspace "${workspace}" must be a file name below the model's folder; ignored`);
    workspace = undefined;
  }
  return {
    ok: true,
    errors: [],
    warnings: [...warnings, ...notes.warnings()],
    model: {
      schemaVersion: version,
      project: {
        name: asString(project.name) || "(unnamed project)",
        summary: asString(project.summary, 200),
        revision: asString(project.revision),
        generatedBy: asString(project.generatedBy),
        repositories,
        workspace,
      },
      components,
      relationships,
      flows,
      unknowns: (Array.isArray(raw.unknowns) ? raw.unknowns : []).map((u) => asString(u?.text)).filter(Boolean),
    },
  };
}

/** Whether a relationship joins these two components, in either direction. */
const connects = (rel, a, b) => (rel.from === a && rel.to === b) || (rel.from === b && rel.to === a);

export const byId = (list, id) => list.find((x) => x.id === id);

export function formatEvidence(ev, { withRepo = false } = {}) {
  const prefix = withRepo && ev.repo ? `[${ev.repo}] ` : "";
  if (!ev.lines) return prefix + ev.path;
  return `${prefix}${ev.path}:${ev.lines[0] === ev.lines[1] ? ev.lines[0] : `${ev.lines[0]}-${ev.lines[1]}`}`;
}

export function relationsOf(model, id) {
  return {
    outgoing: model.relationships.filter((r) => r.from === id),
    incoming: model.relationships.filter((r) => r.to === id),
  };
}

export function countByConfidence(items) {
  const out = { observed: 0, inferred: 0, unknown: 0 };
  for (const i of items) out[i.confidence] += 1;
  return out;
}

/** Resolve an evidence path against the project root; refuses paths that escape it. */
export function resolveEvidencePath(root, rel) {
  if (rel.startsWith("/") || rel.split("/").includes("..")) return null;
  return `${root.replace(/\/$/, "")}/${rel}`;
}

export function excerpt(text, lines, context = 0, maxLines = 12) {
  const all = text.split("\n");
  if (!lines) return { startLine: 1, source: all.slice(0, maxLines).join("\n"), total: all.length, hidden: Math.max(0, all.length - maxLines) };
  const start = Math.max(1, lines[0] - context);
  const wanted = Math.min(all.length, lines[1] + context);
  const end = Math.min(wanted, start + maxLines - 1);
  return { startLine: start, source: all.slice(start - 1, end).join("\n"), total: all.length, hidden: wanted - end };
}

/** Phases in order of first appearance; empty when no step names one. */
export function flowPhases(flow) {
  const phases = [];
  for (const s of flow.steps) {
    const name = s.phase || "";
    let p = phases.find((x) => x.name === name);
    if (!p) phases.push((p = { name, steps: [] }));
    p.steps.push(s.n);
  }
  return phases.length === 1 && phases[0].name === "" ? [] : phases.map((p) => ({ ...p, name: p.name || "Other" }));
}

/** The steps of `flow` that match a focus: an optional phase name and an optional component id (either end of the step). */
export function focusSteps(flow, focus = {}) {
  return flow.steps.filter((s) => {
    if (focus.phase && (s.phase || "Other") !== focus.phase) return false;
    if (focus.component && s.from !== focus.component && s.to !== focus.component) return false;
    return true;
  });
}

/** Every flow step that touches the component, as { flow, step }. */
export function stepsTouching(model, componentId) {
  const out = [];
  for (const flow of model.flows) for (const step of flow.steps) if (step.from === componentId || step.to === componentId) out.push({ flow, step });
  return out;
}

/**
 * The relationship a step travels: { relationship, reverse, ambiguous, candidates }. A declared id wins; otherwise a
 * single forward match is used, and several matches are reported as ambiguous rather than guessed. `reverse` marks a
 * response leg of a relationship declared in the other direction. A step that stays on one component has none.
 */
export function resolveStepRelationship(model, step) {
  if (step.from === step.to) return { relationship: undefined, reverse: false, ambiguous: false, candidates: [] };
  if (step.relationship) {
    const relationship = byId(model.relationships, step.relationship);
    if (relationship) return { relationship, reverse: relationship.from !== step.from, ambiguous: false, candidates: [relationship] };
  }
  const forward = model.relationships.filter((r) => r.from === step.from && r.to === step.to);
  if (forward.length === 1) return { relationship: forward[0], reverse: false, ambiguous: false, candidates: forward };
  if (forward.length > 1) return { relationship: undefined, reverse: false, ambiguous: true, candidates: forward };
  return { relationship: undefined, reverse: false, ambiguous: false, candidates: [] };
}

/** Flow steps that travel along the relationship, in either direction. */
export function stepsUsing(model, rel) {
  const out = [];
  for (const flow of model.flows) for (const step of flow.steps) if (resolveStepRelationship(model, step).relationship?.id === rel.id) out.push({ flow, step });
  return out;
}

/** The modeled relationship a step travels along, if one is recorded or unambiguous. */
export function relationshipOf(model, step) {
  return resolveStepRelationship(model, step).relationship;
}

/** Claims the model makes at each confidence, and the observed ones that cite nothing. */
export function claimSummary(model) {
  const claims = [...model.components, ...model.relationships, ...model.flows.flatMap((f) => f.steps)];
  const counts = countByConfidence(claims);
  return { ...counts, total: claims.length, uncited: claims.filter((c) => c.confidence === "observed" && c.evidence.length === 0).length };
}

const mmId = (id) => id.replace(/[^A-Za-z0-9_]/g, "_");
const mmText = (s) => s.replace(/["\n]/g, " ");
const LINK_COLOR = { runtime: "#1f77b4", contract: "#9467bd", build: "#ff7f0e", package: "#7f7f7f", event: "#2ca02c", deployment: "#8c564b", implementation: "#17becf", other: "#bcbd22" };

/** Mermaid flowchart of the overview; `categories` (ids) limits it to those relationship categories. Dashes encode non-observed confidence; with several categories, link colors encode the category. */
export function overviewToMermaid(model, categories = []) {
  const rels = categories.length ? model.relationships.filter((r) => categories.includes(r.category)) : model.relationships;
  const shown = categories.length ? model.components.filter((c) => rels.some((r) => r.from === c.id || r.to === c.id)) : model.components;
  const multiCategory = new Set(model.relationships.map((r) => r.category)).size > 1;
  const lines = ["flowchart LR"];
  const node = (c) => `${mmId(c.id)}["${mmText(c.name)}<br/>${mmText(c.kind)}"]`;
  if (model.project.repositories.length) {
    for (const repo of model.project.repositories) {
      const members = shown.filter((c) => c.repo === repo.id);
      if (!members.length) continue;
      lines.push(`  subgraph ${mmId(`repo_${repo.id}`)}["${mmText(repo.name)}"]`);
      for (const c of members) lines.push(`    ${node(c)}`);
      lines.push("  end");
    }
    for (const c of shown.filter((c) => !model.project.repositories.some((r) => r.id === c.repo))) lines.push(`  ${node(c)}`);
  } else {
    for (const c of shown) lines.push(`  ${node(c)}`);
  }
  const styles = [];
  rels.forEach((r, i) => {
    const tag = multiCategory ? `[${categoryInfo(r.category).tag}] ` : "";
    const label = mmText(`${tag}${r.label || r.kind}${r.confidence === "observed" ? "" : ` (${r.confidence})`}`);
    lines.push(`  ${mmId(r.from)} ${r.confidence === "observed" ? "-->" : "-.->"}|"${label}"| ${mmId(r.to)}`);
    if (multiCategory) styles.push(`  linkStyle ${i} stroke:${LINK_COLOR[r.category]}`);
  });
  return [...lines, ...styles].join("\n");
}

export function flowToMermaid(model, flow) {
  const used = [];
  for (const s of flow.steps) for (const id of [s.from, s.to]) if (!used.includes(id)) used.push(id);
  const lines = ["sequenceDiagram"];
  const multiCategory = new Set(model.relationships.map((r) => r.category)).size > 1;
  for (const id of used) lines.push(`  participant ${mmId(id)} as ${mmText(byId(model.components, id).name)}`);
  for (const s of flow.steps) {
    const arrow = s.confidence === "observed" ? "->>" : "-->>";
    const tag = s.confidence === "observed" ? "" : ` (${s.confidence})`;
    const rel = multiCategory ? resolveStepRelationship(model, s).relationship : undefined;
    const cat = rel ? `[${categoryInfo(rel.category).tag}] ` : "";
    lines.push(`  ${mmId(s.from)}${arrow}${mmId(s.to)}: ${cat}${s.n}. ${mmText(s.action)}${tag}`);
    if (s.stateChange) lines.push(`  Note over ${mmId(s.to)}: ${mmText(s.stateChange.description)}${s.stateChange.verified ? "" : " (unverified)"}`);
  }
  return lines.join("\n");
}

export function selectionEvidence(model, sel) {
  if (!sel) return [];
  if (sel.kind === "component") return byId(model.components, sel.id)?.evidence ?? [];
  if (sel.kind === "relationship") return byId(model.relationships, sel.id)?.evidence ?? [];
  const [flowId, n] = sel.id.split("#");
  return byId(model.flows, flowId)?.steps.find((s) => s.n === Number(n))?.evidence ?? [];
}

/** Whether a selection still names something in the model (after a reload). */
export function hasSelection(model, sel) {
  if (!sel) return false;
  if (sel.kind === "component") return Boolean(byId(model.components, sel.id));
  if (sel.kind === "relationship") return Boolean(byId(model.relationships, sel.id));
  const [flowId, n] = sel.id.split("#");
  return Boolean(byId(model.flows, flowId)?.steps.some((s) => s.n === Number(n)));
}

