import { impactOf } from "./impact.mjs";
import { resolveStepRelationship } from "./model.mjs";

/** The comparisons a scan can make; `args` follow `git diff`. */
export const DIFF_REFS = {
  working: { label: "Working tree vs HEAD", args: ["HEAD"], untracked: true },
  staged: { label: "Staged only", args: ["--cached"], untracked: false },
};

const HUNK = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/;
const QUOTED = /^"(?:[^"\\]|\\.)*"$/;
const ESCAPES = { a: 7, b: 8, t: 9, n: 10, v: 11, f: 12, r: 13 };
const pct = (byte) => `%${byte.toString(16).padStart(2, "0")}`;

/** Decode a path git C-quoted (one holding `"`, `\` or a control character, whatever core.quotepath says); octal escapes are UTF-8 bytes. */
function unquote(s) {
  if (!QUOTED.test(s)) return s;
  const encoded = s.slice(1, -1).replace(/\\([0-7]{3})|\\(.)|([^\\]+)/g, (_, oct, esc, plain) => (oct ? pct(parseInt(oct, 8)) : esc ? pct(ESCAPES[esc] ?? esc.charCodeAt(0)) : encodeURIComponent(plain)));
  try {
    return decodeURIComponent(encoded);
  } catch {
    return s;
  }
}

/** The new-side path of `diff --git a/P b/P`; an unquoted pair splits symmetrically, since P itself may hold ` b/`. */
function headerPath(rest) {
  const half = (rest.length - 5) / 2;
  if (Number.isInteger(half) && rest.startsWith("a/") && rest.slice(2 + half, 5 + half) === " b/" && rest.slice(2, 2 + half) === rest.slice(5 + half)) return rest.slice(2, 2 + half);
  const quoted = rest.match(/ ("(?:[^"\\]|\\.)*")$/);
  return quoted ? unquote(quoted[1]).slice(2) : rest.slice(rest.lastIndexOf(" b/") + 3);
}

/**
 * Parse `git diff --unified=0 --find-renames` into [{ path, status, ranges, oldRanges, inserts, binary, renamedFrom }].
 * `ranges` are new-side [start, end] lines (a pure deletion is a point); `oldRanges` are the lines the change replaced
 * or removed in the compared revision and `inserts` the old-side lines after which text was only added. Cited lines in
 * a model describe the compared revision, so matching uses the old side, which insertions elsewhere cannot shift.
 */
export function parseDiff(text) {
  const files = [];
  let cur;
  for (const line of text.split("\n")) {
    if (line.startsWith("diff --git ")) {
      files.push((cur = { path: headerPath(line.slice(11)), status: "modified", ranges: [], oldRanges: [], inserts: [] }));
    } else if (!cur) {
      continue;
    } else if (line.startsWith("new file mode")) {
      cur.status = "added";
    } else if (line.startsWith("deleted file mode")) {
      cur.status = "deleted";
    } else if (line.startsWith("rename from ")) {
      cur.renamedFrom = unquote(line.slice(12));
    } else if (line.startsWith("rename to ")) {
      cur.path = unquote(line.slice(10));
    } else if (line.startsWith("Binary files ") || line === "GIT binary patch") {
      cur.binary = true;
    } else {
      const hunk = line.match(HUNK);
      if (hunk) {
        const oldStart = Number(hunk[1]);
        const oldCount = hunk[2] === undefined ? 1 : Number(hunk[2]);
        const start = Number(hunk[3]);
        const count = hunk[4] === undefined ? 1 : Number(hunk[4]);
        cur.ranges.push(count === 0 ? [start, start + 1] : [start, start + count - 1]);
        if (oldCount === 0) cur.inserts.push(oldStart);
        else cur.oldRanges.push([oldStart, oldStart + oldCount - 1]);
      }
    }
  }
  return files;
}

/** Untracked files from `git ls-files --others`, as whole-file additions. */
export const parseUntracked = (text) => text.split("\n").filter(Boolean).map((path) => ({ path, status: "added", ranges: [], untracked: true }));

const overlaps = (a, b) => a[0] <= b[1] && b[0] <= a[1];

/** Whether the change touches cited lines [x, y]; an insertion counts only when it lands inside the range, not at its edge. */
const touches = (change, lines) => {
  if (!change.oldRanges) return change.ranges.some((r) => overlaps(r, lines));
  return change.oldRanges.some((r) => overlaps(r, lines)) || (change.inserts ?? []).some((a) => a >= lines[0] && a < lines[1]);
};

/** Why a hit cannot say whether the change touched the cited lines. */
export const REASONS = {
  stale: "the checkout is not at the revision the model was built from, so cited lines may have moved",
  docStale: "the document was written against another model revision, so its cited lines may have moved",
  docUnknown: "the document records no model revision, so its cited lines may have moved",
  unknownBasis: "the model's revision cannot be compared with this checkout, so cited lines may have moved",
  added: "the file is new here, so the model's line numbers cannot describe it",
  binary: "binary file; line numbers do not apply",
  renamed: "the file was renamed, so the cited path no longer exists",
  nolines: "the model cites no lines for this evidence",
};

/** Lines between the cited range and the nearest changed line on the compared side, or undefined when the change has no line to measure from. */
function gapTo(change, lines) {
  const spans = change.oldRanges ? [...change.oldRanges, ...(change.inserts ?? []).map((a) => [a, a])] : change.ranges;
  if (!spans.length) return undefined;
  return Math.min(...spans.map(([a, b]) => (a > lines[1] ? a - lines[1] : lines[0] > b ? lines[0] - b : 0)));
}

function classify(ev, change) {
  const renamedAway = change.renamedFrom !== undefined && ev.path === change.renamedFrom;
  if (change.status === "added") return { level: "unclear", reason: "added" };
  if (change.binary) return { level: "unclear", reason: "binary" };
  if (!ev.lines) return { level: "file", reason: "nolines" };
  if (change.basis !== "matches") return { level: "unclear", reason: ["stale", "docStale", "docUnknown"].includes(change.basis) ? change.basis : "unknownBasis" };
  if (renamedAway) return { level: "unclear", reason: "renamed" };
  if (touches(change, ev.lines)) return { level: "lines", reason: change.status === "deleted" ? "deleted" : undefined };
  return { level: "file", reason: undefined, gap: gapTo(change, ev.lines) };
}

const ORDER = { lines: 0, file: 1, unclear: 2 };

/**
 * Which modeled elements cite the changed files. `changes` are { repo, path, status, ranges, oldRanges?, inserts?,
 * binary?, renamedFrom?, basis }. A hit is "lines" when a changed line overlaps cited lines, "file" when the file is
 * cited but the change lies outside the cited lines (or none are cited), and "unclear" when line numbers cannot be
 * compared: added or binary files, renames (even with edits), or any `basis` other than "matches" (a checkout at
 * another revision, "stale", or one that cannot be compared, "unknown" or absent). Matching is by cited path only: it
 * never says a change breaks anything.
 */
export function matchChanges(model, changes) {
  const items = [];
  for (const c of model.components) items.push({ kind: "component", id: c.id, label: c.name, evidence: c.evidence });
  for (const r of model.relationships) items.push({ kind: "relationship", id: r.id, label: r.label || r.kind, evidence: r.evidence });
  for (const f of model.flows) for (const s of f.steps) items.push({ kind: "step", id: `${f.id}#${s.n}`, flowId: f.id, n: s.n, label: `${f.name} · step ${s.n}`, evidence: s.evidence });
  const { elements, mapped } = matchItems(items, changes);
  return { elements, unmapped: changes.filter((c) => !mapped.has(changeKey(c))) };
}

const changeKey = (c) => `${c.repo ?? ""}\0${c.path}`;

/**
 * The classification `matchChanges` applies, for any list of `{ kind, id, label, evidence }` (the data and authorization
 * documents cite source the same way the model does). Returns the matched elements, best match first, and the changed
 * files that at least one item cites.
 */
export function matchItems(items, changes) {
  const mapped = new Set();
  const elements = [];
  for (const item of items) {
    const hits = [];
    for (const ev of item.evidence) {
      for (const change of changes) {
        const sameRepo = (change.repo ?? undefined) === (ev.repo ?? undefined);
        if (!sameRepo || (change.path !== ev.path && change.renamedFrom !== ev.path)) continue;
        hits.push({ evidence: ev, change, ...classify(ev, change) });
        mapped.add(changeKey(change));
      }
    }
    if (hits.length) {
      const { evidence, ...rest } = item;
      const level = hits.reduce((best, h) => (ORDER[h.level] < ORDER[best] ? h.level : best), "unclear");
      elements.push({ ...rest, hits, level });
    }
  }
  elements.sort((a, b) => ORDER[a.level] - ORDER[b.level]);
  return { elements, mapped };
}

/** The relationship a matched step travels when the model names it or has exactly one forward link; a response leg, an ambiguous pair or a local step has none. */
function stepLink(model, el) {
  const step = model.flows.find((f) => f.id === el.flowId)?.steps.find((s) => s.n === el.n);
  if (!step) return undefined;
  const res = resolveStepRelationship(model, step);
  return res.relationship && !res.reverse && !res.ambiguous ? res.relationship : undefined;
}

/** Matched steps that map to no single relationship, so nothing is traced downstream from them. */
export const untracedSteps = (model, match) => match.elements.filter((e) => e.kind === "step" && !stepLink(model, e));

/**
 * Consumers of matched components, relationships and steps (through the one relationship a step declares) that no
 * changed file cites: possible downstream effects, with what each hangs on.
 */
export function downstreamOfChanges(model, match, categories = []) {
  const sources = [];
  for (const el of match.elements) {
    if (el.kind !== "step") {
      sources.push(el);
      continue;
    }
    const rel = stepLink(model, el);
    if (rel) sources.push({ kind: "relationship", id: rel.id, label: el.label });
  }
  const matched = new Set(match.elements.filter((e) => e.kind !== "step").map((e) => `${e.kind}:${e.id}`));
  const seen = new Map();
  for (const el of sources) {
    const impact = impactOf(model, { kind: el.kind, id: el.id }, { categories });
    if (!impact) continue;
    for (const e of impact.consumers) {
      if (matched.has(`component:${e.component.id}`) || (e.relationship && matched.has(`relationship:${e.relationship.id}`))) continue;
      const hit = seen.get(e.component.id) ?? { component: e.component, because: [], relationship: e.relationship };
      if (!hit.because.includes(el.label)) hit.because.push(el.label);
      seen.set(e.component.id, hit);
    }
  }
  return [...seen.values()];
}

