import { HOST_LABELS, legendRows, newSeen, recording } from "./shortcuts.mjs";

export const MARK = { observed: "●", inferred: "◐", unknown: "○" };
export const COLOR = { observed: "green", inferred: "yellow", unknown: "red" };

export const CATEGORY_COLOR = { runtime: "cyan", contract: "magenta", build: "yellow", package: "gray", event: "green", deployment: "blue", implementation: "gray", other: undefined };
const REPO_MARK = { ok: "●", mismatch: "◐", unverified: "◐", unconfigured: "○", missing: "○", unreadable: "○" };
const REPO_COLOR = { ok: "green", mismatch: "yellow", unverified: "yellow", unconfigured: "red", missing: "red", unreadable: "red" };
// Line and head glyphs differ per category so a build or package link never reads as a network call.
const ARROWS = { runtime: ["──", "▶"], contract: ["══", "▶"], build: ["━━", "▷"], package: ["··", "▷"], event: ["~~", "▶"], deployment: ["──", "▷"], implementation: ["··", "▷"], other: ["──", "▶"] };

const MAX_STATE_ROWS = 10;
const MAX_LINKS = 6;
const PICK_ROWS = 8;

const cut = (s, n) => (n > 1 && s.length > n ? `${s.slice(0, n - 1)}…` : s);
const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;

export function indicatorText(status, cwdName) {
  if (status.kind === "ready") {
    const m = status.model;
    const flows = m.flows.length;
    const repos = m.project.repositories.length ? `, ${plural(m.project.repositories.length, "repo")}` : "";
    const issues = (status.repos ?? []).filter((r) => r.state !== "ok").length;
    return `◆ ${m.project.name} · ${m.components.length} components, ${flows} flow${flows === 1 ? "" : "s"}${repos}${issues ? ` · ! ${plural(issues, "repo issue")}` : ""}`;
  }
  if (status.kind === "loading") return `◇ ${cwdName} · architecture…`;
  if (status.kind === "invalid") return `◇ ${cwdName} · architecture model invalid`;
  return `◇ ${cwdName} · no architecture model`;
}

export function buildIndicator(h, status, cwdName, cols, open) {
  const { Box, Text, Button } = h;
  const ready = status.kind === "ready";
  return Box({
    flexDirection: "row",
    gap: 1,
    children: [
      Text({ key: "ind", dimColor: !ready, color: ready ? "cyan" : undefined, wrap: "truncate-end", children: cut(indicatorText(status, cwdName), Math.max(10, cols - 14)) }),
      Button({ key: "open", label: "/architecture", plain: true, dimColor: true, onPress: open }),
    ],
  });
}

function nav(h, ctx) {
  const { Box, Button } = h;
  const ready = ctx.status.kind === "ready";
  const active = (view) => ctx.view === view || (ctx.view === "inspect" && ctx.origin === view);
  const tab = (view, label, hotkey) =>
    Button({ key: `tab-${view}`, label: `${active(view) ? "▸ " : ""}${label}`, hotkey, plain: true, onPress: () => ctx.actions.setView(view) });
  return Box({
    key: "nav",
    gap: 2,
    flexWrap: "wrap",
    children: [
      ...(ready ? [tab("overview", "Overview", "o"), tab("flow", "Flow", "f"), tab("impact", "Impact", "i"), tab("behavior", "Behavior", "e"), tab("explore", "Explore", "d"), tab("data", "Data", "t"), tab("auth", "Auth", "u"), tab("mermaid", "Mermaid", "m")] : []),
      ...(ready && ctx.canPicture && ctx.hasDiagram ? [Button({ key: "picmode", label: ctx.pictureMode === "picture" ? "Text view" : "Diagram view", hotkey: "v", plain: true, onPress: () => ctx.actions.setPictureMode(ctx.pictureMode === "picture" ? "text" : "picture") })] : []),
      ...(ready && ctx.hasDiagram ? [Button({ key: "browser", label: "Open in browser", hotkey: "w", plain: true, onPress: ctx.actions.openInBrowser })] : []),
      Button({ key: "reload", label: "Reload", hotkey: "r", plain: true, onPress: ctx.actions.reload }),
      Button({ key: "build", label: ready ? "Refresh model" : "Build model", hotkey: "g", plain: true, onPress: () => ctx.actions.build() }),
      Button({ key: "legend", label: ctx.legendOpen ? "Hide shortcuts" : "Shortcuts", hotkey: "h", plain: true, onPress: ctx.actions.toggleLegend }),
      Button({ key: "close", label: "Close", hotkey: "x", plain: true, onPress: ctx.actions.close }),
    ],
  });
}

// The keys drawn in this pane right now, so the list cannot drift from what the views register.
function shortcutLegend(h, ctx, seen) {
  const { Box, Text, Button } = h;
  const rows = legendRows(seen);
  const entry = ([keys, what], i) => Text({ key: `sc${i}`, wrap: "wrap", children: [Text({ key: "k", bold: true, color: "cyan", children: keys }), Text({ key: "w", children: ` ${what}` })] });
  const host = rows.filter(([k]) => HOST_LABELS.has(k));
  return Box({
    key: "shortcuts",
    flexDirection: "column",
    borderStyle: "round",
    paddingX: 1,
    children: [
      Text({ key: "sch", bold: true, children: "Shortcuts here" }),
      Box({ key: "scl", columnGap: 2, flexWrap: "wrap", children: rows.filter((r) => !host.includes(r)).map(entry) }),
      ...host.map((r, i) => entry(r, rows.length + i)),
      Button({ key: "legend-close", label: "Close shortcuts", plain: true, onPress: ctx.actions.toggleLegend }),
    ],
  });
}

function legend(h, model) {
  const { Box, Text } = h;
  const c = claimSummary(model);
  const rev = model.project.revision ? `  model @ ${model.project.revision}` : model.project.repositories.length ? `  ${plural(model.project.repositories.length, "repository")}` : "";
  return Box({
    key: "legend",
    flexDirection: "column",
    children: [
      Text({ key: "lc", dimColor: true, wrap: "truncate-end", children: `${MARK.observed} observed ${c.observed}  ${MARK.inferred} inferred ${c.inferred}  ${MARK.unknown} unknown ${c.unknown}  (components, relationships, steps)${rev}` }),
      c.uncited
        ? Text({ key: "lu", color: "red", wrap: "truncate-end", children: `! ${plural(c.uncited, "observed claim")} cite no file` })
        : Text({ key: "lu", dimColor: true, wrap: "truncate-end", children: "Every observed claim cites a file; select one to read it." }),
    ],
  });
}

function heading(h, key, text) {
  return h.Text({ key, bold: true, children: text });
}

function evidenceRow(h, ctx, ev, i) {
  const { Button } = h;
  const open = ctx.excerpt?.evIndex === i;
  const label = `${open ? "▸ " : ""}${formatEvidence(ev, { withRepo: ctx.model.project.repositories.length > 0 })}${ev.note ? ` — ${ev.note}` : ""}`;
  return Button({ key: `evb${i}`, label: cut(label, Math.max(10, ctx.cols - 6)), hotkey: i < 9 ? String(i + 1) : undefined, plain: true, onPress: () => ctx.actions.evidence(i) });
}

function evidenceBlock(h, ctx, evidence) {
  const { Box, Text, Code } = h;
  const rows = [heading(h, "evh", "Evidence")];
  if (evidence.length === 0) {
    rows.push(Text({ key: "noev", color: "red", children: "No file evidence recorded — treat as unverified." }));
  }
  evidence.forEach((ev, i) => rows.push(evidenceRow(h, ctx, ev, i)));
  const ex = ctx.excerpt;
  if (ex && ex.evIndex < evidence.length) {
    if (ex.status === "ok") {
      if (ex.warning) rows.push(Text({ key: "exw", color: "yellow", wrap: "wrap", children: `! ${ex.warning}` }));
      rows.push(Text({ key: "exh", dimColor: true, children: `${ex.repo ? `[${ex.repo}] ` : ""}${ex.path}:${ex.startLine}` }));
      rows.push(Code({ key: "code", source: ex.source, path: ex.path, startLine: ex.startLine, wrap: "truncate-end" }));
      if (ex.hidden > 0) rows.push(Text({ key: "exmore", dimColor: true, children: `… ${plural(ex.hidden, "more cited line")} not shown` }));
    } else {
      rows.push(Text({ key: "exm", color: "red", wrap: "wrap", children: ex.message }));
    }
  } else if (evidence.length) {
    rows.push(Text({ key: "exhint", dimColor: true, children: "Select an entry (or press its number) to read the file." }));
  }
  return Box({ key: "evidence", flexDirection: "column", children: rows });
}

function card(h, ctx, c, width) {
  const { Box, Button } = h;
  const selected = ctx.selection?.kind === "component" && ctx.selection.id === c.id;
  return Box({
    key: `c-${c.id}`,
    flexDirection: "column",
    borderStyle: selected ? "bold" : "round",
    borderColor: selected ? "cyan" : COLOR[c.confidence],
    paddingX: 1,
    width,
    children: [
      Button({ key: `cb-${c.id}`, label: `${MARK[c.confidence]} ${c.name} · ${c.kind}`, plain: true, onPress: () => ctx.actions.select("component", c.id) }),
      c.repo ? h.Text({ key: `cr-${c.id}`, dimColor: true, wrap: "truncate-end", children: c.repo }) : null,
    ],
  });
}

// The picture of the current view: its node when drawn, otherwise a one-line status, or nothing.
function drawn(ctx) {
  return ctx.picture?.status === "ready" ? ctx.picture : null;
}

// One dim line under a picture the terminal has to draw small, naming the way to a legible one.
function smallNote(h, ctx, text) {
  return ctx.picture?.status === "ready" && ctx.picture.small ? h.Text({ key: "small", dimColor: true, wrap: "wrap", children: text }) : null;
}

function pictureNote(h, ctx) {
  const pic = ctx.picture;
  if (pic?.status === "pending") return h.Text({ key: "pend", dimColor: true, children: "Drawing the diagram…" });
  if (pic?.status === "error") return h.Text({ key: "perr", color: "yellow", wrap: "wrap", children: `The diagram could not be drawn (${pic.message}); showing the text view.` });
  return null;
}

function participantCount(flow) {
  return new Set(flow.steps.flatMap((s) => [s.from, s.to])).size;
}

function categoryCounts(model) {
  return CATEGORIES.map((c) => ({ ...c, count: model.relationships.filter((r) => r.category === c.id).length })).filter((c) => c.count > 0);
}

function categoryStrip(h, ctx, counts) {
  const { Box, Button } = h;
  const chosen = ctx.categories ?? [];
  const tab = (key, label, active, onPress) => Button({ key, label: `${active ? "▸ " : ""}${label}`, plain: true, onPress });
  return Box({
    key: "cats",
    gap: 2,
    flexWrap: "wrap",
    children: [
      tab("cat-all", `All ${ctx.model.relationships.length}`, chosen.length === 0, ctx.actions.clearCategories),
      ...counts.map((c) => tab(`cat-${c.id}`, `${c.label} ${c.count}`, chosen.includes(c.id), () => ctx.actions.toggleCategory(c.id))),
    ],
  });
}

function relationshipRow(h, ctx, r, tagged) {
  const { model, cols } = ctx;
  const from = byId(model.components, r.from).name;
  const to = byId(model.components, r.to).name;
  const [line, head] = ARROWS[r.category];
  const edge = r.confidence === "observed" ? line : "┄┄";
  const tag = tagged ? `[${categoryInfo(r.category).tag}] ` : "";
  const label = `${tag}${MARK[r.confidence]} ${from} ${edge}${r.label || r.kind}${edge}${head} ${to}${r.evidence.length ? "" : " !"}`;
  return h.Button({ key: `r-${r.id}`, label: cut(label, cols - 2), plain: true, onPress: () => ctx.actions.select("relationship", r.id) });
}

function repositoriesBlock(h, ctx) {
  const { Box, Text } = h;
  const { model } = ctx;
  const repos = ctx.status.repos ?? [];
  if (!model.project.repositories.length) return null;
  const rows = model.project.repositories.map((repo) => {
    const found = repos.find((x) => x.id === repo.id);
    const state = found?.state ?? "unconfigured";
    const members = model.components.filter((c) => c.repo === repo.id).length;
    const rev = repo.revision ? repo.revision.slice(0, 12) : "no revision";
    const tail = state === "ok" ? "checkout matches" : (found?.message ?? "not checked");
    return Text({ key: `rp-${repo.id}`, color: REPO_COLOR[state], wrap: "wrap", children: `${REPO_MARK[state]} ${repo.id} · ${plural(members, "component")} · ${rev}${repo.version ? ` (${repo.version})` : ""} · ${tail}` });
  });
  return Box({ key: "repos", flexDirection: "column", marginTop: 1, children: [heading(h, "rph", "Repositories"), ...rows] });
}

function diagnosticsBlock(h, ctx) {
  const { Box, Text } = h;
  const warnings = ctx.status.warnings ?? [];
  if (!warnings.length) return null;
  const rows = warnings.slice(0, 8).map((w, i) => Text({ key: `dg${i}`, color: "yellow", wrap: "wrap", children: `! ${w}` }));
  if (warnings.length > 8) rows.push(Text({ key: "dgm", dimColor: true, children: `… and ${warnings.length - 8} more` }));
  return Box({ key: "diag", flexDirection: "column", marginTop: 1, children: [heading(h, "dgh", "Diagnostics"), ...rows] });
}

function overviewView(h, ctx) {
  const { Box, Text, Button } = h;
  const { model, cols } = ctx;
  const counts = categoryCounts(model);
  const tagged = counts.length > 1;
  const chosen = tagged ? (ctx.categories ?? []) : [];
  const widest = Math.max(...model.components.map((c) => c.name.length + c.kind.length + 3), 8);
  const cell = Math.min(cols, widest + 6);
  const rows = [];
  const layers = layerComponents(model, chosen);
  layers.forEach((layer, li) => {
    if (li > 0) rows.push(Text({ key: `arrow${li}`, dimColor: true, children: "  ▼" }));
    chunkRow(layer, cols, cell + 1).forEach((chunk, ci) => {
      rows.push(Box({ key: `row${li}-${ci}`, gap: 1, children: chunk.map((id) => card(h, ctx, byId(model.components, id), cell)) }));
    });
  });
  const hidden = model.components.length - layers.flat().length;

  const shownRels = chosen.length ? model.relationships.filter((r) => chosen.includes(r.category)) : model.relationships;
  const relBlocks = [];
  if (tagged) {
    for (const c of counts.filter((x) => !chosen.length || chosen.includes(x.id))) {
      relBlocks.push(Text({ key: `rch-${c.id}`, bold: true, color: CATEGORY_COLOR[c.id], children: `${c.label} (${c.count})` }));
      for (const r of shownRels.filter((x) => x.category === c.id)) relBlocks.push(relationshipRow(h, ctx, r, true));
    }
  } else {
    for (const r of shownRels) relBlocks.push(relationshipRow(h, ctx, r, false));
  }

  const flows = model.flows.map((f) =>
    Button({ key: `wf-${f.id}`, label: cut(`▸ ${f.name} · ${plural(f.steps.length, "step")}, ${plural(participantCount(f), "component")}`, cols - 2), plain: true, onPress: () => ctx.actions.openFlow(f.id) }),
  );

  const pic = drawn(ctx);
  const focus = ctx.overviewFocus ? byId(model.components, ctx.overviewFocus) : undefined;
  const picked = pic
    ? [
        Box({ key: "pic", children: [pic.node] }),
        Box({
          key: "focusrow",
          gap: 2,
          flexWrap: "wrap",
          children: [
