              options: [{ value: "", label: "whole system" }, ...model.components.map((c) => ({ value: c.id, label: `${c.name}${c.repo ? ` · ${c.repo}` : ""}` }))],
              onSelect: (value) => ctx.actions.setOverviewFocus(value || null),
            }),
            ...(focus
              ? [
                  Button({ key: "focus-open", label: `Details ▸ ${cut(focus.name, 28)}`, plain: true, onPress: () => ctx.actions.select("component", focus.id) }),
                  Button({ key: "focus-impact", label: "Impact ▸", plain: true, onPress: () => ctx.actions.openImpact("component", focus.id) }),
                  Button({ key: "focus-clear", label: "Show everything", plain: true, onPress: () => ctx.actions.setOverviewFocus(null) }),
                ]
              : ctx.carriedTotal > 0
                ? [Button({ key: "carried", label: `${ctx.showCarried ? "Hide" : "Show"} ${plural(ctx.carriedTotal, "carried call")}`, hotkey: "c", plain: true, onPress: ctx.actions.toggleCarried })]
                : []),
