  const cov = coverageBlock(h, ctx, { COLOR, MARK, cut, plural });
  const head = pic ? [Box({ key: "picwrap", flexDirection: "column", children: picked }), catbox, legend(h, model), repositoriesBlock(h, ctx), cov] : [legend(h, model), repositoriesBlock(h, ctx), cov, catbox];
  return [
