    ...(pic ? [] : picked),
    Box({
      key: "rels",
      flexDirection: "column",
      marginTop: 1,
      children: [
        pic ? Button({ key: "rellist", label: `${relsOpen ? "▾" : "▸"} Relationship list${chosen.length ? ` (${shownRels.length} of ${model.relationships.length})` : ` (${shownRels.length})`} · select one to read its evidence`, plain: true, onPress: ctx.actions.toggleList }) : heading(h, "relh", `Relationships${chosen.length ? ` (${shownRels.length} of ${model.relationships.length})` : ""} (select for evidence)`),
        ...(relsOpen ? relBlocks : []),
      ],
    }),
    model.unknowns.length
      ? Box({ key: "unk", flexDirection: "column", marginTop: 1, children: [heading(h, "unkh", "Unknowns"), ...model.unknowns.map((u, i) => Text({ key: `u${i}`, color: "red", wrap: "wrap", children: `○ ${u}` }))] })
      : null,
    diagnosticsBlock(h, ctx),
  ];
}

function phaseStrip(h, ctx, flow, phases) {
  const { Box, Button } = h;
  const on = (name) => (ctx.focus.phase ?? null) === name;
  const tab = (key, name, label, count) => Button({ key, label: `${on(name) ? "▸ " : ""}${label} ${count}`, plain: true, onPress: () => ctx.actions.setPhase(name) });
  return Box({ key: "phases", gap: 2, flexWrap: "wrap", children: [tab("ph-all", null, "All", flow.steps.length), ...phases.map((p, i) => tab(`ph-${i}`, p.name, p.name, p.steps.length))] });
}

function stepRow(h, ctx, flow, row, stepsByN, pick = (n) => ctx.actions.select("step", `${flow.id}#${n}`)) {
  const { Button, Text } = h;
  const s = stepsByN.get(row.step);
  const isStep = row.kind === "step";
  const selected = ctx.selection?.kind === "step" && ctx.selection.id === `${flow.id}#${row.step}`;
  const tone = row.kind === "state" ? "green" : row.kind === "state-unverified" ? "yellow" : undefined;
  const dim = isStep && !selected && s.confidence !== "observed";
  const flags = isStep ? `${s.evidence.length ? "" : " !"}${flow.unknowns.some((u) => u.step === s.n) ? " ?" : ""}` : "";
  const children = [
    Text({ key: "ld", dimColor: dim, children: row.lead }),
    Text({ key: "mk", color: isStep ? COLOR[s.confidence] : tone, children: isStep ? ` ${MARK[s.confidence]} ` : "   " }),
    Text({ key: "lb", bold: selected, color: selected ? "cyan" : tone, dimColor: dim, children: row.label }),
  ];
  if (flags) children.push(Text({ key: "fl", color: "red", children: flags }));
  return Button({ key: isStep ? `st-${row.step}` : `sv-${row.step}`, plain: true, onPress: () => pick(row.step), children });
}

// Picks the interaction a diagram highlights; the diagram itself cannot be clicked.
function stepNavigator(h, ctx, flow, visible, pick = (n) => ctx.actions.select("step", `${flow.id}#${n}`)) {
  const { Box, Text, Button, Select } = h;
  const sel = ctx.selection?.kind === "step" && ctx.selection.id.startsWith(`${flow.id}#`) ? Number(ctx.selection.id.split("#")[1]) : null;
  const at = sel === null ? -1 : visible.findIndex((x) => x.n === sel);
  return Box({
    key: "nav-steps",
    gap: 2,
    flexWrap: "wrap",
    children: [
      Button({ key: "np", label: "◀ prev", hotkey: "p", plain: true, onPress: () => ctx.actions.stepBy(-1) }),
      Select({
        key: "stepsel",
        label: "Interaction",
        value: at < 0 ? "" : String(sel),
        options: [{ value: "", label: "choose one to highlight it" }, ...visible.map((s) => ({ value: String(s.n), label: cut(`${s.n}. ${s.action}`, Math.max(20, ctx.cols - 30)) }))],
        onSelect: (value) => value && pick(value),
      }),
      Button({ key: "nn", label: "next ▶", hotkey: "n", plain: true, onPress: () => ctx.actions.stepBy(1) }),
      Text({ key: "npos", dimColor: true, children: at < 0 ? `${plural(visible.length, "interaction")}` : `${at + 1} of ${visible.length}` }),
      ...(ctx.zoomable ? [Button({ key: "zoom", label: ctx.windowed ? "Show all steps" : "Focus window", hotkey: "z", plain: true, onPress: () => ctx.actions.setZoom(ctx.windowed ? "fit" : "focus") })] : []),
    ],
  });
}

// The existing sequence of the exploration's question with the chosen alternative drawn on it (picture, else text); the step detail stays in this view.
function exploreSequence(h, ctx, flow, win, alt) {
  const { Box, Text, Button } = h;
  const overlay = alt ? overlayFor(ctx.status.explore.exploration, alt.id) : null;
  const pick = (n) => ctx.actions.exploreStep(flow.id, Number(n));
  const stepsByN = new Map(flow.steps.map((s) => [s.n, s]));
  const out = [];
  if (ctx.picture?.status === "ready") {
    out.push(stepNavigator(h, ctx, flow, win.steps, pick));
    out.push(Box({ key: "pic", children: [ctx.picture.node] }));
    out.push(smallNote(h, ctx, "Drawn small. Press v for the text view or w to open the diagram in your browser."));
  } else {
    const seq = sequenceDiagram(ctx.model, flow, ctx.cols - 2, win.steps, { states: win.steps.length <= MAX_STATE_ROWS, reserve: 5, overlay });
    const head = [];
    if (ctx.picture?.status === "pending") head.push(Text({ key: "pend", dimColor: true, children: "Drawing the diagram…" }));
    if (ctx.picture?.status === "error") head.push(Text({ key: "perr", color: "yellow", wrap: "wrap", children: `The diagram could not be drawn (${ctx.picture.message}); showing the text view.` }));
    if (seq.mode === "diagram") {
      if (!seq.named) head.push(Text({ key: "sleg", dimColor: true, wrap: "wrap", children: seq.legend.map((l) => `${l.letter}=${l.name}`).join("  ") }));
      head.push(Text({ key: "shead", bold: true, wrap: "truncate-end", children: seq.header || " " }));
    } else head.push(Text({ key: "narrow", dimColor: true, children: "Terminal too narrow for the diagram; showing the ordered list." }));
    const proposed = (r) => Box({ key: `px-${r.step}`, children: [Text({ key: "ld", children: r.lead }), Text({ key: "mk", color: "magenta", children: r.kind === "proposed" ? " + " : " ◆ " }), Text({ key: "lb", bold: true, color: "magenta", children: r.label })] });
    out.push(Box({ key: "seq", flexDirection: "column", marginTop: 1, children: [...head, ...seq.rows.map((r) => (r.kind.startsWith("proposed") ? proposed(r) : stepRow(h, ctx, flow, r, stepsByN, pick)))] }));
    if (overlay) out.push(Text({ key: "pleg", dimColor: true, wrap: "wrap", children: "╞═▶ ⟦id⟧ PROPOSED: a new interaction the alternative would add · ◆ PROPOSED CHANGE: a step it would change · both are hypothetical; every other row is the model" }));
  }
  const sel = ctx.selection;
  const [flowId, n] = sel?.kind === "step" ? sel.id.split("#") : [];
  const step = flowId === flow.id ? stepsByN.get(Number(n)) : undefined;
  if (step && win.steps.some((s) => s.n === step.n)) {
    out.push(stepDetail(h, ctx, flow, step, win.steps));
    out.push(Button({ key: "inflow", label: "Open this step in the Flow view (Back returns here)", hotkey: "l", plain: true, onPress: () => ctx.actions.select("step", `${flow.id}#${step.n}`) }));
  } else out.push(Text({ key: "pick", dimColor: true, children: "Select an interaction to read the file evidence behind it." }));
  return out;
}

function behaviorLink(h, ctx, stepId) {
  const hop = ctx.status.behavior?.kind === "ready" && ctx.status.behavior.behavior.hops.find((x) => x.step === stepId);
  return hop ? h.Button({ key: "lb", label: cut("Behavior ▸ what happens when a failure reaches this?", ctx.cols - 4), plain: true, onPress: () => ctx.actions.openBehavior(hop.id) }) : null;
}

function dataLink(h, ctx, stepId) {
  const st = ctx.status.data;
  const anchored = st?.kind === "ready" && (st.data.effects.some((e) => e.step === stepId) || st.data.lifecycles.some((l) => l.transitions.some((t) => t.step === stepId)));
  return anchored ? h.Button({ key: "ld", label: cut("Data ▸ what state does this step change?", ctx.cols - 4), plain: true, onPress: () => ctx.actions.openData(stepId) }) : null;
}

function authLink(h, ctx, stepId) {
  const st = ctx.status.auth;
  const anchored = st?.kind === "ready" && st.auth.hops.some((x) => x.step === stepId);
  return anchored ? h.Button({ key: "la", label: cut("Auth ▸ whose authority, under which credentials?", ctx.cols - 4), plain: true, onPress: () => ctx.actions.openAuth({ step: stepId }) }) : null;
}

function stepDetail(h, ctx, flow, step, visible) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const from = byId(model.components, step.from);
  const to = byId(model.components, step.to);
  const res = resolveStepRelationship(model, step);
  const rel = res.relationship;
  const pos = visible.findIndex((x) => x.n === step.n);
  const drawn = ctx.picture?.status === "ready";
  const body = [
    Text({ key: "dt", bold: true, color: COLOR[step.confidence], wrap: "wrap", children: `${MARK[step.confidence]} Step ${step.n}: ${from.name} → ${to.name}  [${step.confidence}]` }),
    drawn
      ? null
      : Box({
          key: "dh",
          gap: 2,
          children: [
            Button({ key: "prev", label: "◀ prev", hotkey: "p", plain: true, onPress: () => ctx.actions.stepBy(-1) }),
            Button({ key: "next", label: "next ▶", hotkey: "n", plain: true, onPress: () => ctx.actions.stepBy(1) }),
            pos >= 0 ? Text({ key: "dpos", dimColor: true, children: `${pos + 1} of ${visible.length} shown` }) : null,
          ],
        }),
    drawn ? null : Text({ key: "act", wrap: "wrap", children: step.action }),
  ];
  if (rel) {
    const via = rel.via ? ` · via ${byId(model.components, rel.via).name}` : "";
    body.push(Text({ key: "rel", color: CATEGORY_COLOR[rel.category], wrap: "wrap", children: `Relationship: ${rel.label || rel.kind}${categoryCounts(model).length > 1 ? ` · ${categoryInfo(rel.category).label}` : ""} · ${rel.id}${res.reverse ? " (response leg)" : ""}${via}` }));
  } else if (res.ambiguous) {
    body.push(Text({ key: "rel", color: "yellow", wrap: "wrap", children: `${res.candidates.length} relationships connect ${from.name} and ${to.name} and this step names none: ${res.candidates.map((r) => r.id).join(", ")}` }));
  } else if (model.schemaVersion >= 2) {
    body.push(Text({ key: "rel", dimColor: true, wrap: "wrap", children: step.from === step.to ? `Local operation inside ${from.name}; no relationship.` : `No relationship modeled between ${from.name} and ${to.name}.` }));
  }
  if (step.stateChange && !drawn) {
    body.push(Text({ key: "sch", color: step.stateChange.verified ? "green" : "yellow", wrap: "wrap", children: `State change in ${step.stateChange.store}: ${step.stateChange.description} (${step.stateChange.verified ? "verified in code" : "NOT verified"})` }));
  }
  for (const [i, u] of flow.unknowns.filter((x) => x.step === step.n).entries()) body.push(Text({ key: `su${i}`, color: "red", wrap: "wrap", children: `○ ${u.text}` }));
  body.push(
    Box({
      key: "sl",
      flexDirection: "column",
      children: [
        link(h, ctx, "lf", `Open ${from.name}`, "component", from.id),
        link(h, ctx, "lt", `Open ${to.name}`, "component", to.id),
        rel ? link(h, ctx, "lr", `Open relationship (${rel.label || rel.kind})`, "relationship", rel.id) : null,
        rel ? impactLink(h, ctx, "li", "relationship", rel.id, "this relationship") : null,
        behaviorLink(h, ctx, `${flow.id}#${step.n}`),
        dataLink(h, ctx, `${flow.id}#${step.n}`),
        authLink(h, ctx, `${flow.id}#${step.n}`),
        ...(res.ambiguous ? res.candidates.slice(0, 4).map((r) => link(h, ctx, `lc-${r.id}`, `Open candidate ${r.id} (${r.label || r.kind})`, "relationship", r.id)) : []),
      ],
    }),
  );
  body.push(evidenceBlock(h, ctx, step.evidence));
  return Box({ key: "detail", flexDirection: "column", marginTop: 1, borderStyle: "round", borderColor: COLOR[step.confidence], paddingX: 1, children: body });
}

function flowView(h, ctx) {
  const { Box, Text, Button, Select } = h;
  const { model, cols } = ctx;
  if (model.flows.length === 0) return [Text({ key: "noflow", dimColor: true, children: "This model defines no execution flows." })];
  const flow = byId(model.flows, ctx.flowId) ?? model.flows[0];
  const phases = flowPhases(flow);
  const visible = focusSteps(flow, ctx.focus);
  const stepsByN = new Map(flow.steps.map((s) => [s.n, s]));
  const out = [];

  if (ctx.canBack) out.push(Button({ key: "back", label: "◀ Back", hotkey: "b", plain: true, onPress: ctx.actions.back }));
  if (model.flows.length > 1) {
    out.push(Box({ key: "picker", gap: 2, flexWrap: "wrap", children: model.flows.map((f) => Button({ key: `fl-${f.id}`, label: `${f.id === flow.id ? "▸ " : ""}${f.name}`, plain: true, onPress: () => ctx.actions.openFlow(f.id) })) }));
  }
  out.push(Text({ key: "fname", bold: true, wrap: "truncate-end", children: flow.name }));
  if (flow.summary) out.push(Text({ key: "fsum", dimColor: true, wrap: "wrap", children: flow.summary }));
  if (phases.length) out.push(phaseStrip(h, ctx, flow, phases));

  const people = [];
  for (const s of flow.steps) for (const id of [s.from, s.to]) if (!people.includes(id)) people.push(id);
  out.push(
    Select({
      key: "who",
      label: "Involving",
      value: ctx.focus.component ?? "",
      options: [{ value: "", label: "any component" }, ...people.map((id) => ({ value: id, label: byId(model.components, id).name }))],
      onSelect: (value) => ctx.actions.setFocusComponent(value || null),
    }),
  );

  const shown = visible.length === flow.steps.length ? `All ${plural(visible.length, "step")}` : `${visible.length} of ${plural(flow.steps.length, "step")}`;
  out.push(Text({ key: "cap", dimColor: true, wrap: "truncate-end", children: `${shown} · ${MARK.observed} observed ${MARK.inferred} inferred ${MARK.unknown} unknown  ┄ not observed  ▪ state  ! no evidence  ? open question${categoryCounts(model).length > 1 ? "  [type] relationship" : ""}` }));

  if (visible.length === 0) {
    out.push(Text({ key: "none", color: "yellow", children: "No step matches this focus. Choose “All” or “any component”." }));
  } else {
    const tagged = categoryCounts(model).length > 1;
    const tags = new Map();
    if (tagged) {
      for (const s of visible) {
        const res = resolveStepRelationship(model, s);
        if (res.relationship) tags.set(s.n, ` [${categoryInfo(res.relationship.category).tag}]`);
        else if (res.ambiguous) tags.set(s.n, " [?]");
      }
    }
    if (ctx.picture?.status === "ready") {
      out.push(stepNavigator(h, ctx, flow, visible));
      out.push(Box({ key: "pic", children: [ctx.picture.node] }));
      out.push(smallNote(h, ctx, ctx.zoomable ? "This is the whole sequence, drawn small. Press z for a readable window around the selected step." : "Drawn small. Focus a phase or a component to draw fewer steps larger."));
    } else {
    const seq = sequenceDiagram(model, flow, cols - 2, visible, { states: visible.length <= MAX_STATE_ROWS, reserve: 5, tags });
    const head = [];
    if (ctx.picture?.status === "pending") head.push(Text({ key: "pend", dimColor: true, children: "Drawing the diagram…" }));
    if (ctx.picture?.status === "error") head.push(Text({ key: "perr", color: "yellow", wrap: "wrap", children: `The diagram could not be drawn (${ctx.picture.message}); showing the text view.` }));
    if (seq.mode === "diagram") {
      if (!seq.named) head.push(Text({ key: "sleg", dimColor: true, wrap: "wrap", children: seq.legend.map((l) => `${l.letter}=${l.name}`).join("  ") }));
      head.push(Text({ key: "shead", bold: true, wrap: "truncate-end", children: seq.header || " " }));
    } else {
      head.push(Text({ key: "narrow", dimColor: true, children: "Terminal too narrow for the diagram; showing the ordered list." }));
    }
    out.push(Box({ key: "seq", flexDirection: "column", marginTop: 1, children: [...head, ...seq.rows.map((r) => stepRow(h, ctx, flow, r, stepsByN))] }));
    if (visible.length > MAX_STATE_ROWS && visible.some((s) => s.stateChange)) {
      out.push(Text({ key: "hint", dimColor: true, children: "Focus on a phase or component to list each state change." }));
    }
    }
  }

  const sel = ctx.selection;
  if (sel?.kind === "step") {
    const [flowId, n] = sel.id.split("#");
    const step = flowId === flow.id ? stepsByN.get(Number(n)) : undefined;
    if (step) out.push(stepDetail(h, ctx, flow, step, visible));
  } else if (visible.length) {
    out.push(Text({ key: "pick", dimColor: true, children: "Select an interaction to read the file evidence behind it." }));
  }

  const open = flow.unknowns.filter((u) => !u.step || visible.some((s) => s.n === u.step));
  if (open.length) {
    out.push(Box({ key: "funk", flexDirection: "column", marginTop: 1, children: [heading(h, "fuh", "Unknowns & assumptions"), ...open.map((u, i) => Text({ key: `fu${i}`, color: "red", wrap: "wrap", children: `○ ${u.step ? `(step ${u.step}) ` : ""}${u.text}` }))] }));
  }
  return out;
}

function link(h, ctx, key, label, kind, id) {
  return h.Button({ key, label: cut(label, ctx.cols - 4), plain: true, onPress: () => ctx.actions.select(kind, id) });
}

function stepLinks(h, ctx, key, uses) {
  const { Box, Text } = h;
  if (!uses.length) return null;
  const rows = uses.slice(0, MAX_LINKS).map(({ flow, step }) => link(h, ctx, `${key}-${flow.id}-${step.n}`, `${MARK[step.confidence]} ${flow.name} · step ${step.n}: ${step.action}`, "step", `${flow.id}#${step.n}`));
  if (uses.length > MAX_LINKS) rows.push(Text({ key: `${key}-more`, dimColor: true, children: `… and ${uses.length - MAX_LINKS} more` }));
  return Box({ key: `${key}-box`, flexDirection: "column", marginTop: 1, children: [heading(h, `${key}-h`, `Seen in workflow steps (${uses.length})`), ...rows] });
}

function inspectView(h, ctx) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const sel = ctx.selection;
  const back = Button({ key: "back", label: "◀ Back", hotkey: "b", plain: true, onPress: ctx.actions.back });
  const head = (mark, conf, title) => Text({ key: "ih", bold: true, wrap: "wrap", children: `${mark} ${title}  [${conf}]`, color: COLOR[conf] });
  const body = [back];

  if (sel?.kind === "component") {
    const c = byId(model.components, sel.id);
    if (c) {
      const { outgoing, incoming } = relationsOf(model, c.id);
      const relLink = (r, dir) => link(h, ctx, `${dir}-${r.id}`, `${categoryCounts(model).length > 1 ? `[${categoryInfo(r.category).tag}] ` : ""}${dir === "out" ? "→" : "←"} ${byId(model.components, dir === "out" ? r.to : r.from).name}: ${r.label || r.kind} ${MARK[r.confidence]}${r.evidence.length ? "" : " !"}`, "relationship", r.id);
      body.push(head(MARK[c.confidence], c.confidence, `${c.name} (${c.kind})`));
      if (c.repo) body.push(Text({ key: "crepo", dimColor: true, children: `Repository: ${c.repo}` }));
      body.push(drawn(ctx) ? Box({ key: "pic", children: [drawn(ctx).node] }) : pictureNote(h, ctx));
      body.push(Text({ key: "resp", wrap: "wrap", children: c.responsibility || "No responsibility recorded." }));
      body.push(impactLink(h, ctx, "imp", "component", c.id, c.name));
      body.push(Box({ key: "outs", flexDirection: "column", marginTop: 1, children: [heading(h, "oh", `Depends on (${outgoing.length})`), ...outgoing.map((r) => relLink(r, "out"))] }));
      body.push(Box({ key: "ins", flexDirection: "column", children: [heading(h, "ih2", `Used by (${incoming.length})`), ...incoming.map((r) => relLink(r, "in"))] }));
      body.push(stepLinks(h, ctx, "ws", stepsTouching(model, c.id)));
      body.push(Box({ key: "evwrap", marginTop: 1, children: [evidenceBlock(h, ctx, c.evidence)] }));
      return body;
    }
  }
  if (sel?.kind === "relationship") {
    const r = byId(model.relationships, sel.id);
    if (r) {
      const from = byId(model.components, r.from);
      const to = byId(model.components, r.to);
      body.push(head(MARK[r.confidence], r.confidence, `${from.name} → ${to.name}`));
      const cat = categoryInfo(r.category);
      body.push(Text({ key: "rk", wrap: "wrap", children: `${r.kind}${r.label ? `: ${r.label}` : ""}` }));
      body.push(drawn(ctx) ? Box({ key: "pic", children: [drawn(ctx).node] }) : pictureNote(h, ctx));
      if (categoryCounts(model).length > 1) body.push(Text({ key: "rcat", color: CATEGORY_COLOR[r.category], children: `Type: ${cat.label}` }));
      const via = r.via ? byId(model.components, r.via) : undefined;
      body.push(Box({ key: "rl", gap: 2, flexWrap: "wrap", children: [link(h, ctx, "lf", `Open ${from.name}`, "component", from.id), link(h, ctx, "lt", `Open ${to.name}`, "component", to.id), via ? link(h, ctx, "lv", `Open ${via.name} (via)`, "component", via.id) : null] }));
      body.push(impactLink(h, ctx, "imp", "relationship", r.id, "this relationship"));
      body.push(stepLinks(h, ctx, "ws", stepsUsing(model, r)));
      body.push(Box({ key: "evwrap", marginTop: 1, children: [evidenceBlock(h, ctx, r.evidence)] }));
      return body;
    }
  }
  body.push(Text({ key: "gone", dimColor: true, children: "Nothing selected." }));
  return body;
}

function impactLink(h, ctx, key, kind, id, what) {
  return h.Button({ key, label: cut(`Impact ▸ what may a change to ${what} affect?`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.openImpact(kind, id) });
}

const BASIS_NOTE = {
  carried: "the same interaction, carried over the selected link",
  routed: "goes through the same source to the same target, as another type",
  carrier: "carries the selected interaction",
  parallel: "another relationship between the same two components",
};
const FLIP = { "▶": "◀", "▷": "◁" };

function impactItem(e, tagged, rev) {
  const r = e.relationship;
  const [line, head] = r ? ARROWS[r.category] : ["┄┄", "▶"];
  const base = r ? `${r.label || r.kind}${e.role === "transport" ? ` (carries ${plural(e.carries.length, "interaction")})` : ""}` : "carries it; no link modeled";
  return {
    name: e.component.name,
    repo: e.component.repo,
    tag: r ? `${tagged ? `[${categoryInfo(r.category).tag}] ` : ""}${MARK[r.confidence]}` : "",
    line: !r || r.confidence !== "observed" ? "┄┄" : line,
    head: rev ? FLIP[head] : head,
    label: `${e.basis === "direct" ? "" : `${e.basis}: `}${base}`,
    flag: r && !r.evidence.length ? " !" : "",
    cross: e.crosses,
    rev,
  };
}

function impactRowList(h, ctx, prefix, entries, tagged, rev) {
  const { Box, Text, Button } = h;
  const layout = impactRows(entries.map((e) => impactItem(e, tagged, rev)), ctx.cols - 2, { repos: ctx.model.project.repositories.length > 0 });
  return entries.map((e, i) => {
    const r = e.relationship;
    const parts = layout[i];
    const dim = r && r.confidence !== "observed";
    return Box({
      key: `${prefix}${i}`,
      children: [
        Text({ key: "ld", color: "cyan", children: parts.lead }),
        Button({ key: `${prefix}${i}-n`, plain: true, onPress: () => ctx.actions.openImpact("component", e.component.id), children: [Text({ key: "t", bold: true, children: parts.name })] }),
        Text({ key: "sp", children: " " }),
        r
          ? Button({ key: `${prefix}${i}-r`, plain: true, onPress: () => ctx.actions.openImpact("relationship", r.id), children: [Text({ key: "t", color: CATEGORY_COLOR[r.category], dimColor: dim, children: parts.rel })] })
          : Text({ key: "r", dimColor: true, children: parts.rel }),
        parts.repo ? Text({ key: "rp", dimColor: true, children: ` ${parts.repo}` }) : null,
      ],
    });
  });
}

function impactSection(h, key, title, hint, rows) {
  const { Box, Text } = h;
  return Box({ key, flexDirection: "column", marginTop: 1, children: [heading(h, `${key}-h`, title), hint ? Text({ key: `${key}-n`, dimColor: true, wrap: "wrap", children: hint }) : null, ...rows] });
}

function modeStrip(h, ctx) {
  const { Box, Button } = h;
  const tab = (key, label, on, press) => Button({ key, label: `${on ? "▸ " : ""}${label}`, plain: true, onPress: press });
  return Box({
    key: "imode",
    gap: 2,
    flexWrap: "wrap",
    children: [
      tab("im-sel", "Selected element", ctx.impactMode !== "changes" && ctx.impactMode !== "review", () => ctx.actions.setImpactMode("selection")),
      tab("im-chg", "Local git changes", ctx.impactMode === "changes", () => ctx.actions.setImpactMode("changes")),
      tab("im-rev", "Plan review", ctx.impactMode === "review", () => ctx.actions.setImpactMode("review")),
    ],
  });
}

function reachButtons(h, ctx) {
  const depth = (n, label) => h.Button({ key: `d${n}`, label: `${ctx.impactDepth === n ? "▸ " : ""}${label}`, plain: true, onPress: () => ctx.actions.setImpactDepth(n) });
  return h.Box({ key: "reach", gap: 2, flexWrap: "wrap", children: [depth(1, "direct only"), depth(2, "2 hops"), depth(3, "3 hops")] });
}

function impactPicker(h, ctx) {
  const { Box, Text, Button, Input } = h;
  const { model } = ctx;
  const query = (ctx.pickQuery ?? "").trim();
  const kind = ctx.pickKind ?? "all";
  const tagged = categoryCounts(model).length > 1;
  const degree = (id) => model.relationships.filter((r) => r.from === id || r.to === id).length;
  const kinds = [["all", "Everything", model.components.length + model.relationships.length], ["component", "Components", model.components.length], ["relationship", "Relationships", model.relationships.length]];
  const rows = [
    Text({ key: "ipick", wrap: "wrap", children: "Find a component or relationship to see what the model says depends on it, and what it depends on." }),
    Input({
      key: "iq",
      label: "Find",
      placeholder: "name, repository, type or label",
      value: ctx.pickQuery ?? "",
      submitLabel: "open first",
      autoFocus: true,
      onInput: (value) => ctx.actions.setPickQuery(value),
      onSubmit: (value) => ctx.actions.submitPick(value),
    }),
  ];
  const strip = Box({ key: "ikinds", gap: 2, flexWrap: "wrap", marginTop: 1, children: kinds.map(([id, label, n]) => Button({ key: `ik-${id}`, label: `${kind === id ? "▸ " : ""}${label} ${n}`, plain: true, onPress: () => ctx.actions.setPickKind(id) })) });
  if (!query && kind === "all") {
    const busiest = [...model.components].sort((a, b) => degree(b.id) - degree(a.id)).filter((c) => degree(c.id) > 0).slice(0, PICK_ROWS);
    rows.push(Text({ key: "ihint", dimColor: true, wrap: "wrap", children: "Type to filter; Enter opens the first match. Esc clears what you typed; Esc again closes the pane. Letters type here; Tab leaves the field for shortcuts." }));
    if (busiest.length) rows.push(Box({ key: "ibusy", flexDirection: "column", marginTop: 1, children: [heading(h, "ibh", "Most connected components"), ...busiest.map((c) => Button({ key: `ib-${c.id}`, label: cut(`${c.name} · ${plural(degree(c.id), "relationship")}`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.openImpact("component", c.id) }))] }));
    rows.push(strip);
    return rows;
  }
  const found = searchElements(model, query, kind);
  const buttons = found.slice(0, PICK_ROWS).map((x, i) => {
    const tag = x.kind === "relationship" && tagged ? `[${categoryInfo(x.category).tag}] ` : "";
    const label = x.kind === "component" ? `Component    ${x.label}${x.detail ? ` · ${x.detail}` : ""}` : `Relationship ${tag}${x.label} · ${x.detail}`;
    return Button({ key: `ip-${i}`, label: cut(`${i === 0 ? "↵ " : "  "}${label}`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.openImpact(x.kind, x.id) });
  });
  if (found.length > PICK_ROWS) buttons.push(Text({ key: "ipmore", dimColor: true, children: `… ${found.length - PICK_ROWS} more; keep typing to narrow` }));
  if (!found.length) buttons.push(Text({ key: "ipnone", dimColor: true, wrap: "wrap", children: `Nothing matches “${query}”${kind === "all" ? "" : ` among ${kind}s`}. Every word must appear in a name, repository, type or label.` }));
  rows.push(Box({ key: "ires", flexDirection: "column", marginTop: 1, children: [heading(h, "iph", `Matches (${found.length}) · Enter opens the first`), ...buttons] }));
  rows.push(strip);
  return rows;
}

function impactView(h, ctx) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const counts = categoryCounts(model);
  const tagged = counts.length > 1;
  const out = [];
  if (ctx.canBack) out.push(Button({ key: "back", label: "◀ Back", hotkey: "b", plain: true, onPress: ctx.actions.back }));
  out.push(modeStrip(h, ctx));
  if (ctx.impactMode === "changes") return [...out, ...changesView(h, ctx, counts)];
  if (ctx.impactMode === "review") return [...out, ...reviewView(h, ctx, { COLOR, MARK, cut, plural, link, reachButtons })];

  const sel = ctx.selection;
  const categories = tagged ? (ctx.categories ?? []) : [];
  const impact = sel && (sel.kind === "component" || sel.kind === "relationship") ? impactOf(model, sel, { categories, depth: ctx.impactDepth }) : undefined;
  if (!impact) return [...out, ...impactPicker(h, ctx)];

  const t = impact.target;
  if (impact.kind === "component") {
    out.push(Text({ key: "ihead", bold: true, color: COLOR[t.confidence], wrap: "wrap", children: `${MARK[t.confidence]} Impact of ${t.name} (${t.kind})${t.repo ? ` · ${t.repo}` : ""}` }));
  } else {
    const [a, b] = impact.anchor;
    out.push(Text({ key: "ihead", bold: true, color: COLOR[t.confidence], wrap: "wrap", children: `${MARK[t.confidence]} Impact of ${a.name} → ${b.name}: ${t.label || t.kind}${tagged ? ` · ${categoryInfo(t.category).label}` : ""}` }));
  }
  out.push(Box({ key: "idepth", gap: 2, flexWrap: "wrap", children: [Text({ key: "dl", dimColor: true, children: "Reach:" }), reachButtons(h, ctx)] }));
  if (tagged) out.push(categoryStrip(h, ctx, counts));

  const c = impact.counts;
  out.push(Text({ key: "isum", dimColor: true, wrap: "wrap", children: `Used by ${c.consumers} · depends on ${c.providers}${c.transports ? ` · ${plural(c.transports, "transport link")} listed once, not counted` : ""}${c.crossing ? ` · ${c.crossing} cross repository (⇄)` : ""} · ${plural(c.steps, "workflow step")}` }));
  if (drawn(ctx)) out.push(Box({ key: "pic", children: [drawn(ctx).node] }), smallNote(h, ctx, "Drawn small. A shorter reach (1 or 2) draws fewer components larger."));
  else out.push(Text({ key: "ilegend", dimColor: true, wrap: "wrap", children: "Established = a relationship the model declares. Possible = reachable through those relationships; Sidecar has not confirmed that a change would propagate." }), pictureNote(h, ctx));
  for (const [i, note] of impact.notes.entries()) out.push(Text({ key: `inote${i}`, color: "yellow", wrap: "wrap", children: `! ${note}` }));

  const basisHint = (entries) => [...new Set(entries.map((e) => e.basis))].filter((b) => BASIS_NOTE[b]).map((b) => `${b}: ${BASIS_NOTE[b]}`).join(" · ") || undefined;
  const sides = [
    ["iused", "Used by (consumers) — established", impact.consumers, false],
    ["idep", "Depends on — established", impact.providers, true],
    ["ialong", "Alongside — other relationships between the same components", impact.alongside, true],
  ];
  for (const [key, title, entries, rev] of sides) {
    if (!entries.length) {
      if (key !== "ialong") out.push(impactSection(h, key, title, undefined, [Text({ key: `${key}-none`, dimColor: true, children: "None modeled." })]));
      continue;
    }
    out.push(impactSection(h, key, title, basisHint(entries), impactRowList(h, ctx, `${key}-`, entries, tagged, rev)));
  }

  if (ctx.impactDepth > 1) {
    const rows = impact.downstream.slice(0, 12).map((d, i) => {
      const path = [d.chain[0].from, ...d.chain.map((r) => r.to)].map((id) => byId(model.components, id).name).join(" → ");
      const caveats = `${d.confidence !== "observed" ? ` · weakest link ${d.confidence}` : ""}${d.uncited ? " · a link cites no file" : ""}`;
      return Button({ key: `dn${i}`, label: cut(`${d.crosses ? "⇄ " : "  "}${d.component.name} · ${d.hop} hops: ${path}${caveats}`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.openImpact("component", d.component.id) });
    });
    if (impact.downstream.length > 12) rows.push(Text({ key: "dn-more", dimColor: true, children: `… and ${impact.downstream.length - 12} more` }));
    out.push(
      impactSection(h, "idown", `Possible further effects (${impact.downstream.length}) — not confirmed`, "Consumers of consumers, shortest path only. Reachable in the model does not mean a change reaches them.", rows.length ? rows : [Text({ key: "dn-none", dimColor: true, children: `Nothing further within ${ctx.impactDepth} hops.` })]),
    );
  } else {
    out.push(Text({ key: "idownhint", dimColor: true, wrap: "wrap", children: "Choose 2 or 3 hops to see what depends on those consumers (possible effects, not confirmed)." }));
  }

  const flowRows = [];
  for (const g of impact.flows) {
    flowRows.push(Text({ key: `fg-${g.flow.id}`, bold: true, wrap: "truncate-end", children: g.flow.name }));
    for (const it of g.items.slice(0, 6)) {
      const step = it.step;
      flowRows.push(link(h, ctx, `fs-${g.flow.id}-${step.n}`, `${MARK[step.confidence]} step ${step.n}: ${step.action}${it.basis === "direct" ? "" : ` [${it.basis}]`}`, "step", `${g.flow.id}#${step.n}`));
      if (step.stateChange) flowRows.push(Text({ key: `fc-${g.flow.id}-${step.n}`, color: step.stateChange.verified ? "green" : "yellow", wrap: "truncate-end", children: `    ↳ ${step.stateChange.store}: ${step.stateChange.description}${step.stateChange.verified ? "" : " (unverified)"}` }));
    }
    if (g.items.length > 6) flowRows.push(Text({ key: `fm-${g.flow.id}`, dimColor: true, children: `  … and ${g.items.length - 6} more steps in this workflow` }));
  }
  out.push(impactSection(h, "iflows", `Related workflows (${plural(c.steps, "step")})`, undefined, flowRows.length ? flowRows : [Text({ key: "nof", dimColor: true, children: "No modeled workflow step uses this." })]));

  if (impact.unknowns.length) out.push(impactSection(h, "iunk", "Open questions", undefined, impact.unknowns.map((u, i) => Text({ key: `iu${i}`, color: "red", wrap: "wrap", children: `○ ${u.text} (${u.where})` }))));
  out.push(Box({ key: "iev", marginTop: 1, children: [evidenceBlock(h, ctx, selectionEvidence(model, sel))] }));
  return out;
}

function changesView(h, ctx, counts) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const out = [];
  const tagged = counts.length > 1;
  out.push(Text({ key: "chintro", dimColor: true, wrap: "wrap", children: "Compares local git changes with the files the model cites. Runs git only when you press Scan; nothing is watched or refreshed in the background." }));
  out.push(
    Box({
      key: "chref",
      gap: 2,
      flexWrap: "wrap",
      children: [
        ...Object.entries(DIFF_REFS).map(([id, ref]) => Button({ key: `cr-${id}`, label: `${ctx.diffRef === id ? "▸ " : ""}${ref.label}`, plain: true, onPress: () => ctx.actions.setDiffRef(id) })),
        Button({ key: "scan", label: ctx.changes ? "Scan again" : "Scan now", hotkey: "s", variant: "primary", onPress: ctx.actions.scanChanges }),
      ],
    }),
  );
  const ch = ctx.changes;
  if (!ch) return [...out, Text({ key: "chnone", dimColor: true, children: "Not scanned yet." })];
  if (ch.scanning) return [...out, Text({ key: "chbusy", color: "cyan", children: "Scanning…" })];

  for (const [i, s] of ch.scans.entries()) {
    const label = s.id ? `${s.id}: ` : "";
    if (s.status === "ok") out.push(Text({ key: `cs${i}`, color: s.note ? "yellow" : "green", wrap: "wrap", children: `● ${label}${plural(s.files.length, "changed file")}${s.note ? ` · ${s.note}` : ""}` }));
    else out.push(Text({ key: `cs${i}`, color: s.status === "skipped" ? "yellow" : "red", wrap: "wrap", children: `${s.status === "skipped" ? "○" : "✗"} ${label}${s.message}` }));
  }
  const unscanned = ch.scans.filter((s) => s.status !== "ok").length;
  if (unscanned) out.push(Text({ key: "chpartial", color: "yellow", wrap: "wrap", children: `! ${plural(unscanned, "repository")} could not be scanned, so changes there are missing from the lists below.` }));
  const scanned = ch.scans.flatMap((s) => s.files.map((f) => ({ ...f, repo: s.id, basis: s.basis })));
  if (!scanned.length) return [...out, Text({ key: "chclean", dimColor: true, children: ch.scans.some((s) => s.status !== "ok") ? "No changes found in the repositories that could be scanned." : "No changes found for this comparison." })];

  const lenses = { data: ctx.status.data?.kind === "ready" ? ctx.status.data.data : undefined, auth: ctx.status.auth?.kind === "ready" ? ctx.status.auth.auth : undefined };
  const lensed = Boolean(lenses.data || lenses.auth);
  const everything = matchAll(model, lenses, scanned);
  const files = ctx.changeFile && scanned.some((f) => fileKey(f) === ctx.changeFile) ? scanned.filter((f) => fileKey(f) === ctx.changeFile) : scanned;
  const all = files.length === scanned.length ? everything : matchAll(model, lenses, files);
  const match = all.model;
  if (lensed) out.push(...documentStatus(h, ctx, { plural }));
  out.push(fileStrip(h, ctx, { cut, plural }, scanned, directByFile(everything)));
  const down = downstreamOfChanges(model, match, tagged ? (ctx.categories ?? []) : []);
  const where = (el) => {
    const hit = el.hits.find((x) => x.level === el.level) ?? el.hits[0];
    const ev = hit.evidence;
    const why = hit.reason && (hit.level === "unclear" || hit.reason === "deleted" || hit.reason === "nolines") ? (hit.reason === "renamed" ? `renamed to ${hit.change.path}` : (REASONS[hit.reason] ?? "file deleted")) : "";
    return { at: `${ev.repo ? `[${ev.repo}] ` : ""}${ev.path}${ev.lines ? `:${ev.lines[0]}-${ev.lines[1]}` : ""}${el.hits.length > 1 ? ` (+${el.hits.length - 1} more)` : ""}`, why };
  };
  const GROUPS = [
    ["lines", "overlap", "Overlapping cited lines — a changed line falls inside lines the model cites"],
    ["file", "same file", "Same file, outside the cited lines (or none cited)"],
    ["unclear", "unclear", "Line numbers cannot be compared — only the file is known to match"],
  ];
  const matched = [];
  for (const [level, word, title] of GROUPS) {
    const group = match.elements.filter((el) => el.level === level);
    const lensGroup = all.lens.filter((el) => el.level === level);
    if (!group.length && !lensGroup.length) continue;
    matched.push(Text({ key: `cmh-${level}`, bold: true, wrap: "wrap", children: `${title} (${group.length + lensGroup.length})` }));
    for (const [i, el] of group.slice(0, level === "lines" ? 15 : 8).entries()) {
      const { at, why } = where(el);
      matched.push(
        Button({
          key: `cm-${level}-${i}`,
          label: cut(`${word.padEnd(9)} ${el.kind} ${el.label} — ${at}`, ctx.cols - 4),
          plain: true,
          onPress: () => (el.kind === "step" ? ctx.actions.select("step", el.id) : ctx.actions.openImpact(el.kind, el.id)),
        }),
      );
      if (why) matched.push(Box({ key: `cmw-${level}-${i}`, marginLeft: 10, children: [Text({ key: `cmwt-${level}-${i}`, dimColor: true, wrap: "wrap", children: why })] }));
    }
    if (group.length > (level === "lines" ? 15 : 8)) matched.push(Text({ key: `cm-more-${level}`, dimColor: true, children: `… and ${group.length - (level === "lines" ? 15 : 8)} more` }));
    matched.push(...lensMatchRows(h, ctx, { cut, plural, MARK, COLOR }, lenses, level, lensGroup));
  }
  out.push(
    impactSection(h, "cmatch", `Changes matching modeled evidence (${match.elements.length + all.lens.length})`, "A match means the model cites the file, not that the change breaks anything. Cited lines are compared with the committed version the model describes; overlap is positional, not semantic.", matched.length ? matched : [Text({ key: "cm-none", dimColor: true, children: "No modeled element cites a changed file." })]),
  );
  const untraced = untracedSteps(model, match);
  if (untraced.length) out.push(Text({ key: "cm-untraced", dimColor: true, wrap: "wrap", children: `${plural(untraced.length, "matched step")} name${untraced.length === 1 ? "s" : ""} no single relationship (local, ambiguous or a response leg), so nothing is traced downstream from ${untraced.length === 1 ? "it" : "them"}.` }));

  const u = { cut, plural, MARK, COLOR };
  const seeds = [...match.elements.filter((e) => e.kind === "step" && e.level === "lines"), ...all.lens.filter((e) => e.level === "lines")];
  if (lensed && seeds.length) {
    const reach = reachFrom(model, lenses, seeds);
    out.push(...reachSection(h, ctx, u, reach, seeds.length));
    out.push(...openSection(h, ctx, u, openAbout(model, lenses, seeds, reach)));
  }

  const downRows = down.slice(0, 12).map((d, i) => Button({ key: `cd${i}`, label: cut(`${d.component.name} — consumes ${d.because.join(", ")}`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.openImpact("component", d.component.id) }));
  if (down.length > 12) downRows.push(Text({ key: "cd-more", dimColor: true, children: `… and ${down.length - 12} more` }));
  out.push(impactSection(h, "cdown", `Possible downstream effects (${down.length}) — not confirmed`, "Consumers, in the model, of the matched components, relationships and steps (through the one relationship a step declares) whose own cited files did not change.", downRows.length ? downRows : [Text({ key: "cd-none", dimColor: true, children: "None modeled." })]));

  const cov = ctx.status.coverage?.kind === "ready" ? ctx.status.coverage.coverage : null;
  const un = all.unmapped.slice(0, 12).flatMap((f, i) => [
    Text({ key: `cu${i}`, dimColor: true, wrap: "truncate-end", children: `  ${f.repo ? `[${f.repo}] ` : ""}${f.path} (${f.untracked ? "untracked" : f.status})` }),
    ...(cov ? itemsCiting(cov, f.repo, f.path).map((x, j) => Text({ key: `cu${i}-cov${j}`, wrap: "wrap", color: x.status === "modeled" ? undefined : "yellow", children: `    coverage: ${x.name} (${STATUS_TEXT[x.status]})` })) : []),
  ]);
  if (all.unmapped.length > 12) un.push(Text({ key: "cu-more", dimColor: true, children: `  … and ${all.unmapped.length - 12} more` }));
  out.push(impactSection(h, "cunmapped", `Changed files the model does not cover (${all.unmapped.length})`, `No component, relationship or step${lensed ? ", data element or authorization element" : ""} cites these, so Sidecar cannot say what they affect. A moved file shows here as a deletion and an addition unless git pairs them.${all.lensOnly.length ? ` ${plural(all.lensOnly.length, "changed file")} cited only by a data or authorization document ${all.lensOnly.length === 1 ? "is" : "are"} not listed here.` : ""}`, un.length ? un : [Text({ key: "cu-none", dimColor: true, children: "Every changed file is cited by something in the model." })]));
  const beside = cov ? itemsBesideChanges(cov, files, all.unmapped) : [];
  if (beside.length) {
    const rows = beside.slice(0, 8).map(({ item, files: fs }, i) => Text({ key: `cb${i}`, wrap: "wrap", color: "yellow", children: `  ${item.name} (${STATUS_TEXT[item.status]}) — ${fs.map((f) => `${f.repo ? `[${f.repo}] ` : ""}${f.path}`).join(", ")}` }));
    if (beside.length > 8) rows.push(Text({ key: "cb-more", dimColor: true, children: `  … and ${beside.length - 8} more` }));
    out.push(impactSection(h, "cbeside", `Not fully modeled paths that cite a changed file (${beside.length})`, "The coverage inventory records these in a file that changed and that the model covers. Matched by path only: the change may not touch them, and nothing here says it does.", rows));
  }
  if (lensed) out.push(...coverageSection(h, ctx, u, { seeds: seeds.length, all, files }));
  return out;
}

function mermaidView(h, ctx) {
  const { Text, Code } = h;
  const { model } = ctx;
  const out = [Text({ key: "mh", dimColor: true, wrap: "wrap", children: "Mermaid source for the current model. Paste into any Mermaid renderer; the pane itself cannot render it." })];
  out.push(heading(h, "mo", "Overview"));
  out.push(Code({ key: "mo-code", source: overviewToMermaid(model, ctx.categories ?? []), wrap: "truncate-end" }));
  for (const f of model.flows) {
    out.push(heading(h, `mf-${f.id}`, `Flow: ${f.name}`));
    out.push(Code({ key: `mf-code-${f.id}`, source: flowToMermaid(model, f), wrap: "truncate-end" }));
  }
  return out;
}

function emptyView(h, ctx) {
  const { Text, Button } = h;
  const { status } = ctx;
  const out = [];
  if (status.kind === "loading") {
    out.push(Text({ key: "l", dimColor: true, children: "Loading architecture model…" }));
    return out;
  }
  out.push(Text({ key: "t", bold: true, color: status.kind === "invalid" ? "red" : "yellow", children: status.kind === "invalid" ? "The architecture model could not be used." : "No architecture model found for this project." }));
  if (status.message) out.push(Text({ key: "m", wrap: "wrap", children: status.message }));
  for (const [i, e] of (status.errors ?? []).entries()) out.push(Text({ key: `e${i}`, color: "red", wrap: "wrap", children: `• ${e}` }));
  out.push(Text({ key: "w", bold: true, children: "\nLooked in:" }));
  for (const [i, p] of (status.searched ?? []).entries()) out.push(Text({ key: `p${i}`, dimColor: true, wrap: "truncate-end", children: `  ${p}` }));
  out.push(Text({ key: "how", wrap: "wrap", children: "\nPress g to ask Claude to read this repository and write .architecture/model.json from what it finds, or add the file yourself (schemaVersion 1; see the plugin README)." }));
  out.push(Button({ key: "build-hint", label: "Build model with Claude", plain: true, onPress: () => ctx.actions.build() }));
  return out;
}

export function buildPane(drawing, ctx) {
  const seen = newSeen();
  const h = recording(drawing, seen);
  const { Box, Text } = h;
  const ready = ctx.status.kind === "ready";
  const head = [];
  const tail = [];
  if (ready) {
    const p = ctx.model.project;
    head.push(Text({ key: "proj", wrap: "truncate-end", children: [Text({ key: "pn", bold: true, children: p.name }), Text({ key: "ps", dimColor: true, children: p.summary ? `  ${p.summary}` : "" })] }));
    head.push(nav(h, ctx));
    if (ctx.notice) tail.push(Text({ key: "notice", color: "cyan", wrap: "wrap", children: ctx.notice }));
    if (ctx.hint) tail.push(Text({ key: "hint", dimColor: true, wrap: "wrap", children: ctx.hint }));
    const problems = (ctx.status.repos ?? []).filter((r) => r.state !== "ok");
    if (problems.length) tail.push(Text({ key: "repoprob", color: "yellow", wrap: "wrap", children: `! ${problems.map((r) => `${r.id}: ${r.state}`).join(" · ")} (see Overview › Repositories)` }));
    const view = { inspect: inspectView, flow: flowView, impact: impactView, behavior: (hh, c) => behaviorView(hh, c, { COLOR, MARK, cut, plural }), explore: (hh, c) => exploreView(hh, c, { COLOR, MARK, cut, plural, sequence: exploreSequence }), data: (hh, c) => dataView(hh, c, { COLOR, MARK, cut, plural }), auth: (hh, c) => authView(hh, c, { COLOR, MARK, cut, plural }), mermaid: mermaidView }[ctx.view] ?? overviewView;
    tail.push(Box({ key: "body", flexDirection: "column", marginTop: 1, children: view(h, ctx) }));
    if (ctx.status.warnings?.length && ctx.view !== "overview") {
      tail.push(Text({ key: "warn", dimColor: true, wrap: "truncate-end", children: `${ctx.status.warnings.length} model warning(s); first: ${ctx.status.warnings[0]}` }));
    }
  } else {
    head.push(Text({ key: "proj", bold: true, children: `Architecture · ${ctx.cwdName}` }));
    head.push(nav(h, ctx));
    if (ctx.notice) tail.push(Text({ key: "notice", color: "cyan", wrap: "wrap", children: ctx.notice }));
    tail.push(Box({ key: "body", flexDirection: "column", marginTop: 1, children: emptyView(h, ctx) }));
  }
  return Box({ flexDirection: "column", paddingX: 1, children: [...head, ...(ctx.legendOpen ? [shortcutLegend(h, ctx, seen)] : []), ...tail] });
}

