import { byId, resolveStepRelationship } from "./model.mjs";

const RANK = { observed: 2, inferred: 1, unknown: 0 };
export const weakest = (confidences) => confidences.reduce((w, c) => (RANK[c] < RANK[w] ? c : w), "observed");

/** Interactions a link carries: relationships that go `via` its source to its target in the same category. */
export const carriedBy = (model, rel) => model.relationships.filter((l) => l.via === rel.from && l.to === rel.to && l.category === rel.category && l.id !== rel.id);

const stepsOf = (model, relIds) => {
  const out = [];
  for (const flow of model.flows) for (const step of flow.steps) {
    const rel = resolveStepRelationship(model, step).relationship;
    if (rel && relIds.has(rel.id)) out.push({ flow, step, relationship: rel });
  }
  return out;
};

/** Components and relationships whose name, id, kind, repository, endpoints or label contain every word of `query`, best matches first. `kind` is "all", "component" or "relationship". */
export function searchElements(model, query, kind = "all") {
  const words = String(query ?? "").toLowerCase().split(/\s+/).filter(Boolean);
  const name = (id) => byId(model.components, id)?.name ?? id;
  const rank = (text, fields) => {
    const lower = text.toLowerCase();
    if (words.every((w) => fields.some((f) => f.toLowerCase().includes(w)))) {
      const phrase = words.join(" ");
      return lower === phrase ? 0 : lower.startsWith(phrase) ? 1 : lower.includes(phrase) ? 2 : 3;
    }
    return -1;
  };
  const out = [];
  if (kind !== "relationship") {
    for (const c of model.components) {
      const score = rank(c.name, [c.name, c.id, c.kind, c.repo ?? ""]);
      if (score >= 0) out.push({ kind: "component", id: c.id, label: c.name, detail: [c.kind, c.repo].filter(Boolean).join(" · "), score });
    }
  }
  if (kind !== "component") {
    for (const r of model.relationships) {
      const label = `${name(r.from)} → ${name(r.to)}`;
      const score = rank(label, [label, r.id, r.kind, r.label ?? "", r.category, r.via ? name(r.via) : ""]);
      if (score >= 0) out.push({ kind: "relationship", id: r.id, label, detail: r.label || r.kind, category: r.category, score: score + 4 });
    }
  }
  return out.map((x, i) => ({ ...x, i })).sort((a, b) => a.score - b.score || a.i - b.i).map(({ i, score, ...x }) => x);
}

const mentions = (text, ...needles) => needles.some((n) => n && text.toLowerCase().includes(n.toLowerCase()));

/**
 * What the model says a change to a component or relationship may touch, from its declared relationships only.
 * `consumers` depend on the selection, `providers` are what it depends on; `basis` tells why an entry is listed:
 * direct (a declared endpoint), carried (same interaction over a transport link), routed (goes through the same
 * source to the same target) or carrier (what carries the selection). A transport link that carries logical
 * interactions is listed once as role "transport" and is not counted as a separate interaction.
 * `downstream` are consumers of consumers (up to `depth` hops, shortest path only): possible effects, never confirmed.
 * `categories` limits every list to those relationship categories.
 */
export function impactOf(model, sel, { categories = [], depth = 1 } = {}) {
  const keep = (r) => !categories.length || categories.includes(r.category);
  const comp = (id) => byId(model.components, id);
  const multiRepo = model.project.repositories.length > 0;
  const usage = new Map();
  for (const { relationship } of stepsOf(model, new Set(model.relationships.map((r) => r.id)))) usage.set(relationship.id, (usage.get(relationship.id) ?? 0) + 1);

  const target = sel?.kind === "component" ? comp(sel.id) : sel?.kind === "relationship" ? byId(model.relationships, sel.id) : undefined;
  if (!target) return undefined;
  const isRel = sel.kind === "relationship";
  const anchor = isRel ? [comp(target.from), comp(target.to)] : [target];
  const repos = [...new Set(anchor.map((c) => c.repo).filter(Boolean))];

  const crossesRepo = (r) => Boolean(comp(r.from).repo && comp(r.to).repo && comp(r.from).repo !== comp(r.to).repo);
  const entry = (relationship, component, basis, side) => ({
    relationship,
    component,
    side,
    basis,
    role: relationship && carriedBy(model, relationship).length ? "transport" : "link",
    carries: relationship ? carriedBy(model, relationship).map((l) => l.id) : [],
    carrier: relationship?.via ? comp(relationship.via) : undefined,
    crosses: Boolean(relationship) && crossesRepo(relationship),
    outside: multiRepo && !component.repo,
    steps: relationship ? (usage.get(relationship.id) ?? 0) : 0,
  });

  const consumers = [];
  const providers = [];
  const alongside = [];
  if (!isRel) {
    for (const r of model.relationships.filter((x) => x.to === target.id && keep(x))) consumers.push(entry(r, comp(r.from), "direct", "consumer"));
    for (const r of model.relationships.filter((x) => x.from === target.id && keep(x))) providers.push(entry(r, comp(r.to), "direct", "provider"));
  } else {
    consumers.push(entry(target, comp(target.from), "direct", "consumer"));
    providers.push(entry(target, comp(target.to), "direct", "provider"));
    for (const l of carriedBy(model, target)) consumers.push(entry(l, comp(l.from), "carried", "consumer"));
    for (const l of model.relationships.filter((x) => x.via === target.from && x.to === target.to && x.category !== target.category && keep(x))) consumers.push(entry(l, comp(l.from), "routed", "consumer"));
    if (target.via) {
      const carriers = model.relationships.filter((x) => x.from === target.via && x.to === target.to && x.category === target.category);
      if (carriers.length) for (const x of carriers) providers.push(entry(x, comp(target.via), "carrier", "provider"));
