  for (let hop = 2; hop <= depth; hop++) {
    const next = [];
    for (const node of frontier) {
      for (const r of model.relationships.filter((x) => x.to === node.component.id && keep(x) && !carriedBy(model, x).length)) {
        if (direct.has(r.from)) continue;
        direct.add(r.from);
        const chain = [r, ...node.chain];
        const item = { component: comp(r.from), chain, hop, confidence: weakest(chain.map((c) => c.confidence)), crosses: chain.some(crossesRepo), uncited: chain.some((c) => c.evidence.length === 0) };
        downstream.push(item);
        next.push({ component: item.component, chain });
      }
    }
    frontier = next;
  }

  const relIds = new Set(isRel ? [target.id, ...consumers.filter((e) => e.basis !== "direct").map((e) => e.relationship.id)] : []);
  const basisOf = new Map(consumers.filter((e) => e.relationship).map((e) => [e.relationship.id, e.basis]));
  const affected = [];
  if (isRel) {
    for (const hit of stepsOf(model, relIds)) affected.push({ ...hit, basis: hit.relationship.id === target.id ? "direct" : (basisOf.get(hit.relationship.id) ?? "direct") });
  } else {
    for (const flow of model.flows) for (const step of flow.steps) {
      if (step.from !== target.id && step.to !== target.id) continue;
      const relationship = resolveStepRelationship(model, step).relationship;
      if (categories.length && relationship && !keep(relationship)) continue;
      affected.push({ flow, step, relationship, basis: "direct" });
    }
  }
  const flows = [];
  for (const hit of affected) {
    let group = flows.find((g) => g.flow.id === hit.flow.id);
    if (!group) flows.push((group = { flow: hit.flow, items: [] }));
    group.items.push(hit);
  }

  const names = isRel ? [comp(target.from).name, comp(target.to).name] : [target.name];
  const unknowns = [];
  for (const g of flows) for (const u of g.flow.unknowns) if (u.step && g.items.some((i) => i.step.n === u.step)) unknowns.push({ text: u.text, where: `${g.flow.name}, step ${u.step}` });
  for (const text of model.unknowns) if (mentions(text, ...anchor.map((c) => c.id), ...names)) unknowns.push({ text, where: "model-wide" });

  const all = [...new Map([...consumers, ...providers].filter((e) => e.relationship).map((e) => [e.relationship.id, e])).values()];
  const notes = [];
  if (!consumers.length && !providers.length) notes.push(`No relationships are modeled for ${names.join(" / ")}. That says what the model knows, not that nothing depends on it.`);
  else if (!isRel && !consumers.length) notes.push(`The model records nothing that depends on ${target.name}.`);
  const weak = all.filter((e) => e.relationship.confidence !== "observed").length;
  if (weak) notes.push(`${weak} of ${all.length} links are inferred or unknown, so their reach is uncertain.`);
  const uncited = all.filter((e) => e.relationship.evidence.length === 0).length;
  if (uncited) notes.push(`${uncited} link${uncited === 1 ? " cites" : "s cite"} no file.`);
  const outside = [...consumers, ...providers].filter((e) => e.outside);
  if (outside.length) notes.push(`${[...new Set(outside.map((e) => e.component.name))].join(", ")} sit outside the modeled repositories; what a change does there is not analyzed.`);

  return {
    kind: sel.kind,
    target,
    anchor,
    repos,
    consumers,
    providers,
    alongside,
    downstream,
    flows,
    unknowns,
    notes,
    counts: {
      consumers: consumers.filter((e) => e.role !== "transport").length,
      providers: providers.filter((e) => e.role !== "transport").length,
      transports: all.filter((e) => e.role === "transport").length,
      crossing: all.filter((e) => e.crosses).length,
      steps: affected.length,
    },
  };
}

