import { byId, resolveStepRelationship, stepsTouching, stepsUsing } from "./model.mjs";
import { impactOf, weakest } from "./impact.mjs";
import { textLines } from "./lens.mjs";

export const REVIEW_VERSION = 1;
export const REVIEW_FILE = ".architecture/review.json";

const MODEL_KINDS = ["component", "relationship", "step"];
const PROPOSED_KINDS = ["proposed-component", "proposed-relationship"];
const BASES = ["stated", "inferred"];
const QUESTION_TYPES = ["decision", "omission", "assumption"];
const ACTIONS = ["create", "modify"];
const MIN_QUOTE = 10;

/** A short change detector for text provenance (not a security hash); line endings are normalized. */
export function fingerprint(text) {
  const s = String(text).replace(/\r\n/g, "\n");
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < s.length; i++) {
    const ch = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return `fp1:${(h2 >>> 0).toString(16).padStart(8, "0")}${(h1 >>> 0).toString(16).padStart(8, "0")}`;
}

/** The revisions a model records: `{ "": rev }` for a single repository, `{ id: rev }` for several. */
export const modelRevisions = (model) =>
  model.project.repositories.length ? Object.fromEntries(model.project.repositories.map((r) => [r.id, r.revision])) : { "": model.project.revision };

const asString = (v, max) => {
  const s = typeof v === "string" ? v.trim() : "";
  return max && s.length > max ? `${s.slice(0, max - 1)}…` : s;
};
const unsafePath = (p) => !p || p.startsWith("/") || p.split("/").includes("..");
const issue = (level, where, message) => ({ level, where, message });

const FIELDS = {
  review: ["schemaVersion", "title", "summary", "generatedBy", "plan", "model", "intents", "plannedFiles", "proposed", "nonGoals", "questions"],
  intent: ["id", "statement", "cite", "touches"],
  touch: ["ref", "basis", "why"],
  file: ["path", "repo", "action", "cite"],
  proposedComponent: ["id", "name", "kind", "responsibility", "within", "cite"],
  proposedRelationship: ["id", "from", "to", "kind", "label", "cite"],
  nonGoal: ["id", "statement", "cite", "constrains"],
  question: ["id", "origin", "type", "text", "refs", "cite", "evidence"],
};

function unknownFields(raw, kind, where, issues) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return;
  for (const key of Object.keys(raw)) if (!FIELDS[kind].includes(key)) issues.push(issue("warning", where, `field "${key}" is not part of the review format and was ignored`));
}

function normCite(raw, where, issues, required) {
  if (raw === undefined || raw === null) {
    if (required) issues.push(issue("error", where, "has no plan citation (lines and a verbatim quote)"));
    return undefined;
  }
  const first = Array.isArray(raw.lines) ? raw.lines[0] : undefined;
  const last = Array.isArray(raw.lines) ? raw.lines[1] : undefined;
  const quote = asString(raw.quote, 240);
  if (!Number.isInteger(first) || first < 1 || !quote) {
    issues.push(issue("error", where, "plan citation needs lines [first, last] and a verbatim quote"));
    return undefined;
  }
  return { lines: [first, Number.isInteger(last) && last >= first ? last : first], quote };
}

function normRef(raw, where, issues, kinds) {
  const kind = asString(raw?.kind);
  const id = asString(raw?.id);
  if (!kinds.includes(kind) || !id) {
    issues.push(issue("error", where, `reference needs a kind (${kinds.join(", ")}) and an id`));
    return undefined;
  }
  return { kind, id, label: asString(raw.label, 120) || undefined };
}

const list = (v) => (Array.isArray(v) ? v : []);

function normSource(raw, where, issues) {
  const path = asString(raw?.path);
  if (unsafePath(path)) {
    issues.push(issue("error", where, "source evidence needs a project-relative path (no leading / and no ..)"));
    return undefined;
  }
  const first = Array.isArray(raw.lines) ? raw.lines[0] : undefined;
  const last = Array.isArray(raw.lines) ? raw.lines[1] : undefined;
  const lines = Number.isInteger(first) && first > 0 ? [first, Number.isInteger(last) && last >= first ? last : first] : undefined;
  return { repo: asString(raw.repo) || undefined, path, lines, note: asString(raw.note, 160) };
}

function uniqueId(raw, seen, where, issues) {
  const id = asString(raw?.id);
  if (!id || seen.has(id)) {
    issues.push(issue("error", where, id ? `duplicate id "${id}"; skipped` : "has no id; skipped"));
    return undefined;
  }
  seen.add(id);
  return id;
}

/** Parse and normalize a review overlay. Never throws; fatal problems are `errors`, everything else is an `issue`. */
export function parseReview(text) {
  const issues = [];
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (err) {
    return { ok: false, errors: [`Not valid JSON: ${err.message}`], issues };
  }
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, errors: ["Review must be a JSON object"], issues };
  if (raw.schemaVersion !== REVIEW_VERSION) return { ok: false, errors: [`Unsupported review schemaVersion ${JSON.stringify(raw.schemaVersion)} (expected ${REVIEW_VERSION})`], issues };
  unknownFields(raw, "review", "review", issues);
  const planPath = asString(raw.plan?.path);
  if (unsafePath(planPath)) return { ok: false, errors: ["review.plan.path must name the plan file relative to the project root (no leading / and no ..)"], issues };

  const model = raw.model && typeof raw.model === "object" ? raw.model : {};
  const repositories = {};
  for (const [id, rev] of Object.entries(model.repositories && typeof model.repositories === "object" ? model.repositories : {})) repositories[id] = asString(rev);

  const seen = new Set();
  const intents = [];
  for (const [i, r] of list(raw.intents).entries()) {
    const where = `intent ${asString(r?.id) || i + 1}`;
    const id = uniqueId(r, seen, where, issues);
    if (!id) continue;
    unknownFields(r, "intent", where, issues);
    const touches = [];
    for (const t of list(r.touches)) {
      unknownFields(t, "touch", where, issues);
      const ref = normRef(t?.ref, `${where} touches`, issues, MODEL_KINDS);
      if (!ref) continue;
      let basis = asString(t.basis);
      if (!BASES.includes(basis)) {
        issues.push(issue("warning", where, `touch of ${ref.kind} ${ref.id} has no basis (stated or inferred); treated as inferred`));
        basis = "inferred";
      }
      touches.push({ ref, basis, why: asString(t.why, 300) });
    }
    intents.push({ id, statement: asString(r.statement, 300), cite: normCite(r.cite, where, issues, true), touches });
  }

  const plannedFiles = [];
  for (const [i, f] of list(raw.plannedFiles).entries()) {
    const where = `planned file ${asString(f?.path) || i + 1}`;
    unknownFields(f, "file", where, issues);
    const path = asString(f?.path);
    const action = asString(f?.action);
    if (unsafePath(path) || !ACTIONS.includes(action)) {
      issues.push(issue("error", where, `needs a project-relative path and an action (${ACTIONS.join(" or ")})`));
      continue;
    }
    plannedFiles.push({ path, repo: asString(f.repo) || undefined, action, cite: normCite(f.cite, where, issues, true) });
  }

  const proposedIds = new Set();
  const components = [];
  for (const [i, c] of list(raw.proposed?.components).entries()) {
    const where = `proposed component ${asString(c?.id) || i + 1}`;
    const id = uniqueId(c, proposedIds, where, issues);
    if (!id) continue;
    unknownFields(c, "proposedComponent", where, issues);
    components.push({
      id,
      name: asString(c.name, 40) || id,
      kind: asString(c.kind) || "component",
      responsibility: asString(c.responsibility, 300),
      within: c.within ? normRef(c.within, where, issues, ["component"]) : undefined,
      cite: normCite(c.cite, where, issues, true),
    });
  }
  const relationships = [];
  const relIds = new Set();
  for (const [i, r] of list(raw.proposed?.relationships).entries()) {
    const where = `proposed relationship ${asString(r?.id) || i + 1}`;
    const id = uniqueId(r, relIds, where, issues);
    if (!id) continue;
    unknownFields(r, "proposedRelationship", where, issues);
    const ends = ["component", "proposed-component"];
    const from = normRef(r.from, `${where} from`, issues, ends);
    const to = normRef(r.to, `${where} to`, issues, ends);
    if (!from || !to) continue;
    relationships.push({ id, from, to, kind: asString(r.kind) || "depends-on", label: asString(r.label, 60), cite: normCite(r.cite, where, issues, true) });
  }

  const goalIds = new Set();
  const nonGoals = [];
  for (const [i, g] of list(raw.nonGoals).entries()) {
    const where = `non-goal ${asString(g?.id) || i + 1}`;
    const id = uniqueId(g, goalIds, where, issues);
    if (!id) continue;
    unknownFields(g, "nonGoal", where, issues);
    const constrains = list(g.constrains).map((x) => normRef(x, where, issues, MODEL_KINDS)).filter(Boolean);
    nonGoals.push({ id, statement: asString(g.statement, 300), cite: normCite(g.cite, where, issues, true), constrains });
  }

  const questionIds = new Set();
  const questions = [];
  for (const [i, q] of list(raw.questions).entries()) {
    const where = `question ${asString(q?.id) || i + 1}`;
    const id = uniqueId(q, questionIds, where, issues);
    if (!id) continue;
    unknownFields(q, "question", where, issues);
    const origin = asString(q.origin);
    if (origin !== "plan" && origin !== "suggested") {
      issues.push(issue("error", where, 'needs an origin: "plan" (the plan itself says it is open) or "suggested" (Claude\'s own)'));
      continue;
    }
    let type = asString(q.type);
    if (!QUESTION_TYPES.includes(type)) {
      issues.push(issue("warning", where, `type is not one of ${QUESTION_TYPES.join(", ")}; treated as assumption`));
      type = "assumption";
    }
    questions.push({
      id,
      origin,
      type,
      text: asString(q.text, 400),
      refs: list(q.refs).map((x) => normRef(x, where, issues, [...MODEL_KINDS, ...PROPOSED_KINDS])).filter(Boolean),
      cite: normCite(q.cite, where, issues, origin === "plan"),
      evidence: list(q.evidence).map((x) => normSource(x, where, issues)).filter(Boolean),
    });
  }

  return {
    ok: true,
    errors: [],
    issues,
    review: {
      schemaVersion: REVIEW_VERSION,
      title: asString(raw.title, 120),
      summary: asString(raw.summary, 500),
      generatedBy: asString(raw.generatedBy, 120),
      plan: { path: planPath, fingerprint: asString(raw.plan.fingerprint) || undefined },
      model: { name: asString(model.name, 60), revisions: Object.keys(repositories).length ? repositories : model.revision === undefined ? undefined : { "": asString(model.revision) }, fingerprint: asString(model.fingerprint) || undefined },
      intents,
      plannedFiles,
      proposed: { components, relationships },
      nonGoals,
      questions,
    },
  };
}

/** What a reference currently names: `{ ok, label }`. */
export function resolveRef(model, review, ref) {
  if (ref.kind === "proposed-component") {
    const c = review.proposed.components.find((x) => x.id === ref.id);
    return c ? { ok: true, label: c.name } : { ok: false, label: ref.id };
  }
  if (ref.kind === "proposed-relationship") {
    const r = review.proposed.relationships.find((x) => x.id === ref.id);
    return r ? { ok: true, label: r.label || r.kind } : { ok: false, label: ref.id };
  }
  if (ref.kind === "component") {
    const c = byId(model.components, ref.id);
    return c ? { ok: true, label: c.name } : { ok: false, label: ref.id };
  }
  if (ref.kind === "relationship") {
    const r = byId(model.relationships, ref.id);
    return r ? { ok: true, label: `${byId(model.components, r.from).name} → ${byId(model.components, r.to).name}: ${r.label || r.kind}` } : { ok: false, label: ref.id };
  }
  const [flowId, n] = ref.id.split("#");
  const step = byId(model.flows, flowId)?.steps.find((s) => s.n === Number(n));
  return step ? { ok: true, label: `${byId(model.flows, flowId).name} · step ${step.n}: ${step.action}` } : { ok: false, label: ref.id };
}

export const pathKey = (x) => `${x.repo ?? ""}\0${x.path}`;

const plain = (s) => s.replace(/[`*]/g, "").replace(/\s+/g, " ").trim();

/** Why a citation does not point at its quote in the plan (or in `what`, another text), or undefined when it does. */
export function citeProblem(cite, planLines, what = "plan") {
  if (cite.quote.length < MIN_QUOTE) return `quote is too short to identify a statement (${MIN_QUOTE}+ characters)`;
  const [a, b] = cite.lines;
  if (b > planLines.length) return `cites lines ${a}-${b} but the ${what} has only ${planLines.length} lines`;
  const quote = plain(cite.quote);
  if (plain(planLines.slice(a - 1, b).join(" ")).includes(quote)) return undefined;
  const whole = plain(planLines.join(" "));
  if (!whole.includes(quote)) return `the quoted text does not appear in the ${what}`;
  let at = -1;
  for (let i = 0; i < planLines.length; i++) if (plain(planLines.slice(i, i + (b - a + 3)).join(" ")).includes(quote)) at = i;
  return `the quoted text is not in lines ${a}-${b}${at >= 0 ? `; it appears near line ${at + 1}` : ""}`;
}

const sameRevisions = (a, b) => Object.keys({ ...a, ...b }).every((k) => (a[k] ?? "") === (b[k] ?? ""));
const showRevisions = (r) => Object.entries(r ?? {}).map(([k, v]) => `${k ? `${k} ` : ""}${v ? v.slice(0, 12) : "none"}`).join(", ") || "none";

/**
 * Compare a review with the plan, model and checkout as they are now: `{ stale, issues, citationsChecked }`.
 * `ctx.plannedExists` and `ctx.sourceLines` hold results keyed by `pathKey`; a missing key means the file could not be
 * looked up, which is reported rather than skipped. `ctx.checkouts` maps repository ids to `{ state, message }`.
 */
export function checkReview(model, review, ctx) {
  const stale = [];
  const issues = [];
  const declared = new Set(model.project.repositories.map((r) => r.id));
  const unchecked = new Map();
  const caveats = new Map();
  const checkSource = (item, kind, where, result) => {
    const repo = item.repo ?? "";
    if (item.repo && !declared.has(item.repo)) {
      issues.push(issue("error", where, `names repository "${item.repo}", which the model does not declare`));
      return false;
    }
    if (result === undefined) {
      const entry = unchecked.get(repo) ?? { files: 0, sources: 0 };
      entry[kind] += 1;
      unchecked.set(repo, entry);
      return false;
    }
    const checkout = ctx.checkouts?.get(repo);
    if (checkout && (checkout.state === "mismatch" || checkout.state === "unverified")) caveats.set(repo, checkout.message);
    return true;
  };

  if (!review.plan.fingerprint) stale.push({ kind: "plan-unrecorded", message: "The review records no fingerprint of the plan, so a later change to the plan cannot be detected." });
  else if (ctx.planText === null) stale.push({ kind: "plan-missing", message: `The plan ${review.plan.path} could not be read; the review may be out of date.` });
  else if (fingerprint(ctx.planText) !== review.plan.fingerprint) stale.push({ kind: "plan-changed", message: `The plan ${review.plan.path} changed since this review was generated; the preview may be stale.` });

  const now = modelRevisions(model);
  if (!review.model.revisions) stale.push({ kind: "model-unrecorded", message: "The review records no model revision, so a later model refresh cannot be detected." });
  else if (!sameRevisions(review.model.revisions, now)) stale.push({ kind: "model-revision", message: `The model is now at ${showRevisions(now)}; this review was made against ${showRevisions(review.model.revisions)}. The preview may be stale.` });
  else if (review.model.fingerprint && ctx.modelFingerprint && review.model.fingerprint !== ctx.modelFingerprint) stale.push({ kind: "model-changed", message: "The model file changed since this review was generated (same revision); the preview may be stale." });
  else if (!review.model.fingerprint) stale.push({ kind: "model-unrecorded", message: "The review records no fingerprint of the model file, so edits to the model cannot be detected." });

  const planLines = typeof ctx.planText === "string" ? textLines(ctx.planText) : undefined;
  const checkCite = (cite, where) => {
    if (!cite || !planLines) return;
    const problem = citeProblem(cite, planLines);
    if (problem) issues.push(issue("error", where, `plan citation ${cite.lines[0]}-${cite.lines[1]}: ${problem}`));
  };
  const checkRef = (ref, where) => {
    const r = resolveRef(model, review, ref);
    if (!r.ok) {
      const asProposed = (ref.kind === "component" && review.proposed.components.some((c) => c.id === ref.id)) || (ref.kind === "relationship" && review.proposed.relationships.some((x) => x.id === ref.id));
      issues.push(issue("error", where, asProposed ? `${ref.kind} "${ref.id}" is proposed by the plan, not in the model; reference it as proposed-${ref.kind}` : `${ref.kind} "${ref.id}" is not in the model, so it cannot be presented as existing architecture`));
    } else if (ref.label && !r.label.toLowerCase().includes(ref.label.toLowerCase())) {
      issues.push(issue("warning", where, `${ref.kind} "${ref.id}" was recorded as “${ref.label}”; the model now calls it “${r.label}”`));
    }
  };

  for (const g of review.intents) {
    const where = `intent ${g.id}`;
    checkCite(g.cite, where);
    for (const t of g.touches) checkRef(t.ref, `${where} touches`);
  }
  for (const f of review.plannedFiles) {
    const where = `planned file ${f.path}`;
    checkCite(f.cite, where);
    const found = ctx.plannedExists?.get(pathKey(f));
    if (!checkSource(f, "files", where, found)) continue;
    if (found === false && f.action === "modify") issues.push(issue("warning", where, "the plan says it modifies this file, but it does not exist in the checkout"));
    if (found === true && f.action === "create") issues.push(issue("warning", where, "the plan says it creates this file, but it already exists in the checkout"));
  }
  for (const c of review.proposed.components) {
    const where = `proposed component ${c.id}`;
    checkCite(c.cite, where);
    if (c.within) checkRef(c.within, `${where} within`);
    if (byId(model.components, c.id)) issues.push(issue("warning", where, `the model already has a component with id "${c.id}"; is this really new?`));
  }
  for (const r of review.proposed.relationships) {
    const where = `proposed relationship ${r.id}`;
    checkCite(r.cite, where);
    checkRef(r.from, `${where} from`);
    checkRef(r.to, `${where} to`);
    if (byId(model.relationships, r.id)) issues.push(issue("warning", where, `the model already has a relationship with id "${r.id}"; is this really new?`));
  }
  for (const g of review.nonGoals) {
    const where = `non-goal ${g.id}`;
    checkCite(g.cite, where);
    for (const c of g.constrains) checkRef(c, `${where} constrains`);
  }
  for (const q of review.questions) {
    const where = `question ${q.id}`;
    checkCite(q.cite, where);
    for (const ref of q.refs) checkRef(ref, where);
    for (const ev of q.evidence) {
      const total = ctx.sourceLines?.get(pathKey(ev));
      if (!checkSource(ev, "sources", where, total)) continue;
      if (total === null) issues.push(issue("warning", where, `cites ${ev.path}, which does not exist in the checkout`));
      else if (ev.lines && ev.lines[1] > total) issues.push(issue("warning", where, `cites ${ev.path}:${ev.lines[0]}-${ev.lines[1]}, beyond the end of the file (${total} lines)`));
    }
  }
  for (const [repo, n] of unchecked) {
    const what = [n.files && `${n.files} planned file${n.files === 1 ? "" : "s"}`, n.sources && `${n.sources} source citation${n.sources === 1 ? "" : "s"}`].filter(Boolean).join(" and ");
    const checkout = ctx.checkouts?.get(repo);
    const reason = checkout ? checkout.message || `checkout state ${checkout.state}` : repo ? "no checkout was configured for it" : "no checkout was available";
    issues.push(issue("warning", "verification", `${what} ${repo ? `in repository "${repo}"` : "in this project"} could not be checked against a checkout (${reason}); they are unverified`));
  }
  for (const [repo, message] of caveats) issues.push(issue("warning", "verification", `files and lines in repository "${repo}" were checked against a checkout that may differ from the model's revision (${message})`));
  return { stale, issues, citationsChecked: Boolean(planLines) };
}

const labelOf = (model, kind, id) => resolveRef(model, { proposed: { components: [], relationships: [] } }, { kind, id }).label;

const elementItems = (model) => [
  ...model.components.map((c) => ({ kind: "component", id: c.id, label: c.name, evidence: c.evidence })),
  ...model.relationships.map((r) => ({ kind: "relationship", id: r.id, label: labelOf(model, "relationship", r.id), evidence: r.evidence })),
  ...model.flows.flatMap((f) => f.steps.map((s) => ({ kind: "step", id: `${f.id}#${s.n}`, label: labelOf(model, "step", `${f.id}#${s.n}`), evidence: s.evidence }))),
];

/** What the review touches in the model and the reach `impactOf` derives from it; unresolved references are never used. */
export function deriveReview(model, review, { depth = 1, categories = [] } = {}) {
  const touched = new Map();
  const items = elementItems(model);
  const files = new Set(review.plannedFiles.map(pathKey));
  for (const intent of review.intents) {
    for (const t of intent.touches) {
      if (!resolveRef(model, review, t.ref).ok) continue;
      const key = `${t.ref.kind}:${t.ref.id}`;
      const entry = touched.get(key) ?? { kind: t.ref.kind, id: t.ref.id, label: resolveRef(model, review, t.ref).label, intents: [], basis: "inferred", why: [] };
      entry.intents.push(intent.id);
      if (t.basis === "stated") entry.basis = "stated";
      if (t.why) entry.why.push(t.why);
      touched.set(key, entry);
    }
  }
  for (const e of touched.values()) {
    const evidence = items.find((x) => x.kind === e.kind && x.id === e.id)?.evidence ?? [];
    e.citesPlannedFile = evidence.some((ev) => files.has(pathKey(ev)));
  }

  const touchedComponents = new Set([...touched.values()].filter((e) => e.kind === "component").map((e) => e.id));
  const sources = [];
  const untraced = [];
  for (const e of touched.values()) {
    if (e.kind !== "step") {
      sources.push({ kind: e.kind, id: e.id, label: e.label });
      continue;
    }
    const step = byId(model.flows, e.id.split("#")[0])?.steps.find((s) => s.n === Number(e.id.split("#")[1]));
    const res = step && resolveStepRelationship(model, step);
    if (res?.relationship && !res.reverse && !res.ambiguous) sources.push({ kind: "relationship", id: res.relationship.id, label: e.label });
    else untraced.push(e);
  }

  const reach = new Map();
  const steps = new Map();
  const mergeReach = (component, hop, chain, because) => {
    if (touchedComponents.has(component.id)) return;
    const cur = reach.get(component.id);
    if (cur) {
      if (!cur.because.includes(because)) cur.because.push(because);
      if (hop >= cur.hop) return;
    }
    reach.set(component.id, { component, hop, chain, because: cur?.because ?? [because], confidence: chain.length ? weakest(chain.map((c) => c.confidence)) : "unknown", uncited: chain.some((c) => c.evidence.length === 0) });
  };
  const noteStep = (flow, step, how, label) => {
    const key = `${flow.id}#${step.n}`;
    const cur = steps.get(key) ?? { flow, step, named: false, via: [] };
    if (how === "named") cur.named = true;
    else if (!cur.via.includes(label)) cur.via.push(label);
    steps.set(key, cur);
  };
  for (const e of touched.values()) {
    if (e.kind !== "step") continue;
    const [flowId, n] = e.id.split("#");
    const flow = byId(model.flows, flowId);
    noteStep(flow, flow.steps.find((s) => s.n === Number(n)), "named");
  }
  for (const src of sources) {
    const impact = impactOf(model, { kind: src.kind, id: src.id }, { categories, depth });
    if (!impact) continue;
    for (const c of impact.consumers) mergeReach(c.component, 1, c.relationship ? [c.relationship] : [], src.label);
    for (const d of impact.downstream) mergeReach(d.component, d.hop, d.chain, src.label);
    if (src.kind === "relationship") for (const hit of stepsUsing(model, byId(model.relationships, src.id))) noteStep(hit.flow, hit.step, "via", src.label);
  }
  const listed = [...steps.values()].sort((a, b) => model.flows.indexOf(a.flow) - model.flows.indexOf(b.flow) || a.step.n - b.step.n);
  const involving = [...touchedComponents].map((id) => ({ component: byId(model.components, id), count: stepsTouching(model, id).filter(({ flow, step }) => !steps.has(`${flow.id}#${step.n}`)).length })).filter((x) => x.count > 0);

  const stepKeys = new Set(steps.keys());
  const nonGoals = review.nonGoals.map((g) => {
    const hits = [];
    let resolved = 0;
    for (const ref of g.constrains) {
      const r = resolveRef(model, review, ref);
      if (!r.ok) continue;
      resolved += 1;
      const key = `${ref.kind}:${ref.id}`;
      const reached = ref.kind === "component" && reach.has(ref.id);
      if (touched.has(key)) hits.push({ ref, label: r.label, how: "touched by the plan review" });
      else if (reached) hits.push({ ref, label: r.label, how: "reached through modeled relationships" });
      else if (ref.kind === "step" && stepKeys.has(ref.id)) hits.push({ ref, label: r.label, how: "a workflow step the touched relationships use" });
    }
    return { goal: g, resolved, hits, status: hits.length ? "overlap" : resolved ? "none-found" : "unconstrained" };
  });

  const candidates = review.plannedFiles.map((file) => ({
    file,
    elements: items.filter((it) => it.evidence.some((ev) => pathKey(ev) === pathKey(file))).map((it) => ({ kind: it.kind, id: it.id, label: it.label, named: touched.has(`${it.kind}:${it.id}`) })),
  }));

  return { touched: [...touched.values()], reach: [...reach.values()].sort((a, b) => a.hop - b.hop || a.component.name.localeCompare(b.component.name)), steps: listed, involving, untraced, nonGoals, candidates };
}

/** The model's own relationships between a proposed relationship's endpoints, when both exist already. */
export function parallelLinks(model, rel) {
  if (rel.from.kind !== "component" || rel.to.kind !== "component") return [];
  return model.relationships.filter((r) => r.from === rel.from.id && r.to === rel.to.id);
}

