import { byId } from "./model.mjs";
import { modelRevisions } from "./review.mjs";
import { lineCount } from "./lens.mjs";

export const BEHAVIOR_VERSION = 1;
export const BEHAVIOR_FILE = ".architecture/behavior.json";

const CONFIDENCE = ["observed", "inferred", "unknown"];
const RELEASE = ["waits", "early"];
const ACTIONS = ["return", "drop", "hold", "unknown"];
const MIN_QUOTE = 8;
const RANK = { unknown: 0, inferred: 1, observed: 2 };

const FIELDS = {
  behavior: ["schemaVersion", "title", "summary", "generatedBy", "flow", "model", "hops", "variants", "origins", "questions"],
  hop: ["id", "component", "label", "role", "step", "release", "holds", "onError", "notes"],
  claim: ["text", "confidence", "evidence", "mode", "store", "action", "retries", "signals"],
  evidence: ["repo", "path", "lines", "quote", "note"],
  variant: ["id", "name", "when", "changes", "without"],
  origin: ["id", "hop", "name", "emits"],
  question: ["id", "text", "hop", "evidence"],
};
const CHANGEABLE = ["release", "holds", "onError"];

const issue = (level, where, message) => ({ level, where, message });
const asString = (v, max) => {
  const s = typeof v === "string" ? v.trim() : "";
  return max && s.length > max ? `${s.slice(0, max - 1)}…` : s;
};
const list = (v) => (Array.isArray(v) ? v : []);
const isObject = (v) => v && typeof v === "object" && !Array.isArray(v);
const unsafePath = (p) => !p || p.startsWith("/") || p.split("/").includes("..");

function unknownFields(raw, kind, where, issues) {
  if (!isObject(raw)) return;
  for (const key of Object.keys(raw)) if (!FIELDS[kind].includes(key)) issues.push(issue("warning", where, `field "${key}" is not part of the behavior format and was ignored`));
}

function normEvidence(raw, where, issues) {
  const out = [];
  for (const [i, e] of list(raw).entries()) {
    const at = `${where} evidence ${i + 1}`;
    if (!isObject(e)) {
      issues.push(issue("error", at, "is not an object"));
      continue;
    }
    unknownFields(e, "evidence", at, issues);
    const path = asString(e.path);
    if (unsafePath(path)) {
      issues.push(issue("error", at, `path "${path}" must be relative and stay inside its repository`));
      continue;
    }
    const lines = Array.isArray(e.lines) && e.lines.length === 2 && e.lines.every((n) => Number.isInteger(n) && n >= 1) && e.lines[0] <= e.lines[1] ? e.lines : undefined;
    if (!lines) {
      issues.push(issue("error", at, "needs lines: [first, last] (1-based, first <= last)"));
      continue;
    }
    const quote = asString(e.quote);
    if (quote.length < MIN_QUOTE) issues.push(issue("warning", at, quote ? `quote is shorter than ${MIN_QUOTE} characters, so it identifies nothing` : "has no verbatim quote, so it can only be bounds-checked"));
    out.push({ repo: asString(e.repo) || undefined, path, lines, quote: quote || undefined, note: asString(e.note) || undefined });
  }
  return out;
}

function normClaim(raw, where, issues, kind) {
  if (!isObject(raw)) {
    issues.push(issue("error", where, "is not an object"));
    return undefined;
  }
  unknownFields(raw, "claim", where, issues);
  const text = asString(raw.text, 400);
  if (!text) {
    issues.push(issue("error", where, "needs text"));
    return undefined;
  }
  const confidence = CONFIDENCE.includes(raw.confidence) ? raw.confidence : "unknown";
  if (!CONFIDENCE.includes(raw.confidence)) issues.push(issue("warning", where, `confidence "${raw.confidence}" is not observed, inferred or unknown; treated as unknown`));
  const evidence = normEvidence(raw.evidence, where, issues);
  if (confidence === "observed" && evidence.length === 0) issues.push(issue("error", where, "is marked observed but cites no source"));
  const claim = { text, confidence, evidence, signals: list(raw.signals).map((s) => asString(s, 160)).filter(Boolean) };
  if (kind === "release") {
    if (!RELEASE.includes(raw.mode)) issues.push(issue("error", where, `mode must be one of ${RELEASE.join(", ")}`));
    else claim.mode = raw.mode;
  }
  if (kind === "holds") claim.store = asString(raw.store, 80) || undefined;
  if (kind === "onError") {
    if (!ACTIONS.includes(raw.action)) issues.push(issue("error", where, `action must be one of ${ACTIONS.join(", ")}`));
    else claim.action = raw.action;
    claim.retries = raw.retries === true;
    claim.store = asString(raw.store, 80) || undefined;
  }
  return claim;
}

function normChanges(raw, where, issues) {
  const out = {};
  if (!isObject(raw)) return out;
  for (const [hopId, change] of Object.entries(raw)) {
    const at = `${where} change to ${hopId}`;
    if (!isObject(change)) {
      issues.push(issue("error", at, "is not an object"));
      continue;
    }
    const one = {};
    for (const key of Object.keys(change)) {
      if (!CHANGEABLE.includes(key)) {
        issues.push(issue("warning", at, `"${key}" cannot be changed by a variant (only ${CHANGEABLE.join(", ")}) and was ignored`));
        continue;
      }
      const claim = change[key] === null ? null : normClaim(change[key], `${at} ${key}`, issues, key);
      if (claim !== undefined) one[key] = claim;
    }
    out[hopId] = one;
  }
  return out;
}

export function parseBehavior(text) {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (err) {
    return { ok: false, errors: [`Behavior file is not valid JSON: ${err.message}`] };
  }
  if (!isObject(raw) || raw.schemaVersion !== BEHAVIOR_VERSION) return { ok: false, errors: [`Behavior file must be an object with schemaVersion ${BEHAVIOR_VERSION}`] };
  const issues = [];
  unknownFields(raw, "behavior", "behavior", issues);
  const flow = asString(raw.flow);
  if (!flow) return { ok: false, errors: ["Behavior file needs \"flow\": the id of the model flow its hops follow"] };

  const hopIds = new Set();
  const hops = [];
  for (const [i, h] of list(raw.hops).entries()) {
    const where = `hop ${h?.id ?? i + 1}`;
    if (!isObject(h)) {
      issues.push(issue("error", where, "is not an object"));
      continue;
    }
    unknownFields(h, "hop", where, issues);
    const id = asString(h.id);
    if (!id || hopIds.has(id)) {
      issues.push(issue("error", where, id ? `id "${id}" is used twice` : "needs an id"));
      continue;
    }
    hopIds.add(id);
    const component = asString(h.component) || undefined;
    const label = asString(h.label, 60) || undefined;
    if (!component && !label) issues.push(issue("error", where, "names neither a component nor a label (an external system needs a label)"));
    hops.push({
      id,
      component,
      label,
      role: asString(h.role, 120),
      step: asString(h.step) || undefined,
      release: h.release === undefined ? undefined : normClaim(h.release, `${where} release`, issues, "release"),
      holds: h.holds === undefined ? undefined : normClaim(h.holds, `${where} holds`, issues, "holds"),
      onError: h.onError === undefined ? undefined : normClaim(h.onError, `${where} onError`, issues, "onError"),
      notes: list(h.notes).map((n, j) => normClaim(n, `${where} note ${j + 1}`, issues, "note")).filter(Boolean),
    });
  }
  if (hops.length < 2) return { ok: false, errors: ["Behavior file needs at least two hops (a caller and what it calls)"] };

  const variantIds = new Set(["default"]);
  const variants = [];
  for (const [i, v] of list(raw.variants).entries()) {
    const where = `variant ${v?.id ?? i + 1}`;
    if (!isObject(v)) {
      issues.push(issue("error", where, "is not an object"));
      continue;
    }
    unknownFields(v, "variant", where, issues);
    const id = asString(v.id);
    if (!id || variantIds.has(id)) {
      issues.push(issue("error", where, id ? `id "${id}" is used twice or reserved` : "needs an id"));
      continue;
    }
    variantIds.add(id);
    variants.push({ id, name: asString(v.name, 60) || id, when: asString(v.when, 240), changes: normChanges(v.changes, where, issues), without: list(v.without).map((x) => asString(x)).filter(Boolean) });
  }

  const originIds = new Set();
  const origins = [];
  for (const [i, o] of list(raw.origins).entries()) {
    const where = `origin ${o?.id ?? i + 1}`;
    if (!isObject(o)) {
      issues.push(issue("error", where, "is not an object"));
      continue;
    }
    unknownFields(o, "origin", where, issues);
    const id = asString(o.id);
    if (!id || originIds.has(id)) {
      issues.push(issue("error", where, id ? `id "${id}" is used twice` : "needs an id"));
      continue;
    }
    originIds.add(id);
    const emits = normClaim(o.emits, `${where} emits`, issues, "emits");
    if (!emits) continue;
    origins.push({ id, hop: asString(o.hop), name: asString(o.name, 80) || id, emits });
  }
  if (!origins.length) return { ok: false, errors: ["Behavior file needs at least one origin: where the failure starts"] };

  const questions = [];
  for (const [i, q] of list(raw.questions).entries()) {
    const where = `question ${q?.id ?? i + 1}`;
    if (!isObject(q)) {
      issues.push(issue("error", where, "is not an object"));
      continue;
    }
    unknownFields(q, "question", where, issues);
    const text = asString(q.text, 400);
    if (!text) {
      issues.push(issue("error", where, "needs text"));
      continue;
    }
    questions.push({ id: asString(q.id) || `q${i + 1}`, text, hop: asString(q.hop) || undefined, evidence: normEvidence(q.evidence, where, issues) });
  }

  const revisions = isObject(raw.model?.repositories) ? Object.fromEntries(Object.entries(raw.model.repositories).map(([k, v]) => [k, asString(v)])) : raw.model?.revision ? { "": asString(raw.model.revision) } : undefined;
  const behavior = {
    schemaVersion: BEHAVIOR_VERSION,
    title: asString(raw.title, 120),
    summary: asString(raw.summary, 400),
    generatedBy: asString(raw.generatedBy, 120),
    flow,
    model: { name: asString(raw.model?.name), revisions },
    hops,
    variants,
    origins,
    questions,
  };
  return { ok: true, behavior, issues };
}

export function citations(behavior) {
  const out = [];
  const claim = (where, c) => c && c.evidence.forEach((ev, i) => out.push({ where: `${where} evidence ${i + 1}`, ev }));
  for (const h of behavior.hops) {
    for (const key of CHANGEABLE) claim(`hop ${h.id} ${key}`, h[key]);
    h.notes.forEach((n, i) => claim(`hop ${h.id} note ${i + 1}`, n));
  }
  for (const v of behavior.variants) for (const [hopId, ch] of Object.entries(v.changes)) for (const key of CHANGEABLE) claim(`variant ${v.id} change to ${hopId} ${key}`, ch[key]);
  for (const o of behavior.origins) claim(`origin ${o.id} emits`, o.emits);
  for (const q of behavior.questions) q.evidence.forEach((ev, i) => out.push({ where: `question ${q.id} evidence ${i + 1}`, ev }));
  return out;
}

export const sourceKey = (ev) => `${ev.repo ?? ""}\0${ev.path}`;
const squash = (s) => s.replace(/\s+/g, " ").trim();

export function citationProblem(ev, text) {
  const all = text.split("\n");
  const count = lineCount(text);
  const [a, b] = ev.lines;
  if (b > count) return `cites lines ${a}-${b} but the file has only ${count} lines`;
  if (!ev.quote || ev.quote.length < MIN_QUOTE) return undefined;
  const quote = squash(ev.quote);
  if (squash(all.slice(a - 1, b).join(" ")).includes(quote)) return undefined;
  if (!squash(all.join(" ")).includes(quote)) return "the quoted text does not appear in the file";
  let near = -1;
  for (let i = 0; i < all.length; i++) if (squash(all.slice(i, i + (b - a + 3)).join(" ")).includes(quote)) near = i;
  return `the quoted text is not in lines ${a}-${b}${near >= 0 ? `; it appears near line ${near + 1}` : ""}`;
}

const sameRevisions = (a, b) => Object.keys({ ...a, ...b }).every((k) => (a[k] ?? "") === (b[k] ?? ""));
const showRevisions = (r) => Object.entries(r ?? {}).map(([k, v]) => `${k ? `${k} ` : ""}${v ? v.slice(0, 12) : "none"}`).join(", ") || "none";

/** `ctx.sources` has no entry for a file that could not be looked up, and `null` for one that is missing. */
export function checkBehavior(model, behavior, ctx) {
  const issues = [];
  const stale = [];
  const flow = byId(model.flows, behavior.flow);
  if (!flow) issues.push(issue("error", "flow", `the model has no flow "${behavior.flow}"`));
  const hopById = new Map(behavior.hops.map((h) => [h.id, h]));
  const multi = model.project.repositories.length > 0;
  const declared = new Set(model.project.repositories.map((r) => r.id));

  for (const h of behavior.hops) {
    const where = `hop ${h.id}`;
    if (h.component && !byId(model.components, h.component)) issues.push(issue("error", where, `component "${h.component}" is not in the model`));
    if (h.step) {
      const [flowId, n] = h.step.split("#");
      const step = byId(model.flows, flowId)?.steps.find((s) => s.n === Number(n));
      if (!step) issues.push(issue("error", where, `step "${h.step}" is not in the model`));
      else if (h.component && step.from !== h.component && step.to !== h.component) issues.push(issue("error", where, `step "${h.step}" does not involve component "${h.component}"`));
    }
  }
  behavior.hops.forEach((h, i) => {
    const last = i === behavior.hops.length - 1;
    if (!last) {
      if (!h.release) issues.push(issue("warning", `hop ${h.id}`, "says nothing about when it returns to its caller; a trace through it stops as unresolved"));
      if (!h.onError) issues.push(issue("warning", `hop ${h.id}`, "says nothing about what it does when what it calls fails; a trace through it stops as unresolved"));
    }
    if (h.release?.mode === "early" && h.onError?.action === "return") issues.push(issue("error", `hop ${h.id}`, "returns early, so its caller is gone and onError cannot be \"return\""));
  });
  for (const v of behavior.variants) {
    for (const [hopId, ch] of Object.entries(v.changes)) {
      const hop = hopById.get(hopId);
      if (!hop) issues.push(issue("error", `variant ${v.id}`, `changes unknown hop "${hopId}"`));
      else if ((ch.release ?? hop.release)?.mode === "early" && (ch.onError ?? hop.onError)?.action === "return") issues.push(issue("error", `variant ${v.id}`, `hop ${hopId} would return early and still return an error`));
    }
    for (const id of v.without) if (!behavior.origins.some((o) => o.id === id)) issues.push(issue("error", `variant ${v.id}`, `excludes unknown origin "${id}"`));
  }
  for (const o of behavior.origins) {
    const at = behavior.hops.findIndex((h) => h.id === o.hop);
    if (at < 0) issues.push(issue("error", `origin ${o.id}`, `starts at unknown hop "${o.hop}"`));
    else if (at === 0) issues.push(issue("error", `origin ${o.id}`, "starts at the first hop, so nothing is upstream to receive the error"));
  }
  for (const q of behavior.questions) if (q.hop && !hopById.has(q.hop)) issues.push(issue("error", `question ${q.id}`, `is about unknown hop "${q.hop}"`));

  let checked = 0;
  let confirmed = 0;
  const unreadable = new Set();
  for (const { where, ev } of citations(behavior)) {
    if (multi && !ev.repo) issues.push(issue("error", where, "names no repository, and the model declares repositories"));
    else if (ev.repo && !declared.has(ev.repo)) issues.push(issue("error", where, `names repository "${ev.repo}", which the model does not declare`));
    const key = sourceKey(ev);
    if (!ctx.sources.has(key)) {
      unreadable.add(ev.repo ?? "");
      continue;
    }
    checked++;
    const text = ctx.sources.get(key);
    if (text === null) {
      issues.push(issue("error", where, `${ev.repo ? `[${ev.repo}] ` : ""}${ev.path} does not exist in the checkout`));
      continue;
    }
    const problem = citationProblem(ev, text);
    if (problem) issues.push(issue("error", where, `${ev.path}: ${problem}`));
    else confirmed++;
  }
  for (const repo of unreadable) issues.push(issue("warning", "verification", `${repo ? `Repository ${repo}` : "The project"}: some cited files could not be read, so their citations are unverified`));

  const behaviorRevs = behavior.model.revisions;
  if (!behaviorRevs) stale.push({ message: "The document records no model revision, so it cannot be compared with the model it was written against." });
  else if (!sameRevisions(behaviorRevs, modelRevisions(model))) stale.push({ message: `Written against model ${showRevisions(behaviorRevs)}; the model is now at ${showRevisions(modelRevisions(model))}.` });
  for (const id of new Set(citations(behavior).map((c) => c.ev.repo).filter(Boolean))) {
    const co = ctx.checkouts?.get(id);
    if (co && co.state !== "ok") stale.push({ message: `Repository ${id}: ${co.message || co.state}. Cited lines may have moved.` });
  }
  return { issues, stale, checked: { total: citations(behavior).length, read: checked, confirmed } };
}

export function effectiveHops(behavior, variantId = "default") {
  const variant = behavior.variants.find((v) => v.id === variantId);
  return behavior.hops.map((h) => {
    const ch = variant?.changes[h.id];
    const changed = ch ? Object.keys(ch) : [];
    const next = { ...h, changed };
    for (const key of changed) next[key] = ch[key] ?? undefined;
    return next;
  });
}

const weakest = (claims) => claims.reduce((w, c) => (RANK[c.confidence] < RANK[w] ? c.confidence : w), "observed");

/** A hop that returns early always ends the walk, and a hop with no `onError` ends it unresolved rather than letting the error continue. */
export function traceFailure(behavior, variantId, originId) {
  const hops = effectiveHops(behavior, variantId);
  const variant = behavior.variants.find((v) => v.id === variantId);
  const origin = behavior.origins.find((o) => o.id === originId);
  if (!origin) return undefined;
  const start = hops.findIndex((h) => h.id === origin.hop);
  const firstEarly = hops.findIndex((h) => h.release?.mode === "early");
  const base = { hops, variant, origin, start, firstEarly: firstEarly >= 0 ? firstEarly : undefined };
  if (variant?.without.includes(originId)) return { ...base, available: false, steps: [], reason: `${variant.name} has no such failure` };
  if (start < 1) return { ...base, available: false, steps: [], reason: "the origin has no upstream hop" };

  const steps = [{ index: start, hop: hops[start], kind: "origin", claim: origin.emits }];
  let stop;
  for (let i = start - 1; i >= 0; i--) {
    const hop = hops[i];
    const claim = hop.onError;
    if (!claim || claim.action === "unknown") {
      steps.push({ index: i, hop, kind: "unresolved", claim });
      stop = { index: i, action: "unknown" };
      break;
    }
    if (claim.action === "return" && hop.release?.mode !== "early") {
      steps.push({ index: i, hop, kind: "returns", claim });
      continue;
    }
    steps.push({ index: i, hop, kind: claim.action === "hold" ? "holds" : "drops", claim });
    stop = { index: i, action: claim.action === "return" ? "unknown" : claim.action };
    break;
  }
  const reachedCaller = !stop;
  const last = steps[steps.length - 1];
  const stopAt = stop?.index ?? 0;
  const used = [origin.emits, ...steps.map((s) => s.claim).filter(Boolean)];
  if (firstEarly >= 0 && firstEarly <= stopAt) used.push(hops[firstEarly].release);
  const signals = steps.flatMap((s) => (s.claim?.signals ?? []).map((text) => ({ text, index: s.index, hop: s.hop })));
  return {
    ...base,
    available: true,
    steps,
    stop: stop ? { ...stop, hop: hops[stop.index] } : undefined,
    reachedCaller,
    unseen: hops.slice(0, stop ? stop.index : 0).map((h, i) => ({ index: i, hop: h })),
    callerSees: reachedCaller ? { kind: "error" } : stop.index >= (base.firstEarly ?? Infinity) ? { kind: "ok", why: "early", at: base.firstEarly } : { kind: "ok", why: "swallowed", at: stop.index },
    fate: reachedCaller ? "returned" : stop.action === "drop" ? "dropped" : stop.action === "hold" ? "held" : "unresolved",
    signals,
    weakest: weakest(used),
    last,
  };
}

export const hopName = (model, hop) => hop.label ?? byId(model.components, hop.component)?.name ?? hop.id;

export const hopConfidence = (hop) => {
  const claims = [hop.release, hop.holds, hop.onError].filter(Boolean);
  return claims.length ? weakest(claims) : "unknown";
};

