import { byId } from "./model.mjs";
import { impactOf } from "./impact.mjs";
import { CONFIDENCE, asString, checkCitations, componentProblem, isObject, issue, list, normList, normModelRef, normProvenance, normText, stepDrift, stepProblem, stepRef, unknownFields } from "./lens.mjs";

export const DATA_VERSION = 1;
export const DATA_FILE = ".architecture/data.json";

export const OPS = ["create", "read", "update", "delete", "emit"];
export const GUARD_KINDS = ["state-check", "row-lock", "ownership", "idempotency", "none"];
export const RELATION_KINDS = ["references", "shared-key", "derived-from"];
export const FIELD_ROLES = ["pk", "fk", "unique", "state", "key", "derived", "other"];
const COMPENSATION = ["idempotent-retry", "compensating-write", "reconciler", "none-found"];
export const LOCKS = ["row-lock", "refresh-before-write", "none-found", "unknown"];
export const ASPECTS = ["atomicity", "visibility", "concurrency", "external-failure"];
export const ANY_STATE = "*";

const FIELDS = {
  data: ["schemaVersion", "title", "summary", "generatedBy", "model", "entities", "relations", "effects", "lifecycles", "sequences", "questions"],
  entity: ["id", "name", "store", "kind", "description", "key", "fields", "confidence", "evidence"],
  field: ["name", "role", "note"],
  relation: ["id", "from", "to", "kind", "via", "text", "confidence", "evidence"],
  effect: ["id", "component", "entity", "system", "op", "step", "label", "via", "text", "transition", "confidence", "evidence"],
  lifecycle: ["id", "entity", "field", "initial", "states", "transitions"],
  state: ["id", "label", "terminal"],
  transition: ["id", "from", "to", "by", "step", "label", "trigger", "guard", "text", "confidence", "evidence"],
  guard: ["kind", "lock", "missing", "text", "confidence", "evidence"],
  sequence: ["id", "name", "summary", "steps", "ordering", "compensation", "residue", "uncertainty"],
  uncertainty: ["id", "aspect", "after", "text", "confidence", "evidence"],
  compensation: ["kind", "text", "confidence", "evidence"],
  residue: ["id", "after", "text", "confidence", "evidence"],
  question: ["id", "text", "entity", "evidence"],
};

function normGuard(raw, where, issues) {
  if (raw === undefined || raw === null) return undefined;
  if (!isObject(raw)) {
    issues.push(issue("error", where, "is not an object"));
    return undefined;
  }
  unknownFields(raw, FIELDS.guard, where, issues, "data");
  if (raw.lock !== undefined && !LOCKS.includes(raw.lock)) issues.push(issue("error", where, `lock must be one of ${LOCKS.join(", ")}`));
  if (!GUARD_KINDS.includes(raw.kind)) {
    issues.push(issue("error", where, `kind must be one of ${GUARD_KINDS.join(", ")}; the guard is dropped`));
    return undefined;
  }
  return { kind: raw.kind, lock: LOCKS.includes(raw.lock) ? raw.lock : undefined, missing: list(raw.missing).map((m) => asString(m, 200)).filter(Boolean), text: normText(raw.text, where, issues), ...normProvenance(raw, where, issues) };
}

// null is "created here" (no prior state); "*" is "any state"; a list names several.
const fromList = (v) => (v === null || v === undefined ? [null] : (Array.isArray(v) ? v : [v]).map((x) => (x === null ? null : asString(x))));

function normStates(raw, where, issues, seen) {
  const out = [];
  for (const [i, s] of list(raw).entries()) {
    const at = `${where} state ${s?.id ?? i + 1}`;
    if (!isObject(s)) {
      issues.push(issue("error", at, "is not an object"));
      continue;
    }
    unknownFields(s, FIELDS.state, at, issues, "data");
    const id = asString(s.id);
    if (!id || id === ANY_STATE || seen.has(id)) {
      issues.push(issue("error", at, !id ? "needs an id" : id === ANY_STATE ? `"${ANY_STATE}" is reserved for "any state"` : `id "${id}" is used twice`));
      continue;
    }
    seen.add(id);
    out.push({ id, label: asString(s.label, 60) || id, terminal: s.terminal === true });
  }
  return out;
}

export function parseData(text) {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (err) {
    return { ok: false, errors: [`Data file is not valid JSON: ${err.message}`] };
  }
  if (!isObject(raw) || raw.schemaVersion !== DATA_VERSION) return { ok: false, errors: [`Data file must be an object with schemaVersion ${DATA_VERSION}`] };
  const issues = [];
  unknownFields(raw, FIELDS.data, "data", issues, "data");

  const entities = normList(raw.entities, "entity", FIELDS.entity, issues, "data", (r, id, where) => {
    const store = asString(r.store);
    if (!store) {
      issues.push(issue("error", where, "needs a store: the component that holds it"));
      return undefined;
    }
    const fields = [];
    for (const [i, f] of list(r.fields).entries()) {
      const at = `${where} field ${f?.name ?? i + 1}`;
      if (!isObject(f) || !asString(f.name)) {
        issues.push(issue("error", at, "needs a name"));
        continue;
      }
      unknownFields(f, FIELDS.field, at, issues, "data");
      if (f.role !== undefined && !FIELD_ROLES.includes(f.role)) issues.push(issue("warning", at, `role "${f.role}" is not one of ${FIELD_ROLES.join(", ")}; treated as other`));
      fields.push({ name: asString(f.name, 60), role: FIELD_ROLES.includes(f.role) ? f.role : "other", note: asString(f.note, 160) || undefined });
    }
    return { id, name: asString(r.name, 60) || id, store, kind: asString(r.kind, 40) || "entity", description: asString(r.description, 400), key: asString(r.key, 160) || undefined, fields, ...normProvenance(r, where, issues) };
  });

  const relations = normList(raw.relations, "relation", FIELDS.relation, issues, "data", (r, id, where) => {
    if (!RELATION_KINDS.includes(r.kind)) issues.push(issue("error", where, `kind must be one of ${RELATION_KINDS.join(", ")}`));
    return { id, from: asString(r.from), to: asString(r.to), kind: RELATION_KINDS.includes(r.kind) ? r.kind : "references", via: asString(r.via, 120) || undefined, text: asString(r.text, 300), ...normProvenance(r, where, issues) };
  });

  const effects = normList(raw.effects, "effect", FIELDS.effect, issues, "data", (r, id, where) => {
    if (!OPS.includes(r.op)) {
      issues.push(issue("error", where, `op must be one of ${OPS.join(", ")}; the effect is dropped`));
      return undefined;
    }
    const entity = asString(r.entity) || undefined;
    const system = asString(r.system) || undefined;
    if (!entity && !system) issues.push(issue("error", where, "names neither an entity nor a system (an external effect needs a system)"));
    const component = asString(r.component);
    if (!component) issues.push(issue("error", where, "needs a component: who performs it"));
    const step = asString(r.step) || undefined;
    const via = asString(r.via, 160) || undefined;
    if (!step && !via) issues.push(issue("error", where, "needs a step of a modeled flow, or `via` naming the route or function that is not on one"));
    return { id, component, entity, system, op: r.op, step, label: asString(r.label, 80) || undefined, via, text: normText(r.text, where, issues), transition: asString(r.transition) || undefined, ...normProvenance(r, where, issues) };
  });

  // State and transition ids are keys across the whole document (effect `transition` refs, coverage lookups, view keys), so uniqueness spans lifecycles.
  const stateIds = new Set();
  const transitionIds = new Set();
  const lifecycles = normList(raw.lifecycles, "lifecycle", FIELDS.lifecycle, issues, "data", (r, id, where) => {
    const states = normStates(r.states, where, issues, stateIds);
    const transitions = normList(r.transitions, `${where} transition`, FIELDS.transition, issues, "data", (t, tid, at) => {
      const guard = normGuard(t.guard, `${at} guard`, issues);
      return { id: tid, from: fromList(t.from), to: asString(t.to), by: list([t.by].flat()).map((b) => asString(b)).filter(Boolean), step: asString(t.step) || undefined, label: asString(t.label, 80) || undefined, trigger: asString(t.trigger, 200) || undefined, guard, text: normText(t.text, at, issues), ...normProvenance(t, at, issues) };
    }, transitionIds);
    return { id, entity: asString(r.entity), field: asString(r.field, 40) || "state", initial: asString(r.initial) || undefined, states, transitions };
  });

  const sequences = normList(raw.sequences, "sequence", FIELDS.sequence, issues, "data", (r, id, where) => {
    const steps = list(r.steps).map((s) => asString(s)).filter(Boolean);
    if (steps.length < 2) issues.push(issue("error", where, "needs at least two steps: a partial failure needs a write that can succeed before another one fails"));
    let compensation;
    if (r.compensation !== undefined) {
      const at = `${where} compensation`;
      if (!isObject(r.compensation)) issues.push(issue("error", at, "is not an object"));
      else {
        unknownFields(r.compensation, FIELDS.compensation, at, issues, "data");
        if (!COMPENSATION.includes(r.compensation.kind)) issues.push(issue("error", at, `kind must be one of ${COMPENSATION.join(", ")}`));
        compensation = { kind: COMPENSATION.includes(r.compensation.kind) ? r.compensation.kind : "none-found", text: normText(r.compensation.text, at, issues), ...normProvenance(r.compensation, at, issues) };
      }
    }
    let ordering;
    if (r.ordering !== undefined) {
      const at = `${where} ordering`;
      if (!isObject(r.ordering)) issues.push(issue("error", at, "is not an object"));
      else ordering = { text: normText(r.ordering.text, at, issues), ...normProvenance(r.ordering, at, issues) };
    }
    const residue = normList(r.residue, `${where} residue`, FIELDS.residue, issues, "data", (x, rid, at) => ({ id: rid, after: asString(x.after), text: normText(x.text, at, issues), ...normProvenance(x, at, issues) }));
    const uncertainty = normList(r.uncertainty, `${where} uncertainty`, FIELDS.uncertainty, issues, "data", (x, uid, at) => {
      if (!ASPECTS.includes(x.aspect)) issues.push(issue("error", at, `aspect must be one of ${ASPECTS.join(", ")}`));
      return { id: uid, aspect: ASPECTS.includes(x.aspect) ? x.aspect : "atomicity", after: asString(x.after) || undefined, text: normText(x.text, at, issues), ...normProvenance(x, at, issues) };
    });
    return { id, name: asString(r.name, 80) || id, summary: asString(r.summary, 300), steps, ordering, compensation, residue, uncertainty };
  });

  const questions = normList(raw.questions, "question", FIELDS.question, issues, "data", (r, id, where) => ({ id, text: normText(r.text, where, issues), entity: asString(r.entity) || undefined, evidence: normProvenance({ confidence: "unknown", evidence: r.evidence }, where, issues).evidence }));

  return {
    ok: true,
    data: { schemaVersion: DATA_VERSION, title: asString(raw.title, 120), summary: asString(raw.summary, 400), generatedBy: asString(raw.generatedBy, 120), model: normModelRef(raw.model), entities, relations, effects, lifecycles, sequences, questions },
    issues,
  };
}

/** Every citation in the document, with where it is, for the source loaders and the checker. */
export function dataCitations(data) {
  const out = [];
  const add = (where, evidence) => evidence?.length && out.push({ where, evidence });
  for (const e of data.entities) add(`entity ${e.id}`, e.evidence);
  for (const r of data.relations) add(`relation ${r.id}`, r.evidence);
  for (const e of data.effects) add(`effect ${e.id}`, e.evidence);
  for (const l of data.lifecycles) {
    for (const t of l.transitions) {
      add(`transition ${t.id}`, t.evidence);
      add(`transition ${t.id} guard`, t.guard?.evidence);
    }
  }
  for (const s of data.sequences) {
    add(`sequence ${s.id} compensation`, s.compensation?.evidence);
    add(`sequence ${s.id} ordering`, s.ordering?.evidence);
    for (const r of s.residue) add(`residue ${r.id}`, r.evidence);
    for (const u of s.uncertainty) add(`uncertainty ${u.id}`, u.evidence);
  }
  for (const q of data.questions) add(`question ${q.id}`, q.evidence);
  return out;
}

const hasClaim = (c) => c && c.evidence !== undefined;

/** `ctx.sources` has no entry for a file that could not be looked up, and `null` for one that is missing. */
export function checkData(model, data, ctx) {
  const issues = [];
  const entityIds = new Set(data.entities.map((e) => e.id));
  for (const e of data.entities) {
    const p = componentProblem(model, e.store);
    if (p) issues.push(issue("error", `entity ${e.id}`, `store: ${p}`));
  }
  for (const r of data.relations) {
    for (const end of ["from", "to"]) if (!entityIds.has(r[end])) issues.push(issue("error", `relation ${r.id}`, `${end} "${r[end]}" is not an entity of this document`));
  }
  const transitionIds = new Set(data.lifecycles.flatMap((l) => l.transitions.map((t) => t.id)));
  for (const e of data.effects) {
    const where = `effect ${e.id}`;
    const cp = componentProblem(model, e.component);
    if (cp) issues.push(issue("error", where, cp));
    if (e.system) {
      const sp = componentProblem(model, e.system);
      if (sp) issues.push(issue("error", where, `system: ${sp}`));
    }
    if (e.entity && !entityIds.has(e.entity)) issues.push(issue("error", where, `entity "${e.entity}" is not in this document`));
    if (e.step) {
      const p = stepProblem(model, e.step, byId(model.components, e.component) ? e.component : undefined);
      if (p) issues.push(issue("error", where, p));
      else {
        const drift = stepDrift(model, e.step, e.label);
        if (drift) issues.push(issue("warning", where, drift));
      }
    }
    if (e.transition && !transitionIds.has(e.transition)) issues.push(issue("error", where, `transition "${e.transition}" is not in this document`));
  }
  for (const l of data.lifecycles) {
    const where = `lifecycle ${l.id}`;
    if (!entityIds.has(l.entity)) issues.push(issue("error", where, `entity "${l.entity}" is not in this document`));
    if (!l.states.length) issues.push(issue("error", where, "has no states"));
    const states = new Set(l.states.map((s) => s.id));
    if (l.initial && !states.has(l.initial)) issues.push(issue("error", where, `initial state "${l.initial}" is not one of its states`));
    for (const t of l.transitions) {
      const at = `transition ${t.id}`;
      for (const f of t.from) if (f !== null && f !== ANY_STATE && !states.has(f)) issues.push(issue("error", at, `from "${f}" is not a state of ${l.id}`));
      if (!states.has(t.to)) issues.push(issue("error", at, `to "${t.to}" is not a state of ${l.id}`));
      if (!t.by.length) issues.push(issue("error", at, "needs `by`: the component or components that perform it"));
      for (const b of t.by) {
        const cp = componentProblem(model, b);
        if (cp) issues.push(issue("error", at, `by: ${cp}`));
      }
      if (t.step) {
        const p = stepProblem(model, t.step, t.by.filter((b) => byId(model.components, b)));
        if (p) issues.push(issue("error", at, p));
        else {
          const drift = stepDrift(model, t.step, t.label);
          if (drift) issues.push(issue("warning", at, drift));
        }
      }
      if (!t.guard) issues.push(issue("warning", at, "says nothing about its guard; the view shows it as not examined, never as unguarded"));
    }
    for (const s of l.states) if (s.terminal && l.transitions.some((t) => t.from.includes(s.id))) issues.push(issue("warning", `lifecycle ${l.id} state ${s.id}`, "is marked terminal but a transition leaves it"));
  }
  for (const s of data.sequences) {
    const where = `sequence ${s.id}`;
    for (const ref of s.steps) {
      const p = stepProblem(model, ref);
      if (p) issues.push(issue("error", where, p));
    }
    const writes = s.steps.filter((ref) => data.effects.some((e) => e.step === ref && e.op !== "read"));
    if (!writes.length) issues.push(issue("error", where, "none of its steps has a modeled write, so there is nothing to cut between"));
    const nums = s.steps.map((ref) => stepRef(model, ref)).filter(Boolean);
    if (nums.some((x, i) => i > 0 && x.flow.id === nums[i - 1].flow.id && x.step.n <= nums[i - 1].step.n)) issues.push(issue("warning", where, "lists steps out of the order of their flow; the view follows the order listed"));
    for (const ref of s.steps) if (!data.effects.some((e) => e.step === ref)) issues.push(issue("warning", where, `step ${ref} has no modeled effect; any write it performs is outside the partial-failure walk`));
    if (!s.ordering) issues.push(issue("warning", where, "cites no source for the order of its writes; the order shown is only the model's step numbering"));
    for (const r of s.residue) if (!s.steps.includes(r.after)) issues.push(issue("error", `residue ${r.id}`, `after "${r.after}" is not a step of sequence ${s.id}`));
    for (const u of s.uncertainty) if (u.after && !s.steps.includes(u.after)) issues.push(issue("error", `uncertainty ${u.id}`, `after "${u.after}" is not a step of sequence ${s.id}`));
  }
  for (const q of data.questions) if (q.entity && !entityIds.has(q.entity)) issues.push(issue("error", `question ${q.id}`, `is about unknown entity "${q.entity}"`));

  const cites = checkCitations(model, data, dataCitations(data), ctx);
  return { issues: [...issues, ...cites.issues], stale: cites.stale, checked: cites.checked };
}

// Derived views: computed from the authored claims above; nothing here is written in the file. A reference that does not
// resolve is returned in `unresolved` or `broken`, never skipped, so a view can show it.

export const entityName = (data, id) => byId(data.entities, id)?.name ?? id;

export function claimsOf(data) {
  return [...data.entities, ...data.relations, ...data.effects, ...data.lifecycles.flatMap((l) => l.transitions), ...data.lifecycles.flatMap((l) => l.transitions.map((t) => t.guard)), ...data.sequences.flatMap((s) => [s.ordering, s.compensation, ...s.residue, ...s.uncertainty])].filter(hasClaim);
}

/** Rows of the create/read/update/delete matrix for an entity: component -> operations, each with the effects that say so. */
export function crudOf(data, entityId) {
  const by = new Map();
  for (const e of data.effects.filter((x) => x.entity === entityId)) {
    const row = by.get(e.component) ?? { component: e.component, ops: new Map() };
    const cell = row.ops.get(e.op) ?? [];
    cell.push(e);
    row.ops.set(e.op, cell);
    by.set(e.component, row);
  }
  return [...by.values()];
}

/** Where an entity is touched: modeled flow steps grouped by flow, effects on no modeled flow, and effects whose step does not resolve. */
export function touchesOf(model, data, entityId) {
  const effects = data.effects.filter((e) => e.entity === entityId);
  const flows = new Map();
  const unresolved = [];
  for (const e of effects.filter((x) => x.step)) {
    const hit = stepRef(model, e.step);
    if (!hit) {
      unresolved.push(e);
      continue;
    }
    const row = flows.get(hit.flow.id) ?? { flow: hit.flow, steps: new Map() };
    const at = row.steps.get(hit.step.n) ?? { step: hit.step, effects: [] };
    at.effects.push(e);
    row.steps.set(hit.step.n, at);
    flows.set(hit.flow.id, row);
  }
  return {
    effects,
    flows: [...flows.values()].map((f) => ({ flow: f.flow, steps: [...f.steps.values()].sort((a, b) => a.step.n - b.step.n) })),
    offFlow: effects.filter((x) => !x.step),
    unresolved,
  };
}

export function relationsOf(data, entityId) {
  return { out: data.relations.filter((r) => r.from === entityId), in: data.relations.filter((r) => r.to === entityId) };
}

/** What follows from changing an entity: the document's own claims plus the model's relationships of the store's component. */
export function consequencesOf(model, data, entityId) {
  const entity = byId(data.entities, entityId);
  if (!entity) return undefined;
  const touch = touchesOf(model, data, entityId);
  const rel = relationsOf(data, entityId);
  const writers = [...new Set(touch.effects.filter((e) => e.op !== "read").map((e) => e.component))];
  const readers = [...new Set(touch.effects.filter((e) => e.op === "read").map((e) => e.component))].filter((c) => !writers.includes(c));
  const transitions = data.lifecycles.filter((l) => l.entity === entityId).flatMap((l) => l.transitions.map((t) => ({ lifecycle: l, transition: t })));
  const related = [...rel.out.map((r) => ({ relation: r, other: r.to, direction: "out" })), ...rel.in.map((r) => ({ relation: r, other: r.from, direction: "in" }))];
  const impact = byId(model.components, entity.store) ? impactOf(model, { kind: "component", id: entity.store }, { depth: 1 }) : undefined;
  return { entity, writers, readers, transitions, related, flows: touch.flows, offFlow: touch.offFlow, unresolved: touch.unresolved, impact };
}

/** A lifecycle's transitions in the order the modeled flow performs them, then those on no modeled step, then those whose step does not resolve. */
export function lifecycleOrder(model, lifecycle) {
  const hit = (t) => (t.step ? stepRef(model, t.step) : undefined);
  const on = lifecycle.transitions.filter(hit).sort((a, b) => hit(a).step.n - hit(b).step.n);
  const off = lifecycle.transitions.filter((t) => !t.step);
  const broken = lifecycle.transitions.filter((t) => t.step && !hit(t));
  return { onWorkflow: on, offWorkflow: off, broken, all: [...on, ...off, ...broken] };
}

export function stateDegree(lifecycle, stateId) {
  return { in: lifecycle.transitions.filter((t) => t.to === stateId), out: lifecycle.transitions.filter((t) => t.from.includes(stateId) || t.from.includes(ANY_STATE)) };
}

const systemOf = (data, e) => e.system ?? byId(data.entities, e.entity)?.store;

/**
 * The steps of a sequence in the order the document lists them. A unit is a step with at least one write; its systems are
 * the stores the writes name. Steps whose reference does not resolve are `broken`; steps with no modeled write are `silent`.
 */
export function sequenceUnits(model, data, sequence) {
  const units = [];
  const broken = [];
  const silent = [];
  for (const ref of sequence.steps) {
    const hit = stepRef(model, ref);
    if (!hit) {
      broken.push(ref);
      continue;
    }
    const effects = data.effects.filter((e) => e.step === ref);
    const writes = effects.filter((e) => e.op !== "read");
    if (!writes.length) {
      silent.push({ ref, step: hit.step });
      continue;
    }
    units.push({ ref, step: hit.step, effects, writes, systems: [...new Set(writes.map((e) => systemOf(data, e)).filter(Boolean))] });
  }
  return { units, broken, silent };
}

/**
 * The points between two consecutive writes. Each point lists the writes the order puts before and after it, whether the two
 * name different systems (derived from the entities' stores), and the authored claims about what is left behind. It states
 * nothing about which earlier writes took effect or who can see them: atomicity, visibility, concurrency and external
 * failure are each shown as the document's claim, or as not established.
 */
export function partialFailures(model, data, sequence) {
  const { units, broken, silent } = sequenceUnits(model, data, sequence);
  const cuts = [];
  for (let i = 0; i < units.length - 1; i++) {
    const after = units[i];
    const next = units[i + 1];
    cuts.push({
      after,
      next,
      before: units.slice(0, i),
      later: units.slice(i + 2),
      differentSystems: !after.systems.some((s) => next.systems.includes(s)),
      residue: sequence.residue.filter((r) => r.after === after.ref),
      aspects: ASPECTS.map((aspect) => ({ aspect, claims: sequence.uncertainty.filter((u) => u.aspect === aspect && (!u.after || u.after === after.ref)) })),
    });
  }
  return { units, broken, silent, cuts, ordering: sequence.ordering, compensation: sequence.compensation };
}

/** What `p` and `n` walk in the Operations mode: each write, then the join after it. */
export function operationItems(model, data, sequence) {
  const pf = partialFailures(model, data, sequence);
  return pf.units.flatMap((unit, i) => [{ id: unit.ref, kind: "write", unit }, ...(pf.cuts[i] ? [{ id: `cut:${unit.ref}`, kind: "cut", cut: pf.cuts[i] }] : [])]);
}

export const dataCounts = (data) => {
  const claims = claimsOf(data);
  return { total: claims.length, ...Object.fromEntries(CONFIDENCE.map((c) => [c, claims.filter((x) => x.confidence === c).length])) };
};

