import { byId } from "./model.mjs";
import { impactOf } from "./impact.mjs";
import { CONFIDENCE, asString, checkCitations, componentProblem, isObject, issue, list, normList, normModelRef, normProvenance, normText, stepDrift, stepProblem, stepRef, unknownFields } from "./lens.mjs";

export const AUTH_VERSION = 1;
export const AUTH_FILE = ".architecture/auth.json";

export const PRINCIPAL_KINDS = ["person", "service", "automation"];
export const CREDENTIAL_KINDS = ["session", "bearer-token", "capability-url", "api-token", "connection-string", "workflow-token", "signing-key", "other"];
export const AUTHORITY = ["caller", "service", "delegated", "none", "unknown"];
export const CONCERNS = ["authentication", "authorization"];
export const GUARD_KINDS = ["token-verification", "session-check", "role-list", "database-lookup", "owner-scope", "state-check", "ui-gate", "platform", "other"];
export const ENFORCED_AT = ["server", "client", "platform", "unknown"];
export const POLICY_MODES = ["all", "any", "conditional", "unknown"];
export const ANYONE = "*";

const FIELDS = {
  auth: ["schemaVersion", "title", "summary", "generatedBy", "model", "principals", "credentials", "hops", "guards", "operations", "boundaries", "questions"],
  principal: ["id", "name", "kind", "how", "confidence", "evidence"],
  credential: ["id", "name", "kind", "issuedBy", "issuer", "secret", "lifetime", "carried", "confidence", "evidence"],
  hop: ["id", "step", "label", "from", "to", "presents", "seenAs", "authority", "boundary", "text", "confidence", "evidence"],
  guard: ["id", "name", "concern", "kind", "component", "consults", "deny", "enforcedAt", "admits", "text", "confidence", "evidence"],
  operation: ["id", "name", "route", "component", "initiators", "trigger", "policy", "uxGates", "hops", "recorded", "questions"],
  policy: ["mode", "guards", "text", "confidence", "evidence"],
  recorded: ["text", "confidence", "evidence"],
  boundary: ["id", "name", "text", "confidence", "evidence"],
  question: ["id", "text", "operation", "guard", "evidence"],
};

// A document names secrets, never holds them: anything shaped like a credential value is refused.
const SECRET_SHAPES = /(ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|hf_[A-Za-z0-9]{20,}|eyJ[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{8,}|-----BEGIN [A-Z ]*PRIVATE KEY-----|AKIA[0-9A-Z]{16})/;
const SECRET_NAME = /^[A-Za-z_][A-Za-z0-9_.-]{0,63}$/;

const enumOf = (v, allowed, fallback, where, what, issues) => {
  if (v === undefined || v === null || v === "") return fallback;
  if (!allowed.includes(v)) {
    issues.push(issue("error", where, `${what} must be one of ${allowed.join(", ")}`));
    return fallback;
  }
  return v;
};
const idList = (v) => list(v).map((x) => asString(x)).filter(Boolean);

function normClaim(raw, where, issues, allowedKeys) {
  if (!isObject(raw)) {
    issues.push(issue("error", where, "is not an object"));
    return undefined;
  }
  unknownFields(raw, allowedKeys, where, issues, "authorization");
  return { text: normText(raw.text, where, issues), ...normProvenance(raw, where, issues) };
}

export function parseAuth(text) {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (err) {
    return { ok: false, errors: [`Authorization file is not valid JSON: ${err.message}`] };
  }
  if (!isObject(raw) || raw.schemaVersion !== AUTH_VERSION) return { ok: false, errors: [`Authorization file must be an object with schemaVersion ${AUTH_VERSION}`] };
  const issues = [];
  unknownFields(raw, FIELDS.auth, "auth", issues, "authorization");
  const looks = text.match(SECRET_SHAPES);
  if (looks) issues.push(issue("error", "auth", `contains text shaped like a credential value (${looks[0].slice(0, 6)}…); a document names secrets and never holds them`));

  const principals = normList(raw.principals, "principal", FIELDS.principal, issues, "authorization", (r, id, where) => ({ id, name: asString(r.name, 60) || id, kind: enumOf(r.kind, PRINCIPAL_KINDS, "person", where, "kind", issues), how: asString(r.how, 300), ...normProvenance(r, where, issues) }));
  const credentials = normList(raw.credentials, "credential", FIELDS.credential, issues, "authorization", (r, id, where) => {
    const secret = asString(r.secret, 120) || undefined;
    if (secret && !SECRET_NAME.test(secret)) issues.push(issue("error", where, "secret must be the name of a secret or variable, never its value"));
    return { id, name: asString(r.name, 80) || id, kind: enumOf(r.kind, CREDENTIAL_KINDS, "other", where, "kind", issues), issuedBy: asString(r.issuedBy) || undefined, issuer: asString(r.issuer, 160) || undefined, secret, lifetime: asString(r.lifetime, 120) || undefined, carried: asString(r.carried, 200) || undefined, ...normProvenance(r, where, issues) };
  });
  const hops = normList(raw.hops, "hop", FIELDS.hop, issues, "authorization", (r, id, where) => {
    const authority = enumOf(r.authority, AUTHORITY, "unknown", where, "authority", issues);
    if (r.authority === undefined) issues.push(issue("error", where, `needs authority: one of ${AUTHORITY.join(", ")}`));
    const step = asString(r.step) || undefined;
    return { id, step, label: asString(r.label, 80) || undefined, from: asString(r.from), to: asString(r.to), presents: asString(r.presents) || undefined, seenAs: asString(r.seenAs) || undefined, authority, boundary: asString(r.boundary) || undefined, text: normText(r.text, where, issues), ...normProvenance(r, where, issues) };
  });
  const guards = normList(raw.guards, "guard", FIELDS.guard, issues, "authorization", (r, id, where) => {
    let admits;
    if (r.admits === ANYONE) admits = [ANYONE];
    else if (Array.isArray(r.admits)) {
      admits = idList(r.admits);
      if (!admits.length) issues.push(issue("warning", where, `admits an empty list, which says no principal passes it; list the principals it admits, or ["${ANYONE}"] if it does not narrow callers`));
    } else if (r.admits !== undefined) issues.push(issue("error", where, `admits must be "${ANYONE}" or a list of principal ids`));
    return { id, name: asString(r.name, 80) || id, concern: enumOf(r.concern, CONCERNS, "authorization", where, "concern", issues), kind: enumOf(r.kind, GUARD_KINDS, "other", where, "kind", issues), component: asString(r.component), consults: asString(r.consults, 200) || undefined, deny: asString(r.deny, 120) || undefined, enforcedAt: enumOf(r.enforcedAt, ENFORCED_AT, "unknown", where, "enforcedAt", issues), admits, text: normText(r.text, where, issues), ...normProvenance(r, where, issues) };
  });
  const operations = normList(raw.operations, "operation", FIELDS.operation, issues, "authorization", (r, id, where) => {
    let policy;
    if (!isObject(r.policy)) issues.push(issue("error", where, `needs a policy: { mode: ${POLICY_MODES.join(" | ")}, guards, text } (mode "unknown" says no decision was located)`));
    else {
      const at = `${where} policy`;
      unknownFields(r.policy, FIELDS.policy, at, issues, "authorization");
      policy = { mode: enumOf(r.policy.mode, POLICY_MODES, "unknown", at, "mode", issues), guards: idList(r.policy.guards), text: normText(r.policy.text, at, issues), ...normProvenance(r.policy, at, issues) };
    }
    const recorded = r.recorded === undefined ? undefined : normClaim(r.recorded, `${where} recorded`, issues, FIELDS.recorded);
    return { id, name: asString(r.name, 80) || id, route: asString(r.route, 160) || undefined, component: asString(r.component) || undefined, initiators: idList(r.initiators), trigger: asString(r.trigger, 300) || undefined, policy, uxGates: idList(r.uxGates), hops: idList(r.hops), recorded, questions: idList(r.questions) };
  });
  const boundaries = normList(raw.boundaries, "boundary", FIELDS.boundary, issues, "authorization", (r, id, where) => ({ id, name: asString(r.name, 80) || id, text: normText(r.text, where, issues), ...normProvenance(r, where, issues) }));
  const questions = normList(raw.questions, "question", FIELDS.question, issues, "authorization", (r, id, where) => ({ id, text: normText(r.text, where, issues), operation: asString(r.operation) || undefined, guard: asString(r.guard) || undefined, evidence: normProvenance({ confidence: "unknown", evidence: r.evidence }, where, issues).evidence }));

  return { ok: true, auth: { schemaVersion: AUTH_VERSION, title: asString(raw.title, 120), summary: asString(raw.summary, 400), generatedBy: asString(raw.generatedBy, 120), model: normModelRef(raw.model), principals, credentials, hops, guards, operations, boundaries, questions }, issues };
}

export function authCitations(auth) {
  const out = [];
  const add = (where, evidence) => evidence?.length && out.push({ where, evidence });
  for (const x of auth.principals) add(`principal ${x.id}`, x.evidence);
  for (const x of auth.credentials) add(`credential ${x.id}`, x.evidence);
  for (const x of auth.hops) add(`hop ${x.id}`, x.evidence);
  for (const x of auth.guards) add(`guard ${x.id}`, x.evidence);
  for (const o of auth.operations) {
    add(`operation ${o.id} policy`, o.policy?.evidence);
    add(`operation ${o.id} recorded`, o.recorded?.evidence);
  }
  for (const x of auth.boundaries) add(`boundary ${x.id}`, x.evidence);
  for (const q of auth.questions) add(`question ${q.id}`, q.evidence);
  return out;
}

// Wording in an all-of policy's own text that says a check does not run on every path, which `all` cannot say (docs/decisions/010-structured-policy-meaning.md).
// Guard text is not read: "admitted here only if they have a trust row" restricts and does not skip.
const CONDITIONAL_WORDING = /\bonly (?:for|if|when|on|after)\b|\bunless\b|\bskips?\b|\bskipped\b/i;
const REPEAT_MIN = 5;

/** The words of an all-of policy's text that say a check is conditional, or undefined. */
export function conditionalPolicy(policy) {
  const m = policy?.mode === "all" ? CONDITIONAL_WORDING.exec(policy.text ?? "") : null;
  if (!m) return undefined;
  const t = policy.text;
  const from = m.index > 30 ? t.lastIndexOf(" ", m.index - 30) + 1 : 0;
  const end = m.index + m[0].length + 40;
  const to = end < t.length ? Math.max(t.indexOf(" ", end), end) : t.length;
  return `${from ? "…" : ""}${t.slice(from, to)}${to < t.length ? "…" : ""}`;
}

/** How many distinct things the hops state, and how many source lines the observed ones cite. */
export function hopStatements(auth) {
  const groups = new Map();
  for (const h of auth.hops) if (h.text) groups.set(h.text, (groups.get(h.text) ?? 0) + 1);
  const top = [...groups].sort((a, b) => b[1] - a[1])[0];
  const observed = auth.hops.filter((h) => h.confidence === "observed");
  const lines = new Set(observed.flatMap((h) => h.evidence.map((e) => `${e.repo ?? ""}:${e.path}:${e.lines[0]}`)));
  return { hops: auth.hops.length, distinct: groups.size, observed: observed.length, lines: lines.size, repeated: top && top[1] >= REPEAT_MIN ? { text: top[0], count: top[1] } : undefined };
}

/** `ctx.sources` has no entry for a file that could not be looked up, and `null` for one that is missing. */
export function checkAuth(model, auth, ctx) {
  const issues = [];
  const ids = (xs) => new Set(xs.map((x) => x.id));
  const principals = ids(auth.principals);
  const credentials = ids(auth.credentials);
  const hops = ids(auth.hops);
  const guards = ids(auth.guards);
  const boundaries = ids(auth.boundaries);
  const operations = ids(auth.operations);
  const need = (set, id, where, what) => {
    if (!set.has(id)) issues.push(issue("error", where, `${what} "${id}" is not in this document`));
  };

  for (const c of auth.credentials) if (c.issuedBy) {
    const p = componentProblem(model, c.issuedBy);
    if (p) issues.push(issue("error", `credential ${c.id}`, `issuedBy: ${p}`));
  }
  for (const h of auth.hops) {
    const where = `hop ${h.id}`;
    for (const end of ["from", "to"]) {
      const p = componentProblem(model, h[end]);
      if (p) issues.push(issue("error", where, `${end}: ${p}`));
    }
    if (h.step) {
      const p = stepProblem(model, h.step, [h.from, h.to].filter((c) => byId(model.components, c)));
      if (p) issues.push(issue("error", where, p));
      else {
        const drift = stepDrift(model, h.step, h.label);
        if (drift) issues.push(issue("warning", where, drift));
      }
    }
    if (h.presents) need(credentials, h.presents, where, "credential");
    if (h.seenAs) need(principals, h.seenAs, where, "principal");
    if (h.boundary) need(boundaries, h.boundary, where, "boundary");
    if (h.authority === "caller" && !h.seenAs) issues.push(issue("warning", where, "acts as the caller but names no principal the receiving system sees"));
    if (h.authority === "caller" && !h.presents) issues.push(issue("warning", where, "acts as the caller but presents no credential"));
    if (h.authority === "service" && h.seenAs && byId(auth.principals, h.seenAs)?.kind === "person") issues.push(issue("warning", where, `acts under the service's own authority but is seen as the person-class principal "${h.seenAs}"`));
  }
  for (const g of auth.guards) {
    const where = `guard ${g.id}`;
    const p = componentProblem(model, g.component);
    if (p) issues.push(issue("error", where, p));
    for (const a of g.admits ?? []) if (a !== ANYONE) need(principals, a, where, "principal");
    if (g.concern === "authorization" && g.enforcedAt === "server" && g.admits === undefined) issues.push(issue("warning", where, "does not say who it admits, so no caller set can be derived from it; list the principals it admits, or [\"*\"] if it does not narrow callers"));
  }
  for (const o of auth.operations) {
    const where = `operation ${o.id}`;
    if (o.component) {
      const p = componentProblem(model, o.component);
      if (p) issues.push(issue("error", where, p));
    }
    for (const i of o.initiators) need(principals, i, where, "principal");
    for (const h of o.hops) need(hops, h, where, "hop");
    for (const g of o.uxGates) {
      need(guards, g, where, "guard");
      if (byId(auth.guards, g)?.enforcedAt === "server") issues.push(issue("warning", where, `lists "${g}" as a UX gate, but the document says it is enforced on the server`));
    }
    for (const g of o.policy?.guards ?? []) if (byId(auth.guards, g)?.enforcedAt === "client") issues.push(issue("warning", `${where} policy`, `counts the client-side guard "${g}" as enforcement; a client gate belongs in uxGates`));
    for (const q of o.questions) if (!auth.questions.some((x) => x.id === q)) issues.push(issue("error", where, `question "${q}" is not in this document`));
    if (!o.policy) continue;
    for (const g of o.policy.guards) need(guards, g, `${where} policy`, "guard");
    if ((o.policy.mode === "all" || o.policy.mode === "any") && !o.policy.guards.length) issues.push(issue("error", `${where} policy`, `mode "${o.policy.mode}" needs at least one guard; use "unknown" when no decision was located`));
    if (o.policy.mode === "unknown" && o.policy.guards.length) issues.push(issue("warning", `${where} policy`, "is unknown but lists guards; the view does not combine them"));
    const condition = conditionalPolicy(o.policy);
    if (condition) issues.push(issue("warning", `${where} policy`, `is all-of but its text says a check applies only conditionally (“${condition}”); ${admittedBy(auth, o).derived ? "the caller set is still derived because the other limiting guards admit the same classes, but " : "the caller set is not derived; "}use conditional unless each guard runs on every path`));
    if (!o.initiators.length && !o.trigger) issues.push(issue("warning", where, "says neither who initiates it nor what triggers it"));
    if (!o.hops.length) issues.push(issue("warning", where, "lists no hops, so the credentials it executes with are not shown"));
  }
  for (const q of auth.questions) {
    if (q.operation) need(operations, q.operation, `question ${q.id}`, "operation");
    if (q.guard) need(guards, q.guard, `question ${q.id}`, "guard");
  }

  const st = hopStatements(auth);
  const notes = st.repeated ? [`hops: ${st.hops} hops carry ${st.distinct} distinct statements and the ${st.observed} observed ones cite ${st.lines} distinct lines; one statement is on ${st.repeated.count} hops (“${st.repeated.text.length > 70 ? `${st.repeated.text.slice(0, 69)}…` : st.repeated.text}”). Repetition is not an error; a hop count is a count of entries, not of separate findings`] : [];

  const cites = checkCitations(model, auth, authCitations(auth), ctx);
  return { issues: [...issues, ...cites.issues], stale: cites.stale, checked: cites.checked, notes };
}

// Derived views. A reference that does not resolve is returned in `broken`, never skipped.

export const principalName = (auth, id) => byId(auth.principals, id)?.name ?? id;

export function claimsOf(auth) {
  return [...auth.principals, ...auth.credentials, ...auth.hops, ...auth.guards, ...auth.boundaries, ...auth.operations.flatMap((o) => [o.policy, o.recorded])].filter((c) => c && c.evidence !== undefined);
}

export const authCounts = (auth) => {
  const claims = claimsOf(auth);
  return { total: claims.length, ...Object.fromEntries(CONFIDENCE.map((c) => [c, claims.filter((x) => x.confidence === c).length])) };
};

/** Who the guards of an operation admit, derived only from an all-of policy whose guards each say who they admit. */
export function admittedBy(auth, op) {
  const p = op.policy;
  if (!p) return { derived: false, why: "no policy is recorded" };
  if (p.mode !== "all") return { derived: false, why: p.mode === "any" ? "the policy is any-of: each alternative admits its own callers and this view does not combine them" : p.mode === "conditional" ? "the policy is conditional: whether a caller is admitted depends on the condition in its text" : "no authorization decision was located" };
  const found = p.guards.map((g) => byId(auth.guards, g));
  if (found.some((g) => !g)) return { derived: false, why: "a guard it names does not resolve" };
  const silent = found.filter((g) => g.admits === undefined);
  if (silent.length) return { derived: false, why: `${silent.map((g) => g.name).join(", ")} does not say who it admits` };
  const limited = found.filter((g) => !g.admits.includes(ANYONE));
  if (!limited.length) return { derived: true, anyone: true, principals: [] };
  const meet = (gs) => gs.map((g) => g.admits).reduce((a, b) => a.filter((x) => b.includes(x)));
  const common = meet(limited);
  const condition = conditionalPolicy(p);
  if (condition) {
    // The text does not say which check is conditional, so the set is kept only if skipping any one limiting guard leaves it unchanged.
    const needed = limited.filter((g) => limited.length === 1 || meet(limited.filter((x) => x !== g)).length !== common.length);
    if (needed.length) return { derived: false, why: `skipping ${needed.map((g) => g.name).join(", ")} would widen who is admitted, and the policy's text says a check applies only conditionally (“${condition}”), so whether callers who skip it are admitted is not established` };
    return { derived: true, anyone: false, principals: common, note: "the policy's text says a check is conditional; the other limiting guards admit the same classes, so skipping any one of them does not change this set" };
  }
  return { derived: true, anyone: false, principals: common };
}

/** The hops an operation executes with, in order, plus what changes along them. */
export function executionOf(auth, op) {
  const hops = op.hops.map((id) => byId(auth.hops, id)).filter(Boolean);
  const broken = op.hops.filter((id) => !byId(auth.hops, id));
  const credentials = [...new Set(hops.map((h) => h.presents).filter(Boolean))].map((id) => byId(auth.credentials, id)).filter(Boolean);
  const changes = authorityChanges(hops);
  const by = (a) => hops.filter((h) => h.authority === a);
  return { hops, broken, credentials, changes, caller: by("caller"), service: by("service"), delegated: by("delegated"), unknown: by("unknown"), boundaries: [...new Set(hops.map((h) => h.boundary).filter(Boolean))].map((id) => byId(auth.boundaries, id)).filter(Boolean) };
}

/** Joins between consecutive hops where whose authority the receiver sees changes. */
export function authorityChanges(hops) {
  const out = [];
  for (let i = 0; i < hops.length - 1; i++) if (hops[i].authority !== hops[i + 1].authority) out.push({ after: hops[i], next: hops[i + 1], from: hops[i].authority, to: hops[i + 1].authority });
  return out;
}

export const opsUsingGuard = (auth, guardId) => auth.operations.filter((o) => o.policy?.guards.includes(guardId));
export const opsUsingCredential = (auth, credId) => auth.operations.filter((o) => o.hops.some((h) => byId(auth.hops, h)?.presents === credId));
export const opsAtStep = (auth, ref) => auth.operations.filter((o) => o.hops.some((h) => byId(auth.hops, h)?.step === ref));

/** Phases of the model's flow that the hops fall in, in flow order; hops with no step have none. */
export function hopPhases(model, auth) {
  const seen = new Map();
  for (const h of auth.hops) {
    const hit = h.step && stepRef(model, h.step);
    if (!hit) continue;
    const phase = hit.step.phase || "";
    const row = seen.get(phase) ?? { name: phase, first: hit.step.n };
    row.first = Math.min(row.first, hit.step.n);
    seen.set(phase, row);
  }
  return [...seen.values()].sort((a, b) => a.first - b.first).map((p) => p.name).filter(Boolean);
}

/** The hops of the authority flow, in flow order, optionally limited to a phase; hops on no modeled step come last, and broken steps are listed apart. */
export function flowHops(model, auth, phase = null) {
  const hit = (h) => (h.step ? stepRef(model, h.step) : undefined);
  const on = auth.hops.filter(hit).sort((a, b) => hit(a).step.n - hit(b).step.n || auth.hops.indexOf(a) - auth.hops.indexOf(b));
  const off = auth.hops.filter((h) => !h.step);
  const broken = auth.hops.filter((h) => h.step && !hit(h));
  return { hops: phase ? on.filter((h) => hit(h).step.phase === phase) : [...on, ...off], off, broken };
}

/** What follows from changing a guard: the operations that rely on it, how, the steps and components they reach. */
export function consequencesOfGuard(model, auth, guardId) {
  const guard = byId(auth.guards, guardId);
  if (!guard) return undefined;
  const ops = opsUsingGuard(auth, guardId);
  const hops = [...new Set(ops.flatMap((o) => o.hops))].map((id) => byId(auth.hops, id)).filter(Boolean);
  const steps = [...new Set(hops.map((h) => h.step).filter(Boolean))].filter((ref) => stepRef(model, ref));
  const components = [...new Set([guard.component, ...hops.flatMap((h) => [h.from, h.to])])];
  const impact = byId(model.components, guard.component) ? impactOf(model, { kind: "component", id: guard.component }, { depth: 1 }) : undefined;
  return { guard, operations: ops, steps, components, impact };
}

export function consequencesOfCredential(model, auth, credId) {
  const credential = byId(auth.credentials, credId);
  if (!credential) return undefined;
  const hops = auth.hops.filter((h) => h.presents === credId);
  return { credential, hops, operations: opsUsingCredential(auth, credId), components: [...new Set(hops.flatMap((h) => [h.from, h.to]))], steps: [...new Set(hops.map((h) => h.step).filter(Boolean))].filter((ref) => stepRef(model, ref)) };
}

/** The authority-flow selection: the phases that have hops, the phase shown (the first operation's by default, or all), and its hops. */
export function flowSelection(model, auth, sel = {}) {
  const phases = hopPhases(model, auth);
  const first = auth.operations.flatMap((o) => o.hops).map((id) => byId(auth.hops, id)).find((h) => h?.step && stepRef(model, h.step));
  const fallback = first ? stepRef(model, first.step).step.phase || null : null;
  const phase = sel.phase === "*" ? null : phases.includes(sel.phase) ? sel.phase : fallback && phases.includes(fallback) ? fallback : null;
  return { phases, phase, ...flowHops(model, auth, phase) };
}

