import { byId } from "./model.mjs";
import { CONFIDENCE, asString, checkCitations, componentProblem, isObject, issue, list, normEvidence, normList, normModelRef, normText, stepProblem, unknownFields, weakestOf } from "./lens.mjs";

export const COVERAGE_VERSION = 1;
export const COVERAGE_FILE = ".architecture/coverage.json";

// What the inventory says about an item, relative to the documents of this model. None of these says the item exists or does not exist beyond what it cites.
export const STATUS = ["modeled", "unmodeled", "unresolved", "outside"];
export const STATUS_TEXT = {
  modeled: "modeled",
  unmodeled: "discovered, not modeled",
  unresolved: "investigated, unresolved",
  outside: "outside scope or not investigated",
};
export const ITEM_KINDS = ["entry-point", "writer", "reader", "enforcement", "variant", "other"];
export const DEPTH = ["read", "searched"];
export const REF_KINDS = ["component", "flow", "step", "operation", "guard", "entity", "transition"];

const FIELDS = {
  coverage: ["schemaVersion", "title", "summary", "generatedBy", "model", "scope", "inventory"],
  scope: ["statement", "sources", "denominator"],
  source: ["repo", "path", "depth", "note"],
  denominator: ["method", "limits"],
  item: ["id", "name", "kind", "status", "text", "modeledAs", "relatesTo", "reason", "confidence", "evidence"],
  ref: ["kind", "id", "label"],
};

const enumOf = (v, allowed, fallback, where, what, issues) => {
  if (v === undefined || v === null || v === "") return fallback;
  if (!allowed.includes(v)) {
    issues.push(issue("error", where, `${what} must be one of ${allowed.join(", ")}`));
    return fallback;
  }
  return v;
};

function normRefs(raw, where, what, issues) {
  const out = [];
  for (const [i, r] of list(raw).entries()) {
    const at = `${where} ${what} ${i + 1}`;
    if (!isObject(r)) {
      issues.push(issue("error", at, "is not an object"));
      continue;
    }
    unknownFields(r, FIELDS.ref, at, issues, "coverage");
    const kind = REF_KINDS.includes(r.kind) ? r.kind : undefined;
    const id = asString(r.id);
    if (!kind || !id) {
      issues.push(issue("error", at, [!kind && `kind must be one of ${REF_KINDS.join(", ")}`, !id && "needs an id"].filter(Boolean).join("; ")));
      continue;
    }
    out.push({ kind, id, label: asString(r.label, 80) || undefined });
  }
  return out;
}

export function parseCoverage(text) {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (err) {
    return { ok: false, errors: [`Coverage file is not valid JSON: ${err.message}`] };
  }
  if (!isObject(raw) || raw.schemaVersion !== COVERAGE_VERSION) return { ok: false, errors: [`Coverage file must be an object with schemaVersion ${COVERAGE_VERSION}`] };
  const issues = [];
  unknownFields(raw, FIELDS.coverage, "coverage", issues, "coverage");

  let scope;
  if (!isObject(raw.scope)) issues.push(issue("error", "scope", "needs scope: { statement, sources, denominator }"));
  else {
    unknownFields(raw.scope, FIELDS.scope, "scope", issues, "coverage");
    const statement = normText(raw.scope.statement, "scope statement", issues, true, 600);
    const sources = list(raw.scope.sources).flatMap((s, i) => {
      const at = `scope source ${i + 1}`;
      if (!isObject(s)) {
        issues.push(issue("error", at, "is not an object"));
        return [];
      }
      unknownFields(s, FIELDS.source, at, issues, "coverage");
      const path = asString(s.path);
      if (!path || path.startsWith("/") || path.split("/").includes("..")) {
        issues.push(issue("error", at, `path "${path}" must be relative and stay inside its repository`));
        return [];
      }
      return [{ repo: asString(s.repo) || undefined, path, depth: enumOf(s.depth, DEPTH, "searched", at, "depth", issues), note: asString(s.note, 160) || undefined }];
    });
    let denominator;
    if (!isObject(raw.scope.denominator)) issues.push(issue("error", "scope", "needs denominator: { method, limits }, saying how the inventory was built and what it cannot rule out"));
    else {
      unknownFields(raw.scope.denominator, FIELDS.denominator, "scope denominator", issues, "coverage");
      denominator = { method: normText(raw.scope.denominator.method, "scope denominator method", issues, true, 600), limits: list(raw.scope.denominator.limits).map((l) => asString(l, 300)).filter(Boolean) };
      if (!denominator.limits.length) issues.push(issue("warning", "scope denominator", "states no limits; an inventory built by search cannot rule out what the search could not see"));
    }
    scope = { statement, sources, denominator };
  }

  const inventory = normList(raw.inventory, "item", FIELDS.item, issues, "coverage", (r, id, where) => {
    const status = enumOf(r.status, STATUS, "unresolved", where, "status", issues);
    if (r.status === undefined) issues.push(issue("error", where, `needs status: one of ${STATUS.join(", ")}`));
    const evidence = normEvidence(r.evidence, where, issues);
    const modeledAs = normRefs(r.modeledAs, where, "modeledAs", issues);
    const reason = asString(r.reason, 300) || undefined;
    const claimsExistence = status === "unmodeled" || status === "unresolved";
    let confidence = CONFIDENCE.includes(r.confidence) ? r.confidence : "unknown";
    if (claimsExistence && !CONFIDENCE.includes(r.confidence)) issues.push(issue("warning", where, `confidence "${r.confidence ?? ""}" is not observed, inferred or unknown; treated as unknown`));
    if (confidence === "observed" && !evidence.length) {
      issues.push(issue("error", where, "is marked observed but cites no source"));
      confidence = "unknown";
    }
    if (status === "modeled" && !modeledAs.length) issues.push(issue("error", where, "is marked modeled but names no element of the model or the documents that represents it (modeledAs)"));
    if (status !== "modeled" && modeledAs.length) issues.push(issue("error", where, `is marked ${status} but names modeledAs elements; a modeled item has status "modeled"`));
    if (claimsExistence && !evidence.length) issues.push(issue("error", where, `is marked ${status}: the source that identifies it must be cited`));
    if ((status === "unresolved" || status === "outside") && !reason) issues.push(issue("error", where, status === "unresolved" ? "needs a reason: what was examined and what stays uncertain" : "needs a reason: why no coverage claim is made"));
    return {
      id,
      name: asString(r.name, 100) || id,
      kind: enumOf(r.kind, ITEM_KINDS, "other", where, "kind", issues),
      status,
      text: normText(r.text, where, issues, true, 400),
      modeledAs,
      relatesTo: normRefs(r.relatesTo, where, "relatesTo", issues),
      reason,
      confidence,
      evidence,
    };
  });

  return { ok: true, coverage: { schemaVersion: COVERAGE_VERSION, title: asString(raw.title, 120), summary: asString(raw.summary, 400), generatedBy: asString(raw.generatedBy, 120), model: normModelRef(raw.model), scope, inventory }, issues };
}

export function coverageCitations(cov) {
  return cov.inventory.filter((x) => x.evidence.length).map((x) => ({ where: `item ${x.id}`, evidence: x.evidence }));
}

/** The source paths the scope claims to have looked at, as `{ repo, path }`, for the host to test for existence. */
export const coveragePaths = (cov) => (cov.scope?.sources ?? []).map((s) => ({ repo: s.repo, path: s.path }));

/** How a reference is looked up: the model, or the authorization / data documents when they are loaded. */
function lookup(model, docs, ref) {
  switch (ref.kind) {
    case "component":
      return { found: byId(model.components, ref.id), doc: "model" };
    case "flow":
      return { found: byId(model.flows, ref.id), doc: "model" };
    case "step":
      return { found: !stepProblem(model, ref.id), doc: "model" };
    case "operation":
      return { found: docs?.auth ? byId(docs.auth.operations, ref.id) : undefined, doc: "auth", absent: !docs?.auth };
    case "guard":
      return { found: docs?.auth ? byId(docs.auth.guards, ref.id) : undefined, doc: "auth", absent: !docs?.auth };
    case "entity":
      return { found: docs?.data ? byId(docs.data.entities, ref.id) : undefined, doc: "data", absent: !docs?.data };
    case "transition":
      return { found: docs?.data ? docs.data.lifecycles.flatMap((l) => l.transitions).find((t) => t.id === ref.id) : undefined, doc: "data", absent: !docs?.data };
    default:
      return { found: undefined, doc: "model" };
  }
}

/** `ctx.sources` as for the other lens documents; `ctx.docs` holds the loaded `auth` and `data` documents; `ctx.paths` maps `repo:path` to whether it exists (absent when it could not be tested). */
export function checkCoverage(model, cov, ctx) {
  const issues = [];
  const declared = new Set(model.project.repositories.map((r) => r.id));
  const unverified = new Set();

  const checkRef = (where, ref) => {
    const hit = lookup(model, ctx.docs, ref);
    if (hit.absent) unverified.add(hit.doc);
    else if (!hit.found) issues.push(issue("error", where, `${ref.kind} "${ref.id}" is not in ${hit.doc === "model" ? "the model" : `the ${hit.doc} document`}`));
  };
  for (const item of cov.inventory) {
    const where = `item ${item.id}`;
    for (const r of item.modeledAs) checkRef(`${where} modeledAs`, r);
    for (const r of item.relatesTo) checkRef(`${where} relatesTo`, r);
  }
  for (const doc of unverified) issues.push(issue("warning", "verification", `references into the ${doc} document could not be checked because it is not loaded`));

  let untested = 0;
  for (const s of cov.scope?.sources ?? []) {
    const where = `scope source ${s.path}`;
    if (declared.size && !s.repo) issues.push(issue("error", where, "names no repository, and the model declares repositories"));
    else if (s.repo && !declared.has(s.repo)) issues.push(issue("error", where, `names repository "${s.repo}", which the model does not declare`));
    const seen = ctx.paths?.get(`${s.repo ?? ""}:${s.path}`);
    if (seen === false) issues.push(issue("error", where, "does not exist in the checkout"));
    else if (seen === undefined) untested++;
  }
  if (untested) issues.push(issue("warning", "verification", `${untested} scope source path${untested === 1 ? "" : "s"} could not be tested for existence, so the scope is unverified`));

  if (ctx.docs?.auth) {
    const listed = new Set(cov.inventory.flatMap((x) => [...x.modeledAs, ...x.relatesTo]).filter((r) => r.kind === "operation").map((r) => r.id));
    const missing = ctx.docs.auth.operations.filter((o) => !listed.has(o.id));
    if (missing.length) issues.push(issue("warning", "inventory", `${missing.length} modeled operation${missing.length === 1 ? " is" : "s are"} not in the inventory (${missing.slice(0, 5).map((o) => o.id).join(", ")}${missing.length > 5 ? ", …" : ""}); the inventory is incomplete as a denominator`));
  }

  const cites = checkCitations(model, cov, coverageCitations(cov), ctx);
  return { issues: [...issues, ...cites.issues], stale: cites.stale, checked: cites.checked };
}

export function coverageCounts(cov) {
  const counts = Object.fromEntries(STATUS.map((s) => [s, cov.inventory.filter((x) => x.status === s).length]));
  return { total: cov.inventory.length, ...counts };
}

/** Items that name `ref` in `relatesTo` or `modeledAs`. A reference that does not resolve still matches by id. */
export const itemsFor = (cov, kind, id) => cov.inventory.filter((x) => [...x.relatesTo, ...x.modeledAs].some((r) => r.kind === kind && r.id === id));

/** Items whose citations name this file; matching is by repository and path only. */
export const itemsCiting = (cov, repo, path) => cov.inventory.filter((x) => x.evidence.some((e) => e.path === path && (e.repo ?? "") === (repo ?? "")));

/** Items that are not modeled and cite a changed file the model does cover; `uncovered` files are listed with their own items elsewhere. Matched by repository and path only. */
export function itemsBesideChanges(cov, files, uncovered) {
  const key = (f) => `${f.repo ?? ""}\0${f.path}`;
  const skip = new Set(uncovered.map(key));
  const out = new Map();
  for (const f of files) {
    if (skip.has(key(f))) continue;
    for (const item of itemsCiting(cov, f.repo, f.path)) {
      if (item.status === "modeled") continue;
      const hit = out.get(item.id) ?? { item, files: [] };
      if (!hit.files.some((x) => key(x) === key(f))) hit.files.push(f);
      out.set(item.id, hit);
    }
  }
  return [...out.values()];
}

/** The weakest claim among the elements that represent a modeled item; unresolved references count as unknown. */
export function modeledStrength(model, docs, item) {
  const levels = item.modeledAs.map((ref) => {
    const hit = lookup(model, docs, ref).found;
    if (!hit) return "unknown";
    const c = ref.kind === "operation" ? hit.policy?.confidence : hit.confidence;
