export const PREFLIGHT_SKILL = "architecture-preflight";

const short = (rev) => String(rev ?? "").slice(0, 12);

/** The model, workspace and checkouts the pane resolved, as absolute paths; null when no model is loaded. */
export function architectureContext(status) {
