export function contextInstruction(context) {
  const repos = context.repositories.map((r) => `${r.id}: ${r.root ?? "no checkout"} (${r.state}${r.head ? `, at ${short(r.head)}` : ""}${r.state !== "ok" && r.message ? `; ${r.message}` : ""})`);
