    "Architecture context resolved by Sidecar, the model the pane has loaded. Use exactly these inputs; do not look for another model or workspace, and do not fall back to .architecture/model.json:",
    `Model: ${context.model}`,
    workspace,
    `Project root: ${context.root}`,
    ...(repos.length ? [`Repositories: ${repos.join("; ")}`] : []),
    `Read the model from that path and open repository evidence under those checkouts. Run check-review.mjs on the evidence file by absolute path with ${checkerOptions(context)}.`,
    "If you cannot read the model or a checkout at those paths (permission or sandbox denial, outside the allowed directories), report a model or checkout access problem and name the path. Do not say that no model exists and do not suggest rebuilding it.",
  ].join("\n");
}

/** How far the loaded model can be trusted for this checkout: `{ state, usable, line, context }`, with `line` the instruction Claude receives. */
export function modelBriefing(status, head) {
  if (status?.kind === "missing") {
    const where = (status.searched ?? []).join(", ");
    return { state: "missing", usable: false, line: `There is no architecture model${where ? ` (looked in ${where})` : ""}. Do not build one. Say plainly that modeled evidence is unavailable and answer from the specification and a bounded reading of the source.` };
  }
