    const why = (status?.errors ?? []).slice(0, 2).join("; ") || status?.message || "it could not be read";
    return { state: "invalid", usable: false, line: `The architecture model cannot be used (${why}). Do not repair or rebuild it. Say plainly that modeled evidence is unavailable and answer from the specification and a bounded reading of the source.` };
