export const EXPLORE_VERSION = 1;
export const EXPLORE_FILE = ".architecture/explore.json";

const SUPPORTS = ["spec", "source", "hypothesis"];
const STATUSES = ["meets", "conflicts", "unclear"];
const PLACEMENT_KINDS = ["insert", "change"];
const ANSWERERS = ["spec", "source", "other"];
const OUTCOMES = ["selected", "deferred", "needs-clarification"];
const KINDS = ["component", "relationship", "step"];
const MIN_QUOTE = 10;
const NO_REVIEW = { proposed: { components: [], relationships: [] } };

