  spec: ["path", "fingerprint"],
  requirement: ["id", "summary", "cite"],
  question: ["text", "flow", "steps"],
  constraint: ["id", "text", "cite"],
  premise: ["id", "kind", "statement", "cite", "evidence", "about"],
  evidence: ["repo", "path", "lines", "quote", "note"],
  alternative: ["id", "name", "summary", "placements", "effects", "checks", "assumptions"],
  placement: ["id", "kind", "step", "after", "from", "to", "text"],
  effect: ["id", "text", "support", "premises"],
  check: ["constraint", "status", "why", "premises"],
  unresolved: ["id", "answeredBy", "text", "cite", "evidence", "blocks"],
  decision: ["status", "alternative", "note", "by"],
};
