const isObject = (v) => v && typeof v === "object" && !Array.isArray(v);
const unsafePath = (p) => !p || p.startsWith("/") || p.split("/").includes("..");
const safeId = (id) => /^[A-Za-z0-9._-]{1,24}$/.test(id);

export const stepNumber = (ref) => Number(String(ref).split("#")[1]);
// A step reference counts only in the flow the question is about; another flow's step number says nothing about this one.
export const inFlow = (ex, ref) => String(ref).split("#")[0] === ex.question.flow;

function unknownFields(raw, kind, where, issues) {
  if (!isObject(raw)) return;
  for (const key of Object.keys(raw)) {
    if (key === "confidence" && NO_CONFIDENCE.includes(kind)) issues.push(issue("error", where, "carries a confidence; hypothetical architecture has none (observed, inferred and unknown describe what exists)"));
