  unknownFields(raw, "exploration", "exploration", issues);
  const specPath = asString(raw.spec?.path);
  if (unsafePath(specPath)) return { ok: false, errors: ["exploration.spec.path must name the specification relative to the project root (no leading / and no ..)"], issues };
  unknownFields(raw.spec, "spec", "spec", issues);

  const model = isObject(raw.model) ? raw.model : {};
  const repositories = {};
  for (const [id, rev] of Object.entries(isObject(model.repositories) ? model.repositories : {})) repositories[id] = asString(rev);

  const req = isObject(raw.requirement) ? raw.requirement : {};
  unknownFields(req, "requirement", "requirement", issues);
  const requirement = { id: asString(req.id, 40), summary: asString(req.summary, 300), cite: normCite(req.cite, "requirement", issues, true) };
  if (!requirement.id) issues.push(issue("error", "requirement", "names no requirement id"));

  const q = isObject(raw.question) ? raw.question : {};
  unknownFields(q, "question", "question", issues);
  const question = { text: asString(q.text, 400), flow: asString(q.flow), steps: list(q.steps).map((s) => asString(s)).filter(Boolean) };
  if (!question.text) issues.push(issue("error", "question", "states no design question"));
  if (!question.flow || !question.steps.length) issues.push(issue("error", "question", "needs the model flow and the steps of that flow it is about"));

  const constraintIds = new Set();
  const constraints = [];
  for (const [i, c] of list(raw.constraints).entries()) {
    const where = `constraint ${asString(c?.id) || i + 1}`;
    const id = unique(c, constraintIds, where, issues);
    if (!id) continue;
    unknownFields(c, "constraint", where, issues);
    constraints.push({ id, text: asString(c.text, 300), cite: normCite(c.cite, where, issues, true) });
  }

  const premiseIds = new Set();
  const premises = [];
  for (const [i, p] of list(raw.premises).entries()) {
    const where = `premise ${asString(p?.id) || i + 1}`;
    const id = unique(p, premiseIds, where, issues);
    if (!id) continue;
    unknownFields(p, "premise", where, issues);
    const kind = asString(p.kind);
    if (kind !== "spec" && kind !== "source") {
      issues.push(issue("error", where, 'kind must be "spec" (the specification states it) or "source" (read in cited source); skipped'));
      continue;
    }
    const cite = kind === "spec" ? normCite(p.cite, where, issues, true) : undefined;
    const evidence = kind === "source" ? normEvidence(p.evidence, where, issues) : [];
    if (kind === "source" && !evidence.length) {
      issues.push(issue("error", where, "is a source premise but cites no source (path, lines and a verbatim quote); skipped"));
      continue;
    }
    premises.push({ id, kind, statement: asString(p.statement, 400), cite, evidence, about: list(p.about).map((r, k) => normRef(r, `${where} about ${k + 1}`, issues)).filter(Boolean) });
  }

  const altIds = new Set();
  const placementIds = new Set();
  const alternatives = [];
  for (const [i, a] of list(raw.alternatives).entries()) {
    const where = `alternative ${asString(a?.id) || i + 1}`;
    const id = unique(a, altIds, where, issues);
    if (!id) continue;
    unknownFields(a, "alternative", where, issues);
    const placements = [];
    for (const [k, pl] of list(a.placements).entries()) {
      const at = `${where} placement ${asString(pl?.id) || k + 1}`;
      const pid = unique(pl, placementIds, at, issues);
      if (!pid) continue;
      unknownFields(pl, "placement", at, issues);
      if (pid.length > 8) issues.push(issue("warning", at, "id is long for a diagram tag; 8 characters or fewer read best"));
      const kind = asString(pl.kind);
      if (!PLACEMENT_KINDS.includes(kind)) {
        issues.push(issue("error", at, `kind must be one of ${PLACEMENT_KINDS.join(", ")}; skipped`));
        continue;
      }
      const text = asString(pl.text, 200);
      const base = { id: pid, kind, text };
      if (!text) issues.push(issue("error", at, "says nothing about what is proposed"));
      if (kind === "insert") {
        const after = asString(pl.after);
        const from = asString(pl.from);
        const to = asString(pl.to);
        if (!after || !from || !to) {
          issues.push(issue("error", at, 'an "insert" needs after (the step it follows), from and to (existing components); skipped'));
          continue;
        }
        placements.push({ ...base, after, from, to });
      } else {
        const step = asString(pl.step);
        if (!step) {
          issues.push(issue("error", at, 'a "change" needs step (the existing step it changes); skipped'));
          continue;
        }
        placements.push({ ...base, step });
      }
    }
    const effects = [];
    const effectIds = new Set();
    for (const [k, e] of list(a.effects).entries()) {
      const at = `${where} effect ${asString(e?.id) || k + 1}`;
      const eid = unique(e, effectIds, at, issues);
      if (!eid) continue;
      unknownFields(e, "effect", at, issues);
      let support = asString(e.support);
      if (!SUPPORTS.includes(support)) {
        issues.push(issue("warning", at, `support is not one of ${SUPPORTS.join(", ")}; treated as hypothesis`));
        support = "hypothesis";
      }
      effects.push({ id: eid, text: asString(e.text, 400), support, premises: list(e.premises).map((x) => asString(x)).filter(Boolean) });
    }
    const checks = [];
    for (const [k, c] of list(a.checks).entries()) {
      const at = `${where} check ${asString(c?.constraint) || k + 1}`;
      unknownFields(c, "check", at, issues);
      let status = asString(c?.status);
      if (!STATUSES.includes(status)) {
        issues.push(issue("warning", at, `status is not one of ${STATUSES.join(", ")}; treated as unclear`));
        status = "unclear";
      }
      checks.push({ constraint: asString(c?.constraint), status, why: asString(c?.why, 500), premises: list(c?.premises).map((x) => asString(x)).filter(Boolean) });
    }
    alternatives.push({ id, name: asString(a.name, 80) || id, summary: asString(a.summary, 400), placements, effects, checks, assumptions: list(a.assumptions).map((x) => asString(x, 300)).filter(Boolean) });
  }

  const openIds = new Set();
  const unresolved = [];
  for (const [i, u] of list(raw.unresolved).entries()) {
    const where = `unresolved ${asString(u?.id) || i + 1}`;
    const id = unique(u, openIds, where, issues);
    if (!id) continue;
    unknownFields(u, "unresolved", where, issues);
    let answeredBy = asString(u.answeredBy);
    if (!ANSWERERS.includes(answeredBy)) {
      issues.push(issue("warning", where, `answeredBy is not one of ${ANSWERERS.join(", ")}; treated as other`));
      answeredBy = "other";
    }
    unresolved.push({ id, answeredBy, text: asString(u.text, 500), cite: normCite(u.cite, where, issues, false), evidence: normEvidence(u.evidence, where, issues), blocks: list(u.blocks).map((x) => asString(x)).filter(Boolean) });
  }

  let decision = null;
  if (raw.decision !== undefined && raw.decision !== null) {
    unknownFields(raw.decision, "decision", "decision", issues);
    const status = asString(raw.decision?.status);
    if (OUTCOMES.includes(status)) decision = { status, alternative: asString(raw.decision.alternative) || undefined, note: asString(raw.decision.note, 400), by: asString(raw.decision.by, 80) || undefined };
    else issues.push(issue("error", "decision", `status must be one of ${OUTCOMES.join(", ")}; the decision was ignored`));
  }

  return {
    ok: true,
    errors: [],
    issues,
    exploration: {
      schemaVersion: EXPLORE_VERSION,
      title: asString(raw.title, 140),
      summary: asString(raw.summary, 500),
      generatedBy: asString(raw.generatedBy, 140),
      spec: { path: specPath, fingerprint: asString(raw.spec.fingerprint) || undefined },
      model: { name: asString(model.name, 60), revisions: Object.keys(repositories).length ? repositories : model.revision === undefined ? undefined : { "": asString(model.revision) }, fingerprint: asString(model.fingerprint) || undefined },
      limits: list(raw.limits).map((x) => asString(x, 500)).filter(Boolean),
      requirement,
      question,
      constraints,
      premises,
      alternatives,
      unresolved,
      decision,
    },
  };
}

const sameRevisions = (a, b) => Object.keys({ ...a, ...b }).every((k) => (a[k] ?? "") === (b[k] ?? ""));
const showRevisions = (r) => Object.entries(r ?? {}).map(([k, v]) => `${k ? `${k} ` : ""}${v ? v.slice(0, 12) : "none"}`).join(", ") || "none";

/** Ids that belong to the exploration's own proposal and must never be mistaken for model elements. */
const proposedIds = (ex) => new Set([...ex.alternatives.flatMap((a) => a.placements.map((p) => p.id)), ...ex.alternatives.map((a) => a.id)]);

/** Compare an exploration with the specification, model and checkout as they are now; `failed` holds the premises whose citations did not hold or could not be checked, `unchecked` only the latter. */
export function checkExplore(model, ex, ctx) {
  const issues = [];
  const stale = [];
  const failed = new Set();
  const unchecked = new Set();
  const flow = byId(model.flows, ex.question.flow);
  const specLines = typeof ctx.specText === "string" ? textLines(ctx.specText) : undefined;
  const proposed = proposedIds(ex);
  const declared = new Set(model.project.repositories.map((r) => r.id));
  const premiseById = new Map(ex.premises.map((p) => [p.id, p]));
  const count = { total: 0, read: 0, confirmed: 0 };

  if (!ex.spec.fingerprint) stale.push({ kind: "spec-unrecorded", message: "The exploration records no fingerprint of the specification, so a later change to it cannot be detected." });
  else if (typeof ctx.specText !== "string") stale.push({ kind: "spec-missing", message: `The specification ${ex.spec.path} could not be read; the exploration may be out of date.` });
  else if (fingerprint(ctx.specText) !== ex.spec.fingerprint) stale.push({ kind: "spec-changed", message: `The specification ${ex.spec.path} changed since this exploration was written; its quotes and reading may be stale.` });

  const now = modelRevisions(model);
  if (!ex.model.revisions) stale.push({ kind: "model-unrecorded", message: "The exploration records no model revision, so a later model refresh cannot be detected." });
  else if (!sameRevisions(ex.model.revisions, now)) stale.push({ kind: "model-revision", message: `The model is now at ${showRevisions(now)}; this exploration was written against ${showRevisions(ex.model.revisions)}. It may be stale.` });
  else if (ex.model.fingerprint && ctx.modelFingerprint && ex.model.fingerprint !== ctx.modelFingerprint) stale.push({ kind: "model-changed", message: "The model file changed since this exploration was written (same revision); it may be stale." });
  else if (!ex.model.fingerprint) stale.push({ kind: "model-unrecorded", message: "The exploration records no fingerprint of the model file, so edits to the model cannot be detected." });

  if (ctx.head && !declared.size && /^[0-9a-f]{7,}$/i.test(model.project.revision ?? "")) {
    const a = model.project.revision.toLowerCase();
    const b = ctx.head.toLowerCase();
    if (!(b.startsWith(a) || a.startsWith(b))) stale.push({ kind: "source-revision", message: `The checkout is at ${ctx.head.slice(0, 12)}; the cited source was read at ${model.project.revision.slice(0, 12)}. Cited lines may have moved.` });
  }
  for (const [repo, co] of ctx.checkouts ?? []) if (declared.size && co.state !== "ok") stale.push({ kind: "source-revision", message: `Repository ${repo}: ${co.message || co.state}. Cited lines may have moved.` });

  const cite = (c, where) => {
    if (!c) return false;
    count.total += 1;
    if (!specLines) return undefined;
    count.read += 1;
    const problem = citeProblem(c, specLines, "specification");
    if (problem) issues.push(issue("error", where, `citation ${c.lines[0]}-${c.lines[1]}: ${problem}`));
    else count.confirmed += 1;
    return Boolean(problem);
  };
  const ref = (r, where) => {
    const res = resolveRef(model, NO_REVIEW, r);
    if (!res.ok) issues.push(issue("error", where, proposed.has(r.id) ? `${r.kind} "${r.id}" is proposed by this exploration, not in the model, so it cannot be presented as existing architecture` : `${r.kind} "${r.id}" is not in the model`));
    else if (r.label && !res.label.toLowerCase().includes(r.label.toLowerCase())) issues.push(issue("warning", where, `${r.kind} "${r.id}" was recorded as “${r.label}”; the model now calls it “${res.label}”`));
  };
  // A step reference names a step of the one flow the question is about: another flow's step is a wrong anchor.
  const stepRef = (s, where) => {
    const [flowId, n] = String(s).split("#");
    const masquerade = proposed.has(String(s)) || proposed.has(flowId) || proposed.has(n);
    const missing = masquerade ? `"${s}" is proposed by this exploration, not a step of the model` : `step "${s}" is not in the model`;
    if (flowId !== ex.question.flow) {
      issues.push(issue("error", where, byId(model.flows, flowId) ? `step "${s}" belongs to flow "${flowId}", not to "${ex.question.flow}", the flow this question is about` : missing));
      return;
    }
    if (!flow?.steps.some((x) => x.n === Number(n))) issues.push(issue("error", where, missing));
  };
  const source = (ev, where) => {
    if (ev.repo && !declared.has(ev.repo)) {
      issues.push(issue("error", where, `names repository "${ev.repo}", which the model does not declare`));
      return "bad";
    }
    if (declared.size && !ev.repo) {
      issues.push(issue("error", where, "names no repository, and the model declares several"));
      return "bad";
    }
    count.total += 1;
    const key = pathKey(ev);
    if (!ctx.sources?.has(key)) return "unread";
    count.read += 1;
    const text = ctx.sources.get(key);
    if (text === null) {
      issues.push(issue("error", where, `${ev.path} does not exist in the checkout`));
      return "bad";
    }
    const problem = citeProblem(ev, textLines(text), ev.path);
    if (problem) {
      issues.push(issue("error", where, `${ev.path}:${ev.lines[0]}-${ev.lines[1]}: ${problem}`));
      return "bad";
    }
    count.confirmed += 1;
    return "ok";
  };

  if (!flow) issues.push(issue("error", "question", `the model has no flow "${ex.question.flow}"`));
  else ex.question.steps.forEach((s, i) => stepRef(s, `question step ${i + 1}`));
  cite(ex.requirement.cite, `requirement ${ex.requirement.id}`);
  for (const c of ex.constraints) cite(c.cite, `constraint ${c.id}`);

  const unread = new Set();
  for (const p of ex.premises) {
    const where = `premise ${p.id}`;
    let bad = false;
    let open = false;
    if (p.kind === "spec") {
      const r = cite(p.cite, where);
      if (r === undefined) open = true;
      else bad = r;
    }
    for (const ev of p.evidence) {
      const r = source(ev, where);
      if (r === "bad") bad = true;
      else if (r === "unread") {
        unread.add(ev.repo ?? "");
        open = true;
      }
    }
    for (const r of p.about) ref(r, `${where} about`);
    if (bad) failed.add(p.id);
    else if (open) unchecked.add(p.id);
  }
  for (const u of ex.unresolved) {
    const where = `unresolved ${u.id}`;
    cite(u.cite, where);
    for (const ev of u.evidence) if (source(ev, where) === "unread") unread.add(ev.repo ?? "");
    for (const b of u.blocks) if (!ex.alternatives.some((a) => a.id === b)) issues.push(issue("error", where, `blocks unknown alternative "${b}"`));
  }
  for (const repo of unread) issues.push(issue("warning", "verification", `${repo ? `Repository ${repo}` : "The project"}: some cited files could not be read, so their citations are unverified`));
  if (typeof ctx.specText !== "string") issues.push(issue("warning", "verification", `The specification ${ex.spec.path} could not be read, so its citations were not checked`));

  const constraintIds = new Set(ex.constraints.map((c) => c.id));
  const knownPremise = (id, at) => {
    if (!premiseById.has(id)) issues.push(issue("error", at, `cites unknown premise "${id}"`));
    return premiseById.get(id);
  };
  for (const a of ex.alternatives) {
    const where = `alternative ${a.id}`;
    if (!a.placements.length) issues.push(issue("warning", where, "proposes no placement, so nothing can be drawn for it"));
    for (const pl of a.placements) {
      const at = `${where} placement ${pl.id}`;
      if (pl.kind === "insert") {
        stepRef(pl.after, `${at} after`);
        for (const [end, id] of [["from", pl.from], ["to", pl.to]]) if (!byId(model.components, id)) issues.push(issue("error", `${at} ${end}`, proposed.has(id) ? `"${id}" is proposed by this exploration, not a component of the model` : `component "${id}" is not in the model`));
      } else stepRef(pl.step, `${at} step`);
      if (byId(model.components, pl.id) || byId(model.relationships, pl.id)) issues.push(issue("warning", at, `the model already has an element with id "${pl.id}"; is this really new?`));
    }
    for (const e of a.effects) {
      const at = `${where} effect ${e.id}`;
      for (const id of e.premises) knownPremise(id, at);
      const gap = supportGap(ex, e, new Set([...failed, ...unchecked]), unchecked);
      if (gap) issues.push(issue("warning", at, `claims ${e.support} support but ${gap}; shown as hypothetical`));
    }
    for (const c of a.checks) {
      const at = `${where} check ${c.constraint}`;
      if (!constraintIds.has(c.constraint)) issues.push(issue("error", at, `names unknown constraint "${c.constraint}"`));
      for (const id of c.premises) knownPremise(id, at);
    }
  }
  if (ex.decision?.alternative && !ex.alternatives.some((a) => a.id === ex.decision.alternative)) issues.push(issue("error", "decision", `selects unknown alternative "${ex.decision.alternative}"`));
  if (ex.decision?.status === "selected" && !ex.decision.alternative) issues.push(issue("error", "decision", "is selected but names no alternative"));
  const open = ex.decision?.alternative ? ex.unresolved.filter((u) => u.answeredBy === "spec" && u.blocks.includes(ex.decision.alternative)) : [];
  if (open.length) issues.push(issue("warning", "decision", `selects ${ex.decision.alternative} while ${open.map((u) => u.id).join(", ")} (specification questions that block it) stay open`));

  return { stale, issues, failed: new Set([...failed, ...unchecked]), unchecked, checked: count };
}

/** Why an effect cannot keep the support it claims, or null: every premise it cites must hold, and at least one must be of the kind claimed. */
function supportGap(ex, effect, failed, unchecked) {
  if (effect.support === "hypothesis") return null;
  const cited = effect.premises.map((id) => ({ id, premise: ex.premises.find((p) => p.id === id) }));
  const blocked = cited.filter(({ id, premise }) => !premise || failed.has(id)).map(({ id, premise }) => (!premise ? `${id} is not a premise` : unchecked.has(id) ? `${id} could not be checked` : `${id} does not hold`));
  if (blocked.length) return `${blocked.join(" and ")}, so the effect is not verified`;
  return cited.some(({ premise }) => premise.kind === effect.support) ? null : `cites no ${effect.support} premise`;
}

/** How an effect is shown: its stated support, or hypothesis (with `why`) when a premise it leans on does not hold or none of the claimed kind is cited. */
export function supportOf(ex, effect, failed = new Set(), unchecked = new Set()) {
  const why = supportGap(ex, effect, failed, unchecked);
  return why ? { support: "hypothesis", downgraded: true, why } : { support: effect.support, downgraded: false };
}

/** The steps of the question's flow worth drawing: the ones the question and the placements name, with a neighbour each side. */
export function explorationWindow(model, ex, selected = null) {
  const flow = byId(model.flows, ex.question.flow);
  if (!flow) return null;
  const named = [...ex.question.steps, ...ex.alternatives.flatMap((a) => a.placements.map((p) => (p.kind === "insert" ? p.after : p.step)))].filter((r) => inFlow(ex, r)).map(stepNumber).filter((n) => flow.steps.some((s) => s.n === n));
  if (!named.length) return null;
  const first = flow.steps.findIndex((s) => s.n === Math.min(...named));
  const last = flow.steps.findIndex((s) => s.n === Math.max(...named));
  const start = Math.max(0, first - 1);
  const end = Math.min(flow.steps.length, last + 2);
  const steps = flow.steps.slice(start, end);
  return { flow, all: flow.steps, steps, before: flow.steps.slice(0, start), after: flow.steps.slice(end), selected: steps.some((s) => s.n === selected) ? selected : null };
}

// Two changes to one step are drawn as one note, so the picture and the text rows agree.
const mergeChanges = (list) => [...Map.groupBy(list, (c) => c.step)].map(([step, group]) => ({ id: group.map((c) => c.id).join("+"), step, text: group.map((c) => c.text).join("; ") }));

/** What one alternative adds to the sequence, by step number: new interactions between existing steps and changes to existing ones. */
export function overlayFor(ex, altId) {
  const alt = ex.alternatives.find((a) => a.id === altId);
  if (!alt) return null;
  const order = (a, b) => a.id.localeCompare(b.id);
  return {
    alt: { id: alt.id, name: alt.name },
    inserts: alt.placements.filter((p) => p.kind === "insert" && inFlow(ex, p.after)).sort(order).map((p) => ({ id: p.id, after: stepNumber(p.after), from: p.from, to: p.to, text: p.text })),
    changes: mergeChanges(alt.placements.filter((p) => p.kind === "change" && inFlow(ex, p.step)).sort(order).map((p) => ({ id: p.id, step: stepNumber(p.step), text: p.text }))),
  };
}

/** Constraint rows with each alternative's reading of it, and the conflicts and open readings each alternative shows. */
export function compareAlternatives(ex) {
  const rows = ex.constraints.map((c) => ({ constraint: c, byAlt: new Map(ex.alternatives.map((a) => [a.id, a.checks.find((k) => k.constraint === c.id)])) }));
  const withStatus = (status) => new Map(ex.alternatives.map((a) => [a.id, a.checks.filter((k) => k.status === status).map((k) => k.constraint)]));
  return { rows, conflicts: withStatus("conflicts"), unclear: withStatus("unclear") };
}

/** What stands between the reader and a decision, from the exploration alone: open questions by who can answer them, and what each blocks. */
export function readiness(ex) {
  return {
    open: ex.unresolved,
    bySpec: ex.unresolved.filter((u) => u.answeredBy === "spec"),
    blocked: new Map(ex.alternatives.map((a) => [a.id, ex.unresolved.filter((u) => u.blocks.includes(a.id)).map((u) => u.id)])),
  };
}

const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

/** What a later version of an exploration added, removed or changed, by id; it does not judge whether the change was right. */
export function diffExploration(prev, next) {
  const out = { added: [], removed: [], changed: [] };
  const sets = [
    ["alternative", (e) => e.alternatives.map((a) => ({ id: a.id, value: { name: a.name, summary: a.summary, assumptions: a.assumptions } }))],
    ["placement", (e) => e.alternatives.flatMap((a) => a.placements.map((p) => ({ id: `${a.id}/${p.id}`, value: p })))],
    ["effect", (e) => e.alternatives.flatMap((a) => a.effects.map((x) => ({ id: `${a.id}/${x.id}`, value: x })))],
    ["check", (e) => e.alternatives.flatMap((a) => a.checks.map((x) => ({ id: `${a.id}/${x.constraint}`, value: x })))],
    ["premise", (e) => e.premises.map((p) => ({ id: p.id, value: p }))],
    ["constraint", (e) => e.constraints.map((c) => ({ id: c.id, value: c }))],
    ["open question", (e) => e.unresolved.map((u) => ({ id: u.id, value: u }))],
  ];
  for (const [label, pick] of sets) {
    const before = new Map(pick(prev).map((x) => [x.id, x.value]));
    const after = new Map(pick(next).map((x) => [x.id, x.value]));
    for (const [id, value] of after) {
      if (!before.has(id)) out.added.push({ label, id });
      else if (!same(before.get(id), value)) out.changed.push({ label, id });
    }
    for (const id of before.keys()) if (!after.has(id)) out.removed.push({ label, id });
  }
  if (!same(prev.question, next.question)) out.changed.push({ label: "question", id: next.question.flow });
  if (!same(prev.requirement, next.requirement)) out.changed.push({ label: "requirement", id: next.requirement.id });
  if (!same(prev.decision, next.decision)) out.changed.push({ label: "decision", id: next.decision?.status ?? "cleared" });
