export function describeDiff(d) {
  const part = (verb, items) => (items.length ? `${verb} ${items.slice(0, 6).map((x) => `${x.label} ${x.id}`).join(", ")}${items.length > 6 ? `, +${items.length - 6} more` : ""}` : "");
