import { byId, categoryInfo, focusSteps, formatEvidence, resolveStepRelationship, stepsTouching, stepsUsing } from "./model.mjs";
import { hopConfidence, hopName } from "./behavior.mjs";
import { esc, palette } from "./svgkit.mjs";
import { overviewSvg } from "./diagram-graph.mjs";
import { selectableKeys, viewerVariants } from "./pictures.mjs";
import { explorationWindow, overlayFor, supportOf } from "./explore.mjs";
import { authEntries, authOrder, dataEntries, dataEvidence, dataOrder } from "./lens-entries.mjs";

export const evKey = (ev) => `${ev.repo ?? ""}\0${ev.path}\0${ev.lines ? ev.lines.join("-") : ""}`;

// Lines shown around a cited range in the page, and the most lines one citation may carry.
export const VIEWER_CONTEXT = 3;
export const VIEWER_MAX_LINES = 40;

/**
 * What the page will offer: the picture swaps, which extra controls apply and the set of element keys that can be
 * selected in any of its pictures. The panel entries and the source excerpts are limited to that set.
 */
export function viewerPlan(model, ctx, spec, theme) {
  const { variants, modes } = viewerVariants({ ...ctx, model }, theme);
  if (modes.carried) variants["@carried"] = overviewSvg(model, { categories: ctx.categories ?? [], theme, showCarried: true }).svg;
  const scope = selectableKeys([spec.svg, ...Object.values(variants)]);
  return { variants, modes, scope };
}

const inScope = (scope, key) => !scope || scope.has(key);

/** Every distinct evidence reference the viewer will offer (for the elements in `scope`), so the caller can read each file once. */
export function viewerEvidence(model, behavior, scope, extra = []) {
  const seen = new Map();
  const add = (list) => {
    for (const ev of list ?? []) seen.set(evKey(ev), ev);
  };
  for (const c of model.components) if (inScope(scope, `component:${c.id}`)) add(c.evidence);
  for (const r of model.relationships) if (inScope(scope, `relationship:${r.id}`)) add(r.evidence);
  for (const f of model.flows) for (const s of f.steps) if (inScope(scope, `step:${f.id}#${s.n}`)) add(s.evidence);
  if (behavior) for (const hop of behavior.hops) if (inScope(scope, `hop:${hop.id}`)) for (const k of ["release", "holds", "onError"]) add(hop[k]?.evidence);
  add(extra);
  return [...seen.values()];
}

export const evidenceOf = (list, withRepo, excerpts) =>
  (list ?? []).map((ev) => {
    const ex = excerpts.get(evKey(ev));
    return {
      label: formatEvidence(ev, { withRepo }),
      repo: withRepo ? (ev.repo ?? "") : "",
      path: ev.path,
      range: ev.lines ? [ev.lines[0], ev.lines[1]] : null,
      note: ev.note ?? "",
      excerpt: ex?.status === "ok" ? { startLine: ex.startLine, source: ex.source, from: ev.lines?.[0], to: ev.lines?.[1], hidden: ex.hidden ?? 0 } : null,
      problem: ex?.status === "whole" ? "Cites the whole file, not a line range: the source is not embedded here." : ex && ex.status !== "ok" ? ex.message : ex ? "" : "not read",
    };
