/**
 * What the side panel shows for each selectable element, keyed `<kind>:<id>`. Everything is copied from the model
 * (and the behavior document), never inferred; `excerpts` is a Map from evidence reference to the lines read.
 * `scope` (a Set of keys) limits the entries, and the links between them, to what the page draws.
 */
/** Panel entries for the placements of the alternative an exploration shows: hypothetical, with the effects and readings that go with them. */
export const EXPLORE_HOME = "explore:question";

/** The page's opening panel: the question and the requirement behind it, what this snapshot draws and does not, and how to read the marks. */
function exploreQuestion(model, explore, { withRepo, excerpts, scope }) {
