  const alt = ex.alternatives.find((a) => a.id === explore.alt);
  const others = ex.alternatives.filter((a) => a !== alt);
  const win = explorationWindow(model, ex);
  const stepLinks = (win?.steps ?? []).map((s) => ({ to: `step:${win.flow.id}#${s.n}`, label: `${s.n}. ${s.action}`, confidence: s.confidence })).filter((l) => inScope(scope, l.to));
  const overlay = alt && overlayFor(ex, alt.id);
