  return {
    title: `${ex.requirement.id} · the question`,
    subtitle: `${ex.title ?? "Exploration"} · ${ex.spec.path}`,
    confidence: "",
    text: [
      ex.question.text,
      `Requirement ${ex.requirement.id}: ${ex.requirement.summary}`,
      alt ? `This page draws alternative ${alt.id} (${alt.name}) on the existing sequence and no other.${others.length ? ` Not drawn here: ${others.map((a) => `${a.id} (${a.name})`).join("; ")}.` : ""}` : "This page draws the existing sequence only; no alternative is drawn.",
      "Reading the marks: ● observed, ◐ inferred and ○ unknown describe the architecture as the model records it. PROPOSED marks are hypothetical, belong to one alternative, are not in the model and carry no confidence.",
