  ];
  const first = proposals[0]?.id;
  const cited = new Set([...alt.effects.flatMap((e) => e.premises), ...alt.checks.flatMap((c) => c.premises)]);
  const evidence = ex.premises
    .filter((p) => cited.has(p.id))
    .flatMap((p) => (p.kind === "spec" && p.cite ? [{ path: ex.spec.path, lines: p.cite.lines, note: p.id }] : p.evidence.map((e) => ({ repo: e.repo, path: e.path, lines: e.lines, note: e.note ?? p.id }))));
  const detail = [
    `Alternative ${alt.id} · ${alt.name}: ${alt.summary}`,
    "Expected effects (source: follows from cited lines; spec: stated by the specification; hypothesis: a prediction nothing cited establishes):",
    ...alt.effects.map((e) => {
      const s = supportOf(ex, e, failed, unchecked);
      return `• [${s.support}${s.downgraded ? `, recorded as ${e.support} but ${s.why}` : ""}] ${e.text}`;
    }),
    "Readings of the specification (Claude's reading, not a verdict):",
    ...alt.checks.map((c) => `• ${c.constraint} ${c.status.toUpperCase()}: ${c.why}`),
    ...alt.assumptions.map((a) => `assumes: ${a}`),
  ];
  const data = { ...question };
  for (const p of proposals) {
    if (!inScope(scope, `proposal:${p.id}`)) continue;
    data[`proposal:${p.id}`] = {
      title: `${p.id} · PROPOSED ${p.kind === "insert" ? "interaction" : "change"}`,
      subtitle: `Alternative ${alt.id} · hypothetical, not in the model`,
      confidence: "proposed",
      text: [p.text, p.position, ...(p.id === first ? detail : [])],
      groups: p.id === first ? [] : [{ title: "The rest of this alternative", links: [{ to: `proposal:${first}`, label: `${first} · effects, readings and evidence` }], omitted: 0 }],
      evidence: p.id === first ? evidenceOf(evidence, withRepo, excerpts) : [],
    };
  }
  return data;
}

export function viewerData(model, { behavior, excerpts = new Map(), scope, explore, dataDoc, authDoc, auth } = {}) {
  const withRepo = model.project.repositories.length > 0;
  const drawn = explore && overlayFor(explore.exploration, explore.alt);
  const proposedAt = (flowId, n) =>
    drawn && flowId === explore.exploration.question.flow
      ? [...drawn.inserts.filter((i) => i.after === n).map((i) => ({ id: i.id, label: `${i.id} · PROPOSED interaction after this step` })), ...drawn.changes.filter((c) => c.step === n).map((c) => ({ id: c.id, label: `${c.id} · PROPOSED change to this step` }))]
          .map((p) => ({ to: `proposal:${p.id}`, label: p.label }))
          .filter((l) => inScope(scope, l.to))
      : [];
  const name = (id) => byId(model.components, id)?.name ?? id;
  const data = {};
  const tagged = new Set(model.relationships.map((r) => r.category)).size > 1;
  const group = (title, links) => {
    const kept = links.filter((l) => inScope(scope, l.to));
    return { title, links: kept, omitted: links.length - kept.length };
  };
  const groups = (list) => list.map(([t, l]) => group(t, l)).filter((g) => g.links.length || g.omitted);
  for (const c of model.components) {
    if (!inScope(scope, `component:${c.id}`)) continue;
    const out = model.relationships.filter((r) => r.from === c.id);
    const inn = model.relationships.filter((r) => r.to === c.id);
    data[`component:${c.id}`] = {
      title: c.name,
      subtitle: `${c.kind}${c.repo ? ` · ${c.repo}` : ""}`,
      confidence: c.confidence,
      text: c.responsibility ? [c.responsibility] : [],
      groups: groups([
        [`Depends on (${out.length})`, out.map((r) => ({ to: `relationship:${r.id}`, label: `${tagged ? `[${categoryInfo(r.category).tag}] ` : ""}→ ${name(r.to)}: ${r.label || r.kind}`, confidence: r.confidence }))],
        [`Used by (${inn.length})`, inn.map((r) => ({ to: `relationship:${r.id}`, label: `${tagged ? `[${categoryInfo(r.category).tag}] ` : ""}← ${name(r.from)}: ${r.label || r.kind}`, confidence: r.confidence }))],
        ["Seen in workflow steps", stepsTouching(model, c.id).slice(0, 12).map(({ flow, step }) => ({ to: `step:${flow.id}#${step.n}`, label: `${flow.name} · ${step.n}. ${step.action}`, confidence: step.confidence }))],
      ]),
      evidence: evidenceOf(c.evidence, withRepo, excerpts),
    };
  }
  for (const r of model.relationships) {
    if (!inScope(scope, `relationship:${r.id}`)) continue;
    data[`relationship:${r.id}`] = {
      title: `${name(r.from)} → ${name(r.to)}`,
      subtitle: `${categoryInfo(r.category).label}: ${r.label || r.kind}${r.via ? ` · via ${name(r.via)}` : ""}`,
      confidence: r.confidence,
      text: [],
      groups: groups([
        ["Endpoints", [{ to: `component:${r.from}`, label: name(r.from) }, { to: `component:${r.to}`, label: name(r.to) }]],
        ["Seen in workflow steps", stepsUsing(model, r).slice(0, 12).map(({ flow, step }) => ({ to: `step:${flow.id}#${step.n}`, label: `${flow.name} · ${step.n}. ${step.action}`, confidence: step.confidence }))],
      ]),
      evidence: evidenceOf(r.evidence, withRepo, excerpts),
    };
  }
  for (const f of model.flows) {
    for (const s of f.steps) {
      if (!inScope(scope, `step:${f.id}#${s.n}`)) continue;
      const res = resolveStepRelationship(model, s);
      const rel = res.relationship;
      const text = [s.action];
      if (rel) text.push(`Relationship: ${rel.label || rel.kind} · ${categoryInfo(rel.category).label}${res.reverse ? " (response leg)" : ""}`);
      else if (res.ambiguous) text.push(`${res.candidates.length} relationships connect these components and this step names none.`);
      if (s.stateChange) text.push(`State change in ${s.stateChange.store}: ${s.stateChange.description} (${s.stateChange.verified ? "verified in code" : "not verified"})`);
      for (const u of f.unknowns.filter((x) => x.step === s.n)) text.push(`Open question: ${u.text}`);
      data[`step:${f.id}#${s.n}`] = {
        title: `Step ${s.n}: ${name(s.from)} → ${name(s.to)}`,
        subtitle: `${f.name}${s.phase ? ` · ${s.phase}` : ""}`,
        confidence: s.confidence,
        text,
        groups: groups([["Open", [{ to: `component:${s.from}`, label: name(s.from) }, { to: `component:${s.to}`, label: name(s.to) }, ...(rel ? [{ to: `relationship:${rel.id}`, label: `relationship: ${rel.label || rel.kind}` }] : [])]], [`Proposed here by ${explore?.alt} (hypothetical)`, proposedAt(f.id, s.n)]]),
        evidence: evidenceOf(s.evidence, withRepo, excerpts),
      };
    }
  }
  if (behavior) {
    for (const hop of behavior.hops) {
      if (!inScope(scope, `hop:${hop.id}`)) continue;
      const claims = [["release", "Returns to its caller"], ["holds", "Holds the data"], ["onError", "When what it calls fails"]].filter(([k]) => hop[k]);
      data[`hop:${hop.id}`] = {
        title: hopName(model, hop),
        subtitle: hop.role ?? "",
        confidence: hopConfidence(hop),
        text: claims.map(([k, label]) => `${label}: ${hop[k].text}`),
        groups: hop.component ? groups([["Open", [{ to: `component:${hop.component}`, label: name(hop.component) }]]]) : [],
        evidence: claims.flatMap(([k]) => evidenceOf(hop[k].evidence, withRepo, excerpts)),
      };
    }
  }
  if (explore) Object.assign(data, exploreEntries(model, explore, { withRepo, excerpts, scope }));
  if (dataDoc) Object.assign(data, dataEntries(model, dataDoc, { withRepo, excerpts, scope, evidenceOf }));
  if (authDoc) Object.assign(data, authEntries(model, authDoc, { withRepo, excerpts, scope, evidenceOf, sel: auth }));
  return data;
}

/** The viewer page for what a pane view shows: its diagram, the panel entries, stepping order and what starts selected. */
export function viewerPage(model, ctx, spec, { behavior, excerpts, theme, plan, explore, dataDoc, authDoc }) {
  const flow = byId(model.flows, ctx.flowId) ?? model.flows[0];
  const chosen = plan ?? viewerPlan(model, ctx, spec, theme);
  const lens = ctx.view === "data" && dataDoc ? dataOrder(model, dataDoc, ctx.data) : ctx.view === "auth" && authDoc ? authOrder(model, authDoc, ctx.auth) : null;
  const shown = ctx.view === "explore" && explore ? explorationWindow(model, explore.exploration) : null;
  const order = shown ? shown.steps.map((s) => `step:${shown.flow.id}#${s.n}`) : ctx.view === "flow" && flow ? focusSteps(flow, ctx.focus).map((s) => `step:${flow.id}#${s.n}`) : ctx.view === "behavior" ? (behavior?.hops ?? []).map((h) => `hop:${h.id}`) : lens ? lens.order : [];
  const sel = ctx.selection;
  const initial = lens ? lens.initial : ctx.view === "behavior" ? (ctx.behavior?.hop ? `hop:${ctx.behavior.hop}` : null) : sel ? `${sel.kind}:${sel.id}` : null;
  return viewerHtml({ title: model.project.name, subtitle: spec.title ?? "", svg: spec.svg, theme, data: viewerData(model, { behavior, excerpts, scope: chosen.scope, explore, dataDoc, authDoc, auth: ctx.auth }), order, initial, variants: chosen.variants, modes: chosen.modes, home: explore && ctx.view === "explore" ? EXPLORE_HOME : null });
}

