/** One self-contained page: the diagram, a side panel, no network, no server. */
export function viewerHtml({ title, subtitle = "", svg, theme = "dark", data, order = [], initial = null, variants = {}, modes = { focus: false, carried: false }, home = null }) {
  const p = palette(theme);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'"><title>${esc(title)}</title><style>${CSS(p, theme)}</style></head><body>
<header><h1>${esc(title)}</h1><span class="sub">${esc(subtitle)}</span><div class="bar"><button id="back" disabled title="Back (b / Esc)" aria-label="Back to the previous selection">◀ Back</button><button id="home" title="The question this page is about" hidden>Question</button><span class="seg" id="stepper" role="group" aria-label="Step through the sequence" hidden><button id="prev" title="Previous (p / ←)" aria-label="Previous step">◀</button><span id="pos" role="status"></span><button id="next" title="Next (n / →)" aria-label="Next step">▶</button></span><span class="seg" role="group" aria-label="Zoom of the picture"><button id="m-focus" title="Readable neighbourhood of the selection (z)">Focus</button><button id="m-full" title="The whole picture (z)">Full</button></span><button id="carried" aria-pressed="false" title="Show the logical calls a transport link carries (c)" hidden>Carried calls</button><button id="grow" title="Read the details over the whole screen">Details only</button><button id="out" title="Zoom out (-)" aria-label="Zoom out">−</button><button id="z" disabled style="min-width:52px;cursor:default">100%</button><button id="in" title="Zoom in (+)" aria-label="Zoom in">+</button><button id="fit" title="Fit to width (0)">Fit</button><button id="one" title="Actual size (1)">1:1</button></div><div id="note"></div><noscript><div style="width:100%;color:#f0a;font-size:14px">The controls, the question and the evidence on this page need JavaScript, and it is not running here. A file preview (for example in a Files app) may block scripts: open this file in a browser instead.</div></noscript></header>
<main id="stage"><div id="canvas">${svg}</div></main><div id="split" role="separator" aria-orientation="vertical" title="Drag to resize the panel"></div><aside id="panel" aria-live="polite"></aside>
<script type="application/json" id="d">${json({ data, order, initial, modes, home })}</script><script type="application/json" id="v">${json(variants)}</script><script>${SCRIPT}</script></body></html>`;
}

