import { byId } from "./model.mjs";
import { ANY_STATE, consequencesOf, entityName, lifecycleOrder, operationItems, partialFailures, stateDegree } from "./data.mjs";
import { transitionName } from "./diagram-data.mjs";
import { ANYONE, admittedBy, authorityChanges, executionOf, flowSelection, principalName } from "./auth.mjs";
import { AUTHORITY_TEXT, MODE_TEXT } from "./diagram-auth.mjs";

// What the browser page's side panel shows for the elements of the Data tab's pictures, keyed `<kind>:<id>` (pure).
// Everything is copied from the document or derived from it; a link to anything the picture does not draw is counted, not followed.

const ASPECT_NAME = { atomicity: "Atomicity", visibility: "Visibility", concurrency: "Concurrency", "external-failure": "External failure" };
const fromText = (t) => t.from.map((f) => (f === null ? "created" : f === ANY_STATE ? "any state" : f)).join(" | ");

/** The evidence the page needs excerpts for: every citation under an element in `scope`. */
export function dataEvidence(model, data, scope) {
  const keys = (k) => !scope || scope.has(k);
  const out = [];
  for (const e of data.entities) if (keys(`entity:${e.id}`)) out.push(...e.evidence);
  for (const r of data.relations) if (keys(`relation:${r.id}`)) out.push(...r.evidence);
  for (const l of data.lifecycles) for (const t of l.transitions) if (keys(`transition:${t.id}`)) out.push(...t.evidence, ...(t.guard?.evidence ?? []));
  for (const s of data.sequences) {
    const refs = operationItems(model, data, s);
    for (const item of refs) {
      if (!keys(`${item.kind}:${item.id.replace(/^cut:/, "")}`)) continue;
      if (item.kind === "write") out.push(...item.unit.effects.flatMap((e) => e.evidence));
      else out.push(...(s.ordering?.evidence ?? []), ...(s.compensation?.evidence ?? []), ...item.cut.residue.flatMap((r) => r.evidence), ...item.cut.aspects.flatMap((a) => a.claims.flatMap((c) => c.evidence)));
    }
  }
  return out;
}

export function dataEntries(model, data, { withRepo, excerpts, scope, evidenceOf }) {
  const inScope = (k) => !scope || scope.has(k);
  const name = (id) => byId(model.components, id)?.name ?? id;
  const group = (title, links) => {
    const kept = links.filter((l) => inScope(l.to));
    return { title, links: kept, omitted: links.length - kept.length };
  };
  const groups = (list) => list.map(([t, l]) => group(t, l)).filter((g) => g.links.length || g.omitted);
  const out = {};

  for (const e of data.entities) {
    if (!inScope(`entity:${e.id}`)) continue;
    const c = consequencesOf(model, data, e.id);
    out[`entity:${e.id}`] = {
      title: e.name,
      subtitle: `${e.kind} · ${name(e.store)}`,
      confidence: e.confidence,
      text: [e.description, ...(e.key ? [`Key: ${e.key}`] : []), ...e.fields.map((f) => `${f.role} ${f.name}${f.note ? ` — ${f.note}` : ""}`), `derived: written by ${c.writers.length ? c.writers.map(name).join(", ") : "no listed component"}${c.readers.length ? `; read by ${c.readers.map(name).join(", ")}` : ""}`, ...c.offFlow.map((x) => `derived: outside any modeled workflow, ${x.op} by ${name(x.component)} via ${x.via}`)],
      groups: groups([
        ["Relations", c.related.map((r) => ({ to: `relation:${r.relation.id}`, label: `${r.direction === "out" ? "→" : "←"} ${entityName(data, r.other)}: ${r.relation.kind}${r.relation.via ? ` via ${r.relation.via}` : ""}`, confidence: r.relation.confidence }))],
        ["Workflow steps that touch it (derived)", c.flows.flatMap((f) => f.steps.map((at) => ({ to: `step:${f.flow.id}#${at.step.n}`, label: `${f.flow.name} · step ${at.step.n}: ${at.effects.map((x) => x.op).join(", ")}` })))],
      ]),
      evidence: evidenceOf(e.evidence, withRepo, excerpts),
    };
  }
  for (const r of data.relations) {
    if (!inScope(`relation:${r.id}`)) continue;
    out[`relation:${r.id}`] = {
      title: `${entityName(data, r.from)} → ${entityName(data, r.to)}`,
      subtitle: `${r.kind}${r.via ? ` via ${r.via}` : ""}`,
      confidence: r.confidence,
      text: [r.text],
      groups: groups([["Endpoints", [{ to: `entity:${r.from}`, label: entityName(data, r.from) }, { to: `entity:${r.to}`, label: entityName(data, r.to) }]]]),
      evidence: evidenceOf(r.evidence, withRepo, excerpts),
    };
  }
  for (const l of data.lifecycles) {
    const order = lifecycleOrder(model, l);
    for (const s of l.states) {
      if (!inScope(`state:${s.id}`)) continue;
      const deg = stateDegree(l, s.id);
      out[`state:${s.id}`] = {
        title: s.label,
        subtitle: `${entityName(data, l.entity)}.${l.field}${s.terminal ? " · marked terminal" : s.id === l.initial ? " · initial" : ""}`,
        confidence: "",
        text: s.terminal && deg.out.length ? [`derived: marked terminal, yet ${deg.out.map(transitionName).join(", ")} can leave it`] : [],
        groups: groups([["Enters through", deg.in.map((t) => ({ to: `transition:${t.id}`, label: `${fromText(t)} → ${t.to} · ${transitionName(t)}`, confidence: t.confidence }))], ["Leaves through", deg.out.map((t) => ({ to: `transition:${t.id}`, label: `${fromText(t)} → ${t.to} · ${transitionName(t)}`, confidence: t.confidence }))]]),
        evidence: [],
      };
    }
    for (const t of order.all) {
      if (!inScope(`transition:${t.id}`)) continue;
      const effects = data.effects.filter((e) => e.transition === t.id);
      out[`transition:${t.id}`] = {
        title: `${fromText(t)} → ${t.to}`,
        subtitle: `${transitionName(t)} · by ${t.by.map(name).join(", ")}${t.step ? "" : " · not on the modeled workflow"}`,
        confidence: t.confidence,
        text: [t.text, ...(t.trigger ? [`Trigger: ${t.trigger}`] : []), ...(t.guard ? [`Guard (${t.guard.kind}, ${t.guard.confidence}): ${t.guard.text}`, ...(t.guard.lock ? [`Lock: ${t.guard.lock}`] : []), ...t.guard.missing.map((m) => `Not checked: ${m}`)] : ["Guard: not examined by this document (not a statement that it is unguarded)"]), ...effects.map((e) => `derived: ${e.op} ${entityName(data, e.entity)} by ${name(e.component)}: ${e.text}`)],
        groups: groups([["States", t.from.filter((f) => f && f !== ANY_STATE).map((f) => ({ to: `state:${f}`, label: f })).concat([{ to: `state:${t.to}`, label: t.to }])], ["Flow step", t.step ? [{ to: `step:${t.step}`, label: t.step }] : []]]),
        evidence: evidenceOf([...t.evidence, ...(t.guard?.evidence ?? [])], withRepo, excerpts),
      };
    }
  }
  for (const s of data.sequences) {
    const pf = partialFailures(model, data, s);
    for (const item of operationItems(model, data, s)) {
      if (item.kind === "write") {
        const unit = item.unit;
        if (!inScope(`write:${unit.ref}`)) continue;
        out[`write:${unit.ref}`] = {
          title: `Step ${unit.step.n}: ${name(unit.step.from)} → ${name(unit.step.to)}`,
          subtitle: `${s.name} · ${unit.systems.map(name).join(", ")}`,
          confidence: unit.writes[0].confidence,
          text: [unit.step.action, ...unit.effects.map((e) => `${e.op} ${e.entity ? entityName(data, e.entity) : `signal to ${name(e.system)}`} by ${name(e.component)}: ${e.text} (${e.confidence})`)],
          groups: groups([["Open", [{ to: `step:${unit.ref}`, label: `flow step ${unit.step.n}` }]], ["Next", pf.cuts.filter((c) => c.after.ref === unit.ref).map((c) => ({ to: `cut:${unit.ref}`, label: "if the next write does not happen" }))]]),
          evidence: evidenceOf(unit.effects.flatMap((e) => e.evidence), withRepo, excerpts),
        };
      } else {
        const cut = item.cut;
        const ref = cut.after.ref;
        if (!inScope(`cut:${ref}`)) continue;
        const sys = (x) => x.systems.map(name).join(", ");
        out[`cut:${ref}`] = {
          title: `If step ${cut.after.step.n} happens and step ${cut.next.step.n} does not`,
          subtitle: `${s.name} · reads the order the code runs these writes in; asserts nothing about which earlier writes took effect or who can see them`,
          confidence: "",
          text: [
            `derived: ordered before: ${[...cut.before, cut.after].map((x) => `step ${x.step.n}`).join(", ")}; ordered after, not reached: ${[cut.next, ...cut.later].map((x) => `step ${x.step.n}`).join(", ")}`,
            cut.differentSystems ? `derived: different systems (${sys(cut.after)} and ${sys(cut.next)}), so one transaction cannot cover both` : `derived: both name ${sys(cut.after)}; whether one transaction covers them is not stated`,
            ...(s.ordering ? [`Order, as the source states it (${s.ordering.confidence}): ${s.ordering.text}`] : ["No source is cited for the order"]),
            ...cut.aspects.flatMap((a) => (a.claims.length ? a.claims.map((c) => `${ASPECT_NAME[a.aspect]} (${c.confidence}): ${c.text}`) : [`${ASPECT_NAME[a.aspect]}: not established by this document`])),
            ...(cut.residue.length ? cut.residue.map((r) => `Left behind (${r.confidence}): ${r.text}`) : ["Left behind: the document claims nothing, which is not a statement that nothing remains"]),
            ...(s.compensation ? [`Recovery, ${s.compensation.kind} (${s.compensation.confidence}): ${s.compensation.text}`] : ["Recovery: not described"]),
          ],
          groups: groups([["Writes", [{ to: `write:${ref}`, label: `step ${cut.after.step.n}` }, { to: `write:${cut.next.ref}`, label: `step ${cut.next.step.n}` }]]]),
          evidence: evidenceOf([...(s.ordering?.evidence ?? []), ...cut.residue.flatMap((r) => r.evidence), ...cut.aspects.flatMap((a) => a.claims.flatMap((c) => c.evidence)), ...(s.compensation?.evidence ?? [])], withRepo, excerpts),
        };
      }
    }
  }
  return out;
}

/** The order `p` and `n` step through in the page, and the element it opens on. */
export function dataOrder(model, data, sel) {
  const mode = sel?.mode ?? "entities";
  if (mode === "lifecycle") {
    const life = byId(data.lifecycles, sel.lifecycle) ?? data.lifecycles[0];
    return life ? { order: lifecycleOrder(model, life).all.map((t) => `transition:${t.id}`), initial: sel.transition ? `transition:${sel.transition}` : null } : { order: [], initial: null };
  }
  if (mode === "operations") {
    const seq = byId(data.sequences, sel.sequence) ?? data.sequences[0];
    const items = seq ? operationItems(model, data, seq) : [];
    const key = (i) => (i.kind === "write" ? `write:${i.id}` : i.id);
    return { order: items.map(key), initial: sel.item ? key({ id: sel.item, kind: sel.item.startsWith("cut:") ? "cut" : "write" }) : null };
  }
  return { order: data.entities.map((e) => `entity:${e.id}`), initial: sel?.entity ? `entity:${sel.entity}` : null };
}

const admitsText = (auth, g) => (g.admits === undefined ? "not stated" : g.admits.includes(ANYONE) ? "any caller that passes the check" : g.admits.map((p) => principalName(auth, p)).join(", "));

/** The evidence the page needs excerpts for: every citation under an element of the Auth tab's pictures. */
export function authEvidence(model, auth, scope) {
  const keys = (k) => !scope || scope.has(k);
  const out = [];
  const credOf = (id) => auth.credentials.find((c) => c.id === id);
  for (const hop of auth.hops) {
    if (!keys(`credhop:${hop.id}`)) continue;
    out.push(...hop.evidence, ...(credOf(hop.presents)?.evidence ?? []), ...(auth.boundaries.find((b) => b.id === hop.boundary)?.evidence ?? []));
  }
  for (const o of auth.operations) {
    if (!keys(`operation:${o.id}`)) continue;
    out.push(...(o.policy?.evidence ?? []), ...(o.recorded?.evidence ?? []), ...(o.policy?.guards ?? []).flatMap((id) => auth.guards.find((g) => g.id === id)?.evidence ?? []));
  }
  return out;
}

export function authEntries(model, auth, { withRepo, excerpts, scope, evidenceOf, sel }) {
  const inScope = (k) => !scope || scope.has(k);
  const name = (id) => byId(model.components, id)?.name ?? id;
  const group = (title, links) => {
    const kept = links.filter((l) => inScope(l.to));
    return { title, links: kept, omitted: links.length - kept.length };
  };
  const groups = (list) => list.map(([t, l]) => group(t, l)).filter((g) => g.links.length || g.omitted);
  const out = {};
  const fs = flowSelection(model, auth, sel ?? {});
  const changeAfter = new Map(authorityChanges(fs.hops).map((c) => [c.after.id, c]));
  for (const hop of auth.hops) {
    const cred = auth.credentials.find((c) => c.id === hop.presents);
    const boundary = auth.boundaries.find((b) => b.id === hop.boundary);
    const users = auth.operations.filter((o) => o.hops.includes(hop.id));
    if (inScope(`credhop:${hop.id}`)) {
      out[`credhop:${hop.id}`] = {
        title: `${name(hop.from)} → ${name(hop.to)}`,
        subtitle: `${AUTHORITY_TEXT[hop.authority]}${hop.step ? ` · ${hop.step}` : ""}`,
        confidence: hop.confidence,
        text: [hop.text, hop.seenAs ? `The receiving system sees: ${principalName(auth, hop.seenAs)}` : "The receiving system is not shown the caller (not established for this hop)", ...(cred ? [`Presents ${cred.name}: ${cred.kind}${cred.secret ? `, secret name ${cred.secret}` : ""}${cred.lifetime ? `, lifetime ${cred.lifetime}` : ""}${cred.carried ? `; ${cred.carried}` : ""}`] : ["No credential is recorded for this hop"]), ...(boundary ? [`Trust boundary (${boundary.confidence}): ${boundary.name}: ${boundary.text}`] : []), `derived: used by ${users.length ? users.map((o) => o.name).join(", ") : "no listed operation"}`],
        groups: groups([["Open", hop.step ? [{ to: `step:${hop.step}`, label: `flow step ${hop.step.split("#")[1]}` }] : []], ["Used by operations", users.map((o) => ({ to: `operation:${o.id}`, label: o.name }))]]),
        evidence: evidenceOf([...hop.evidence, ...(cred?.evidence ?? []), ...(boundary?.evidence ?? [])], withRepo, excerpts),
      };
    }
    const ch = changeAfter.get(hop.id);
    if (ch && inScope(`authchange:${hop.id}`)) {
      out[`authchange:${hop.id}`] = { title: "Whose authority the receiver sees changes", subtitle: `${AUTHORITY_TEXT[ch.from]} → ${AUTHORITY_TEXT[ch.to]}`, confidence: "", text: [`derived: between ${name(ch.after.from)} → ${name(ch.after.to)} and ${name(ch.next.from)} → ${name(ch.next.to)}`, "A join marks where the credential presented changes the authority the next system acts under; it is not a judgement."], groups: groups([["The two hops", [{ to: `credhop:${ch.after.id}`, label: `${name(ch.after.from)} → ${name(ch.after.to)}` }, { to: `credhop:${ch.next.id}`, label: `${name(ch.next.from)} → ${name(ch.next.to)}` }]]]), evidence: [] };
    }
  }
  for (const o of auth.operations) {
    if (!inScope(`operation:${o.id}`)) continue;
    const ex = executionOf(auth, o);
    const adm = admittedBy(auth, o);
    const guards = (o.policy?.guards ?? []).map((id) => auth.guards.find((g) => g.id === id)).filter(Boolean);
    out[`operation:${o.id}`] = {
      title: o.name,
      subtitle: o.route ?? o.trigger ?? "",
      confidence: o.policy?.confidence ?? "",
      text: [
        `Initiating identity: ${o.initiators.length ? o.initiators.map((i) => principalName(auth, i)).join(", ") : "not stated"}${o.trigger ? `. Trigger: ${o.trigger}` : ""}`,
        `Authorization decision (${MODE_TEXT(o.policy)}): ${o.policy?.text ?? "no policy is recorded"}`,
        ...guards.map((g) => `${g.name}: ${g.concern}, ${g.kind}, ${g.enforcedAt} in ${name(g.component)}${g.deny ? `, deny ${g.deny}` : ""}; admits: ${admitsText(auth, g)} (${g.confidence})`),
        adm.derived ? `derived: callers admitted: ${adm.anyone ? "anyone who passes the checks" : adm.principals.map((p) => principalName(auth, p)).join(", ") || "none"}${adm.note ? ` (${adm.note})` : ""}` : `derived: caller set not derived: ${adm.why}`,
        ...(o.uxGates.length ? [`Client-side only, not enforcement: ${o.uxGates.map((g) => auth.guards.find((x) => x.id === g)?.name ?? g).join(", ")}`] : []),
        `Executing credentials (derived): ${[ex.caller.length && `as the caller on ${ex.caller.length}`, ex.service.length && `under the service's own credential on ${ex.service.length}`, ex.delegated.length && `delegated on ${ex.delegated.length}`, ex.unknown.length && `not established on ${ex.unknown.length}`].filter(Boolean).join("; ") || "no hops listed"}`,
