const REPO_ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

/** Parse a workspace file: { schemaVersion: 1, repositories: { <repo id>: { path } } }. Never throws. */
export function parseWorkspace(text) {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (err) {
    return { ok: false, errors: [`Workspace is not valid JSON: ${err.message}`], warnings: [] };
  }
  if (!raw || typeof raw !== "object" || Array.isArray(raw) || raw.schemaVersion !== 1) {
    return { ok: false, errors: ["Workspace must be an object with schemaVersion 1"], warnings: [] };
  }
  const warnings = [];
  const repositories = {};
  const entries = raw.repositories && typeof raw.repositories === "object" && !Array.isArray(raw.repositories) ? Object.entries(raw.repositories) : [];
  for (const [id, entry] of entries) {
    const path = typeof entry?.path === "string" ? entry.path.trim() : "";
    if (!REPO_ID.test(id) || !path) warnings.push(`Workspace repository "${id}" needs a valid id and a path; ignored`);
    else repositories[id] = { path };
  }
  for (const key of Object.keys(raw)) if (key !== "schemaVersion" && key !== "repositories") warnings.push(`Workspace field "${key}" is not part of the format and was ignored`);
  return { ok: true, errors: [], warnings, workspace: { repositories } };
}

const dirname = (p) => p.replace(/\/[^/]*$/, "") || "/";

/** Join and normalize a path ("." and ".." resolved); `rel` may be absolute. */
export function joinPath(base, rel) {
  const parts = [];
  for (const seg of (rel.startsWith("/") ? rel : `${base}/${rel}`).split("/")) {
    if (!seg || seg === ".") continue;
    if (seg === "..") parts.pop();
    else parts.push(seg);
  }
  return `/${parts.join("/")}`;
}

/** Whether a recorded revision names the same commit as the checkout's HEAD (hex prefix of at least 7 characters). */
export function revisionMatches(expected, actual) {
  const a = expected.toLowerCase();
  const b = actual.toLowerCase();
  return a.length >= 7 && b.length >= 7 && (b.startsWith(a) || a.startsWith(b));
}

/** Whether a recorded revision is a commit id (an abbreviated or full hex sha) rather than a tag or branch name. */
export const isHex = (s) => /^[0-9a-f]{7,40}$/i.test(s);

/**
 * The workspace a checker reads, `{ path, workspace, warnings }` or `{ error }`: an explicit `--workspace` path ("" when
 * the flag had no value, undefined when absent) must exist, read and parse, else the first existing candidate is read.
 */
export function loadWorkspace(explicit, candidates, { exists, read }) {
  const strict = explicit !== undefined;
  if (strict && !explicit) return { error: "--workspace needs a path to a workspace file" };
  const path = strict ? explicit : candidates.find(exists);
  if (!path) return { path: undefined, workspace: undefined, warnings: [] };
  let text;
  try {
    text = read(path);
  } catch (err) {
    const why = `could not read ${path}: ${err.code ?? err.message}`;
    return strict ? { error: why } : { path, workspace: undefined, warnings: [`${path}: ${why}`] };
  }
  const ws = parseWorkspace(text);
  if (strict && !ws.ok) return { error: `${path} is not a valid workspace file: ${ws.errors.join("; ")}` };
  return { path, workspace: ws.ok ? ws.workspace : undefined, warnings: [...ws.warnings, ...ws.errors].map((w) => `${path}: ${w}`) };
}

async function readIf(fs, path) {
  return (await fs.exists(path)) ? (await fs.read(path)).trim() : null;
}

/** The commit a checkout's HEAD points at, read through `fs`; null when it cannot be determined. */
export async function readHead(fs, root) {
  let gitDir = `${root}/.git`;
  const headText = await readIf(fs, `${gitDir}/HEAD`).catch(() => null);
  if (headText === null) {
    // A worktree checkout keeps a ".git" file pointing at its real git directory.
    const pointer = await readIf(fs, gitDir).catch(() => null);
    const match = pointer?.match(/^gitdir:\s*(.+)$/);
    if (!match) return null;
    gitDir = joinPath(root, match[1].trim());
  }
  const head = headText ?? (await readIf(fs, `${gitDir}/HEAD`));
  if (!head) return null;
  if (isHex(head)) return head;
  const ref = head.match(/^ref:\s*(.+)$/)?.[1];
  if (!ref) return null;
  let commonDir = gitDir;
  const common = await readIf(fs, `${gitDir}/commondir`);
  if (common) commonDir = joinPath(gitDir, common);
  for (const dir of [gitDir, commonDir]) {
    const loose = await readIf(fs, `${dir}/${ref}`);
    if (loose && isHex(loose)) return loose;
  }
  const packed = await readIf(fs, `${commonDir}/packed-refs`);
  for (const line of (packed ?? "").split("\n")) {
    const [sha, name] = line.split(" ");
    if (name === ref && isHex(sha)) return sha;
  }
  return null;
}

/**
 * Resolve each repository the model declares to a checkout and compare its HEAD with the recorded revision.
 * Returns one entry per repository: { id, name, state, root, revision, head, message } where state is one of
 * ok | unconfigured | missing | mismatch | unverified | unreadable. Reads only through `fs`; denials surface as `unreadable`.
 */
export async function inspectRepositories(fs, model, workspace, workspaceDir) {
  const out = [];
  for (const repo of model.project.repositories) {
    const entry = { id: repo.id, name: repo.name, state: "ok", root: undefined, revision: repo.revision, head: undefined, message: "" };
    out.push(entry);
    const configured = workspace && Object.hasOwn(workspace.repositories, repo.id) ? workspace.repositories[repo.id] : undefined;
    if (!configured) {
      Object.assign(entry, { state: "unconfigured", message: workspace ? `Not listed in the workspace file` : "No workspace file found" });
      continue;
    }
    entry.root = joinPath(workspaceDir, configured.path);
    try {
      if (!(await fs.exists(entry.root))) {
        Object.assign(entry, { state: "missing", message: `No checkout at ${entry.root}` });
        continue;
      }
      entry.head = (await readHead(fs, entry.root)) ?? undefined;
    } catch (err) {
      Object.assign(entry, { state: "unreadable", message: `Could not read ${entry.root}: ${String(err?.message ?? err)}` });
      continue;
    }
    if (!entry.head) Object.assign(entry, { state: "unverified", message: "Could not read the checkout's git HEAD" });
    else if (!repo.revision || !isHex(repo.revision)) Object.assign(entry, { state: "unverified", message: repo.revision ? `Recorded revision "${repo.revision}" is not a commit id` : "Model records no revision" });
    else if (!revisionMatches(repo.revision, entry.head)) Object.assign(entry, { state: "mismatch", message: `Model records ${repo.revision.slice(0, 12)}, checkout is at ${entry.head.slice(0, 12)}` });
  }
  return out;
}

/** The checkout root a repo-qualified path should be read under: `{ root, warning? }` or `{ error }`. A path naming no repository reads under `projectRoot`. */
export function evidenceRoot(model, repos, repoId, projectRoot) {
  if (!repoId || !model.project.repositories.length) return { root: projectRoot };
  const repo = repos?.find((r) => r.id === repoId);
  if (!repo?.root) return { error: `Repository ${repoId} has no checkout configured (${repo?.message || "no workspace"}). Add it to the workspace file.` };
  if (repo.state === "missing" || repo.state === "unreadable") return { error: `Repository ${repoId}: ${repo.message}` };
  return { root: repo.root, warning: repo.state === "mismatch" ? `${repoId}: ${repo.message}; lines may have moved.` : undefined };
}

/** Repositories whose state the reader should be warned about (everything except ok). */
export const repoProblems = (repos) => repos.filter((r) => r.state !== "ok");

