import { byId } from "./model.mjs";

/**
 * Group components into rows by dependency depth (from -> to points downward). Cycles are broken at back edges.
 * `categories` (relationship category ids) limits the layout to those relationships and the components they touch.
 */
export function layerComponents(model, categories = []) {
  const rels = categories.length ? model.relationships.filter((r) => categories.includes(r.category)) : model.relationships;
  const ids = model.components.filter((c) => !categories.length || rels.some((r) => r.from === c.id || r.to === c.id)).map((c) => c.id);
  const out = new Map(ids.map((id) => [id, []]));
  const incoming = new Map(ids.map((id) => [id, 0]));
  for (const r of rels) {
    if (r.from === r.to) continue;
    out.get(r.from).push(r.to);
    incoming.set(r.to, incoming.get(r.to) + 1);
  }

  const depth = new Map();
  const active = new Set();
  const visit = (id, d) => {
    if (active.has(id) || (depth.has(id) && depth.get(id) >= d)) return;
    depth.set(id, d);
    active.add(id);
    for (const next of out.get(id)) visit(next, d + 1);
    active.delete(id);
  };
  const roots = ids.filter((id) => incoming.get(id) === 0);
  for (const id of roots.length ? roots : ids.slice(0, 1)) visit(id, 0);
  for (const id of ids) if (!depth.has(id)) visit(id, 0);

  const rows = [];
  for (const id of ids) (rows[depth.get(id)] ??= []).push(id);
  return rows.filter(Boolean);
}

/** Split a row into chunks that fit `width` columns when each cell takes `cell` columns. */
export function chunkRow(row, width, cell) {
  const perLine = Math.max(1, Math.floor(width / cell));
  const chunks = [];
  for (let i = 0; i < row.length; i += perLine) chunks.push(row.slice(i, i + perLine));
  return chunks;
}

const fit = (s, n) => (n <= 0 ? "" : s.length > n ? `${s.slice(0, Math.max(0, n - 1))}…` : s);

function put(arr, pos, str) {
  for (let i = 0; i < str.length; i++) if (pos + i >= 0 && pos + i < arr.length) arr[pos + i] = str[i];
}

export const SEQUENCE_CELL = 4;
export const MIN_SEQUENCE_LABEL = 16;
const NAMED_CELL = 9;
const MAX_CELL = 14;
const NAMED_LABEL = 26;

const LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

/**
 * Text sequence diagram over `steps` (default: all of the flow's): one lifeline per participant in order of
