          const text = r.kind === "proposed" ? `⟦${r.id}⟧ PROPOSED ${nameOf(r.from)} → ${nameOf(r.to)}: ${r.text}` : `⟦${r.id}⟧ PROPOSED CHANGE to step ${r.at}: ${r.text}`;
          return { step: r.id, kind: r.kind, text, lead: "", label: text };
        });
        return [{ step: s.n, kind: "step", text: label, lead: "", label }, ...proposed];
      }),
    };
  }

  const center = new Map(used.map((id, i) => [id, i * cell + Math.floor(cell / 2)]));
  const lifelines = () => {
    const row = Array(total).fill(" ");
