  const rows = [];
  const emit = (n, kind, lead, label, tag = "") => {
    const shown = fit(label, labelRoom - tag.length) + tag;
    rows.push({ step: n, kind, lead, label: shown, text: `${lead}  ${shown}` });
  };
  for (const s of steps) {
    const a = center.get(s.from);
    const b = center.get(s.to);
    const fill = s.confidence === "observed" ? "─" : "┄";
    const row = lifelines();
    if (a === b) {
      row[a] = "↻";
    } else {
      const lo = Math.min(a, b);
      const hi = Math.max(a, b);
      for (let x = lo + 1; x < hi; x++) row[x] = fill;
      row[a] = a < b ? "├" : "┤";
      row[b] = a < b ? "▶" : "◀";
    }
    emit(s.n, "step", row.join(""), `${s.n}. ${s.action}`, `${tags.get(s.n) ?? ""}${s.stateChange && !states ? " ▪" : ""}`);
    if (s.stateChange && states) {
      const verified = s.stateChange.verified ? "" : " (unverified)";
      emit(s.n, s.stateChange.verified ? "state" : "state-unverified", lifelines().join(""), `↳ ${s.stateChange.store}: ${s.stateChange.description}${verified}`);
    }
    for (const r of proposedRows(s.n)) {
      const lane = lifelines();
      if (r.kind === "proposed-change") {
        lane[center.get(s.to)] = "◆";
        emit(r.id, r.kind, lane.join(""), `⟦${r.id}⟧ PROPOSED CHANGE: ${r.text}`);
        continue;
      }
      const a = center.get(r.from);
      const b = center.get(r.to);
      if (a === b) lane[a] = "↻";
      else {
        for (let x = Math.min(a, b) + 1; x < Math.max(a, b); x++) lane[x] = "═";
        lane[a] = a < b ? "╞" : "╡";
        lane[b] = a < b ? "▶" : "◀";
