import { byId } from "./model.mjs";
import { matchChanges, matchItems } from "./changes.mjs";
import { revisionMatches } from "./workspace.mjs";
import { modelRevisions } from "./review.mjs";
import { ANY_STATE, entityName, partialFailures, touchesOf } from "./data.mjs";
import { executionOf, opsAtStep, opsUsingCredential, opsUsingGuard } from "./auth.mjs";
import { stepRef, weakestOf } from "./lens.mjs";
import { transitionName } from "./diagram-data.mjs";

// Data and authorization elements for a set of changed files (pure). Three kinds of statement are kept apart:
//   matched   a changed file shares lines or only a file with a citation (the classifier `matchChanges` applies to the model);
//   reached   an element the model or a document connects to a directly overlapped one, with the link that does so;
//   open      what the documents themselves record as unknown or unchecked about those elements.
// Nothing here says a change breaks or is compatible with anything.

export const lensOf = (kind) => (kind.startsWith("data.") ? "data" : kind.startsWith("auth.") ? "auth" : "model");

const KIND_WORD = { step: "step", "data.entity": "entity", "data.relation": "relation", "data.effect": "effect", "data.transition": "transition", "data.sequence": "write order", "auth.guard": "guard", "auth.operation": "operation", "auth.hop": "hop", "auth.credential": "credential", "auth.principal": "principal", "auth.boundary": "trust boundary" };
export const kindWord = (kind) => KIND_WORD[kind] ?? kind;

const guardText = (t) => (t.guard ? `guard: ${t.guard.kind}${t.guard.lock ? `, lock ${t.guard.lock}` : ""}` : "guard not examined");
const fromText = (t) => t.from.map((f) => (f === null ? "created" : f === ANY_STATE ? "any state" : f)).join(" | ");
const withPart = (evidence, part) => (evidence ?? []).map((ev) => ({ ...ev, part }));

/** Items for `matchItems`: every Data and Authorization element that cites source, one per element, each citation tagged with the part of the element it supports. */
export function lensItems(model, data, auth) {
  const items = [];
  const comp = (id) => byId(model.components, id)?.name ?? id;
  const push = (kind, id, label, detail, parts) => {
    const evidence = parts.flatMap(([part, ev]) => withPart(ev, part));
    if (evidence.length) items.push({ kind, id, label, detail, evidence });
  };
  for (const e of data?.entities ?? []) push("data.entity", e.id, e.name, `${e.kind} in ${comp(e.store)}`, [["entity", e.evidence]]);
  for (const r of data?.relations ?? []) push("data.relation", r.id, `${entityName(data, r.from)} → ${entityName(data, r.to)}`, r.kind, [["relation", r.evidence]]);
  for (const e of data?.effects ?? []) push("data.effect", e.id, `${e.op} ${e.entity ? entityName(data, e.entity) : `signal to ${comp(e.system)}`}`, `by ${comp(e.component)}${e.step ? ` at step ${e.step.split("#")[1]}` : ` via ${e.via}`}`, [["effect", e.evidence]]);
  for (const l of data?.lifecycles ?? []) for (const t of l.transitions) push("data.transition", t.id, transitionName(t), `${fromText(t)} → ${t.to} · ${guardText(t)}`, [["transition", t.evidence], ["guard", t.guard?.evidence]]);
  for (const s of data?.sequences ?? []) push("data.sequence", s.id, s.name, `write order of steps ${s.steps.map((r) => r.split("#")[1]).join(", ")}`, [["order", s.ordering?.evidence], ["recovery", s.compensation?.evidence], ...s.residue.map((r) => [`left behind after step ${r.after.split("#")[1]}`, r.evidence]), ...s.uncertainty.map((u) => [`${u.aspect} claim`, u.evidence])]);
  for (const g of auth?.guards ?? []) push("auth.guard", g.id, g.name, `${g.concern}, ${g.kind}, ${g.enforcedAt === "server" ? "enforced" : g.enforcedAt === "client" ? "client-side" : "where enforced unknown"} in ${comp(g.component)}`, [["guard", g.evidence]]);
  for (const o of auth?.operations ?? []) push("auth.operation", o.id, o.name, o.route ?? o.trigger, [["policy", o.policy?.evidence], ["recorded identity", o.recorded?.evidence]]);
  for (const h of auth?.hops ?? []) push("auth.hop", h.id, `${comp(h.from)} → ${comp(h.to)}`, `${h.authority}${h.step ? `, step ${h.step.split("#")[1]}` : ""}`, [["hop", h.evidence]]);
  for (const c of auth?.credentials ?? []) push("auth.credential", c.id, c.name, c.kind, [["credential", c.evidence]]);
  for (const p of auth?.principals ?? []) push("auth.principal", p.id, p.name, p.kind, [["principal", p.evidence]]);
  for (const b of auth?.boundaries ?? []) push("auth.boundary", b.id, b.name, "trust boundary", [["boundary", b.evidence]]);
  return items;
}

/** A document written against another model revision cannot be compared line by line with the checkout, whatever the checkout's own revision is. */
function documentBasis(model, doc, repo) {
  const recorded = doc.model.revisions?.[repo ?? ""];
  const current = modelRevisions(model)[repo ?? ""];
  if (!recorded || !current) return "docUnknown";
  return recorded === current || revisionMatches(recorded, current) ? "matches" : "docStale";
