const forDocument = (model, doc, changes) => changes.map((c) => ({ ...c, basis: c.basis === "matches" ? documentBasis(model, doc, c.repo) : c.basis }));
const ORDER = { lines: 0, file: 1, unclear: 2 };
const changeKey = (c) => `${c.repo ?? ""}\0${c.path}`;

/**
 * The model's, the data document's and the authorization document's citations compared with the changed files.
 * `changes` are as for `matchChanges`. `model` is `matchChanges`' own result, unchanged; `lens` the matched Data and
 * Authorization elements, best match first and, within a level, nearest cited lines first; `unmapped` the changed files
 * that nothing cites and `lensOnly` those that only a document cites.
 */
export function matchAll(model, lenses, changes) {
  const base = matchChanges(model, changes);
  const items = lensItems(model, lenses.data, lenses.auth);
  const lens = [];
  const covered = new Set();
  for (const [prefix, doc] of [["data.", lenses.data], ["auth.", lenses.auth]]) {
    if (!doc) continue;
    const { elements, mapped } = matchItems(items.filter((i) => i.kind.startsWith(prefix)), forDocument(model, doc, changes));
    lens.push(...elements);
    for (const m of mapped) covered.add(m);
  }
  lens.sort((a, b) => ORDER[a.level] - ORDER[b.level] || (a.hits[0].gap ?? Infinity) - (b.hits[0].gap ?? Infinity));
  return { model: base, lens, unmapped: base.unmapped.filter((c) => !covered.has(changeKey(c))), lensOnly: base.unmapped.filter((c) => covered.has(changeKey(c))) };
}

// ---- reach ---------------------------------------------------------------------------------------------------------

/** A hop opens under the operation that lists it; a hop no operation lists opens in the authority flow, which shows every hop. */
function hopTarget(auth, h) {
  const op = auth.operations.find((o) => o.hops.includes(h.id));
  return op ? { to: "auth", patch: { mode: "operations", operation: op.id, guard: null, hop: h.id } } : { to: "auth", patch: { mode: "flow", phase: "*", operation: null, guard: null, hop: h.id } };
}

const SAME_STEP = "same workflow step";
const KIND_ORDER = ["step", "data.transition", "data.entity", "data.write", "data.cut", "data.effect", "data.lifecycle", "auth.operation", "auth.guard", "auth.hop", "auth.credential", "component"];

function stepInfo(model, ref) {
  const hit = stepRef(model, ref);
  return hit && { ref, flow: hit.flow, step: hit.step };
}

/**
 * What the model and the two documents connect to the directly overlapped elements `seeds` (`level === "lines"` in
 * `matchAll`'s result). Each item lists the links that connect it (`because`): what the link is, how many steps from the
 * overlap it is (`chain`: 1 is a link a document states, 2 goes through a workflow step or an operation) and the weakest
 * confidence among the authored claims it rests on. A reference that does not resolve is not followed. Components and
 * relationships are not seeds: their citations are too coarse to stand for a connected workflow step.
 */
export function reachFrom(model, lenses, seeds) {
  const { data, auth } = lenses;
  const items = new Map();
  const seedKeys = new Set(seeds.map((s) => `${s.kind}:${s.id}`));
  const compName = (id) => byId(model.components, id)?.name ?? id;
  const unitText = (u) => u.writes.map((w) => `${w.op} ${w.entity ? entityName(data, w.entity) : `signal ${compName(w.system)}`}`).join(", ");
  const guardText = (t) => (t.guard ? `guard: ${t.guard.kind}${t.guard.lock ? `, lock ${t.guard.lock}` : ""}` : "guard not examined");

  const add = (seed, kind, id, label, detail, how, { claims = [], chain = 1, go, cites = [], rank = 1 } = {}) => {
    const key = `${kind}:${id}`;
    if (seedKeys.has(key)) return;
    const cur = items.get(key) ?? { key, kind, lens: lensOf(kind), id, label, detail, go, cites: [], because: [], rank };
    cur.rank = Math.min(cur.rank, rank);
    if (!cur.because.some((b) => b.seed === seed.name && b.how === how)) {
      cur.because.push({ seed: seed.name, how, chain, confidence: claims.length ? weakestOf(claims.map((c) => c.confidence)) : "observed", uncited: claims.some((c) => (c.evidence ?? []).length === 0) });
    }
    for (const ev of cites) if (!cur.cites.some((x) => x.path === ev.path && x.lines?.[0] === ev.lines?.[0])) cur.cites.push(ev);
    items.set(key, cur);
  };

  const stepItem = (seed, ref, how, opts) => {
    const info = stepInfo(model, ref);
    if (info) add(seed, "step", ref, `${info.flow.name} · step ${info.step.n}: ${info.step.action}`, undefined, how, { go: { to: "step", id: ref }, cites: info.step.evidence.slice(0, 1), ...opts });
  };

  const writeItem = (seed, sq, unit, how, opts) => add(seed, "data.write", `${sq.id}:${unit.ref}`, `write at step ${unit.step.n} of ${sq.name}`, unitText(unit), how, { claims: unit.writes, go: { to: "data", patch: { mode: "operations", sequence: sq.id, item: unit.ref } }, cites: unit.writes[0].evidence.slice(0, 1), ...opts });

  // Transitions that leave, enter or follow a state `t` moves between, as the document's own `from` and `to` say.
  const stateNeighbors = (seed, l, t, chain, via) => {
    const concrete = t.from.filter((f) => f && f !== ANY_STATE);
    for (const u of l.transitions.filter((x) => x.id !== t.id)) {
      const reasons = [
        ...concrete.filter((f) => u.from.includes(f) || u.from.includes(ANY_STATE)).map((f) => `also leaves ${f}${u.from.includes(ANY_STATE) ? " (from any state)" : ""}`),
        ...concrete.filter((f) => u.to === f).map((f) => `enters ${f}, which ${transitionName(t)} leaves`),
        ...(u.from.includes(t.to) || u.from.includes(ANY_STATE) ? [`can leave ${t.to}, where ${transitionName(t)} ends`] : []),
      ];
      for (const how of [...new Set(reasons)]) add(seed, "data.transition", u.id, `${transitionName(u)}: ${fromText(u)} → ${u.to}`, guardText(u), `${via}${how}`, { claims: [t, u], chain, go: { to: "data", patch: { mode: "lifecycle", lifecycle: l.id, transition: u.id, state: null } }, cites: u.evidence.slice(0, 1) });
    }
  };

  const via = (how, what) => (how === SAME_STEP ? what : `${what} — ${how}`);

  const dataAtStep = (seed, ref, how, chain, neighbors = false) => {
    if (!data || !stepInfo(model, ref)) return;
    const n = ref.split("#")[1];
    for (const l of data.lifecycles) {
      for (const t of l.transitions.filter((x) => x.step === ref)) {
        add(seed, "data.transition", t.id, `${transitionName(t)}: ${fromText(t)} → ${t.to}`, guardText(t), via(how, `performed at step ${n}`), { claims: [t], chain, go: { to: "data", patch: { mode: "lifecycle", lifecycle: l.id, transition: t.id, state: null } }, cites: t.evidence.slice(0, 1) });
        if (neighbors) stateNeighbors(seed, l, t, chain + 1, `${transitionName(t)} is performed at step ${n}; `);
      }
    }
    for (const e of data.effects.filter((x) => x.step === ref && x.entity)) {
      add(seed, "data.entity", e.entity, entityName(data, e.entity), compName(byId(data.entities, e.entity)?.store), via(how, `${e.op} by ${compName(e.component)} at step ${n}`), { claims: [e], chain, go: { to: "data", patch: { mode: "entities", entity: e.entity, relation: null } }, cites: e.evidence.slice(0, 1) });
    }
    for (const sq of data.sequences.filter((x) => x.steps.includes(ref))) {
      const pf = partialFailures(model, data, sq);
      const unit = pf.units.find((u) => u.ref === ref);
      if (unit) writeItem(seed, sq, unit, via(how, `step ${n} is a write in the order of ${sq.name}`), { chain });
      for (const cut of pf.cuts.filter((c) => c.after.ref === ref || c.next.ref === ref)) {
        add(seed, "data.cut", `${sq.id}:${cut.after.ref}`, `if step ${cut.after.step.n} happens and step ${cut.next.step.n} does not (${sq.name})`, cut.differentSystems ? "different systems" : "same system", via(how, `a join next to the write at step ${n}`), { claims: [...cut.residue, ...cut.aspects.flatMap((a) => a.claims)], chain, go: { to: "data", patch: { mode: "operations", sequence: sq.id, item: `cut:${cut.after.ref}` } }, cites: cut.residue.flatMap((r) => r.evidence).slice(0, 1) });
      }
    }
  };

  const hopText = (h) => {
    const cred = byId(auth.credentials, h.presents);
    return `${compName(h.from)} → ${compName(h.to)}${cred ? ` presenting ${cred.name}` : ""}`;
  };
  const opGo = (o, extra = {}) => ({ to: "auth", patch: { mode: "operations", operation: o?.id ?? null, guard: null, hop: null, ...extra } });
  const hopGo = (h) => hopTarget(auth, h);

  const authAtStep = (seed, ref, how, chain) => {
    if (!auth || !stepInfo(model, ref)) return;
    const n = ref.split("#")[1];
    for (const o of opsAtStep(auth, ref)) {
      add(seed, "auth.operation", o.id, o.name, `policy: ${o.policy?.mode ?? "none recorded"}`, via(how, `${o.name} has a credential hop at step ${n}`), { claims: [o.policy, ...o.hops.map((h) => byId(auth.hops, h)).filter((h) => h?.step === ref)].filter(Boolean), chain, go: opGo(o), cites: (o.policy?.evidence ?? []).slice(0, 1) });
    }
    for (const h of auth.hops.filter((x) => x.step === ref)) {
      add(seed, "auth.hop", h.id, hopText(h), h.authority, via(how, `credential hop at step ${n}`), { claims: [h], chain, go: hopGo(h), cites: h.evidence.slice(0, 1) });
    }
  };

  const joinStep = (seed, ref, how, { into = ["step", "data", "auth"], chain = 1, neighbors = false } = {}) => {
    if (into.includes("step")) stepItem(seed, ref, how, { chain });
    if (into.includes("data")) dataAtStep(seed, ref, how, chain, neighbors);
    if (into.includes("auth")) authAtStep(seed, ref, how, chain);
  };

  const stepName = (ref) => {
    const info = stepInfo(model, ref);
    return info ? `step ${info.step.n}${model.flows.length > 1 ? ` of ${info.flow.name}` : ""}` : ref;
  };
  const guardGo = (g) => opGo(auth.operations.find((o) => o.policy?.guards.includes(g.id)), { guard: g.id });

  for (const seed of seeds) {
    const s = { name: seed.kind === "step" ? stepName(seed.id) : `${kindWord(seed.kind)} ${seed.label}` };
    if (seed.kind === "step") joinStep(s, seed.id, SAME_STEP, { into: ["data", "auth"], neighbors: true });
    else if (seed.kind === "data.transition" && data) {
      const l = data.lifecycles.find((x) => x.transitions.some((t) => t.id === seed.id));
      const t = l?.transitions.find((x) => x.id === seed.id);
      if (!t) continue;
      if (t.step) joinStep(s, t.step, SAME_STEP);
      for (const e of data.effects.filter((x) => x.transition === t.id && x.entity)) add(s, "data.entity", e.entity, entityName(data, e.entity), undefined, `${e.op} by ${compName(e.component)} names this transition`, { claims: [e], go: { to: "data", patch: { mode: "entities", entity: e.entity, relation: null } }, cites: e.evidence.slice(0, 1) });
      stateNeighbors(s, l, t, 1, "");
    } else if (seed.kind === "data.effect" && data) {
      const e = byId(data.effects, seed.id);
      if (!e) continue;
      if (e.step) joinStep(s, e.step, SAME_STEP, { neighbors: true });
      if (e.entity) add(s, "data.entity", e.entity, entityName(data, e.entity), undefined, `the entity this effect ${e.op}s`, { claims: [e], go: { to: "data", patch: { mode: "entities", entity: e.entity, relation: null } } });
    } else if (seed.kind === "data.entity" && data) {
      const entity = byId(data.entities, seed.id);
      if (!entity) continue;
      const storeOf = (id) => compName(byId(data.entities, id)?.store);
      for (const r of data.relations.filter((x) => x.from === entity.id || x.to === entity.id)) {
        const other = r.from === entity.id ? r.to : r.from;
        const cross = byId(data.entities, other)?.store !== entity.store;
        add(s, "data.entity", other, entityName(data, other), storeOf(other), `${r.kind}${r.via ? ` via ${r.via}` : ""}${cross ? `, held in another store (${storeOf(other)})` : ""}`, { claims: [r], rank: cross ? 0 : 1, go: { to: "data", patch: { mode: "entities", entity: other, relation: r.id } }, cites: r.evidence.slice(0, 1) });
      }
      const touch = touchesOf(model, data, entity.id);
      for (const f of touch.flows) {
        for (const at of f.steps) {
          const ref = `${f.flow.id}#${at.step.n}`;
          add(s, "step", ref, `${f.flow.name} · step ${at.step.n}: ${at.step.action}`, undefined, at.effects.map((e) => `${e.op} by ${compName(e.component)}`).join("; "), { claims: at.effects, go: { to: "step", id: ref }, cites: at.step.evidence.slice(0, 1) });
          for (const sq of data.sequences.filter((x) => x.steps.includes(ref))) {
            const unit = partialFailures(model, data, sq).units.find((u) => u.ref === ref);
            if (unit) writeItem(s, sq, unit, `${entity.name} is written at this step of the order of ${sq.name}`);
          }
        }
      }
      for (const e of touch.offFlow) add(s, "data.effect", e.id, `${e.op} ${entity.name} by ${compName(e.component)}`, e.via, "touches this entity outside any modeled workflow", { claims: [e], go: { to: "data", patch: { mode: "entities", entity: entity.id, relation: null } }, cites: e.evidence.slice(0, 1) });
      for (const l of data.lifecycles.filter((x) => x.entity === entity.id)) add(s, "data.lifecycle", l.id, `${entity.name}.${l.field}: ${l.states.length} states, ${l.transitions.length} transitions`, undefined, "its state changes through these transitions", { go: { to: "data", patch: { mode: "lifecycle", lifecycle: l.id, transition: null, state: null } } });
    } else if (seed.kind === "data.sequence" && data) {
      const sq = byId(data.sequences, seed.id);
      if (!sq) continue;
      const pf = partialFailures(model, data, sq);
      const parts = [...new Set(seed.hits.filter((h) => h.level === "lines").map((h) => h.evidence.part))].join(", ");
      for (const u of pf.units) {
        writeItem(s, sq, u, `a write in the order this claim covers (${parts})`);
        authAtStep(s, u.ref, `step ${u.step.n} of ${sq.name}`, 2);
      }
      for (const cut of pf.cuts) {
        if (![...sq.residue, ...sq.uncertainty].some((x) => x.after === cut.after.ref)) continue;
        add(s, "data.cut", `${sq.id}:${cut.after.ref}`, `if step ${cut.after.step.n} happens and step ${cut.next.step.n} does not (${sq.name})`, cut.differentSystems ? "different systems" : "same system", "a join this document records claims against", { claims: [...cut.residue, ...cut.aspects.flatMap((a) => a.claims)], go: { to: "data", patch: { mode: "operations", sequence: sq.id, item: `cut:${cut.after.ref}` } } });
      }
    } else if (seed.kind === "auth.guard" && auth) {
      const g = byId(auth.guards, seed.id);
      if (!g) continue;
      for (const o of opsUsingGuard(auth, g.id)) {
        add(s, "auth.operation", o.id, o.name, `policy: ${o.policy.mode}`, `lists ${g.name} in its ${o.policy.mode} policy`, { claims: [o.policy], go: opGo(o, { guard: g.id }), cites: o.policy.evidence.slice(0, 1) });
        for (const ref of new Set(executionOf(auth, o).hops.map((h) => h.step).filter(Boolean))) joinStep(s, ref, `a hop of ${o.name}, which relies on ${g.name}`, { into: ["step", "data"], chain: 2 });
      }
      if (byId(model.components, g.component)) add(s, "component", g.component, compName(g.component), undefined, `${g.name} is enforced in it`, { claims: [g], go: { to: "impact", kind: "component", id: g.component } });
    } else if (seed.kind === "auth.operation" && auth) {
      const o = byId(auth.operations, seed.id);
      if (!o) continue;
      for (const g of (o.policy?.guards ?? []).map((id) => byId(auth.guards, id)).filter(Boolean)) add(s, "auth.guard", g.id, g.name, `${g.concern}, ${g.kind}`, "in this operation's policy", { claims: [o.policy, g], go: opGo(o, { guard: g.id }), cites: g.evidence.slice(0, 1) });
      for (const h of executionOf(auth, o).hops) {
        add(s, "auth.hop", h.id, hopText(h), h.authority, "a credential hop of this operation", { claims: [h], go: opGo(o, { hop: h.id }), cites: h.evidence.slice(0, 1) });
        if (h.step) joinStep(s, h.step, `a hop of ${o.name}`, { into: ["step", "data"], chain: 2 });
      }
    } else if (["auth.hop", "auth.credential", "auth.boundary"].includes(seed.kind) && auth) {
      const hops = seed.kind === "auth.hop" ? [byId(auth.hops, seed.id)] : seed.kind === "auth.credential" ? auth.hops.filter((h) => h.presents === seed.id) : auth.hops.filter((h) => h.boundary === seed.id);
      for (const h of hops.filter(Boolean)) {
        for (const o of auth.operations.filter((x) => x.hops.includes(h.id))) add(s, "auth.operation", o.id, o.name, `policy: ${o.policy?.mode ?? "none recorded"}`, `has the hop ${hopText(h)}`, { claims: [h], go: opGo(o, { hop: h.id }), cites: h.evidence.slice(0, 1) });
        if (h.step) joinStep(s, h.step, `a hop at step ${h.step.split("#")[1]}`, { into: ["step", "data"], chain: 2 });
      }
      if (seed.kind === "auth.credential") for (const o of opsUsingCredential(auth, seed.id)) add(s, "auth.operation", o.id, o.name, `policy: ${o.policy?.mode ?? "none recorded"}`, "executes with this credential", { claims: [o.policy].filter(Boolean), go: opGo(o) });
    } else if (seed.kind === "auth.principal" && auth) {
      for (const g of auth.guards.filter((x) => (x.admits ?? []).includes(seed.id))) add(s, "auth.guard", g.id, g.name, `${g.concern}, ${g.kind}`, "admits this principal", { claims: [g], go: guardGo(g), cites: g.evidence.slice(0, 1) });
      for (const o of auth.operations.filter((x) => x.initiators.includes(seed.id))) add(s, "auth.operation", o.id, o.name, `policy: ${o.policy?.mode ?? "none recorded"}`, "initiated by this principal", { go: opGo(o) });
    }
  }

  const nearest = (it) => Math.min(...it.because.map((b) => b.chain));
  return [...items.values()].sort((a, b) => nearest(a) - nearest(b) || KIND_ORDER.indexOf(a.kind) - KIND_ORDER.indexOf(b.kind) || a.rank - b.rank || a.label.localeCompare(b.label));
}

// ---- what the documents leave open ---------------------------------------------------------------------------------

/**
 * What the data and authorization documents themselves record as unknown or unchecked about the seeds and reached
 * elements: unchecked preconditions, missing locks, aspects of a join that are not established, operations whose
 * decision was not located, and the questions they list. Each row names its source; none is a finding about the change.
 */
export function openAbout(model, lenses, seeds, reached) {
  const near = reached.filter((r) => r.kind !== "data.entity" && r.because.some((b) => b.chain === 1));
  const { data, auth } = lenses;
  const rows = [];
  const seen = new Set();
  const row = (key, text, where, go) => {
    if (seen.has(key)) return;
    seen.add(key);
    rows.push({ key, text, where, go });
  };
  for (const { kind, id } of [...seeds, ...near]) {
    if (kind === "data.transition" && data) {
      const l = data.lifecycles.find((x) => x.transitions.some((t) => t.id === id));
      const t = l?.transitions.find((x) => x.id === id);
      if (!t) continue;
      const go = { to: "data", patch: { mode: "lifecycle", lifecycle: l.id, transition: t.id, state: null } };
      if (!t.guard) row(`g0:${t.id}`, `${transitionName(t)}: the document does not say what guards it (that is not a statement that it is unguarded)`, "data", go);
      else {
        if (t.guard.lock === "none-found" || t.guard.lock === "unknown") row(`lk:${t.id}`, `${transitionName(t)}: ${t.guard.lock === "none-found" ? "no row lock or re-read was found in the cited function" : "lock behavior was not examined"}`, "data", go);
        for (const m of t.guard.missing) row(`ms:${t.id}:${m}`, `${transitionName(t)}: not checked — ${m}`, "data", go);
      }
    } else if (kind === "data.cut" && data) {
      const [sid, ref] = id.split(":");
      const sq = byId(data.sequences, sid);
      const cut = sq && partialFailures(model, data, sq).cuts.find((c) => c.after.ref === ref);
      if (!cut) continue;
      const go = { to: "data", patch: { mode: "operations", sequence: sid, item: `cut:${ref}` } };
      const missing = cut.aspects.filter((a) => !a.claims.length).map((a) => a.aspect.replace("-", " "));
      if (missing.length) row(`as:${id}`, `after step ${cut.after.step.n}: ${missing.join(", ")} ${missing.length === 1 ? "is" : "are"} not established by the document`, "data", go);
      for (const c of cut.aspects.flatMap((a) => a.claims)) if (c.confidence !== "observed") row(`ac:${c.id}`, `after step ${cut.after.step.n}: ${c.text} (${c.confidence})`, "data", go);
    } else if (kind === "data.entity" && data) {
      for (const q of data.questions.filter((x) => x.entity === id)) row(`dq:${q.id}`, q.text, "data", { to: "data", patch: { mode: "entities", entity: id, relation: null } });
    } else if (kind === "auth.operation" && auth) {
      const o = byId(auth.operations, id);
      if (!o) continue;
      const go = { to: "auth", patch: { mode: "operations", operation: o.id, guard: null, hop: null } };
      if (o.policy?.mode === "unknown") row(`pu:${o.id}`, `${o.name}: no authorization decision was located`, "auth", go);
      for (const h of executionOf(auth, o).hops.filter((x) => x.authority === "unknown")) row(`hu:${h.id}`, `${o.name}: whose authority the receiver sees is not established${h.step ? ` at step ${h.step.split("#")[1]}` : ""}`, "auth", go);
      for (const q of auth.questions.filter((x) => x.operation === o.id)) row(`aq:${q.id}`, q.text, "auth", go);
    } else if (kind === "auth.guard" && auth) {
      const g = byId(auth.guards, id);
      if (!g) continue;
      const go = { to: "auth", patch: { mode: "operations", operation: auth.operations.find((o) => o.policy?.guards.includes(g.id))?.id ?? null, guard: g.id, hop: null } };
      if (g.admits === undefined && g.concern === "authorization") row(`ga:${g.id}`, `${g.name}: the document does not say who it admits`, "auth", go);
      for (const q of auth.questions.filter((x) => x.guard === g.id)) row(`gq:${q.id}`, q.text, "auth", go);
    } else if (kind === "step") {
      const info = stepInfo(model, id);
      for (const u of info?.flow.unknowns ?? []) if (u.step === info.step.n) row(`su:${id}:${u.text}`, `${info.flow.name}, step ${info.step.n}: ${u.text}`, "model", { to: "step", id });
    }
  }
  return rows;
}

/** Where a matched Data or Authorization element opens: the same selection the Data and Auth tabs make for it. */
export function openTarget(lenses, kind, id) {
  const { data, auth } = lenses;
  const opGo = (o, extra = {}) => ({ to: "auth", patch: { mode: "operations", operation: o?.id ?? null, guard: null, hop: null, ...extra } });
  switch (kind) {
    case "data.entity": return { to: "data", patch: { mode: "entities", entity: id, relation: null } };
    case "data.relation": return { to: "data", patch: { mode: "entities", entity: byId(data.relations, id)?.from ?? null, relation: id } };
    case "data.effect": {
      const e = byId(data.effects, id);
      const l = e?.transition && data.lifecycles.find((x) => x.transitions.some((t) => t.id === e.transition));
      return l ? { to: "data", patch: { mode: "lifecycle", lifecycle: l.id, transition: e.transition, state: null } } : { to: "data", patch: { mode: "entities", entity: e?.entity ?? null, relation: null } };
    }
    case "data.transition": return { to: "data", patch: { mode: "lifecycle", lifecycle: data.lifecycles.find((l) => l.transitions.some((t) => t.id === id))?.id ?? null, transition: id, state: null } };
    case "data.sequence": return { to: "data", patch: { mode: "operations", sequence: id, item: null } };
    case "auth.guard": return opGo(auth.operations.find((o) => o.policy?.guards.includes(id)), { guard: id });
    case "auth.operation": return opGo(byId(auth.operations, id));
    case "auth.hop": return hopTarget(auth, byId(auth.hops, id));
    case "auth.credential": { const h = auth.hops.find((x) => x.presents === id); return h ? hopTarget(auth, h) : opGo(undefined); }
    case "auth.boundary": { const h = auth.hops.find((x) => x.boundary === id); return h ? hopTarget(auth, h) : opGo(undefined); }
    case "auth.principal": return opGo(auth.operations.find((o) => o.initiators.includes(id)));
    default: return undefined;
  }
}

