import { REASONS } from "./changes.mjs";
import { kindWord, openTarget } from "./change-review.mjs";
import { evidenceRows, heading, lineRange, note } from "./lens-view.mjs";

// The data and authorization parts of Impact ▸ Local git changes (pure; elements come from the host table `h`).
// Everything shown is either a citation that shares lines or a file with the change, a link a document states, or
// something a document records as unknown. None of it says what the change does.

const TAG = { data: "[data]", auth: "[auth]", model: "[flow]" };
const LEVEL_WORD = { lines: "overlap", file: "same file", unclear: "unclear" };
const MAX_LENS = { lines: 15, file: 5, unclear: 5 };
const MAX_REACH = 5;
const MAX_REACH_ALL = 40;
const MAX_OPEN = 8;
const RANK = { observed: 2, inferred: 1, unknown: 0 };

export const fileKey = (f) => `${f.repo ?? ""}\0${f.path}`;
const baseName = (p) => p.split("/").pop();

/** Opens the Data tab, the Auth tab, the Flow view or Impact at what `g` names; each of them leaves Back pointing here. */
function go(ctx, g) {
  if (!g) return undefined;
  if (g.to === "step") return ctx.actions.select("step", g.id);
  if (g.to === "impact") return ctx.actions.openImpact(g.kind, g.id);
  return g.to === "data" ? ctx.actions.openData({ patch: g.patch }) : ctx.actions.openAuth({ patch: g.patch });
}

/** One line per document compared: what it is, whether it could be used, and why its line matches may be unclear. */
export function documentStatus(h, ctx, u) {
  const rows = [];
  for (const [key, label, file, st] of [["data", "Data", "data.json", ctx.status.data], ["auth", "Authorization", "auth.json", ctx.status.auth]]) {
    if (st?.kind === "ready") {
      const problems = [...st.parseIssues, ...st.issues].filter((i) => i.level === "error").length;
      rows.push(h.Text({ key: `cds-${key}`, dimColor: !problems && !st.stale.length, color: problems || st.stale.length ? "yellow" : undefined, wrap: "wrap", children: `${label}: ${file} compared${st.stale.length ? ` · ${st.stale[0].message}` : ""}${problems ? ` · ${u.plural(problems, "problem")} in the document (a quote on a line this change edited no longer matches its citation; see the tab's Checks)` : ""}` }));
    } else rows.push(h.Text({ key: `cds-${key}`, dimColor: true, wrap: "wrap", children: st?.kind === "invalid" ? `${label}: ${file} could not be used, so its citations are not compared` : `${label}: no ${file}; its elements are not compared and its consequences are not derived` }));
  }
  return rows;
}

/** Changed files as a strip; choosing one narrows every list below to it. */
export function fileStrip(h, ctx, u, files, direct) {
  if (files.length < 2) return null;
  const multi = files.some((f) => f.repo);
  const shown = files.slice(0, 10);
  return h.Box({
    key: "cfiles",
    flexDirection: "column",
    marginTop: 1,
    children: [
      h.Text({ key: "cf-h", dimColor: true, wrap: "wrap", children: "Changed files — choose one to narrow every list below to it:" }),
      h.Box({
        key: "cf-row",
        gap: 2,
        flexWrap: "wrap",
        children: [
          h.Button({ key: "cf-all", label: `${ctx.changeFile ? "" : "▸ "}All ${files.length}`, plain: true, onPress: () => ctx.actions.setChangeFile(null) }),
          ...shown.map((f, i) => {
            const n = direct.get(fileKey(f)) ?? 0;
            return h.Button({ key: `cf-${i}`, label: u.cut(`${ctx.changeFile === fileKey(f) ? "▸ " : ""}${multi && f.repo ? `${f.repo}/` : ""}${baseName(f.path)}${n ? ` · ${n} overlap${n === 1 ? "" : "s"}` : ""}`, ctx.cols - 6), plain: true, onPress: () => ctx.actions.setChangeFile(fileKey(f)) });
          }),
          files.length > shown.length ? h.Text({ key: "cf-more", dimColor: true, children: `… ${files.length - shown.length} more` }) : null,
        ],
      }),
    ],
  });
}

const shortPath = (p) => p.split("/").slice(-2).join("/");

const locate = (el) => {
  const hit = el.hits.find((x) => x.level === el.level) ?? el.hits[0];
  const ev = hit.evidence;
  return { hit, part: ev.part ? ` (${ev.part})` : "", at: `${ev.repo ? `[${ev.repo}] ` : ""}${shortPath(ev.path)}:${lineRange(ev)}${el.hits.length > 1 ? ` +${el.hits.length - 1} more` : ""}` };
};

/** Data and Authorization elements whose citations share `level` with the change, as buttons that open the element, with the reason under each. */
export function lensMatchRows(h, ctx, u, lenses, level, els) {
  const out = [];
  const max = MAX_LENS[level];
  for (const [i, el] of els.slice(0, max).entries()) {
    const { hit, part, at } = locate(el);
    const lens = el.kind.startsWith("data.") ? "data" : "auth";
    const why = level === "unclear" ? REASONS[hit.reason] ?? "line numbers cannot be compared" : level === "file" ? (hit.gap !== undefined ? `the nearest changed line is ${u.plural(hit.gap, "line")} from the cited lines${el.detail ? ` · ${el.detail}` : ""}` : (REASONS[hit.reason] ?? "")) : [el.detail, hit.reason === "deleted" ? "the cited lines were deleted" : ""].filter(Boolean).join(" · ");
    out.push(h.Button({ key: `cl-${level}-${i}`, label: u.cut(`${LEVEL_WORD[level].padEnd(9)} ${TAG[lens]} ${kindWord(el.kind)} ${el.label}${part} — ${at}`, ctx.cols - 4), plain: true, onPress: () => go(ctx, openTarget(lenses, el.kind, el.id)) }));
    if (why) out.push(h.Box({ key: `clw-${level}-${i}`, marginLeft: 10, children: [h.Text({ key: `clwt-${level}-${i}`, dimColor: true, wrap: "wrap", children: why })] }));
    if (level === "lines") out.push(h.Box({ key: `cle-${level}-${i}`, marginLeft: 10, flexDirection: "column", children: evidenceRows(h, ctx, u, `cl${i}`, [hit.evidence]) }));
  }
  if (els.length > max) out.push(h.Text({ key: `cl-more-${level}`, dimColor: true, children: `… and ${els.length - max} more` }));
  return out;
}

const best = (it) => it.because.slice().sort((a, b) => a.chain - b.chain || RANK[b.confidence] - RANK[a.confidence])[0];
const GROUPS = [
  ["step", "Workflow steps", (it) => it.kind === "step"],
  ["transition", "[data] Lifecycle transitions", (it) => it.kind === "data.transition"],
  ["entity", "[data] Entities", (it) => it.kind === "data.entity"],
  ["write", "[data] Write order, joins and other effects", (it) => ["data.write", "data.cut", "data.effect", "data.lifecycle"].includes(it.kind)],
  ["operation", "[auth] Operations", (it) => it.kind === "auth.operation"],
  ["guard", "[auth] Guards", (it) => it.kind === "auth.guard"],
  ["hop", "[auth] Credential hops", (it) => it.kind === "auth.hop" || it.kind === "auth.credential"],
  ["component", "Components", (it) => it.kind === "component"],
];

/** Elements connected to the direct overlaps by a link the model or a document states, each with the link and how strong it is. */
export function reachSection(h, ctx, u, reach, seeds, title = `Derived reach from ${u.plural(seeds, "direct overlap")}`, source = "a directly overlapped element") {
  const cap = ctx.changeMore ? MAX_REACH_ALL : MAX_REACH;
  const rows = [];
  let hidden = 0;
  for (const [id, title, test] of GROUPS) {
    const group = reach.filter(test);
    if (!group.length) continue;
    rows.push(h.Text({ key: `cr-${id}-h`, bold: true, wrap: "wrap", children: `${title} (${group.length})` }));
    for (const [i, it] of group.slice(0, cap).entries()) {
      const b = best(it);
      const more = it.because.length - 1;
      rows.push(h.Button({ key: `cr-${id}-${i}`, label: u.cut(`${u.MARK[b.confidence]} ${it.label}${it.detail ? ` · ${it.detail}` : ""}`, ctx.cols - 4), plain: true, onPress: () => go(ctx, it.go) }));
      rows.push(
        h.Box({
          key: `crw-${id}-${i}`,
          marginLeft: 2,
          children: [h.Text({ key: `crwt-${id}-${i}`, dimColor: true, wrap: "wrap", children: `← ${b.seed}: ${b.how}${b.chain > 1 ? " · two links" : ""}${b.confidence !== "observed" ? ` · weakest claim ${b.confidence}` : ""}${b.uncited ? " · a claim cites no file" : ""}${more > 0 ? ` · +${more} more link${more === 1 ? "" : "s"}` : ""}${it.cites[0] ? ` · ${it.cites[0].path.split("/").pop()}${it.cites[0].lines ? `:${lineRange(it.cites[0])}` : ""}` : ""}` })],
        }),
      );
    }
    hidden += Math.max(0, group.length - cap);
    if (group.length > cap) rows.push(h.Text({ key: `cr-${id}-more`, dimColor: true, children: `… and ${group.length - cap} more` }));
  }
  if (!rows.length) rows.push(h.Text({ key: "cr-none", dimColor: true, children: "Nothing is linked to these overlaps in the model or the documents." }));
  if (hidden || ctx.changeMore) rows.push(h.Button({ key: "cr-far", label: ctx.changeMore ? "Show fewer" : `Show ${hidden} more`, plain: true, onPress: ctx.actions.toggleChangeMore }));
  return [
    h.Box({
      key: "creach",
      flexDirection: "column",
      marginTop: 1,
      children: [
        heading(h, "creach-h", `${title} (${reach.length}) — not confirmed`),
        note(h, "creach-n", `Each row names the link a document or the model states between ${source} and this one, and the weakest claim it rests on. “two links” goes through a workflow step or an operation. Following a link says what is connected, not that the change reaches it. Only what the model and the documents state is followed: a caller of a changed function that none of them cites is not found.`),
        ...rows,
      ],
    }),
  ];
}

/** What the documents themselves leave unknown or unchecked about the overlapped and linked elements. */
export function openSection(h, ctx, u, rows) {
  if (!rows.length) return [];
  const body = rows.slice(0, MAX_OPEN).map((r, i) => h.Button({ key: `co-${i}`, label: u.cut(`${u.MARK.unknown} ${r.text}${r.where === "model" ? "" : ` (${r.where}.json)`}`, ctx.cols - 4), plain: true, onPress: () => go(ctx, r.go) }));
  if (rows.length > MAX_OPEN) body.push(h.Text({ key: "co-more", dimColor: true, children: `… and ${rows.length - MAX_OPEN} more` }));
  return [h.Box({ key: "copen", flexDirection: "column", marginTop: 1, children: [heading(h, "copen-h", `Recorded as unknown or unchecked (${rows.length})`), note(h, "copen-n", "Quoted from the documents about the overlapped and directly linked elements. A gap listed here is the document's own statement, not a finding about the change."), ...body] })];
}

/** The limits of what was compared, so an empty list is not read as a clean one. */
export function coverageSection(h, ctx, u, { seeds, all, files }) {
  const lines = [];
  const lens = all.lens;
  const weak = (l) => lens.filter((e) => e.level === l).length + all.model.elements.filter((e) => e.level === l).length;
  if (!seeds) lines.push(`No citation overlaps a changed line${weak("unclear") ? `, and ${weak("unclear")} match${weak("unclear") === 1 ? "" : "es"} could not be compared line by line` : ""}; nothing is derived from file-level matches, so no reach is listed.`);
  else if (weak("file") || weak("unclear")) lines.push(`${[weak("file") && `${weak("file")} match${weak("file") === 1 ? "" : "es"} by file only`, weak("unclear") && `${weak("unclear")} that cannot be compared line by line`].filter(Boolean).join(" and ")} ${weak("file") + weak("unclear") === 1 ? "was" : "were"} not followed.`);
  if (ctx.status.data?.kind !== "ready") lines.push("No data document: lifecycle transitions, entities and write order are not considered.");
  if (ctx.status.auth?.kind !== "ready") lines.push("No authorization document: guards, operations and credentials are not considered.");
  lines.push("Components and relationships are not followed from here (their citations are too coarse); open one from the matches for its own impact.");
  lines.push("Only lines cited by the model or a document can overlap. A change in code none of them cites is listed above as uncovered, and what it affects is not known.");
  if (files.some((f) => f.untracked)) lines.push("Untracked files are new, so no cited line can be compared with them.");
  return [h.Box({ key: "ccover", flexDirection: "column", marginTop: 1, children: [heading(h, "ccover-h", "What this view does not cover"), ...lines.map((t, i) => h.Text({ key: `cc-${i}`, dimColor: true, wrap: "wrap", children: `· ${t}` }))] })];
}

/** For each changed file, how many matched elements (model, data or authorization) have a cited line the change overlaps. */
export function directByFile(all) {
  const out = new Map();
  for (const el of [...all.model.elements, ...all.lens]) {
    const keys = new Set(el.hits.filter((x) => x.level === "lines").map((x) => fileKey(x.change)));
    for (const k of keys) out.set(k, (out.get(k) ?? 0) + 1);
  }
  return out;
}

