import { byId } from "./model.mjs";
import { deriveReview, parallelLinks, pathKey, resolveRef } from "./review.mjs";
import { reachFrom } from "./change-review.mjs";
import { reachSection } from "./change-view.mjs";

const TAG = { plan: ["[plan]", "cyan"], model: ["[model]", undefined], derived: ["[derived]", "blue"], suggested: ["[suggested]", "yellow"] };
const LIST_MAX = 12;

const base = (path) => path.split("/").pop();

const confidenceOf = (model, kind, id) => {
  if (kind === "component") return byId(model.components, id)?.confidence;
  if (kind === "relationship") return byId(model.relationships, id)?.confidence;
  const [flowId, n] = id.split("#");
  return byId(model.flows, flowId)?.steps.find((s) => s.n === Number(n))?.confidence;
};

/** Impact ▸ Plan review; `[plan]`, `[model]`, `[derived]` and `[suggested]` statements stay visibly apart. */
export function reviewView(h, ctx, u) {
  const { Box, Text, Button, Input } = h;
  const { model } = ctx;
  const st = ctx.status.review;
  const out = [];

  const heading = (key, title, tags) =>
    Box({ key, gap: 1, marginTop: 1, children: [Text({ key: `${key}-t`, bold: true, children: title }), ...tags.map((t) => Text({ key: `${key}-${t}`, color: TAG[t][1], dimColor: t === "derived", children: TAG[t][0] }))] });
  const note = (key, text, props = {}) => Text({ key, dimColor: true, wrap: "wrap", children: text, ...props });
  const more = (key, n) => Text({ key, dimColor: true, children: `… and ${n} more` });

  const picker = (label) =>
    Input({
      key: "rvp",
      label,
      placeholder: ".specify/specs/NNN-feature/plan.md",
      value: ctx.reviewPath ?? "",
      submitLabel: "review",
      onInput: (value) => ctx.actions.setReviewPath(value),
      onSubmit: (value) => ctx.actions.requestReview(value),
    });

  if (!st || st.kind === "none") {
    out.push(Text({ key: "rvn", bold: true, children: "No plan review yet." }));
    out.push(note("rvnh", "Review a Spec Kit plan against the model before implementing it. Claude reads the plan, the model and the code and writes .architecture/review.json; this view then shows what the plan proposes, what it touches, and what is uncertain. It runs one Claude turn when you ask, and nothing else."));
    out.push(ctx.reviewing ? Text({ key: "rvw", color: "cyan", children: "Waiting for Claude's turn…" }) : picker("Plan"));
    out.push(note("rvl", `Looked for: ${(st?.searched ?? []).join(", ")}`, { wrap: "truncate-end" }));
    return out;
  }
  if (st.kind === "invalid") {
    out.push(Text({ key: "rvi", bold: true, color: "red", children: "The plan review could not be used." }));
    out.push(Text({ key: "rvip", dimColor: true, wrap: "truncate-end", children: st.path }));
    for (const [i, e] of st.errors.entries()) out.push(Text({ key: `rve${i}`, color: "red", wrap: "wrap", children: `• ${e}` }));
    out.push(picker("Review a plan again"));
    return out;
  }

  const { review } = st;
  const derived = deriveReview(model, review, { depth: ctx.impactDepth });
  const errors = st.issues.filter((i) => i.level === "error");
  const warnings = st.issues.filter((i) => i.level === "warning");
  const revisions = Object.entries(review.model.revisions ?? {}).map(([k, v]) => `${k ? `${k} ` : ""}${v ? v.slice(0, 12) : "no revision"}`).join(", ") || "no revision recorded";

  const alreadyThere = (f) => f.action === "create" && st.plannedExists?.get(pathKey(f)) === true;
  const existingCreates = review.plannedFiles.filter(alreadyThere).length;
  const newFiles = review.plannedFiles.filter((f) => f.action === "create").length - existingCreates;

  const touchCount = (g) => {
    const unresolved = g.touches.filter((t) => !resolveRef(model, review, t.ref).ok).length;
    const resolved = g.touches.length - unresolved;
    return `${resolved ? `touches ${resolved}` : "touches no modeled element"}${unresolved ? ` · ${unresolved} unresolved` : ""}`;
  };
  const citeButton = (key, cite, label) =>
    cite
      ? Button({ key, label: `${ctx.reviewExcerpt?.key === key ? "▾" : "▸"} ${label ?? `${base(review.plan.path)}:${cite.lines[0]}${cite.lines[1] > cite.lines[0] ? `-${cite.lines[1]}` : ""}`}`, plain: true, onPress: () => ctx.actions.peek(key, { path: review.plan.path, lines: cite.lines, quote: cite.quote }) })
      : Text({ key, color: "red", children: "no plan citation" });
  const sourceButton = (key, ev) =>
    Button({ key, label: u.cut(`${ctx.reviewExcerpt?.key === key ? "▾" : "▸"} ${ev.path}${ev.lines ? `:${ev.lines[0]}${ev.lines[1] > ev.lines[0] ? `-${ev.lines[1]}` : ""}` : ""}${ev.note ? ` — ${ev.note}` : ""}`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.peek(key, ev) });
  const excerptFor = (key) => {
    const ex = ctx.reviewExcerpt;
    if (ex?.key !== key) return null;
    if (ex.status !== "ok") return Text({ key: `${key}-x`, color: "red", wrap: "wrap", children: ex.message });
    return Box({
      key: `${key}-x`,
      flexDirection: "column",
      marginLeft: 2,
      children: [
        ex.warning ? Text({ key: "w", color: "yellow", wrap: "wrap", children: `! ${ex.warning}` }) : null,
        Text({ key: "h", dimColor: true, children: `${ex.path}:${ex.startLine}` }),
        ex.quote ? Text({ key: "q", wrap: "wrap", children: `“${ex.quote}”` }) : null,
        h.Code({ key: "c", source: ex.source, path: ex.path, startLine: ex.startLine, wrap: "truncate-end" }),
        ex.hidden > 0 ? Text({ key: "m", dimColor: true, children: `… ${u.plural(ex.hidden, "more cited line")} not shown` }) : null,
      ],
    });
  };
  const refButtons = (prefix, refs) =>
    refs.map((ref, i) => {
      const key = `${prefix}-${i}`;
      const r = resolveRef(model, review, ref);
      if (ref.kind.startsWith("proposed")) return Text({ key, color: "cyan", wrap: "truncate-end", children: `┄ ${r.label}${r.ok ? "" : " ✗ not proposed anywhere"}` });
      if (!r.ok) return Text({ key, color: "red", wrap: "truncate-end", children: `✗ ${r.label} (not in the model)` });
      return Button({ key, label: u.cut(r.label, ctx.cols - 6), plain: true, onPress: () => ctx.actions.select(ref.kind, ref.id, key) });
    });

  out.push(Text({ key: "rvtitle", bold: true, wrap: "wrap", children: review.title || "Plan review" }));
  out.push(Text({ key: "rvprov", dimColor: true, wrap: "wrap", children: `plan ${review.plan.path}${review.plan.fingerprint ? ` (${review.plan.fingerprint.slice(4, 12)})` : ""} · reviewed against model @ ${revisions}${review.generatedBy ? ` · ${review.generatedBy}` : ""}` }));
  for (const [i, s] of st.stale.entries()) out.push(Text({ key: `rvs${i}`, color: "yellow", wrap: "wrap", children: `! ${s.message}` }));
  if (!st.citationsChecked) out.push(Text({ key: "rvnc", color: "yellow", wrap: "wrap", children: "! The plan could not be read, so its citations were not checked." }));
  for (const [i, w] of warnings.filter((x) => x.where === "verification").entries()) out.push(Text({ key: `rvu${i}`, color: "yellow", wrap: "wrap", children: `! ${w.message}` }));
  if (errors.length) out.push(Text({ key: "rverr", color: "red", wrap: "wrap", children: `✗ ${u.plural(errors.length, "problem")} in this review; the affected items are marked or left out (see Checks).` }));
  out.push(
    Box({
      key: "rvact",
      gap: 2,
      flexWrap: "wrap",
      children: [Button({ key: "rvagain", label: ctx.reviewing ? "Waiting for Claude…" : "Review again", plain: true, onPress: () => ctx.actions.requestReview(review.plan.path) }), Text({ key: "rvdepth", dimColor: true, children: "Reach:" }), u.reachButtons(h, ctx)],
    }),
  );
  const stated = derived.touched.filter((e) => e.basis === "stated").length;
  const names = (list, n) => `${list.slice(0, n).join(", ")}${list.length > n ? `, +${list.length - n}` : ""}`;
  const comps = derived.touched.filter((e) => e.kind === "component").map((e) => e.label);
  const asked = review.questions.filter((q) => q.origin === "suggested").length;
  const glance = [
    ["rvh1", "1  Proposes", `${u.plural(review.intents.length, "change")}${review.summary || review.title ? `: ${u.cut(review.summary || review.title, 90)}` : ""}`],
    ["rvh2", "2  Implicates", `${derived.touched.length} existing elements (${stated} stated, ${derived.touched.length - stated} inferred)${comps.length ? ` incl. ${names(comps, 3)}` : ""}`],
    ["rvh3", "3  Not modeled", `${u.plural(review.proposed.components.length, "proposed component")}, ${u.plural(review.proposed.relationships.length, "proposed relationship")}, ${u.plural(newFiles, "new file")}${existingCreates ? `, ${existingCreates} already in the checkout` : ""}`],
    ["rvh4", "4  Look next", `${derived.reach.length ? `${names(derived.reach.map((r) => r.component.name), 3)} depend${derived.reach.length === 1 ? "s" : ""} on what is touched` : "no dependent component modeled"} · ${u.plural(derived.steps.length, "workflow step")}`],
    ["rvh5", "5  Uncertain", `${review.questions.length - asked} left open by the plan · ${asked} suggested by Claude · ${u.plural(review.nonGoals.length, "non-goal")} to verify`],
  ];
  out.push(Box({ key: "rvglance", flexDirection: "column", marginTop: 1, children: glance.map(([target, title, text], i) => Box({ key: `rvgr${i + 1}`, gap: 2, children: [Button({ key: `rvgl${i + 1}`, label: title, plain: true, onPress: () => ctx.actions.jump(target) }), Text({ key: `rvgt${i + 1}`, wrap: "wrap", children: text })] })) }));
  out.push(note("rvleg", "[plan] stated by the plan · [model] existing architecture, as modeled · [derived] computed by Sidecar from modeled relationships · [suggested] Claude's question, not verified", { wrap: "wrap" }));

  const intentRows = review.intents.flatMap((g) => [
    Box({ key: `rvi-${g.id}`, flexDirection: "column", children: [
      Text({ key: `rvi-${g.id}-s`, wrap: "wrap", children: `▪ ${g.statement}` }),
      Box({ key: `rvi-${g.id}-r`, marginLeft: 2, gap: 2, children: [citeButton(`pc-i-${g.id}`, g.cite), Text({ key: `rvi-${g.id}-t`, dimColor: true, children: touchCount(g) })] }),
      excerptFor(`pc-i-${g.id}`),
    ] }),
  ]);
  out.push(heading("rvh1", "1  What the plan proposes", ["plan"]));
  if (review.summary) out.push(Text({ key: "rvsm", wrap: "wrap", children: review.summary }));
  out.push(...(intentRows.length ? intentRows : [note("rvno1", "The review lists no intents.")]));

  out.push(heading("rvh2", "2  Existing architecture implicated", ["model", "plan"]));
  out.push(note("rvh2n", "Elements the model already contains that the review maps the plan onto. “stated”: the plan names it. “inferred”: Claude's mapping. The mark is the model's own confidence in that element."));
  if (!derived.touched.length) out.push(note("rvno2", "The review maps the plan onto no modeled element."));
  for (const [i, e] of derived.touched.entries()) {
    const conf = confidenceOf(model, e.kind, e.id);
    out.push(
      Box({ key: `rvt${i}`, flexDirection: "column", children: [
        Box({ key: `rvt${i}-a`, gap: 1, children: [
          Text({ key: `rvt${i}-m`, color: u.COLOR[conf], children: u.MARK[conf] ?? " " }),
          Button({ key: `rvt${i}-n`, label: u.cut(e.label, ctx.cols - 30), plain: true, onPress: () => ctx.actions.select(e.kind, e.id, `rvt${i}-n`) }),
          Text({ key: `rvt${i}-b`, color: e.basis === "stated" ? "cyan" : "yellow", children: e.basis === "stated" ? "stated in plan" : "inferred by Claude" }),
          e.kind !== "step" ? Button({ key: `rvt${i}-i`, label: "Impact ▸", plain: true, onPress: () => ctx.actions.openImpact(e.kind, e.id, `rvt${i}-i`) }) : null,
        ] }),
        Text({ key: `rvt${i}-w`, dimColor: true, wrap: "wrap", children: `  ${e.kind}${e.why.length ? ` · ${e.why[0]}` : ""} · ${e.citesPlannedFile ? "cites a file the plan names" : "cites no file the plan names"} · ← ${e.intents.join(", ")}` }),
      ] }),
    );
  }

  out.push(heading("rvh3", "3  Proposed — not in the model", ["plan"]));
  out.push(note("rvh3n", "Not in the model. Dashed (┄) means the review proposes it; nothing here is a modeled fact or has source evidence. A file marked “create · already exists” is already in this checkout, so that work may already be done."));
  const proposed = review.proposed;
  if (!proposed.components.length && !proposed.relationships.length) out.push(note("rvno3", "The review proposes no new component or relationship."));
  for (const c of proposed.components) {
    const within = c.within ? byId(model.components, c.within.id) : undefined;
    out.push(
      Box({ key: `rvc-${c.id}`, flexDirection: "column", children: [
        Text({ key: `rvc-${c.id}-a`, color: "cyan", wrap: "wrap", children: `┄ + ${c.name} (${c.kind})${within ? ` inside ${within.name}` : ""}` }),
        c.responsibility ? Text({ key: `rvc-${c.id}-r`, dimColor: true, wrap: "wrap", children: `  ${c.responsibility}` }) : null,
        Box({ key: `rvc-${c.id}-l`, marginLeft: 2, gap: 2, children: [citeButton(`pc-c-${c.id}`, c.cite), within ? Button({ key: `rvc-${c.id}-w`, label: `Open ${within.name}`, plain: true, onPress: () => ctx.actions.select("component", within.id, `rvc-${c.id}-w`) }) : null] }),
        excerptFor(`pc-c-${c.id}`),
      ] }),
    );
  }
  for (const r of proposed.relationships) {
    const [from, to] = [resolveRef(model, review, r.from), resolveRef(model, review, r.to)];
    const parallel = parallelLinks(model, r);
    const endpoint = (ref, key) => (ref.kind.startsWith("proposed") ? [Text({ key, color: "cyan", children: `+${resolveRef(model, review, ref).label}` })] : refButtons(key, [ref]));
    out.push(
      Box({ key: `rvr-${r.id}`, flexDirection: "column", children: [
        Box({ key: `rvr-${r.id}-a`, gap: 1, flexWrap: "wrap", children: [
          ...endpoint(r.from, `rvr-${r.id}-e1`),
          Text({ key: `rvr-${r.id}-arr`, color: "cyan", children: "┄┄▶" }),
          ...endpoint(r.to, `rvr-${r.id}-e2`),
          Text({ key: `rvr-${r.id}-k`, dimColor: true, children: `${r.kind}${from.ok && to.ok ? "" : " ✗ endpoint unresolved"}` }),
        ] }),
        r.label ? Text({ key: `rvr-${r.id}-lb`, dimColor: true, wrap: "wrap", children: `  ${r.label}` }) : null,
        ...parallel.map((x, i) => Box({ key: `rvr-${r.id}-par${i}`, marginLeft: 2, gap: 1, children: [Text({ key: `rvr-${r.id}-par${i}-t`, dimColor: true, children: "the model already links these two:" }), Button({ key: `rvr-${r.id}-par${i}-b`, label: u.cut(`${x.label || x.kind} (${x.id})`, ctx.cols - 40), plain: true, onPress: () => ctx.actions.select("relationship", x.id, `rvr-${r.id}-par${i}-b`) })] })),
        Box({ key: `rvr-${r.id}-l`, marginLeft: 2, children: [citeButton(`pc-r-${r.id}`, r.cite)] }),
        excerptFor(`pc-r-${r.id}`),
      ] }),
    );
  }
  if (review.plannedFiles.length) {
    out.push(Text({ key: "rvfh", bold: true, children: `Files the plan names (${review.plannedFiles.length})` }));
    out.push(note("rvfn", "A path match only finds elements worth a look; it is a candidate signal, not impact, and says nothing about what a change does."));
    for (const [i, c] of derived.candidates.slice(0, LIST_MAX).entries()) {
      const comps = c.elements.filter((x) => x.kind !== "step");
      const steps = c.elements.filter((x) => x.kind === "step").length;
      const cited = comps.length || steps ? `cited by ${comps.map((x) => `${x.label}${x.named ? "" : " ?"}`).join(", ")}${steps ? `${comps.length ? " +" : ""} ${u.plural(steps, "workflow step")}` : ""}` : "cited by nothing in the model";
      out.push(
        Box({ key: `rvf${i}`, flexDirection: "column", children: [
          Box({ key: `rvf${i}-a`, gap: 1, children: [Box({ key: `rvf${i}-xb`, flexShrink: 0, children: [Text({ key: `rvf${i}-x`, color: c.file.action === "create" && !alreadyThere(c.file) ? "cyan" : undefined, children: c.file.action === "create" ? (alreadyThere(c.file) ? "create · already exists" : "create") : "modify" })] }), Text({ key: `rvf${i}-p`, wrap: "truncate-start", children: c.file.path })] }),
          Box({ key: `rvf${i}-b`, marginLeft: 2, gap: 2, children: [Text({ key: `rvf${i}-t`, dimColor: true, wrap: "truncate-end", children: cited }), citeButton(`pc-f-${i}`, c.file.cite)] }),
          excerptFor(`pc-f-${i}`),
        ] }),
      );
    }
    if (derived.candidates.length > LIST_MAX) out.push(more("rvfm", derived.candidates.length - LIST_MAX));
    out.push(note("rvfq", "“?” marks an element the file matches that the review did not name: worth a look, not a finding."));
  }

  out.push(heading("rvh4", "4  Where to look next", ["derived"]));
  out.push(note("rvh4n", "Computed from the model's declared relationships, never from the review's prose. Reachable in the model is not confirmed breakage; a missing relationship is a silent gap."));
  const reachRows = derived.reach.slice(0, LIST_MAX).map((d, i) => {
    const path = d.chain.length ? [d.chain[0].from, ...d.chain.map((r) => r.to)].map((id) => byId(model.components, id).name).join(" → ") : "linked through a relationship";
    const caveat = `${d.confidence !== "observed" ? ` · weakest link ${d.confidence}` : ""}${d.uncited ? " · a link cites no file" : ""}`;
    return Button({ key: `rvd${i}`, label: u.cut(`${d.component.name} · ${d.hop === 1 ? "direct" : `${d.hop} hops`}: ${path}${caveat} · via ${d.because.join(", ")}`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.openImpact("component", d.component.id, `rvd${i}`) });
  });
  out.push(Text({ key: "rvdh", bold: true, children: `Components that depend on what is touched (${derived.reach.length})` }));
  out.push(...(reachRows.length ? reachRows : [note("rvno4", "None modeled within the chosen reach.")]));
  if (derived.reach.length > LIST_MAX) out.push(more("rvdm", derived.reach.length - LIST_MAX));
  out.push(Text({ key: "rvsh", bold: true, children: `Workflow steps (${derived.steps.length})` }));
  for (const [i, s] of derived.steps.slice(0, LIST_MAX).entries()) {
    out.push(u.link(h, ctx, `rvs-${i}`, `${u.MARK[s.step.confidence]} ${s.flow.name} · step ${s.step.n}: ${s.step.action}${s.named ? " [named in review]" : ""}${s.via.length ? ` [via ${s.via.join(", ")}]` : ""}`, "step", `${s.flow.id}#${s.step.n}`));
  }
  if (!derived.steps.length) out.push(note("rvno5", "No workflow step is named or reached through a touched relationship."));
  if (derived.steps.length > LIST_MAX) out.push(more("rvsm2", derived.steps.length - LIST_MAX));
  const lenses = { data: ctx.status.data?.kind === "ready" ? ctx.status.data.data : undefined, auth: ctx.status.auth?.kind === "ready" ? ctx.status.auth.auth : undefined };
  const touchedSteps = derived.touched.filter((e) => e.kind === "step").map((e) => ({ kind: "step", id: e.id, label: e.label }));
  if ((lenses.data || lenses.auth) && touchedSteps.length) out.push(...reachSection(h, ctx, u, reachFrom(model, lenses, touchedSteps), touchedSteps.length, `Data and authorization at ${u.plural(touchedSteps.length, "step")} the review touches (the plan's mapping, not a code overlap)`, "a step the review touches"));
  if (derived.involving.length) out.push(note("rvinv", `Not listed: steps that merely involve a touched component (${derived.involving.map((x) => `${x.component.name} ${x.count}`).join(", ")}). Open that component's Impact to see them.`));
  if (derived.untraced.length) out.push(note("rvun", `${u.plural(derived.untraced.length, "named step")} map${derived.untraced.length === 1 ? "s" : ""} to no single relationship (local, ambiguous or a response leg), so nothing is traced downstream from ${derived.untraced.length === 1 ? "it" : "them"}.`));

  out.push(heading("rvh5", "5  Uncertain or needs a decision", ["plan", "suggested"]));
  const questionRow = (q, tag) =>
    Box({ key: `rvq-${q.id}`, flexDirection: "column", children: [
      Text({ key: `rvq-${q.id}-t`, wrap: "wrap", children: [Text({ key: "g", color: TAG[tag][1], children: `${TAG[tag][0]} ` }), Text({ key: "k", dimColor: true, children: `${q.type}: ` }), Text({ key: "x", children: q.text })] }),
      q.cite ? Box({ key: `rvq-${q.id}-c`, marginLeft: 2, children: [citeButton(`pc-q-${q.id}`, q.cite)] }) : null,
      q.cite ? excerptFor(`pc-q-${q.id}`) : null,
      ...q.evidence.flatMap((ev, i) => [Box({ key: `rvq-${q.id}-e${i}`, marginLeft: 2, children: [sourceButton(`pq-${q.id}-${i}`, ev)] }), excerptFor(`pq-${q.id}-${i}`)]),
      q.refs.length ? Box({ key: `rvq-${q.id}-r`, marginLeft: 2, flexDirection: "column", children: [Text({ key: `rvq-${q.id}-l`, dimColor: true, children: "about" }), ...refButtons(`rvq-${q.id}-rf`, q.refs)] }) : null,
    ] });
  const fromPlan = review.questions.filter((q) => q.origin === "plan");
  const suggested = review.questions.filter((q) => q.origin === "suggested");
  out.push(Text({ key: "rvqp", bold: true, children: `Left open by the plan itself (${fromPlan.length})` }));
  out.push(...(fromPlan.length ? fromPlan.map((q) => questionRow(q, "plan")) : [note("rvnq1", "None recorded.")]));
  out.push(Text({ key: "rvqs", bold: true, children: `Suggested by Claude — not verified (${suggested.length})` }));
  out.push(note("rvqsn", "Possible omissions or disagreements between the plan and the model or code. Treat each as a question for a person; the evidence shows what Claude read, not that it is right."));
  out.push(...(suggested.length ? suggested.map((q) => questionRow(q, "suggested")) : [note("rvnq2", "None.")]));

  out.push(Text({ key: "rvgh", bold: true, children: `Non-goals the plan states — a person has to verify (${derived.nonGoals.length})` }));
  for (const n of derived.nonGoals) {
    const g = n.goal;
    const status =
      n.status === "overlap"
        ? Text({ key: `rvg-${g.id}-s`, color: "yellow", wrap: "wrap", children: `! The review touches or reaches what this constrains: ${n.hits.map((x) => `${x.label} (${x.how})`).join("; ")}. Check the plan honors it.` })
        : n.status === "none-found"
          ? Text({ key: `rvg-${g.id}-s`, dimColor: true, wrap: "wrap", children: "○ No overlap found in the modeled relationships. That is not verification: the model may be incomplete." })
          : Text({ key: `rvg-${g.id}-s`, dimColor: true, wrap: "wrap", children: "○ Names no existing element, so Sidecar cannot compare it with anything." });
    out.push(Box({ key: `rvg-${g.id}`, flexDirection: "column", children: [Text({ key: `rvg-${g.id}-t`, wrap: "wrap", children: `▪ ${g.statement}` }), Box({ key: `rvg-${g.id}-c`, marginLeft: 2, children: [citeButton(`pc-n-${g.id}`, g.cite)] }), excerptFor(`pc-n-${g.id}`), Box({ key: `rvg-${g.id}-st`, marginLeft: 2, children: [status] })] }));
  }
  if (!derived.nonGoals.length) out.push(note("rvnng", "The plan states none that the review recorded."));

  out.push(heading("rvh6", "Checks", ["derived"]));
  const rows = [...errors.map((x) => ({ x, c: "red", m: "✗" })), ...warnings.map((x) => ({ x, c: "yellow", m: "!" }))];
  for (const [i, r] of rows.slice(0, 20).entries()) out.push(Text({ key: `rvk${i}`, color: r.c, wrap: "wrap", children: `${r.m} ${r.x.where}: ${r.x.message}` }));
  if (rows.length > 20) out.push(more("rvkm", rows.length - 20));
  out.push(note("rvkn", `${rows.length ? "" : "No reference or citation problems found. "}This confirms that references resolve and quotes appear where cited. It does not confirm that the plan is right, that the mapping is complete, or that any non-goal holds.`));
  return out;
}

