import { byId } from "./model.mjs";
import { hopConfidence, hopName, traceFailure } from "./behavior.mjs";

const CLAIMS = [
  ["release", "Returns to its caller"],
  ["holds", "Holds the data"],
  ["onError", "When what it calls fails"],
];
const TAG = {
  origin: ["✗ failure starts here", "red"],
  returns: ["↑ passes the error up", "yellow"],
  drops: ["⊘ error ends: data dropped", "red"],
  holds: ["⏸ error ends: data kept", "cyan"],
  unresolved: ["? the document is silent", "magenta"],
};
const FATE = { dropped: "dropped", held: "kept", returned: "returned to the caller", unresolved: "not stated" };

const ACTION = { return: "returns the error to its caller", drop: "drops the data", hold: "keeps the data", unknown: "not stated" };

function claimSummary(claim) {
  if (claim.mode) return `: ${claim.mode === "early" ? "returns without waiting" : "waits for the result"}`;
  if (claim.action) return `: ${ACTION[claim.action]}${claim.action === "hold" && claim.store ? ` in ${claim.store}` : ""}${claim.retries ? ", after retrying" : ""}`;
  return claim.store ? `: in ${claim.store}` : "";
}

const lineRange = (ev) => `${ev.lines[0]}${ev.lines[1] > ev.lines[0] ? `-${ev.lines[1]}` : ""}`;

export function behaviorView(h, ctx, u) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const st = ctx.status.behavior;
  const out = [];
  const note = (key, text, props = {}) => Text({ key, dimColor: true, wrap: "wrap", children: text, ...props });
  const heading = (key, text) => Box({ key, marginTop: 1, children: [Text({ key: `${key}-t`, bold: true, children: text })] });

  if (ctx.canBack) out.push(Button({ key: "back", label: "◀ Back", hotkey: "b", plain: true, onPress: ctx.actions.back }));
  if (!st || st.kind === "none") {
    out.push(Text({ key: "bhn", bold: true, children: "No behavior description yet." }));
    out.push(note("bhnh", "This view follows one failure through the hops of a workflow: who is told, who is not, what holds the data and where it ends up. It reads .architecture/behavior.json, which cites the source for every claim."));
    out.push(note("bhl", `Looked for: ${(st?.searched ?? []).join(", ")}`, { wrap: "truncate-end" }));
    return out;
  }
  if (st.kind === "invalid") {
    out.push(Text({ key: "bhi", bold: true, color: "red", children: "The behavior description could not be used." }));
    out.push(Text({ key: "bhip", dimColor: true, wrap: "truncate-end", children: st.path }));
    for (const [i, e] of st.errors.entries()) out.push(Text({ key: `bhe${i}`, color: "red", wrap: "wrap", children: `• ${e}` }));
    return out;
  }

  const { behavior: b } = st;
  const sel = ctx.behavior;
  const variantId = b.variants.some((v) => v.id === sel.variant) ? sel.variant : "default";
  const originId = b.origins.some((o) => o.id === sel.origin) ? sel.origin : b.origins[0].id;
  const trace = traceFailure(b, variantId, originId);
  const hops = trace.hops;
  const name = (hop) => hopName(model, hop);
  const selected = hops.find((x) => x.id === sel.hop) ?? (trace.available ? trace.stop?.hop : undefined) ?? hops[0];
  const errors = [...st.parseIssues, ...st.issues].filter((i) => i.level === "error");
  const warnings = [...st.parseIssues, ...st.issues].filter((i) => i.level === "warning");

  const all = [...b.hops.flatMap((x) => [x.release, x.holds, x.onError, ...x.notes]), ...b.origins.map((o) => o.emits), ...b.variants.flatMap((v) => Object.values(v.changes).flatMap((c) => Object.values(c)))].filter(Boolean);
  const count = (c) => all.filter((x) => x.confidence === c).length;
  out.push(Text({ key: "bht", bold: true, wrap: "wrap", children: b.title || "Behavior" }));
  if (b.summary) out.push(note("bhs", b.summary));
  out.push(note("bhprov", `${all.length} claims: ${u.MARK.observed} ${count("observed")} ${u.MARK.inferred} ${count("inferred")} ${u.MARK.unknown} ${count("unknown")} · ${st.checked.confirmed}/${st.checked.total} quotes found at their lines${b.generatedBy ? ` · ${b.generatedBy}` : ""}`));
  for (const [i, s] of st.stale.entries()) out.push(Text({ key: `bhst${i}`, color: "yellow", wrap: "wrap", children: `! ${s.message}` }));
  if (errors.length) out.push(Text({ key: "bherr", color: "red", wrap: "wrap", children: `✗ ${u.plural(errors.length, "problem")} in this document; the affected claims may not be trustworthy (see Checks).` }));

  const strip = (key, label, items, on, press) =>
    Box({ key, gap: 2, flexWrap: "wrap", children: [Text({ key: `${key}-l`, dimColor: true, children: label }), ...items.map((x) => Button({ key: `${key}-${x.id}`, label: `${on === x.id ? "▸ " : ""}${x.name}`, plain: true, onPress: () => press(x.id) }))] });
  out.push(strip("bhv", "Configuration:", [{ id: "default", name: "Default" }, ...b.variants], variantId, (id) => ctx.actions.setBehavior({ variant: id })));
  const variant = b.variants.find((v) => v.id === variantId);
  if (variant) out.push(note("bhw", `${variant.name}: ${variant.when}`));
  out.push(strip("bho", "Failure starts at:", b.origins, originId, (id) => ctx.actions.setBehavior({ origin: id })));

  const nameList = (xs) => xs.map((x) => name(x.hop)).join(", ");
  if (trace.available) {
    const route = trace.steps.map((s) => name(s.hop)).join(" → ");
    const told = trace.callerSees.kind === "error" ? "the error comes back to it" : trace.callerSees.why === "early" ? `OK: ${name(hops[trace.callerSees.at])} returned before the downstream work finished` : `OK: ${name(hops[trace.callerSees.at])} swallowed the error`;
    const keptIn = trace.stop?.hop.onError?.store ?? trace.stop?.hop.holds?.store;
    const data = trace.fate === "held" ? `${FATE.held}${keptIn ? ` in ${keptIn}` : "; the document does not say where"}` : trace.fate === "dropped" ? `${FATE.dropped} by ${name(trace.stop.hop)}` : FATE[trace.fate];
    const row = (key, label, text, props = {}) => Box({ key, gap: 1, children: [Box({ key: `${key}-b`, width: 19, flexShrink: 0, children: [Text({ key: `${key}-l`, dimColor: true, children: label })] }), Text({ key: `${key}-t`, wrap: "wrap", ...props, children: text })] });
    out.push(
      Box({
        key: "bhsum",
        flexDirection: "column",
        marginTop: 1,
        borderStyle: "round",
        borderColor: u.COLOR[trace.weakest],
        paddingX: 1,
        children: [
          Text({ key: "bhsh", bold: true, wrap: "wrap", children: `${variant ? variant.name : "Default"} · ${trace.origin.name}` }),
          row("bhs1", "Caller is told", told, { color: trace.callerSees.kind === "error" ? "red" : "green" }),
          row("bhs2", "Error travels", `${route}${trace.reachedCaller ? ", back to the caller" : ", then stops"}`),
          row("bhs3", "Data is", data, { color: trace.fate === "dropped" ? "red" : trace.fate === "held" ? "cyan" : undefined }),
          row("bhs4", "Error never reaches", trace.unseen.length ? nameList(trace.unseen) : "every hop up to the caller sees it"),
          row("bhs5", "Where it shows", trace.signals.length ? `${u.plural(trace.signals.length, "signal")} (listed below)` : "no signal is claimed"),
          row("bhs6", "Weakest link", `${u.MARK[trace.weakest]} ${trace.weakest}`, { color: u.COLOR[trace.weakest] }),
        ],
      }),
    );
  } else {
    out.push(Text({ key: "bhna", color: "yellow", wrap: "wrap", children: `! ${trace.reason}. Choose another failure or configuration.` }));
  }

  const pic = ctx.picture?.status === "ready" ? ctx.picture : null;
  out.push(heading("bhph", "Path, caller first"));
  if (pic) {
    const at = hops.findIndex((x) => x.id === selected.id);
    out.push(
      Box({
        key: "bhnav",
        gap: 2,
        flexWrap: "wrap",
        children: [
          Button({ key: "bhp", label: "◀ prev", hotkey: "p", plain: true, onPress: () => ctx.actions.setBehavior({ hop: hops[Math.max(0, at - 1)].id }) }),
          h.Select({ key: "bhsel", label: "Hop", value: selected.id, options: hops.map((x, i) => ({ value: x.id, label: u.cut(`${i + 1}. ${name(x)}`, Math.max(20, ctx.cols - 24)) })), onSelect: (value) => ctx.actions.setBehavior({ hop: value }) }),
          Button({ key: "bhn", label: "next ▶", hotkey: "n", plain: true, onPress: () => ctx.actions.setBehavior({ hop: hops[Math.min(hops.length - 1, at + 1)].id }) }),
        ],
      }),
    );
    out.push(Box({ key: "pic", children: [pic.node] }));
  } else {
    if (ctx.picture) out.push(h.Text({ key: "bhpn", dimColor: true, children: ctx.picture.status === "pending" ? "Drawing the diagram…" : `The diagram could not be drawn (${ctx.picture.message}); showing the text view.` }));
    out.push(note("bhleg", "│ waits · ┊ returns early · ✗ starts · ↑ passes up · ⊘ ⏸ ends"));
  }
  const role = new Map();
  if (trace.available) {
    for (const s of trace.steps) role.set(s.index, s.kind);
  }
  const nameWidth = Math.min(Math.max(...hops.map((x) => name(x).length)) + 2, Math.max(14, ctx.cols - 40));
  if (!pic) hops.forEach((hop, i) => {
    const conf = hopConfidence(hop);
    const on = hop.id === selected.id;
    const kind = role.get(i);
    const tag = trace.available ? (kind ? TAG[kind] : i < trace.start ? ["· never sees it", undefined] : ["· not involved", undefined]) : undefined;
    const marked = kind === "returns" && hop.onError?.retries ? ["↻ retries, then ↑ passes it up", "yellow"] : tag;
    out.push(
      Box({
        key: `bhr-${hop.id}`,
        gap: 1,
        children: [
          Text({ key: `bhr-${hop.id}-n`, color: on ? "cyan" : undefined, dimColor: !on, children: `${on ? "▸" : " "}${i + 1}`.padStart(3) }),
          Text({ key: `bhr-${hop.id}-m`, color: u.COLOR[conf], children: u.MARK[conf] }),
          Box({ key: `bhr-${hop.id}-w`, width: nameWidth, flexShrink: 0, children: [Button({ key: `bhr-${hop.id}-b`, label: u.cut(name(hop), nameWidth - 1), plain: true, onPress: () => ctx.actions.setBehavior({ hop: hop.id }) })] }),
          marked ? Text({ key: `bhr-${hop.id}-t`, color: marked[1], dimColor: !marked[1], wrap: "truncate-end", children: marked[0] }) : null,
        ],
      }),
    );
    if (i < hops.length - 1) {
      const early = hop.release?.mode === "early";
      const wait = hop.release?.mode === "waits";
      out.push(Text({ key: `bhc-${hop.id}`, color: early ? "yellow" : undefined, dimColor: !early, wrap: "truncate-end", children: `      ${early ? "┊ returns to its caller without waiting" : wait ? "│ waits for the next hop" : "│ not stated"}${early && trace.firstEarly === i ? "  ◀ callers above are told OK" : ""}` }));
      if (hop.holds) out.push(Text({ key: `bhk-${hop.id}`, dimColor: true, wrap: "truncate-end", children: `      ▪ holds the data in ${hop.holds.store ?? "memory"}` }));
    }
  });

  const evidenceRows = (prefix, claim) =>
    claim.evidence.flatMap((ev, i) => {
      const key = `bx-${prefix}-${i}`;
      const open = ctx.reviewExcerpt?.key === key;
      const ex = open ? ctx.reviewExcerpt : null;
      return [
        Button({ key, label: u.cut(`${open ? "▾" : "▸"} ${ev.repo ? `[${ev.repo}] ` : ""}${ev.path}:${lineRange(ev)}${ev.note ? ` — ${ev.note}` : ""}`, ctx.cols - 8), plain: true, onPress: () => ctx.actions.peek(key, ev) }),
        ex
          ? ex.status !== "ok"
            ? Text({ key: `${key}-x`, color: "red", wrap: "wrap", children: ex.message })
            : Box({ key: `${key}-x`, flexDirection: "column", marginLeft: 2, children: [ex.warning ? Text({ key: "w", color: "yellow", wrap: "wrap", children: `! ${ex.warning}` }) : null, Text({ key: "h", dimColor: true, children: `${ex.path}:${ex.startLine}` }), ex.quote ? Text({ key: "q", wrap: "wrap", children: `“${ex.quote}”` }) : null, h.Code({ key: "c", source: ex.source, path: ex.path, startLine: ex.startLine, wrap: "truncate-end" }), ex.hidden > 0 ? Text({ key: "m", dimColor: true, children: `… ${u.plural(ex.hidden, "more cited line")} not shown` }) : null] })
          : null,
      ];
    });
  const claimBlock = (prefix, title, claim, changed) =>
    Box({
      key: `bxc-${prefix}`,
      flexDirection: "column",
      marginTop: 1,
      children: [
        Text({ key: `bxc-${prefix}-t`, wrap: "wrap", color: u.COLOR[claim.confidence], children: `${u.MARK[claim.confidence]} ${title}${claimSummary(claim)}${changed ? "  [changed in this configuration]" : ""}` }),
        Text({ key: `bxc-${prefix}-x`, wrap: "wrap", children: claim.text }),
        ...evidenceRows(prefix, claim),
        claim.evidence.length === 0 ? Text({ key: `bxc-${prefix}-n`, color: "red", children: "No source cited — treat as unverified." }) : null,
      ],
    });
  const detail = [Text({ key: "bxh", bold: true, wrap: "wrap", color: u.COLOR[hopConfidence(selected)], children: `${u.MARK[hopConfidence(selected)]} ${hops.indexOf(selected) + 1}. ${name(selected)}` }), selected.role ? note("bxr", selected.role) : null];
  const comp = selected.component && byId(model.components, selected.component);
  detail.push(
    Box({
      key: "bxl",
      gap: 2,
      flexWrap: "wrap",
      children: [
        comp ? Button({ key: "bxl-c", label: `Open ${comp.name}`, plain: true, onPress: () => ctx.actions.select("component", comp.id, "bxl-c") }) : Text({ key: "bxl-c", dimColor: true, children: "external to the model" }),
        selected.step ? Button({ key: "bxl-s", label: `Open flow step ${selected.step}`, plain: true, onPress: () => ctx.actions.select("step", selected.step, "bxl-s") }) : null,
        comp ? Button({ key: "bxl-i", label: "Impact ▸", plain: true, onPress: () => ctx.actions.openImpact("component", comp.id, "bxl-i") }) : null,
      ],
    }),
  );
  for (const [key, title] of CLAIMS) {
    const claim = selected[key];
    const changed = selected.changed.includes(key);
    if (claim) detail.push(claimBlock(`${selected.id}-${key}`, title, claim, changed));
    else if (changed) detail.push(note(`bxc-${selected.id}-${key}-gone`, `${title}: not present in this configuration.`));
  }
  for (const [i, n] of selected.notes.entries()) detail.push(claimBlock(`${selected.id}-note${i}`, "Also", n, false));
  if (selected.id === (trace.origin.hop ?? "")) detail.push(claimBlock(`${selected.id}-origin`, "Where the failure starts", trace.origin.emits, false));
  out.push(Box({ key: "bxd", flexDirection: "column", marginTop: 1, borderStyle: "round", borderColor: u.COLOR[hopConfidence(selected)], paddingX: 1, children: detail }));

  if (trace.available && trace.signals.length) {
    out.push(heading("bhsgh", "Where it shows"));
    for (const [i, s] of trace.signals.entries()) out.push(Text({ key: `bhsg${i}`, wrap: "wrap", children: `▪ ${s.text}  (${name(s.hop)})` }));
    out.push(note("bhsgn", "Names come from the source that was read. Nothing was run, so none of these was seen in output."));
  }

  out.push(heading("bhqh", `Unresolved (${b.questions.length})`));
  for (const q of b.questions) {
    const hop = q.hop && b.hops.find((x) => x.id === q.hop);
    out.push(
      Box({
        key: `bhq-${q.id}`,
        flexDirection: "column",
        children: [
          Text({ key: `bhq-${q.id}-t`, wrap: "wrap", children: `${u.MARK.unknown} ${q.text}` }),
          hop ? Button({ key: `bhq-${q.id}-h`, label: `  about ${name(hop)}`, plain: true, onPress: () => ctx.actions.setBehavior({ hop: hop.id }) }) : null,
          ...q.evidence.flatMap((ev, i) => {
            const key = `bx-${q.id}-${i}`;
            return [Button({ key, label: u.cut(`  ${ctx.reviewExcerpt?.key === key ? "▾" : "▸"} ${ev.repo ? `[${ev.repo}] ` : ""}${ev.path}:${lineRange(ev)}`, ctx.cols - 6), plain: true, onPress: () => ctx.actions.peek(key, ev) }), ctx.reviewExcerpt?.key === key ? (ctx.reviewExcerpt.status === "ok" ? Box({ key: `${key}-x`, flexDirection: "column", marginLeft: 4, children: [h.Code({ key: "c", source: ctx.reviewExcerpt.source, path: ctx.reviewExcerpt.path, startLine: ctx.reviewExcerpt.startLine, wrap: "truncate-end" })] }) : Text({ key: `${key}-x`, color: "red", wrap: "wrap", children: ctx.reviewExcerpt.message })) : null];
          }),
        ],
      }),
    );
  }

  out.push(heading("bhkh", "Checks"));
  const rows = [...errors.map((x) => ({ x, c: "red", m: "✗" })), ...warnings.map((x) => ({ x, c: "yellow", m: "!" }))];
  for (const [i, r] of rows.slice(0, 12).entries()) out.push(Text({ key: `bhk${i}`, color: r.c, wrap: "wrap", children: `${r.m} ${r.x.where}: ${r.x.message}` }));
  if (rows.length > 12) out.push(note("bhkm", `… and ${rows.length - 12} more`));
  out.push(note("bhkn", `${rows.length ? "" : "No citation or reference problems found. "}This confirms that the cited lines contain the quoted text. It does not confirm that a claim is a correct reading of that code, that the walk is complete, or that the code behaves so when run.`));
  return out;
}

