import { byId } from "./model.mjs";
import { compareAlternatives, describeDiff, explorationWindow, readiness, stepNumber, supportOf } from "./explore.mjs";

const SUPPORT = { spec: ["[spec]", "cyan"], source: ["[source]", "blue"], hypothesis: ["[hypothesis]", "magenta"] };
const STATUS = { meets: ["meets", "green"], conflicts: ["CONFLICTS", "red"], unclear: ["unclear", "yellow"] };
const PROPOSED = "magenta";

const base = (path) => path.split("/").pop();
const range = (c) => `${c.lines[0]}${c.lines[1] > c.lines[0] ? `-${c.lines[1]}` : ""}`;

/** The Explore view: one requirement and question, the sequence with the chosen alternative drawn on it, how each alternative reads against the spec, and what is unresolved. */
export function exploreView(h, ctx, u) {
  const { Box, Text, Button, Input } = h;
  const st = ctx.status.explore;
  const out = [];
  const note = (key, text, props = {}) => Text({ key, dimColor: true, wrap: "wrap", children: text, ...props });

  const specField = (label) =>
    Input({
      key: "xsp",
      label,
      placeholder: ".specify/specs/NNN-feature/spec.md",
      value: ctx.explorePath ?? "",
      submitLabel: "explore",
      onInput: (value) => ctx.actions.setExplorePath(value),
      onSubmit: (value) => ctx.actions.requestExplore(value),
    });

  if (!st || st.kind === "none") {
    out.push(Text({ key: "xn", bold: true, children: "No exploration yet." }));
    out.push(note("xnh", "Start from a specification: Claude reads one requirement, the architecture model and the code, and writes one exploration of a single architectural decision with two or more alternatives drawn on the existing workflow. It runs one Claude turn when you ask, and nothing else."));
    out.push(ctx.exploring ? Text({ key: "xw", color: "cyan", children: "Waiting for Claude's turn…" }) : specField("Specification"));
    out.push(note("xnl", `Looked for: ${(st?.searched ?? []).join(", ")}`, { wrap: "truncate-end" }));
    return out;
  }
  if (st.kind === "invalid") {
    out.push(Text({ key: "xi", bold: true, color: "red", children: "The exploration could not be used." }));
    out.push(Text({ key: "xip", dimColor: true, wrap: "truncate-end", children: st.path }));
    for (const [i, e] of st.errors.entries()) out.push(Text({ key: `xie${i}`, color: "red", wrap: "wrap", children: `• ${e}` }));
    out.push(specField("Explore a specification"));
    return out;
  }

  const { model } = ctx;
  const { exploration: ex, failed } = st;
  const unchecked = st.unchecked ?? new Set();
  const alt = ex.alternatives.find((a) => a.id === ctx.exploreAlt);
  const errors = st.issues.filter((i) => i.level === "error");
  const warnings = st.issues.filter((i) => i.level === "warning");
  const compare = compareAlternatives(ex);
  const ready = readiness(ex);
  const win = explorationWindow(model, ex);
  const flow = win?.flow;
  const revisions = Object.entries(ex.model.revisions ?? {}).map(([k, v]) => `${k ? `${k} ` : ""}${v ? v.slice(0, 12) : "no revision"}`).join(", ") || "no revision recorded";

  const heading = (key, title, tags) =>
    Box({ key, gap: 1, marginTop: 1, children: [Text({ key: `${key}-t`, bold: true, children: title }), ...tags.map(([label, color], i) => Text({ key: `${key}-${i}`, color, dimColor: !color, children: label }))] });
  const cite = (key, c, label) =>
    Button({ key, label: `${ctx.reviewExcerpt?.key === key ? "▾" : "▸"} ${label ?? `${base(ex.spec.path)}:${range(c)}`}`, plain: true, onPress: () => ctx.actions.peek(key, { path: ex.spec.path, lines: c.lines, quote: c.quote }) });
  const sourceButton = (key, ev) =>
    Button({ key, label: u.cut(`${ctx.reviewExcerpt?.key === key ? "▾" : "▸"} ${ev.path}:${range(ev)}${ev.note ? ` — ${ev.note}` : ""}`, ctx.cols - 4), plain: true, onPress: () => ctx.actions.peek(key, ev) });
  const excerptFor = (key) => {
    const x = ctx.reviewExcerpt;
    if (x?.key !== key) return null;
    if (x.status !== "ok") return Text({ key: `${key}-x`, color: "red", wrap: "wrap", children: x.message });
    return Box({
      key: `${key}-x`,
      flexDirection: "column",
      marginLeft: 2,
      children: [
        x.warning ? Text({ key: "w", color: "yellow", wrap: "wrap", children: `! ${x.warning}` }) : null,
        Text({ key: "h", dimColor: true, children: `${x.path}:${x.startLine}` }),
        x.quote ? Text({ key: "q", wrap: "wrap", children: `“${u.cut(x.quote, 700)}”` }) : null,
        h.Code({ key: "c", source: x.source, path: x.path, startLine: x.startLine, wrap: "truncate-end" }),
        x.hidden > 0 ? Text({ key: "m", dimColor: true, children: `… ${u.plural(x.hidden, "more cited line")} not shown` }) : null,
      ],
    });
  };
  // A premise opens its first citation; the page reads it from the spec or from the cited source.
  const premiseButton = (key, p) => {
    const first = p.kind === "spec" ? p.cite && { path: ex.spec.path, lines: p.cite.lines, quote: p.cite.quote } : p.evidence[0];
    if (!first) return Text({ key, color: "red", children: `${p.id} ✗ no citation` });
    return Button({ key, label: `${ctx.reviewExcerpt?.key === key ? "▾" : "▸"} ${p.id}${failed.has(p.id) ? (unchecked.has(p.id) ? " ?" : " ✗") : ""}`, plain: true, onPress: () => ctx.actions.peek(key, first) });
  };
  const stepName = (ref) => {
    const [flowId, n] = String(ref).split("#");
    const s = byId(model.flows, flowId)?.steps.find((x) => x.n === Number(n));
    return s ? `step ${n}${flowId === flow?.id ? "" : ` of ${flowId}`} (${s.action})` : String(ref);
  };

  out.push(Text({ key: "xtitle", bold: true, wrap: "wrap", children: ex.title || "Exploration" }));
  out.push(Text({ key: "xprov", dimColor: true, wrap: "wrap", children: `spec ${ex.spec.path}${ex.spec.fingerprint ? ` (${ex.spec.fingerprint.slice(4, 12)})` : ""} · model @ ${revisions}${ex.generatedBy ? ` · ${ex.generatedBy}` : ""}` }));
  for (const [i, s] of st.stale.entries()) out.push(Text({ key: `xs${i}`, color: "yellow", wrap: "wrap", children: `! ${s.message}` }));
  for (const [i, w] of warnings.filter((x) => x.where === "verification").entries()) out.push(Text({ key: `xu${i}`, color: "yellow", wrap: "wrap", children: `! ${w.message}` }));
  if (errors.length) out.push(Text({ key: "xerr", color: "red", wrap: "wrap", children: `✗ ${u.plural(errors.length, "problem")} in this exploration; claims that rest on a failed citation are shown as hypothetical (see Checks).` }));
  if (ctx.exploreChange) out.push(Text({ key: "xchg", color: "cyan", wrap: "wrap", children: `Changed since the last load: ${describeDiff(ctx.exploreChange)}` }));
  out.push(Text({ key: "xlimn", dimColor: true, wrap: "wrap", children: `${u.plural(ex.limits.length, "limit")} recorded on this exploration (end of this view).` }));

  const conflictLine = (a) => {
    const c = compare.conflicts.get(a.id);
    const q = compare.unclear.get(a.id);
    return `${a.id}: ${c.length ? `${u.plural(c.length, "potential conflict")} (${c.join(", ")})` : "no conflict found"}${q.length ? ` · ${q.length} unclear` : ""}`;
  };
  const sourceCount = ex.premises.filter((p) => p.kind === "source").length;
  const open = ready.bySpec.map((q) => q.id);
  const glance = [
    ["xr1", "1  Requirement", `${ex.requirement.id}${ex.requirement.summary ? `: ${u.cut(ex.requirement.summary, 100)}` : ""}`],
    ["xr2", "2  Question", u.cut(ex.question.text, 110)],
    ["xr3", "3  Sequence", `${flow ? u.plural(win.steps.length, "existing step") : "no flow"} · ${ex.alternatives.map((a) => `${a.id} (${u.plural(a.placements.length, "placement")})`).join(", ") || "no alternative"}`],
    ["xr4", "4  Compare", ex.alternatives.map(conflictLine).join(" · ") || "no alternative"],
    ["xr5", "5  Evidence", `${u.plural(ex.premises.length - sourceCount, "spec statement")}, ${u.plural(sourceCount, "source premise")} · ${st.checked.confirmed} of ${st.checked.total} citations confirmed`],
    ["xr6", "6  Unresolved", `${ready.open.length} open · ${open.length ? `${open.join(", ")} need the specification's answer` : "none needs the specification"}`],
    ["xr7", "7  Decision", ex.decision ? `${ex.decision.status}${ex.decision.alternative ? ` ${ex.decision.alternative}` : ""}${ex.decision.note ? `: ${u.cut(ex.decision.note, 80)}` : ""}` : "none recorded"],
  ];
  out.push(Box({ key: "xglance", flexDirection: "column", marginTop: 1, children: glance.map(([target, title, text], i) => Box({ key: `xg${i}`, gap: 2, children: [Button({ key: `xgl${i}`, label: title, plain: true, onPress: () => ctx.actions.jump(target) }), Text({ key: `xgt${i}`, wrap: "wrap", children: text })] })) }));
  out.push(note("xleg", "[spec] stated by the specification · [source] read in cited source · [hypothesis] a prediction nothing cited establishes · ⟦id⟧ PROPOSED is an alternative's hypothetical addition, never observed, inferred or unknown", { wrap: "wrap" }));

  // 1 requirement
  out.push(heading("xr1", "1  Requirement", [[SUPPORT.spec[0], SUPPORT.spec[1]]]));
  out.push(Text({ key: "xrq", bold: true, wrap: "wrap", children: `${ex.requirement.id}${ex.requirement.summary ? ` — ${ex.requirement.summary}` : ""}` }));
  out.push(Box({ key: "xrqc", marginLeft: 2, children: [ex.requirement.cite ? cite("ex-req", ex.requirement.cite, `Open the exact text · ${base(ex.spec.path)}:${range(ex.requirement.cite)}`) : Text({ key: "xrqn", color: "red", children: "no citation" })] }));
  out.push(excerptFor("ex-req"));
  out.push(Text({ key: "xcsh", bold: true, children: `What it requires (${ex.constraints.length})` }));
  for (const c of ex.constraints) {
    out.push(Box({ key: `xc-${c.id}`, flexDirection: "column", children: [Text({ key: `xc-${c.id}-t`, wrap: "wrap", children: `▪ ${c.id}  ${c.text}` }), Box({ key: `xc-${c.id}-c`, marginLeft: 2, children: [c.cite ? cite(`ex-c-${c.id}`, c.cite) : Text({ key: "n", color: "red", children: "no citation" })] }), excerptFor(`ex-c-${c.id}`)] }));
  }

  // 2 question
  out.push(heading("xr2", "2  Design question", []));
  out.push(Text({ key: "xq", wrap: "wrap", children: ex.question.text }));

  // 3 sequence
  out.push(heading("xr3", "3  The existing workflow and the alternatives", [["[model]", undefined], ["existing", undefined]]));
  out.push(
    Box({
      key: "xalts",
      gap: 2,
      flexWrap: "wrap",
      children: [
        Text({ key: "xal", dimColor: true, children: "Show:" }),
        Button({ key: "alt-none", label: `${alt ? "" : "▸ "}Existing only`, plain: true, onPress: () => ctx.actions.setExploreAlt(null) }),
        ...ex.alternatives.map((a) => Button({ key: `alt-${a.id}`, label: `${alt?.id === a.id ? "▸ " : ""}${a.id}  ${u.cut(a.name, 36)}`, plain: true, onPress: () => ctx.actions.setExploreAlt(a.id) })),
        Button({ key: "xnext", label: "Next ▸", hotkey: "a", plain: true, onPress: () => ctx.actions.cycleExploreAlt() }),
        Button({ key: "xtoreq", label: "↑ Requirement", plain: true, onPress: () => ctx.actions.jump("xr1") }),
      ],
    }),
  );
  if (!win) out.push(Text({ key: "xnowin", color: "red", wrap: "wrap", children: "The workflow steps this question is about are not in the model, so nothing can be drawn (see Checks)." }));
  else out.push(...u.sequence(h, ctx, flow, win, alt));
  if (alt) {
    out.push(
      Box({ key: "xaltbox", flexDirection: "column", marginTop: 1, children: [
        Text({ key: "xah", bold: true, color: PROPOSED, wrap: "wrap", children: `Alternative ${alt.id} · ${alt.name} — hypothetical, not in the model` }),
        Text({ key: "xas", wrap: "wrap", children: alt.summary }),
        ...alt.placements.map((p) => Text({ key: `xap-${p.id}`, color: PROPOSED, wrap: "wrap", children: `⟦${p.id}⟧ PROPOSED ${p.kind === "insert" ? `after ${stepName(p.after)}, ${byId(model.components, p.from)?.name ?? p.from} → ${byId(model.components, p.to)?.name ?? p.to}` : `change to ${stepName(p.step)}`}: ${p.text}` })),
        ...alt.assumptions.map((a, i) => Text({ key: `xaa${i}`, dimColor: true, wrap: "wrap", children: `assumes: ${a}` })),
      ] }),
    );
  } else if (win) out.push(note("xnoalt", "Choose an alternative to draw its proposed placement on the sequence. Without one, the sequence is exactly the model's."));

  // 4 compare
  out.push(heading("xr4", "4  Compare against the specification", [SUPPORT.spec, ["reading", undefined]]));
  out.push(note("xcmpn", "Each reading is Claude's reading of the cited text, not a verdict: “CONFLICTS” means the alternative departs from the words of that requirement, “unclear” that the words do not settle it."));
  for (const a of ex.alternatives) {
    const bad = compare.conflicts.get(a.id);
    if (bad.length) out.push(Text({ key: `xw-${a.id}`, color: "yellow", wrap: "wrap", children: `! ${a.id} may conflict with ${ex.requirement.id}: ${bad.map((id) => `${id} (${u.cut(ex.constraints.find((c) => c.id === id)?.text ?? "", 70)})`).join("; ")}` }));
  }
  for (const row of compare.rows) {
    const c = row.constraint;
    out.push(
      Box({ key: `xm-${c.id}`, flexDirection: "column", children: [
        Box({ key: `xm-${c.id}-a`, gap: 2, flexWrap: "wrap", children: [
          Text({ key: "i", bold: true, children: c.id }),
          ...ex.alternatives.map((a) => {
            const k = row.byAlt.get(a.id);
            const [label, color] = STATUS[k?.status ?? "unclear"];
            return Text({ key: `s-${a.id}`, color: k ? color : undefined, dimColor: !k, bold: alt?.id === a.id, children: `${a.id} ${k ? label : "not assessed"}` });
          }),
          c.cite ? cite(`ex-m-${c.id}`, c.cite, `${base(ex.spec.path)}:${range(c.cite)}`) : null,
        ] }),
        Text({ key: `xm-${c.id}-t`, dimColor: true, wrap: "wrap", children: `  ${c.text}` }),
        ...ex.alternatives.flatMap((a) => {
          const k = row.byAlt.get(a.id);
          return k?.why ? [Text({ key: `xm-${c.id}-w-${a.id}`, bold: alt?.id === a.id, wrap: "wrap", children: `  ${a.id} ${STATUS[k.status][0]}: ${k.why}` })] : [];
        }),
        excerptFor(`ex-m-${c.id}`),
      ] }),
    );
  }
  out.push(Box({ key: "xefb", marginTop: 1, children: [Text({ key: "xefh", bold: true, children: "Expected effects" })] }));
  out.push(note("xefn", "[source] follows from cited lines (not executed) · [spec] stated by the specification · [hypothesis] depends on behavior no cited text shows. An effect that claims support its premises do not give is shown as [hypothesis]."));
  for (const a of ex.alternatives) {
    const counts = ["spec", "source", "hypothesis"].map((s) => [s, a.effects.filter((e) => supportOf(ex, e, failed, unchecked).support === s).length]).filter(([, n]) => n);
    const shown = alt?.id === a.id;
    out.push(Text({ key: `xe-${a.id}-h`, bold: true, color: shown ? PROPOSED : undefined, wrap: "wrap", children: `${shown ? "▸ " : ""}${a.id} · ${a.name} — ${counts.map(([s, n]) => `${n} ${s}`).join(", ") || "no effects recorded"}${shown ? "" : " (choose it to read them)"}` }));
    if (!shown) continue;
    for (const e of a.effects) {
      const { support, downgraded, why } = supportOf(ex, e, failed, unchecked);
      const [label, color] = SUPPORT[support];
      out.push(
        Box({ key: `xe-${a.id}-${e.id}`, flexDirection: "column", children: [
          Text({ key: "t", wrap: "wrap", children: [Text({ key: "g", color, children: `${label} ` }), Text({ key: "x", children: e.text })] }),
          downgraded ? Text({ key: "d", color: "yellow", wrap: "wrap", children: `  ! recorded as ${e.support}, but ${why}; shown as hypothetical` }) : null,
          Box({ key: "p", marginLeft: 2, gap: 1, flexWrap: "wrap", children: [Text({ key: "l", dimColor: true, children: e.premises.length ? "premises" : "no premise cited" }), ...e.premises.map((id) => {
            const p = ex.premises.find((x) => x.id === id);
            return p ? premiseButton(`ex-e-${a.id}-${e.id}-${id}`, p) : Text({ key: `u-${id}`, color: "red", children: `${id} ✗ unknown` });
          })] }),
          ...e.premises.map((id) => excerptFor(`ex-e-${a.id}-${e.id}-${id}`)),
        ] }),
      );
    }
  }

  // 5 evidence
  out.push(heading("xr5", "5  Evidence behind the claims", [SUPPORT.spec, SUPPORT.source]));
  out.push(note("xevn", `${st.checked.confirmed} of ${st.checked.total} citations confirmed: the quoted text was found at the cited lines. That confirms where text is, not that a claim built on it is right.`));
  for (const p of ex.premises) {
    out.push(
      Box({ key: `xp-${p.id}`, flexDirection: "column", children: [
        Text({ key: "t", wrap: "wrap", children: [Text({ key: "g", color: SUPPORT[p.kind][1], children: `${SUPPORT[p.kind][0]} ` }), Text({ key: "i", bold: true, children: `${p.id} ` }), Text({ key: "x", children: p.statement }), failed.has(p.id) ? Text({ key: "f", color: unchecked.has(p.id) ? "yellow" : "red", children: unchecked.has(p.id) ? "  ? citation not checked" : "  ✗ citation does not hold" }) : null] }),
        p.kind === "spec" && p.cite ? Box({ key: "c", marginLeft: 2, children: [cite(`ex-p-${p.id}`, p.cite)] }) : null,
        p.kind === "spec" ? excerptFor(`ex-p-${p.id}`) : null,
        ...p.evidence.flatMap((ev, i) => [Box({ key: `e${i}`, marginLeft: 2, children: [sourceButton(`ex-p-${p.id}-${i}`, ev)] }), excerptFor(`ex-p-${p.id}-${i}`)]),
        p.about.length ? Box({ key: "a", marginLeft: 2, gap: 1, flexWrap: "wrap", children: [Text({ key: "al", dimColor: true, children: "about" }), ...p.about.map((r, i) => Button({ key: `ab${i}`, label: u.cut(r.kind === "step" ? stepName(r.id) : (byId(r.kind === "component" ? model.components : model.relationships, r.id)?.name ?? r.id), ctx.cols - 20), plain: true, onPress: () => ctx.actions.select(r.kind, r.id) }))] }) : null,
      ] }),
    );
  }

  // 6 unresolved
  out.push(heading("xr6", "6  Unresolved", [SUPPORT.spec]));
  out.push(note("xrn", "What the exploration could not settle, and who can: the specification's authors, a reader of more source, or someone outside the code. An alternative is blocked by a question when the answer decides whether it is acceptable."));
  for (const q of ready.open) {
    out.push(
      Box({ key: `xq-${q.id}`, flexDirection: "column", children: [
        Text({ key: "t", wrap: "wrap", children: [Text({ key: "g", color: q.answeredBy === "spec" ? "yellow" : undefined, dimColor: q.answeredBy !== "spec", children: `${q.answeredBy === "spec" ? "needs the spec" : q.answeredBy === "source" ? "needs more source" : "needs someone outside the code"} · ` }), Text({ key: "i", bold: true, children: `${q.id} ` }), Text({ key: "x", children: q.text })] }),
        q.blocks.length ? Text({ key: "b", dimColor: true, children: `  blocks ${q.blocks.join(", ")}` }) : null,
        q.cite ? Box({ key: "c", marginLeft: 2, children: [cite(`ex-u-${q.id}`, q.cite)] }) : null,
        q.cite ? excerptFor(`ex-u-${q.id}`) : null,
        ...q.evidence.flatMap((ev, i) => [Box({ key: `e${i}`, marginLeft: 2, children: [sourceButton(`ex-u-${q.id}-${i}`, ev)] }), excerptFor(`ex-u-${q.id}-${i}`)]),
      ] }),
    );
  }
  if (!ready.open.length) out.push(note("xrnone", "None recorded."));
  out.push(
    Text({ key: "xrdy", bold: true, wrap: "wrap", children: ready.bySpec.length ? `Before choosing: ${u.plural(ready.bySpec.length, "specification question")} (${open.join(", ")}) stay open. ${ex.alternatives.map((a) => `${a.id} is blocked by ${ready.blocked.get(a.id).join(", ") || "nothing recorded"}`).join("; ")}.` : "No specification question is recorded as open." }),
  );

  // 7 decision
  out.push(heading("xr7", "7  Decision", []));
  out.push(Text({ key: "xdc", wrap: "wrap", children: ex.decision ? `Recorded: ${ex.decision.status}${ex.decision.alternative ? ` — alternative ${ex.decision.alternative}` : ""}${ex.decision.by ? ` · ${ex.decision.by}` : ""}${ex.decision.note ? ` · ${ex.decision.note}` : ""}` : "No decision is recorded in the exploration." }));
  out.push(
    Box({ key: "xdb", gap: 2, flexWrap: "wrap", children: [
      Text({ key: "xdl", dimColor: true, children: "Your choice:" }),
      ...ex.alternatives.map((a) => Button({ key: `xlean-${a.id}`, label: `${ctx.exploreLean?.alternative === a.id ? "▸ " : ""}Choose ${a.id}`, plain: true, onPress: () => ctx.actions.leanDecision({ status: "selected", alternative: a.id }) })),
      Button({ key: "xlean-defer", label: `${ctx.exploreLean?.status === "deferred" ? "▸ " : ""}Defer`, plain: true, onPress: () => ctx.actions.leanDecision({ status: "deferred" }) }),
      Button({ key: "xlean-clar", label: `${ctx.exploreLean?.status === "needs-clarification" ? "▸ " : ""}Needs spec clarification`, plain: true, onPress: () => ctx.actions.leanDecision({ status: "needs-clarification" }) }),
    ] }),
  );
  if (ctx.exploreLean) {
    const l = ctx.exploreLean;
    const blocked = l.alternative ? ready.blocked.get(l.alternative) : [];
    out.push(Text({ key: "xlt", wrap: "wrap", children: `${l.status}${l.alternative ? ` ${l.alternative}` : ""} — kept in this pane only; nothing is written until you record it.` }));
    if (blocked?.length) out.push(Text({ key: "xlw", color: "yellow", wrap: "wrap", children: `! ${l.alternative} is blocked by open questions: ${blocked.join(", ")}.` }));
    out.push(Button({ key: "xrec", label: ctx.exploring ? "Waiting for Claude…" : "Record it in the exploration (asks Claude)", plain: true, onPress: () => ctx.actions.recordDecision() }));
  } else out.push(note("xlnone", "Choosing here does not write anything. Recording it asks Claude to put it in the exploration."));

  // follow-up
  out.push(heading("xr8", "Ask a follow-up", []));
  out.push(note("xfn", "Claude investigates the question against the same specification and source and updates this exploration narrowly (an alternative, an effect, a question). The pane reloads when the turn finishes and keeps what you selected."));
  out.push(
    ctx.exploring
      ? Text({ key: "xfw", color: "cyan", children: "Waiting for Claude's turn…" })
      : Input({ key: "xask", label: "Ask", placeholder: "for example: what changes if the transition is claimed before the pointer move?", value: ctx.exploreAsk ?? "", submitLabel: "ask Claude", onInput: (value) => ctx.actions.setExploreAsk(value), onSubmit: (value) => ctx.actions.requestFollowUp(value) }),
  );
  out.push(specField("Explore another specification"));

  // checks, limits
  out.push(heading("xr9", "Checks", [["[derived]", "blue"]]));
  const rows = [...errors.map((x) => ({ x, c: "red", m: "✗" })), ...warnings.filter((x) => x.where !== "verification").map((x) => ({ x, c: "yellow", m: "!" }))];
  for (const [i, r] of rows.slice(0, 20).entries()) out.push(Text({ key: `xk${i}`, color: r.c, wrap: "wrap", children: `${r.m} ${r.x.where}: ${r.x.message}` }));
  if (rows.length > 20) out.push(Text({ key: "xkm", dimColor: true, children: `… and ${rows.length - 20} more` }));
  out.push(note("xkn", `${rows.length ? "" : "No reference or citation problems found. "}This confirms that references resolve and quotes appear where cited. It does not confirm that a reading of the specification or the source is right.`));
  out.push(Text({ key: "xlh", bold: true, children: `Limits (${ex.limits.length})` }));
  for (const [i, l] of ex.limits.entries()) out.push(Text({ key: `xl${i}`, wrap: "wrap", children: `• ${l}` }));
  return out;
}

