import { byId } from "./model.mjs";
import { coverageNotes } from "./coverage-view.mjs";
import { ANY_STATE, consequencesOf, crudOf, dataCounts, entityName, lifecycleOrder, operationItems, partialFailures, stateDegree, touchesOf } from "./data.mjs";
import { opsAtStep } from "./auth.mjs";
import { transitionName } from "./diagram-data.mjs";
import { claimBlock, checksBlock, evidenceRows, heading, missingScreen, note, provenance, strip } from "./lens-view.mjs";

const MODES = [
  { id: "entities", name: "Entities" },
  { id: "lifecycle", name: "Lifecycle" },
  { id: "operations", name: "Operations" },
];
const GLYPH = { "row-lock": "row lock", "state-check": "state check", ownership: "owner check", idempotency: "idempotency", none: "no state check" };
const LOCK = { "row-lock": "takes a row lock", "refresh-before-write": "re-reads the row before writing", "none-found": "no lock or re-read found in the cited function", unknown: "not examined" };
const ASPECT = { atomicity: "Atomicity", visibility: "Visibility", concurrency: "Concurrency", "external-failure": "External failure" };

/** Links to the authorization view for the operations whose credential hops sit on these steps. */
function authLinks(h, ctx, u, refs, prefix) {
  const st = ctx.status.auth;
  if (st?.kind !== "ready") return [];
  const ops = [...new Map(refs.filter(Boolean).flatMap((r) => opsAtStep(st.auth, r)).map((o) => [o.id, o])).values()];
  return ops.slice(0, 3).map((o) => h.Button({ key: `${prefix}-${o.id}`, label: u.cut(`Authority ▸ ${o.name}: who may do this, under which credentials?`, ctx.cols - 8), plain: true, onPress: () => ctx.actions.openAuth({ operation: o.id }) }));
}

export function dataView(h, ctx, u) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const st = ctx.status.data;
  const out = [];
  if (ctx.canBack) out.push(Button({ key: "back", label: "◀ Back", hotkey: "b", plain: true, onPress: ctx.actions.back }));
  if (!st || st.kind !== "ready") {
    return [...out, ...missingScreen(h, st, { title: "data description", what: "This view shows what state a workflow changes: the entities and how they relate, a lifecycle with the guard on each transition, and the order of writes across systems. It reads .architecture/data.json, which cites the source for every claim.", hint: "Ask Claude to use the architecture-data skill to write it; nothing runs unless you ask." })];
  }
  const d = st.data;
  const sel = ctx.data;
  const mode = MODES.some((m) => m.id === sel.mode) ? sel.mode : "entities";
  const name = (id) => byId(model.components, id)?.name ?? id;
  const set = (patch) => ctx.actions.setData(patch);
  const pic = ctx.picture?.status === "ready" ? ctx.picture : null;
  const stepButton = (key, ref, text) => Button({ key, label: u.cut(text, ctx.cols - 6), plain: true, onPress: () => ctx.actions.select("step", ref, key) });
  const stepText = (ref) => {
    const hit = byId(model.flows, ref.split("#")[0])?.steps.find((s) => s.n === Number(ref.split("#")[1]));
    return hit ? `step ${hit.n}: ${name(hit.from)} → ${name(hit.to)}, ${hit.action}` : undefined;
  };
  const broken = (key, what, ref) => Text({ key, color: "red", wrap: "wrap", children: `✗ ${what} cites ${ref}, which is not in the model; it is not drawn or followed.` });

  out.push(...provenance(h, u, st, d, dataCounts(d), "dp"));
  out.push(note(h, "dleg", "● ◐ ○ are this document's claims. Lines that begin “derived” are computed from those claims and carry no mark of their own."));
  out.push(strip(h, "dmode", "Show:", MODES, mode, (id) => set({ mode: id })));
  if (pic) out.push(Box({ key: "pic", marginTop: 1, children: [pic.node] }));
  else if (ctx.picture) out.push(note(h, "dpn", ctx.picture.status === "pending" ? "Drawing the diagram…" : `The diagram could not be drawn (${ctx.picture.message}); showing the text view.`));

  if (mode === "entities") out.push(...entitiesMode(h, ctx, u, { d, sel, name, set, stepButton, broken }));
  else if (mode === "lifecycle") out.push(...lifecycleMode(h, ctx, u, { d, sel, name, set, stepButton, stepText, broken }));
  else out.push(...operationsMode(h, ctx, u, { d, sel, name, set, stepButton, stepText, broken }));

  out.push(heading(h, "dqh", `Unresolved (${d.questions.length})`));
  if (!d.questions.length) out.push(note(h, "dq0", "The document lists no open questions. That is not evidence that none exist."));
  for (const q of d.questions) {
    out.push(Box({ key: `dq-${q.id}`, flexDirection: "column", children: [Text({ key: `dq-${q.id}-t`, wrap: "wrap", children: `${u.MARK.unknown} ${q.text}` }), q.entity ? Button({ key: `dq-${q.id}-e`, label: `  about ${entityName(d, q.entity)}`, plain: true, onPress: () => set({ mode: "entities", entity: q.entity, relation: null }) }) : null, ...evidenceRows(h, ctx, u, `q-${q.id}`, q.evidence)] }));
  }
  out.push(...checksBlock(h, u, st, "d", "It does not confirm that a claim reads that code correctly, that the list of entities, transitions or writes is complete, or how the system behaves when run."));
  return out;
}

function entitiesMode(h, ctx, u, { d, sel, name, set, stepButton, broken }) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const out = [];
  if (!d.entities.length) return [note(h, "de0", "This document models no entities.")];
  const entity = byId(d.entities, sel.entity) ?? d.entities[0];
  out.push(heading(h, "deh", `Entities (${d.entities.length})`));
  for (const e of d.entities) {
    const on = e.id === entity.id;
    out.push(Box({ key: `de-${e.id}`, gap: 1, children: [Text({ key: `de-${e.id}-m`, color: u.COLOR[e.confidence], children: u.MARK[e.confidence] }), Button({ key: `de-${e.id}-b`, label: u.cut(`${on ? "▸ " : "  "}${e.name}  ·  ${name(e.store)}`, ctx.cols - 8), plain: true, onPress: () => set({ entity: e.id, relation: null }) })] }));
  }
  const c = consequencesOf(model, d, entity.id);
  const touch = touchesOf(model, d, entity.id);
  const crud = crudOf(d, entity.id);
  const detail = [Text({ key: "dh", bold: true, wrap: "wrap", color: u.COLOR[entity.confidence], children: `${u.MARK[entity.confidence]} ${entity.name}  ·  ${entity.kind} in ${name(entity.store)}` }), Text({ key: "dd", wrap: "wrap", children: entity.description })];
  if (entity.key) detail.push(note(h, "dk", `Key: ${entity.key}`));
  for (const [i, f] of entity.fields.entries()) detail.push(Text({ key: `df${i}`, wrap: "truncate-end", dimColor: true, children: `  ${f.role.padEnd(7)} ${f.name}${f.note ? ` — ${f.note}` : ""}` }));

  const rels = [...c.related];
  detail.push(heading(h, "drh", `Relations (${rels.length})`));
  if (!rels.length) detail.push(note(h, "dr0", "No relation is documented for this entity."));
  for (const r of rels) {
    const on = sel.relation === r.relation.id;
    detail.push(Button({ key: `dr-${r.relation.id}`, label: u.cut(`${on ? "▾" : "▸"} ${r.direction === "out" ? "→" : "←"} ${entityName(d, r.other)}  ·  ${r.relation.kind}${r.relation.via ? ` via ${r.relation.via}` : ""}`, ctx.cols - 10), plain: true, onPress: () => set({ relation: on ? null : r.relation.id }) }));
    if (on) detail.push(claimBlock(h, ctx, u, `rel-${r.relation.id}`, `${entityName(d, r.relation.from)} → ${entityName(d, r.relation.to)}`, r.relation), Button({ key: `dr-${r.relation.id}-go`, label: `  Open ${entityName(d, r.other)}`, plain: true, onPress: () => set({ entity: r.other, relation: null }) }));
  }

  detail.push(heading(h, "dth", "Touched by (derived from the effects the document lists)"));
  if (!crud.length) detail.push(note(h, "dt0", "No effect names this entity."));
  for (const row of crud) detail.push(Text({ key: `dc-${row.component}`, wrap: "wrap", children: `derived  ${name(row.component)}: ${[...row.ops.keys()].join(", ")}` }));
  for (const f of touch.flows) {
    detail.push(Text({ key: `dfl-${f.flow.id}`, dimColor: true, wrap: "wrap", children: `derived  in the workflow “${f.flow.name}”` }));
    for (const at of f.steps) detail.push(stepButton(`dst-${f.flow.id}-${at.step.n}`, `${f.flow.id}#${at.step.n}`, `  ▸ step ${at.step.n}: ${at.effects.map((e) => `${e.op} by ${name(e.component)}`).join("; ")}`));
  }
  if (touch.offFlow.length) {
    detail.push(Text({ key: "doff", dimColor: true, wrap: "wrap", children: `derived  outside any modeled workflow (${touch.offFlow.length}):` }));
    for (const e of touch.offFlow) detail.push(Text({ key: `doff-${e.id}`, wrap: "wrap", children: `  ${e.op} by ${name(e.component)} via ${e.via}` }));
  }
  for (const e of touch.unresolved) detail.push(broken(`dbr-${e.id}`, `effect ${e.id}`, e.step));

  detail.push(heading(h, "dch", "If this changes (derived)"));
  detail.push(Text({ key: "dcw", wrap: "wrap", children: `derived  written by ${c.writers.length ? c.writers.map(name).join(", ") : "no listed component"}${c.readers.length ? `; read by ${c.readers.map(name).join(", ")}` : ""}` }));
  if (c.transitions.length) detail.push(Button({ key: "dcl", label: u.cut(`derived  ${entity.name}.${d.lifecycles.find((l) => l.entity === entity.id).field} has ${c.transitions.length} documented transitions  ▸ Lifecycle`, ctx.cols - 6), plain: true, onPress: () => set({ mode: "lifecycle", lifecycle: d.lifecycles.find((l) => l.entity === entity.id).id, transition: null, state: null }) }));
  if (c.impact) detail.push(Button({ key: "dci", label: u.cut(`derived  ${name(entity.store)} is used by ${c.impact.counts.consumers} and depends on ${c.impact.counts.providers} in the model  ▸ Impact`, ctx.cols - 6), plain: true, onPress: () => ctx.actions.openImpact("component", entity.store, "dci") }));
  detail.push(note(h, "dcn", "Reachability in the model's relationships, not confirmed breakage. Entities in another store are linked only by equal key values, so a change here is not visible to the database."));

  detail.push(...coverageNotes(h, ctx, u, "entity", entity.id, "dcv"));
  detail.push(claimBlock(h, ctx, u, `ent-${entity.id}`, "The entity", { text: entity.description, confidence: entity.confidence, evidence: entity.evidence }));
  out.push(Box({ key: "dd-box", flexDirection: "column", marginTop: 1, borderStyle: "round", borderColor: u.COLOR[entity.confidence], paddingX: 1, children: detail }));
  return out;
}

function lifecycleMode(h, ctx, u, { d, sel, name, set, stepButton, stepText, broken }) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const out = [];
  if (!d.lifecycles.length) return [note(h, "dl0", "This document models no lifecycle.")];
  const life = byId(d.lifecycles, sel.lifecycle) ?? d.lifecycles[0];
  const order = lifecycleOrder(model, life);
  const items = order.all;
  const current = byId(items, sel.transition);
  const stateSel = !current && life.states.some((s) => s.id === sel.state) ? sel.state : null;
  const at = current ? items.indexOf(current) : -1;
  if (d.lifecycles.length > 1) out.push(strip(h, "dlstrip", "Lifecycle:", d.lifecycles.map((l) => ({ id: l.id, name: `${entityName(d, l.entity)}.${l.field}` })), life.id, (id) => set({ lifecycle: id, transition: null, state: null })));
  out.push(heading(h, "dlh", `${entityName(d, life.entity)}.${life.field}: ${life.states.length} states, ${life.transitions.length} transitions`));
  out.push(Box({ key: "dls", gap: 2, flexWrap: "wrap", children: [Text({ key: "l", dimColor: true, children: "States:" }), ...life.states.map((s) => Button({ key: `dls-${s.id}`, label: `${stateSel === s.id ? "▸ " : ""}${s.label}${s.terminal ? " ■" : ""}`, plain: true, onPress: () => set({ state: s.id, transition: null }) }))] }));
  out.push(Box({ key: "dlnav", gap: 2, children: [Button({ key: "dlp", label: "◀ prev", hotkey: "p", plain: true, onPress: () => set({ transition: items[Math.max(0, at - 1)]?.id, state: null }) }), Button({ key: "dln", label: "next ▶", hotkey: "n", plain: true, onPress: () => set({ transition: items[Math.min(items.length - 1, at + 1)]?.id, state: null }) }), Text({ key: "dlpos", dimColor: true, children: at >= 0 ? `${at + 1} of ${items.length}` : `${items.length} transitions` })] }));
  const from = (t) => t.from.map((f) => (f === null ? "created" : f === ANY_STATE ? "any state" : f)).join(" | ");
  const label = (t) => u.cut(`${from(t)} → ${t.to}  ·  ${transitionName(t)}  ·  ${t.guard ? GLYPH[t.guard.kind] : "guard not examined"}`, ctx.cols - 14);
  const section = (key, title, list) => {
    if (!list.length) return;
    out.push(note(h, `${key}h`, title));
    for (const t of list) out.push(Box({ key: `dlt-${t.id}`, gap: 1, children: [Text({ key: `dlt-${t.id}-m`, color: u.COLOR[t.confidence], children: u.MARK[t.confidence] }), Button({ key: `dlt-${t.id}-b`, label: `${current?.id === t.id ? "▸ " : "  "}${label(t)}`, plain: true, onPress: () => set({ transition: t.id, state: null }) })] }));
  };
  section("dlon", "On the modeled workflow, in order:", order.onWorkflow);
  section("dloff", "Not on the modeled workflow:", order.offWorkflow);
  for (const t of order.broken) out.push(broken(`dlbr-${t.id}`, `transition ${t.id}`, t.step));

  if (current) {
    const t = current;
    const detail = [Text({ key: "th", bold: true, wrap: "wrap", color: u.COLOR[t.confidence], children: `${u.MARK[t.confidence]} ${from(t)} → ${t.to}  (${transitionName(t)})` })];
    detail.push(Text({ key: "tt", wrap: "wrap", children: t.text }));
    if (t.trigger) detail.push(note(h, "ttr", `Trigger: ${t.trigger}`));
    detail.push(note(h, "tby", `Performed by: ${t.by.map(name).join(", ")}`));
    const hit = t.step && byId(model.flows, t.step.split("#")[0])?.steps.find((s) => s.n === Number(t.step.split("#")[1]));
    if (hit) detail.push(stepButton("tstep", t.step, `Open flow ${stepText(t.step)}`));
    else if (t.step) detail.push(broken("tbr", "this transition", t.step));
    if (hit) detail.push(...authLinks(h, ctx, u, [t.step], "tauth"));
    else detail.push(note(h, "tno", "No step of a modeled workflow performs this; it is reached through the trigger above."));
    const effects = d.effects.filter((e) => e.transition === t.id);
    if (effects.length) {
      detail.push(Text({ key: "tef", dimColor: true, wrap: "wrap", children: `derived  the effects that name this transition (${effects.length}):` }));
      for (const e of effects) detail.push(Text({ key: `tef-${e.id}`, wrap: "wrap", children: `  ${e.op} ${entityName(d, e.entity)} by ${name(e.component)}: ${e.text}` }));
    }
    if (t.guard) {
      detail.push(claimBlock(h, ctx, u, `g-${t.id}`, `Guard: ${GLYPH[t.guard.kind]}`, t.guard, { lines: [...(t.guard.lock ? [`Lock: ${LOCK[t.guard.lock]}`] : []), ...t.guard.missing.map((m) => `Not checked: ${m}`)] }));
    } else detail.push(Text({ key: "tg0", wrap: "wrap", color: "yellow", children: `${u.MARK.unknown} The document does not say what guards this transition. That is not a statement that it is unguarded.` }));
    detail.push(claimBlock(h, ctx, u, `t-${t.id}`, "The transition", t));
    out.push(Box({ key: "dld", flexDirection: "column", marginTop: 1, borderStyle: "round", borderColor: u.COLOR[t.confidence], paddingX: 1, children: detail }));
  } else if (stateSel) {
    const s = byId(life.states, stateSel);
    const deg = stateDegree(life, stateSel);
    const detail = [Text({ key: "sh", bold: true, children: `${s.label}${s.terminal ? "  (marked terminal)" : ""}` })];
    for (const [key, title, list] of [["sin", "Enters through", deg.in], ["sout", "Leaves through", deg.out]]) {
      detail.push(note(h, `${key}h`, `${title} (${list.length})`));
      for (const t of list) detail.push(Button({ key: `${key}-${t.id}`, label: u.cut(`  ${label(t)}`, ctx.cols - 6), plain: true, onPress: () => set({ transition: t.id, state: null }) }));
    }
    if (s.terminal && deg.out.length) detail.push(Text({ key: "sterm", color: "yellow", wrap: "wrap", children: `derived  marked terminal, yet ${deg.out.length} transition${deg.out.length === 1 ? "" : "s"} can leave it (${deg.out.map(transitionName).join(", ")}).` }));
    out.push(Box({ key: "dld", flexDirection: "column", marginTop: 1, borderStyle: "round", paddingX: 1, children: detail }));
  } else out.push(note(h, "dlpick", "Select a transition or a state to read its guard, trigger and citations."));
  return out;
}

function operationsMode(h, ctx, u, { d, sel, name, set, stepButton, stepText, broken }) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const out = [];
  if (!d.sequences.length) return [note(h, "do0", "This document lists no ordered write sequences.")];
  const seq = byId(d.sequences, sel.sequence) ?? d.sequences[0];
  const pf = partialFailures(model, d, seq);
  const items = operationItems(model, d, seq);
  const current = byId(items, sel.item) ?? items[0];
  const at = items.indexOf(current);
  out.push(strip(h, "dosq", "Operation:", d.sequences.map((s) => ({ id: s.id, name: s.name })), seq.id, (id) => set({ sequence: id, item: null })));
  if (seq.summary) out.push(note(h, "dosum", seq.summary));
  out.push(Box({ key: "donav", gap: 2, children: [Button({ key: "dop", label: "◀ prev", hotkey: "p", plain: true, onPress: () => set({ item: items[Math.max(0, at - 1)]?.id }) }), Button({ key: "don", label: "next ▶", hotkey: "n", plain: true, onPress: () => set({ item: items[Math.min(items.length - 1, at + 1)]?.id }) }), Text({ key: "dopos", dimColor: true, children: at >= 0 ? `${at + 1} of ${items.length}` : "" })] }));
  out.push(note(h, "doord", "Writes in the order the cited code runs them. Each join is a point where the next write might not happen."));
  for (const item of items) {
    if (item.kind === "write") {
      const u0 = item.unit;
      out.push(Box({ key: `dow-${u0.ref}`, gap: 1, children: [Text({ key: `dow-${u0.ref}-m`, color: u.COLOR[u0.writes[0].confidence], children: u.MARK[u0.writes[0].confidence] }), Button({ key: `dow-${u0.ref}-b`, label: u.cut(`${current.id === item.id ? "▸ " : "  "}${u0.step.n}. ${name(u0.step.from)} → ${name(u0.step.to)}: ${u0.writes.map((w) => `${w.op} ${w.entity ? entityName(d, w.entity) : `signal ${name(w.system)}`}`).join(", ")}`, ctx.cols - 10), plain: true, onPress: () => set({ item: item.id }) })] }));
    } else out.push(Button({ key: `doc-${item.id}`, label: u.cut(`${current.id === item.id ? "▸ " : "  "}    ↳ if the next write does not happen (${item.cut.differentSystems ? "different systems" : "same system"})`, ctx.cols - 6), plain: true, onPress: () => set({ item: item.id }) }));
  }
  for (const ref of pf.broken) out.push(broken(`dobr-${ref}`, `sequence ${seq.id}`, ref));
  if (pf.silent.length) out.push(note(h, "dosil", `No modeled write at: ${pf.silent.map((s) => `step ${s.step.n}`).join(", ")}. Anything those steps write is outside this walk.`));

  if (!current) return out;
  const detail = [];
  if (current.kind === "write") {
    const unit = current.unit;
    detail.push(Text({ key: "wh", bold: true, wrap: "wrap", children: `Step ${unit.step.n}: ${name(unit.step.from)} → ${name(unit.step.to)}` }), Text({ key: "wa", wrap: "wrap", children: unit.step.action }));
    detail.push(stepButton("wstep", unit.ref, `Open flow ${stepText(unit.ref)}`), ...authLinks(h, ctx, u, [unit.ref], "wauth"));
    for (const e of unit.effects) detail.push(claimBlock(h, ctx, u, `e-${e.id}`, `${e.op} ${e.entity ? entityName(d, e.entity) : `signal to ${name(e.system)}`}  ·  by ${name(e.component)}${e.system || e.entity ? `  ·  in ${name(e.system ?? byId(d.entities, e.entity)?.store)}` : ""}`, e));
  } else {
    const cut = current.cut;
    const sys = (x) => x.systems.map(name).join(", ");
    detail.push(Text({ key: "ch", bold: true, wrap: "wrap", children: `Suppose step ${cut.after.step.n} (${sys(cut.after)}) happens and step ${cut.next.step.n} (${sys(cut.next)}) does not` }));
    detail.push(...authLinks(h, ctx, u, [cut.after.ref, cut.next.ref], "cauth"));
    detail.push(note(h, "cnote", "This reads the order the code runs these writes in; it asserts nothing about which earlier writes took effect or who can see them."));
    detail.push(Text({ key: "cord", wrap: "wrap", children: `derived  ordered before: ${[...cut.before, cut.after].map((x) => `step ${x.step.n}`).join(", ")}; ordered after, not reached: ${[cut.next, ...cut.later].map((x) => `step ${x.step.n}`).join(", ")}` }));
    detail.push(Text({ key: "csys", wrap: "wrap", color: cut.differentSystems ? "yellow" : undefined, children: cut.differentSystems ? `derived  the two writes name different systems (${sys(cut.after)} and ${sys(cut.next)}), so one transaction cannot cover both.` : `derived  both writes name ${sys(cut.after)}; this document does not say whether one transaction covers them.` }));
    if (pf.ordering) detail.push(claimBlock(h, ctx, u, `ord-${seq.id}`, "Order, as the source states it", pf.ordering));
    else detail.push(Text({ key: "cno", color: "yellow", wrap: "wrap", children: "! No source is cited for the order; it is the model's step numbering only." }));
    detail.push(heading(h, "caspects", "What is established about this point"));
    for (const a of cut.aspects) {
      if (!a.claims.length) detail.push(Text({ key: `ca-${a.aspect}`, dimColor: true, wrap: "wrap", children: `${u.MARK.unknown} ${ASPECT[a.aspect]}: not established by this document` }));
      for (const c of a.claims) detail.push(claimBlock(h, ctx, u, `u-${c.id}`, ASPECT[a.aspect], c));
    }
    detail.push(heading(h, "cres", "What may be left behind, as claimed"));
    if (!cut.residue.length) detail.push(Text({ key: "cres0", dimColor: true, wrap: "wrap", children: `${u.MARK.unknown} The document claims nothing about what remains here. That is not a statement that nothing does.` }));
    for (const r of cut.residue) detail.push(claimBlock(h, ctx, u, `r-${r.id}`, "Left behind", r));
    if (pf.compensation) detail.push(claimBlock(h, ctx, u, `comp-${seq.id}`, `Recovery: ${pf.compensation.kind.replace(/-/g, " ")}`, pf.compensation));
    else detail.push(Text({ key: "ccomp", dimColor: true, wrap: "wrap", children: `${u.MARK.unknown} Recovery is not described for this operation.` }));
  }
  out.push(Box({ key: "dod", flexDirection: "column", marginTop: 1, borderStyle: "round", paddingX: 1, children: detail }));
  return out;
}

