import { byId } from "./model.mjs";
import { admittedBy, authCounts, conditionalPolicy, consequencesOfCredential, consequencesOfGuard, executionOf, flowSelection, hopStatements, opsUsingCredential, principalName } from "./auth.mjs";
import { AUTHORITY_TEXT, MODE_TEXT } from "./diagram-auth.mjs";
import { coverageNotes } from "./coverage-view.mjs";
import { claimBlock, checksBlock, heading, missingScreen, note, provenance, strip } from "./lens-view.mjs";
import { stepRef } from "./lens.mjs";

const MODES = [
  { id: "operations", name: "Operations" },
  { id: "flow", name: "Authority flow" },
];
const MODE_WORDS = { all: "all of these must pass", any: "any one of these is enough", conditional: "depends on a condition", unknown: "no decision was located" };
const WHERE = { server: "enforced on the server", client: "client-side only (not enforcement)", platform: "enforced by the platform", unknown: "where it is enforced is not established" };

export function authView(h, ctx, u) {
  const { Box, Text, Button } = h;
  const { model } = ctx;
  const st = ctx.status.auth;
  const out = [];
  if (ctx.canBack) out.push(Button({ key: "back", label: "◀ Back", hotkey: "b", plain: true, onPress: ctx.actions.back }));
  if (!st || st.kind !== "ready") {
    return [...out, ...missingScreen(h, st, { title: "authorization description", what: "This view separates who initiates an operation, where the authorization decision is enforced, and which credentials execute it. It reads .architecture/auth.json, which cites the source for every claim and never holds a secret.", hint: "Ask Claude to use the architecture-auth skill to write it; nothing runs unless you ask." })];
  }
  const a = st.auth;
  const sel = ctx.auth;
  const mode = MODES.some((m) => m.id === sel.mode) ? sel.mode : "operations";
  const name = (id) => byId(model.components, id)?.name ?? id;
  const set = (patch) => ctx.actions.setAuth(patch);
  const pic = ctx.picture?.status === "ready" ? ctx.picture : null;
  const stepText = (ref) => {
    const hit = stepRef(model, ref);
    return hit ? `step ${hit.step.n}: ${name(hit.step.from)} → ${name(hit.step.to)}, ${hit.step.action}` : undefined;
  };
  const dd = ctx.status.data?.kind === "ready" ? ctx.status.data.data : null;
  const dataAnchored = (ref) => Boolean(dd) && (dd.effects.some((e) => e.step === ref) || dd.lifecycles.some((l) => l.transitions.some((t) => t.step === ref)));
  // A step that anchors an ordered write sequence is the most useful place to open the Data tab, then a lifecycle transition, then an entity.
  const dataRank = (ref) => (dd.sequences.some((s) => s.steps.includes(ref) && dd.effects.some((e) => e.step === ref && e.op !== "read")) ? 0 : dd.lifecycles.some((l) => l.transitions.some((t) => t.step === ref)) ? 1 : 2);
  const bestDataStep = (refs) => refs.filter((r) => r && dataAnchored(r)).sort((x, y) => dataRank(x) - dataRank(y))[0];
  const env = { a, sel, name, set, stepText, dataAnchored, bestDataStep };

  out.push(...provenance(h, u, st, a, authCounts(a), "ap"));
  const hs = hopStatements(a);
  if (hs.repeated) out.push(note(h, "aprep", `${hs.hops} hops carry ${hs.distinct} distinct statements (the most repeated is on ${hs.repeated.count}). Repetition is not an error; read the hop count as entries, not as separate findings.`));
  out.push(note(h, "aleg", "● ◐ ○ are this document's claims. Lines that begin “derived” are computed from them. Initiating identity, authorization decision and executing credentials are recorded separately; none is inferred from another, and a decision that was not located is not the same as none."));
  out.push(strip(h, "amode", "Show:", MODES, mode, (id) => set({ mode: id })));
  if (pic) out.push(Box({ key: "pic", marginTop: 1, children: [pic.node] }));
  else if (ctx.picture) out.push(note(h, "apn", ctx.picture.status === "pending" ? "Drawing the diagram…" : `The diagram could not be drawn (${ctx.picture.message}); showing the text view.`));

  out.push(...(mode === "operations" ? operationsMode(h, ctx, u, env) : flowMode(h, ctx, u, env)));

  out.push(heading(h, "aqh", `Unresolved (${a.questions.length})`));
  if (!a.questions.length) out.push(note(h, "aq0", "The document lists no open questions. That is not evidence that none exist."));
  for (const q of a.questions) {
    out.push(Box({ key: `aq-${q.id}`, flexDirection: "column", children: [Text({ key: `aq-${q.id}-t`, wrap: "wrap", children: `${u.MARK.unknown} ${q.text}` }), q.operation ? Button({ key: `aq-${q.id}-o`, label: `  about ${byId(a.operations, q.operation)?.name ?? q.operation}`, plain: true, onPress: () => set({ mode: "operations", operation: q.operation, guard: null, hop: null }) }) : null] }));
  }
  out.push(...checksBlock(h, u, st, "a", "It does not confirm that a claim reads that code correctly, that every guard or credential was found, what a token's scope allows, or how the platforms involved behave. No secret was read."));
  return out;
}

function hopDetail(h, ctx, u, { a, name, set, stepText, dataAnchored }, hop, prefix) {
  const { Text, Button } = h;
  const cred = byId(a.credentials, hop.presents);
  const body = [Text({ key: `${prefix}t`, bold: true, wrap: "wrap", color: u.COLOR[hop.confidence], children: `${u.MARK[hop.confidence]} ${name(hop.from)} → ${name(hop.to)}  ·  ${AUTHORITY_TEXT[hop.authority]}` })];
  const hit = hop.step && stepRef(ctx.model, hop.step);
  if (hit) body.push(Button({ key: `${prefix}s`, label: u.cut(`Open flow ${stepText(hop.step)}`, ctx.cols - 8), plain: true, onPress: () => ctx.actions.select("step", hop.step, `${prefix}s`) }));
  else if (hop.step) body.push(Text({ key: `${prefix}br`, color: "red", wrap: "wrap", children: `✗ this hop cites ${hop.step}, which is not in the model; it is not followed.` }));
  else body.push(note(h, `${prefix}no`, "No step of a modeled workflow performs this call."));
  if (hit && dataAnchored(hop.step)) body.push(Button({ key: `${prefix}d`, label: u.cut("Data ▸ what state does this step change?", ctx.cols - 8), plain: true, onPress: () => ctx.actions.openData(hop.step) }));
  body.push(claimBlock(h, ctx, u, `hop-${hop.id}`, "The hop", { text: hop.text, confidence: hop.confidence, evidence: hop.evidence }));
  body.push(Text({ key: `${prefix}seen`, wrap: "wrap", children: hop.seenAs ? `The receiving system sees: ${principalName(a, hop.seenAs)}${byId(a.principals, hop.seenAs)?.how ? ` — ${byId(a.principals, hop.seenAs).how}` : ""}` : "The receiving system is not shown the caller's identity (not established for this hop)." }));
  if (cred) {
    const c = consequencesOfCredential(ctx.model, a, cred.id);
    body.push(claimBlock(h, ctx, u, `cred-${cred.id}`, `Credential presented: ${cred.name}`, { text: `${cred.kind}${cred.issuedBy ? `, issued by ${name(cred.issuedBy)}` : ""}${cred.issuer ? `, ${cred.issuer}` : ""}`, confidence: cred.confidence, evidence: cred.evidence }, { lines: [...(cred.secret ? [`Secret name: ${cred.secret}`] : []), ...(cred.lifetime ? [`Lifetime: ${cred.lifetime}`] : []), ...(cred.carried ? [`Carried: ${cred.carried}`] : [])] }));
    body.push(Text({ key: `${prefix}cd`, dimColor: true, wrap: "wrap", children: `derived  presented on ${c.hops.length} hop${c.hops.length === 1 ? "" : "s"} in ${c.operations.length} operation${c.operations.length === 1 ? "" : "s"}: ${c.operations.map((o) => o.name).join(", ") || "none listed"}` }));
  } else body.push(Text({ key: `${prefix}nc`, dimColor: true, wrap: "wrap", children: `${u.MARK.unknown} No credential is recorded for this hop.` }));
  const boundary = byId(a.boundaries, hop.boundary);
  if (boundary) body.push(claimBlock(h, ctx, u, `bnd-${boundary.id}`, `Trust boundary: ${boundary.name}`, boundary));
  return body;
}

function operationsMode(h, ctx, u, env) {
  const { Box, Text, Button } = h;
  const { a, sel, name, set, bestDataStep } = env;
  const out = [];
  if (!a.operations.length) return [note(h, "ao0", "This document lists no operations.")];
  const op = byId(a.operations, sel.operation) ?? a.operations[0];
  const at = a.operations.indexOf(op);
  out.push(Box({ key: "aonav", gap: 2, children: [Button({ key: "aop", label: "◀ prev", hotkey: "p", plain: true, onPress: () => set({ operation: a.operations[Math.max(0, at - 1)].id, guard: null, hop: null }) }), Button({ key: "aon", label: "next ▶", hotkey: "n", plain: true, onPress: () => set({ operation: a.operations[Math.min(a.operations.length - 1, at + 1)].id, guard: null, hop: null }) }), Text({ key: "aopos", dimColor: true, children: `${at + 1} of ${a.operations.length}` })] }));
  out.push(heading(h, "aoh", `Operations (${a.operations.length})`));
  for (const o of a.operations) {
    out.push(Box({ key: `ao-${o.id}`, gap: 1, children: [Text({ key: `ao-${o.id}-m`, color: u.COLOR[o.policy?.confidence ?? "unknown"], children: u.MARK[o.policy?.confidence ?? "unknown"] }), Button({ key: `ao-${o.id}-b`, label: u.cut(`${o.id === op.id ? "▸ " : "  "}${o.name}  ·  policy: ${MODE_TEXT(o.policy)}`, ctx.cols - 10), plain: true, onPress: () => set({ operation: o.id, guard: null, hop: null }) })] }));
  }

  const ex = executionOf(a, op);
  const detail = [Text({ key: "oh", bold: true, wrap: "wrap", children: `${op.name}${op.route ? `  ·  ${op.route}` : ""}` })];
  const firstAnchored = bestDataStep(ex.hops.map((x) => x.step));
  if (firstAnchored) detail.push(Button({ key: "od", label: u.cut("Data ▸ what state does this operation change?", ctx.cols - 8), plain: true, onPress: () => ctx.actions.openData(firstAnchored) }));

  detail.push(heading(h, "oid", "1. Initiating identity: who starts it"));
  if (!op.initiators.length) detail.push(Text({ key: "oi0", dimColor: true, wrap: "wrap", children: `${u.MARK.unknown} The document does not name who initiates this.` }));
  for (const id of op.initiators) {
    const p = byId(a.principals, id);
    detail.push(Text({ key: `oi-${id}`, wrap: "wrap", color: p ? u.COLOR[p.confidence] : undefined, children: `${p ? u.MARK[p.confidence] : "✗"} ${p ? p.name : `${id} (not in this document)`}${p?.how ? ` — ${p.how}` : ""}` }));
  }
  if (op.trigger) detail.push(note(h, "oit", `Trigger: ${op.trigger}`));
  const authn = (op.policy?.guards ?? []).map((g) => byId(a.guards, g)).filter((g) => g?.concern === "authentication");
  detail.push(Text({ key: "oia", dimColor: true, wrap: "wrap", children: authn.length ? `derived  established by: ${authn.map((g) => g.name).join(", ")}` : "derived  no authentication guard is listed for this operation" }));

  detail.push(heading(h, "oaz", "2. Authorization decision: who may do it, and where it is enforced"));
  detail.push(...coverageNotes(h, ctx, u, "operation", op.id, "ocv"));
  if (op.policy) {
    detail.push(claimBlock(h, ctx, u, `pol-${op.id}`, `Policy: ${MODE_WORDS[op.policy.mode]}${conditionalPolicy(op.policy) ? ", but its text names a condition" : ""}`, op.policy));
    for (const id of op.policy.guards) {
      const g = byId(a.guards, id);
      detail.push(g ? Button({ key: `og-${id}`, label: u.cut(`${sel.guard === id ? "▾" : "▸"} ${g.name}  ·  ${g.concern}, ${g.kind}  ·  ${WHERE[g.enforcedAt]} in ${name(g.component)}${g.deny ? `  ·  deny ${g.deny}` : ""}`, ctx.cols - 8), plain: true, onPress: () => set({ guard: sel.guard === id ? null : id }) }) : Text({ key: `og-${id}`, color: "red", wrap: "wrap", children: `✗ guard ${id} is not in this document` }));
      if (g && sel.guard === id) detail.push(...guardDetail(h, ctx, u, env, g, op));
    }
    const adm = admittedBy(a, op);
    detail.push(Text({ key: "oadm", wrap: "wrap", dimColor: !adm.derived, children: adm.derived ? `derived  every guard must pass, so the callers admitted: ${adm.anyone ? "anyone who passes the checks" : adm.principals.map((p) => principalName(a, p)).join(", ") || "no one (the guards admit disjoint classes)"}. A login can belong to more than one class; an overlap is not modeled.${adm.note ? ` Note: ${adm.note}.` : ""}` : `derived  caller set not derived: ${adm.why}` }));
  } else detail.push(Text({ key: "op0", color: "red", wrap: "wrap", children: "✗ no policy is recorded for this operation." }));
  const ux = op.uxGates.map((g) => byId(a.guards, g)).filter(Boolean);
  if (ux.length) detail.push(note(h, "oux", `Client-side only, not enforcement: ${ux.map((g) => g.name).join(", ")}. The server decides.`));

  detail.push(heading(h, "oex", "3. Executing credentials: what the call runs with"));
  if (ex.broken.length) for (const id of ex.broken) detail.push(Text({ key: `oxb-${id}`, color: "red", wrap: "wrap", children: `✗ hop ${id} is not in this document` }));
  if (!ex.hops.length) detail.push(Text({ key: "ox0", dimColor: true, wrap: "wrap", children: `${u.MARK.unknown} No hops are listed, so the credentials this runs with are not shown.` }));
  else {
    const part = (label, list) => (list.length ? `${label} on ${[...new Set(list.map((x) => (x.step ? `step ${x.step.split("#")[1]}` : x.id)))].join(", ")}` : null);
    detail.push(Text({ key: "oxs", wrap: "wrap", children: `derived  ${[part("as the caller", ex.caller), part("under the service's own credential", ex.service), part("under a delegated capability", ex.delegated), part("authority not established", ex.unknown)].filter(Boolean).join("; ")}` }));
    for (const c of ex.changes) detail.push(Text({ key: `oxc-${c.after.id}`, dimColor: true, wrap: "wrap", color: "yellow", children: `derived  authority changes after ${c.after.step ? `step ${c.after.step.split("#")[1]}` : c.after.id}: ${AUTHORITY_TEXT[c.from]} → ${AUTHORITY_TEXT[c.to]}` }));
    if (ex.boundaries.length) detail.push(Text({ key: "oxbd", dimColor: true, wrap: "wrap", children: `derived  trust boundaries crossed: ${ex.boundaries.map((b) => b.name).join(", ")}` }));
    for (const hop of ex.hops) {
      const on = sel.hop === hop.id;
      detail.push(Box({ key: `ox-${hop.id}`, gap: 1, children: [Text({ key: `ox-${hop.id}-m`, color: u.COLOR[hop.confidence], children: u.MARK[hop.confidence] }), Button({ key: `ox-${hop.id}-b`, label: u.cut(`${on ? "▾" : "▸"} ${hop.step ? `${hop.step.split("#")[1]}. ` : ""}${name(hop.from)} → ${name(hop.to)}  ·  ${byId(a.credentials, hop.presents)?.name ?? "no credential"}  ·  ${AUTHORITY_TEXT[hop.authority]}`, ctx.cols - 10), plain: true, onPress: () => set({ hop: on ? null : hop.id }) })] }));
