  out.push(Box({ key: "aod", flexDirection: "column", marginTop: 1, borderStyle: "round", borderColor: u.COLOR[op.policy?.confidence ?? "unknown"], paddingX: 1, children: detail }));
  return out;
}

function guardDetail(h, ctx, u, { a, name, set }, g, op) {
