  for (const hop of fs.broken) out.push(Text({ key: `afb-${hop.id}`, color: "red", wrap: "wrap", children: `✗ hop ${hop.id} cites ${hop.step}, which is not in the model; it is not drawn or followed.` }));
  if (current) {
    const used = opsUsingCredential(a, current.presents ?? "").filter((o) => o.hops.includes(current.id));
    const detail = hopDetail(h, ctx, u, env, current, "ahd-");
