    out.push(Box({ key: "afd", flexDirection: "column", marginTop: 1, borderStyle: "round", borderColor: u.COLOR[current.confidence], paddingX: 1, children: detail }));
  } else out.push(note(h, "afpick", "Select a hop to read the credential it presents, what the receiver sees, and the source behind it."));
  return out;
}

