import { ITEM_KINDS, STATUS, STATUS_TEXT, coverageCounts, itemsFor, modeledStrength } from "./coverage.mjs";
import { checksBlock, evidenceRows, heading, note } from "./lens-view.mjs";

// The coverage manifest as pane elements (pure). It says what an inventory lists, never that the inventory is complete.

const STATUS_COLOR = { modeled: undefined, unmodeled: "yellow", unresolved: "red", outside: undefined };
const KIND_WORDS = { "entry-point": "entry point", writer: "writer", reader: "reader", enforcement: "enforcement point", variant: "variant", other: "other" };

const ready = (ctx) => (ctx.status.coverage?.kind === "ready" ? ctx.status.coverage : null);
const docsOf = (ctx) => ({ auth: ctx.status.auth?.kind === "ready" ? ctx.status.auth.auth : undefined, data: ctx.status.data?.kind === "ready" ? ctx.status.data.data : undefined });

/** The Overview section: scope, revision, counts by status and the standing caveat; the items that are not covered open on request. */
export function coverageBlock(h, ctx, u) {
  const { Box, Text, Button } = h;
  const st = ready(ctx);
  if (!st) return ctx.status.coverage?.kind === "invalid" ? Box({ key: "cov", flexDirection: "column", marginTop: 1, children: [heading(h, "cvh", "Coverage"), Text({ key: "cvbad", color: "red", wrap: "wrap", children: `✗ The coverage document could not be used: ${ctx.status.coverage.errors.join("; ")}` })] }) : null;
  const cov = st.coverage;
  const counts = coverageCounts(cov);
  const errors = [...st.parseIssues, ...st.issues].filter((i) => i.level === "error");
  const open = Boolean(ctx.coverageOpen);
  const uncovered = cov.inventory.filter((x) => x.status !== "modeled");
  const rows = [heading(h, "cvh", "Coverage")];
  rows.push(Text({ key: "cvs", wrap: "wrap", children: cov.scope.statement }));
  rows.push(Text({ key: "cvc", wrap: "wrap", children: STATUS.map((s) => `${STATUS_TEXT[s]} ${counts[s]}`).join(" · ") + `  (of ${counts.total} inventoried)`, color: counts.unmodeled || counts.unresolved ? "yellow" : undefined }));
  rows.push(note(h, "cvn", "Counts cover what the inventory lists, not every such item in the system. “Modeled” means an element represents it, not that the representation is right."));
  for (const [i, s] of st.stale.entries()) rows.push(Text({ key: `cvst${i}`, color: "yellow", wrap: "wrap", children: `! ${s.message}` }));
  if (errors.length) rows.push(Text({ key: "cver", color: "red", wrap: "wrap", children: `✗ ${u.plural(errors.length, "problem")} in the coverage document; the counts may not be trustworthy (open the list for the checks).` }));
  rows.push(Button({ key: "cvt", label: `${open ? "▾" : "▸"} ${open ? "Hide" : "Show"} how it was built and the ${uncovered.length} items not covered`, plain: true, onPress: ctx.actions.toggleCoverage }));
  if (!open) return Box({ key: "cov", flexDirection: "column", marginTop: 1, children: rows });

  const read = cov.scope.sources.filter((s) => s.depth === "read").length;
  rows.push(heading(h, "cvmh", "How the inventory was built"));
  rows.push(Text({ key: "cvm", wrap: "wrap", children: cov.scope.denominator.method }));
  for (const [i, l] of cov.scope.denominator.limits.entries()) rows.push(note(h, `cvl${i}`, `Limit: ${l}`));
  rows.push(note(h, "cvsrc", `${u.plural(cov.scope.sources.length, "source path")} declared: ${read} read, ${cov.scope.sources.length - read} searched only. A path being listed says it was looked at, not what was found there.`));
  const modeled = cov.inventory.filter((x) => x.status === "modeled");
  if (modeled.length) {
    const byKind = ITEM_KINDS.map((k) => [k, modeled.filter((x) => x.kind === k).length]).filter(([, n]) => n);
    const docs = docsOf(ctx);
    const weak = modeled.filter((x) => modeledStrength(ctx.model, docs, x) !== "observed").length;
    rows.push(note(h, "cvmod", `Modeled: ${byKind.map(([k, n]) => u.plural(n, KIND_WORDS[k])).join(", ")}${weak ? `; ${weak} rest on elements that are not fully observed` : ""}.`));
  }
  for (const status of ["unmodeled", "unresolved", "outside"]) {
    const group = cov.inventory.filter((x) => x.status === status);
    if (!group.length) continue;
    rows.push(heading(h, `cvg-${status}`, `${STATUS_TEXT[status][0].toUpperCase()}${STATUS_TEXT[status].slice(1)} (${group.length})`));
    for (const x of group) {
      rows.push(Text({ key: `cvi-${x.id}`, wrap: "wrap", color: STATUS_COLOR[status], children: `${x.name}  ·  ${KIND_WORDS[x.kind]}${status !== "outside" ? `  ·  ${u.MARK[x.confidence]} ${x.confidence}` : ""}` }));
      rows.push(Text({ key: `cvx-${x.id}`, wrap: "wrap", children: x.text }));
      if (x.reason) rows.push(note(h, `cvr-${x.id}`, `${status === "outside" ? "Not covered because" : "Unresolved"}: ${x.reason}`));
      rows.push(...evidenceRows(h, ctx, u, `cv-${x.id}`, x.evidence));
      const bears = x.relatesTo.map((r) => `${r.kind} ${r.label ?? r.id}`);
      if (bears.length) rows.push(note(h, `cvb-${x.id}`, `Bears on: ${bears.join(", ")}`));
    }
  }
  rows.push(...checksBlock(h, u, st, "cv", "It does not confirm that an item exists beyond what it cites, that every such item was found, or that a “modeled” element represents it correctly."));
  return Box({ key: "cov", flexDirection: "column", marginTop: 1, children: rows });
}

/**
 * Lines for one modeled element (an operation, a guard, an entity, a component or a flow): what the inventory records beside it.
 * Returns [] when no coverage document is loaded, so a model without one is drawn exactly as before.
 */
export function coverageNotes(h, ctx, u, kind, id, prefix) {
  const st = ready(ctx);
  if (!st) return [];
  const cov = st.coverage;
  const items = itemsFor(cov, kind, id);
  const here = items.filter((x) => x.status === "modeled");
  const beside = items.filter((x) => x.status !== "modeled");
  const out = [];
  const label = (x) => `${x.name} (${STATUS_TEXT[x.status]})`;
  if (!items.length) {
    if (kind !== "operation") return [];
    out.push(h.Text({ key: `${prefix}0`, dimColor: true, wrap: "wrap", children: `coverage  the inventory does not mention this ${kind}; whether anything else bears on it is not recorded.` }));
  } else {
    if (here.length) out.push(h.Text({ key: `${prefix}m`, dimColor: true, wrap: "wrap", children: `coverage  inventoried as: ${here.map((x) => x.name).join(", ")}` }));
    out.push(h.Text({ key: `${prefix}b`, wrap: "wrap", color: beside.length ? "yellow" : undefined, dimColor: !beside.length, children: beside.length ? `coverage  ${u.plural(beside.length, "inventoried item")} bear${beside.length === 1 ? "s" : ""} on this ${kind} and ${beside.length === 1 ? "is" : "are"} not fully modeled: ${beside.slice(0, 4).map(label).join("; ")}${beside.length > 4 ? `; and ${beside.length - 4} more` : ""}` : `coverage  the inventory lists nothing else that bears on this ${kind} (that is the inventory, not the system).` }));
  }
  if (beside.length || !items.length) out.push(h.Button({ key: `${prefix}o`, label: u.cut("Coverage ▸ what the inventory records and how it was built", ctx.cols - 8), plain: true, onPress: ctx.actions.openCoverage }));
  return out;
}

