// One short description per hotkey a view may register; a hotkey drawn without an entry here fails the tests.
export const KEY_HELP = {
  o: "Overview",
  f: "Flow",
  i: "Impact",
  e: "Behavior",
  d: "Explore",
  t: "Data",
  u: "Auth",
  m: "Mermaid source",
  v: "diagram or text view",
  w: "open in browser",
  r: "reload model",
  g: "ask Claude to build the model",
  h: "show or hide this list",
  x: "close pane",
  b: "back",
  p: "previous interaction",
  n: "next interaction",
  z: "window or whole sequence",
  c: "show or hide carried calls",
  a: "next alternative",
  l: "open step in Flow",
  s: "scan git changes",
};

const VIEW_KEYS = ["o", "f", "i", "e", "d", "t", "u", "m"];
const HOST_KEYS = [
  ["Tab, Shift+Tab", "move between controls; Enter presses the one in focus"],
  ["arrows, wheel", "scroll"],
  ["ctrl+x Tab", "move the keyboard between this pane and the prompt (default binding)"],
  ["Esc", "closes this list first, then the pane; it never means Back"],
];
const FIELD_ROW = ["in a field", "letters are typed, not shortcuts: Tab leaves the field, Enter submits it"];
export const HOST_LABELS = new Set([FIELD_ROW[0], ...HOST_KEYS.map(([k]) => k)]);

/** Wraps the element table so that each hotkey and each text field a view draws is noted in `seen`. */
export function recording(h, seen) {
  return {
    ...h,
    Button: (props) => {
      if (props.hotkey) seen.hotkeys.add(props.hotkey);
      return h.Button(props);
    },
    Input: (props) => {
      seen.fields = true;
      return h.Input(props);
    },
  };
}

export const newSeen = () => ({ hotkeys: new Set(), fields: false });

/** Rows of [keys, what it does] for what is drawn right now: the hotkeys of the tree, then the host's keys. */
export function legendRows(seen) {
  const has = (k) => seen.hotkeys.has(k);
  const rows = [];
  const views = VIEW_KEYS.filter(has);
  if (views.length) rows.push([views.join(" "), "switch view"]);
  for (const k of Object.keys(KEY_HELP)) if (has(k) && !VIEW_KEYS.includes(k) && k !== "p" && k !== "n") rows.push([k, KEY_HELP[k]]);
  if (has("p") && has("n")) rows.push(["p n", "previous or next interaction (hop)"]);
  else for (const k of ["p", "n"]) if (has(k)) rows.push([k, KEY_HELP[k]]);
  const digits = [...seen.hotkeys].filter((k) => /^[1-9]$/.test(k)).sort();
  if (digits.length) rows.push([digits.length > 1 ? `${digits[0]}-${digits[digits.length - 1]}` : digits[0], "read that evidence file"]);
  if (seen.fields) rows.push(FIELD_ROW);
  return [...rows, ...HOST_KEYS];
}

/** Every hotkey in `seen` that has no description in KEY_HELP (digits excepted). */
export const undescribed = (seen) => [...seen.hotkeys].filter((k) => !/^[1-9]$/.test(k) && !(k in KEY_HELP));

