import { byId, categoryInfo, formatEvidence, resolveStepRelationship } from "./model.mjs";
import { edgeStyler } from "./diagram-graph.mjs";
import { HATCH_ID, catColor, chip, confColor, dashFor, esc, hatchDef, headOf, legendItems, legendRow, markerDefs, markerKey, markerUrl, num, palette, svgOpen, textWidth, truncate, truncateMiddle, wrap } from "./svgkit.mjs";

const LABEL = 12.5;
const LINE = 15;
const HEAD_TOP = 14;
const BAND_H = 22;
const RULER_H = 30;
const FOLD_H = 24;
const CARD_H = 58;
const MARK_H = 24;

/** Participants in repository groups (first appearance orders both the groups and the members); unmodeled components trail. */
export function participantGroups(model, steps) {
  const used = [];
  for (const s of steps) for (const id of [s.from, s.to]) if (!used.includes(id)) used.push(id);
  const multi = model.project.repositories.length > 0;
  const groups = [];
  for (const id of used) {
    const comp = byId(model.components, id);
    const key = multi ? (comp.repo ?? "") : "";
    let g = groups.find((x) => x.key === key);
    if (!g) groups.push((g = { key, repo: model.project.repositories.find((r) => r.id === key), members: [] }));
    g.members.push(comp);
  }
  if (multi) groups.sort((a, b) => (a.key === "") - (b.key === ""));
  return groups;
}

const evidenceLine = (ev, withRepo) => formatEvidence(ev, { withRepo });

export const WINDOW_STEPS = 6;
const WINDOW_PARTICIPANTS = 6;

/**
 * The slice of `all` (the steps a view lists) worth drawing large: the selected step (or the first) with its
 * neighbours, never more than `max` steps nor more participants than stay readable. `before` and `after` are the
 * steps left out on each side, so the picture can say what it is not showing and where to find it.
 */
export function sequenceWindow(all, selected = null, { max = WINDOW_STEPS, participants = WINDOW_PARTICIPANTS } = {}) {
  const at = Math.max(0, all.findIndex((s) => s.n === selected));
  let start = Math.max(0, at - 2);
  let end = Math.min(all.length, start + max);
  start = Math.max(0, end - max);
  const people = (a, b) => new Set(all.slice(a, b).flatMap((s) => [s.from, s.to])).size;
  while (end - start > 3 && people(start, end) > participants) {
    if (at - start > end - 1 - at) start++;
    else end--;
  }
  return { all, steps: all.slice(start, end), before: all.slice(0, start), after: all.slice(end), selected: all.some((s) => s.n === selected) ? selected : null };
}

/**
 * Sequence diagram of `steps` as an SVG string. One lifeline per participant, grouped under their repository; one
 * message per step, drawn from the step's own fields: the relationship category (colour and head), the step's
 * confidence (line style) and its state change (square). `selected` is a step number; that step is highlighted and
 * expanded into a callout that lists its evidence references. `overlay` (see explore.mjs) draws one alternative's hatched, PROPOSED additions.
 */
export function sequenceSvg(model, flow, { steps = flow.steps, selected = null, theme = "dark", inlineStates = null, window = null, callout: withCallout = true, fullHint = "", overlay = null } = {}) {
  if (window) steps = window.steps;
  inlineStates ??= steps.length <= 24;
  const context = window?.all ?? steps;
  const p = palette(theme);
  const style = edgeStyler(model, p);
  // An insert between components the model lacks cannot be placed; it is reported by the check and not drawn.
  const inserts = (overlay?.inserts ?? []).filter((i) => steps.some((s) => s.n === i.after) && byId(model.components, i.from) && byId(model.components, i.to));
  const groups = participantGroups(model, [...steps, ...inserts]);
  const members = groups.flatMap((g) => g.members.map((c) => ({ comp: c, group: g })));
  const index = new Map(members.map((m, i) => [m.comp.id, i]));
  const multiRepo = model.project.repositories.length > 0;
  const hasPhases = context.some((s) => s.phase);

  const pitch = Math.max(136, Math.min(168, Math.max(...members.map((m) => Math.min(150, textWidth(m.comp.name, 12.5, { bold: true }) / 1.6 + 34)))));
  const gutter = hasPhases ? Math.min(118, Math.max(84, ...context.map((s) => textWidth((s.phase || "Other").toUpperCase(), 10.5, { bold: true }) + 30))) : 14;
  const width = Math.max(gutter + members.length * pitch + 14, 560);
  const xOf = (id) => gutter + (width - gutter - 14 - members.length * pitch) / 2 + index.get(id) * pitch + pitch / 2;
  const headH = HEAD_TOP + (multiRepo ? BAND_H + 6 : 0) + CARD_H + 10;

  const rels = new Map(steps.map((s) => [s.n, resolveStepRelationship(model, s)]));
  const categoryOfStep = (s) => rels.get(s.n).relationship?.category;
  const categoriesUsed = [...new Set(steps.map(categoryOfStep).filter(Boolean))];
  const showTag = categoriesUsed.length > 1 && !style.byKind;

  const rows = [];
  let y = headH;
  const ruler = window ? { y, h: RULER_H } : null;
  if (ruler) y += RULER_H;
  const foldTop = window?.before.length ? { y, h: FOLD_H } : null;
  if (foldTop) y += FOLD_H;
  const marks = new Map((overlay?.changes ?? []).map((c) => [c.step, c]));
  for (const s of steps) {
    const self = s.from === s.to;
    const a = xOf(s.from);
    const b = xOf(s.to);
    const span = Math.abs(a - b);
    const mirror = self && width - a - 70 < 190;
    const room = self ? Math.max(120, Math.min(pitch * 1.9, mirror ? a - gutter - 70 : width - a - 70)) : Math.max(span - 30, 250);
    const lines = wrap(s.action, Math.min(room, 320), LABEL, 2);
    const note = inlineStates && s.stateChange ? 22 : 0;
    const mark = marks.get(s.n);
    const markH = mark ? MARK_H : 0;
    const h = 10 + lines.length * LINE + 11 + (self ? 8 : 0) + note + markH;
    const sel = selected === s.n;
    const callout = sel && withCallout ? calloutFor(model, flow, s, rels.get(s.n), width - gutter - 28) : null;
    rows.push({ s, self, a, b, lines, y, h, sel, callout, note, mirror, mark, markH });
    y += h + (callout ? callout.h + 8 : 0);
    for (const ins of inserts.filter((i) => i.after === s.n)) {
      const ghostLines = wrap(`PROPOSED · ${ins.text}`, Math.min(Math.max(Math.abs(xOf(ins.from) - xOf(ins.to)) - 30, 250), 320), LABEL, 2);
      const ghostH = 10 + ghostLines.length * LINE + 11;
      rows.push({ ghost: ins, s: { phase: s.phase }, self: ins.from === ins.to, a: xOf(ins.from), b: xOf(ins.to), lines: ghostLines, y, h: ghostH, markH: 0, note: 0 });
      y += ghostH;
    }
  }
  const foldBottom = window?.after.length ? { y: y + 2, h: FOLD_H } : null;
  if (foldBottom) y += FOLD_H + 2;
  const bodyBottom = y + 6;

  const markers = new Set();
  const confs = new Set();
  let anyState = false;
  const out = [];

  // A shortened lane label drops the prefix every repository name shares ("saleor-").
  const names = groups.filter((g) => g.repo).map((g) => g.repo.name);
  const prefix = names.length > 1 ? (names.reduce((a, b) => { let i = 0; while (i < a.length && a[i] === b[i]) i++; return a.slice(0, i); }).match(/^.*[-_./]/)?.[0].length ?? 0) : 0;

  // lanes: one band per repository group, a dashed divider between neighbours
  groups.forEach((g, gi) => {
    const x0 = xOf(g.members[0].id) - pitch / 2;
    const x1 = xOf(g.members[g.members.length - 1].id) + pitch / 2;
    if (multiRepo) {
      out.push(`<rect x="${num(x0)}" y="${HEAD_TOP}" width="${num(x1 - x0)}" height="${num(bodyBottom - HEAD_TOP)}" fill="${gi % 2 ? p.band : "none"}"/>`);
      if (gi > 0) out.push(`<line x1="${num(x0)}" y1="${HEAD_TOP}" x2="${num(x0)}" y2="${num(bodyBottom)}" stroke="${p.faint}" stroke-width="1.2" stroke-dasharray="3 4"/>`);
      const name = g.repo?.name ?? "Not modeled";
      const version = g.repo?.version ? ` · ${g.repo.version}` : "";
      const room = x1 - x0 - 20;
      const label = [`${name}${version}`, `${name.slice(prefix)}${version}`, name.slice(prefix)].map((t) => t.toUpperCase()).find((t) => textWidth(t, 11.5, { bold: true }) <= room) ?? name.slice(prefix).toUpperCase();
      out.push(`<text x="${num(x0 + 10)}" y="${HEAD_TOP + 15}" font-size="11.5" font-weight="700" letter-spacing="0.6" fill="${g.repo ? p.text : p.muted}"><title>${esc(`${name}${version}`)}</title>${esc(truncate(label, room, 11.5, { bold: true }))}</text>`);
    }
  });

  // phase gutter
  if (hasPhases) {
    out.push(`<rect x="0" y="${headH - 4}" width="${gutter - 6}" height="${num(bodyBottom - headH + 4)}" fill="${p.band}"/>`);
    let i = 0;
    while (i < rows.length) {
      let j = i;
      while (j + 1 < rows.length && (rows[j + 1].s.phase || "") === (rows[i].s.phase || "")) j++;
      const top = rows[i].y - 3;
      const bottom = rows[j].y + rows[j].h + (rows[j].callout ? rows[j].callout.h + 8 : 0);
      if (i > 0) out.push(`<line x1="2" y1="${num(top)}" x2="${num(width - 8)}" y2="${num(top)}" stroke="${p.grid}" stroke-width="1"/>`);
      out.push(`<rect x="0" y="${num(top + 2)}" width="3" height="${num(bottom - top - 4)}" rx="1.5" fill="${p.faint}"/>`);
      const label = rows[i].s.phase || "Other";
      wrap(label.toUpperCase(), gutter - 22, 10.5, 2, { bold: true }).forEach((t, k) => out.push(`<text x="12" y="${num(top + 17 + k * 13)}" font-size="10.5" font-weight="700" letter-spacing="0.5" fill="${p.muted}">${esc(t)}</text>`));
      i = j + 1;
    }
  }

  // participant cards and lifelines
  const cardTop = HEAD_TOP + (multiRepo ? BAND_H + 4 : 0);
  for (const { comp } of members) {
    const x = xOf(comp.id);
    const w = pitch - 16;
    out.push(`<line x1="${num(x)}" y1="${cardTop + CARD_H}" x2="${num(x)}" y2="${num(bodyBottom)}" stroke="${p.border}" stroke-width="1.3" stroke-dasharray="1 5" stroke-linecap="round"/>`);
    out.push(`<g data-kind="component" data-id="${esc(comp.id)}"><title>${esc(`${comp.name} (${comp.kind}) · ${comp.confidence}`)}</title><rect x="${num(x - w / 2)}" y="${cardTop}" width="${num(w)}" height="${CARD_H}" rx="9" fill="${p.surface}" stroke="${p.border}"/>`);
    out.push(`<circle cx="${num(x + w / 2 - 9)}" cy="${cardTop + 9}" r="3.6" fill="${confColor(p, comp.confidence)}"/>`);
    const nameLines = wrap(comp.name, w - 22, 12.5, 2, { bold: true });
    nameLines.forEach((t, k) => out.push(`<text x="${num(x)}" y="${cardTop + 22 + k * 15}" text-anchor="middle" font-size="12.5" font-weight="650" fill="${p.text}">${esc(t)}</text>`));
    out.push(`<text x="${num(x)}" y="${cardTop + CARD_H - 8}" text-anchor="middle" font-size="10.5" fill="${p.muted}">${esc(truncate(comp.kind, w - 12, 10.5))}</text></g>`);
  }

  if (window) {
    out.push(drawRuler(window, flow, gutter + 8, ruler.y + 6, width - gutter - 22, p));
    if (foldTop) out.push(drawFold(flow, window.before, "above", gutter + 8, foldTop.y + 3, p));
    if (foldBottom) out.push(drawFold(flow, window.after, "below", gutter + 8, foldBottom.y + 3, p));
  }

  // messages
  for (const r of rows) {
    if (r.ghost) {
      out.push(drawProposedInteraction(r, { p, theme, gutter, width, markers }));
      continue;
    }
    const { s, self, a, b, lines, y: y0, h, sel } = r;
    const rel = rels.get(s.n).relationship;
    const cat = rel?.category;
    const color = rel ? style.color(rel) : p.muted;
    const head = rel ? style.head(rel) : "filled";
    const dash = dashFor(s.confidence);
    confs.add(s.confidence);
    markers.add(markerKey(head, color));
    const labelW = Math.max(0, ...lines.map((t) => textWidth(t, LABEL)));
    const arrowY = y0 + h - 8 - (self ? 8 : 0) - r.note - r.markH;
    const cx = self ? (r.mirror ? a - 54 - labelW / 2 : a + 54 + labelW / 2) : (a + b) / 2;
    const left = cx - labelW / 2;
    const id = `${flow.id}#${s.n}`;
    out.push(`<g data-kind="step" data-id="${esc(id)}"${sel ? ' data-selected="true"' : ""} opacity="${selected !== null && !sel ? 0.78 : 1}"><title>${esc(`${s.n}. ${s.action} · ${s.confidence}${rel ? ` · ${categoryInfo(rel.category).label}` : ""}`)}</title>`);
    if (sel) out.push(`<rect x="${gutter - 6}" y="${num(y0 - 2)}" width="${num(width - gutter + 6)}" height="${num(h + 2)}" fill="${p.accentSoft}"/><rect x="${gutter - 6}" y="${num(y0 - 2)}" width="3" height="${num(h + 2)}" fill="${p.accent}"/>`);
    out.push(`<rect x="${gutter}" y="${num(y0)}" width="${num(width - gutter)}" height="${num(h)}" fill="transparent"/>`);
    lines.forEach((t, k) => {
      const ty = y0 + 10 + LINE * (k + 1) - 4;
      out.push(`<text x="${num(left)}" y="${num(ty)}" font-size="${LABEL}" fill="${p.text}" stroke="${sel ? "transparent" : p.bg}" stroke-width="5" paint-order="stroke" stroke-linejoin="round">${esc(t)}</text>`);
    });
    const bx = Math.max(gutter + 12, left - 14);
    out.push(`<circle cx="${num(bx)}" cy="${num(y0 + 10 + LINE - 8)}" r="8.5" fill="${sel ? p.accent : color}"/><text x="${num(bx)}" y="${num(y0 + 10 + LINE - 4.2)}" text-anchor="middle" font-size="${s.n > 9 ? 9.5 : 10.5}" font-weight="700" fill="${theme === "dark" ? "#0f141a" : "#ffffff"}">${s.n}</text>`);
    let tagX = left + labelW + 8;
    if (s.stateChange) {
      anyState = true;
    }
    if (s.stateChange && !r.note) {
      const v = s.stateChange.verified;
      out.push(`<rect x="${num(tagX)}" y="${num(y0 + 10 + LINE - 14)}" width="9" height="9" rx="1.5" fill="${v ? p.text : "none"}" stroke="${p.text}" stroke-width="1.4"${v ? "" : ' stroke-dasharray="2 1.6"'}/>`);
      tagX += 15;
    }
    if (showTag && cat && cat !== "runtime") out.push(`<text x="${num(tagX)}" y="${num(y0 + 10 + LINE - 4)}" font-size="10.5" font-weight="600" fill="${color}">${esc(categoryInfo(cat).tag)}</text>`);
    const sw = sel ? 3 : 2;
    if (self) {
      const d = r.mirror ? -1 : 1;
      out.push(`<path d="M${num(a)} ${num(arrowY - 12)} h${22 * d} q${6 * d} 0 ${6 * d} 6 v0 q0 6 ${-6 * d} 6 h${-20 * d}" fill="none" stroke="${color}" stroke-width="${sw}"${dash ? ` stroke-dasharray="${dash}"` : ""} stroke-linecap="round" marker-end="${markerUrl(head, color)}"/>`);
    } else {
      const dir = b > a ? 1 : -1;
      out.push(`<line x1="${num(a + dir * 3)}" y1="${num(arrowY)}" x2="${num(b - dir * 3)}" y2="${num(arrowY)}" stroke="${color}" stroke-width="${sw}"${dash ? ` stroke-dasharray="${dash}"` : ""} stroke-linecap="round" marker-end="${markerUrl(head, color)}"/>`);
      out.push(`<circle cx="${num(a)}" cy="${num(arrowY)}" r="2.8" fill="${color}"/>`);
    }
    if (r.note) {
      const sc = s.stateChange;
      const text = truncate(`${sc.store}: ${sc.description}`, window ? 420 : 270, 11);
      const w = textWidth(text, 11) + 30;
      const nx = Math.min(width - w - 10, Math.max(gutter + 6, b - w / 2));
      const ny = y0 + h - r.markH - r.note + 3;
      out.push(`<rect x="${num(nx)}" y="${num(ny)}" width="${num(w)}" height="17" rx="5" fill="${p.surface}" stroke="${sc.verified ? p.muted : p.warn}"${sc.verified ? "" : ' stroke-dasharray="3 2.5"'}/><rect x="${num(nx + 7)}" y="${num(ny + 4)}" width="8" height="8" rx="1.5" fill="${sc.verified ? p.text : "none"}" stroke="${p.text}" stroke-width="1.3"/><text x="${num(nx + 21)}" y="${num(ny + 12.5)}" font-size="11" fill="${sc.verified ? p.text : p.muted}">${esc(text)}</text>`);
    }
    if (r.mark) out.push(drawProposedChange(r, { p, theme, gutter, width, window }));
    out.push("</g>");
    if (r.callout) out.push(drawCallout(r.callout, gutter + 8, y0 + h + 4, width - gutter - 22, p, a, b));
  }

  const items = style.byKind
    ? [...new Set(steps.map((st) => rels.get(st.n).relationship?.kind).filter(Boolean))].sort().map((k) => ({ kind: "cat", color: style.kindColor(k), label: k, head: "filled" }))
    : legendItems(p, { categories: categoriesUsed });
  items.push(...legendItems(p, { confidences: ["observed", "inferred", "unknown"].filter((c) => confs.has(c)) }));
  for (const it of items) if (it.kind === "cat") markers.add(markerKey(it.head, it.color));
  if (anyState) items.push({ kind: "state", label: inlineStates ? "state change (dashed: unverified)" : "state change (hollow: unverified)" });
  if (overlay) items.push({ kind: "proposal", label: `proposed by ${overlay.alt.id}: hypothetical, not in the model` });
  const legend = legendRow(items, gutter + 4, bodyBottom + 14, p, width - gutter - 20);
  const everyone = new Set(context.flatMap((s) => [s.from, s.to])).size;
  const note = window ? truncate(`Showing ${steps.length} of ${context.length} steps and the ${members.length} of ${everyone} participants they involve.${fullHint ? ` ${fullHint}` : ""}`, width - gutter - 24, 11.5) : "";
  const noteY = bodyBottom + 14 + legend.height + 6;
  const height = noteY + (note ? 22 : 6);

  const defs = `<defs>${markerDefs(markers)}${overlay ? hatchDef(p) : ""}</defs>`;
  const label = overlay ? `Sequence diagram: ${flow.name}, with the proposal of alternative ${overlay.alt.id} drawn as hypothetical` : `Sequence diagram: ${flow.name}`;
  const svg = `${svgOpen(width, height, p, `role="img" aria-label="${esc(label)}"`)}${defs}<rect width="${num(width)}" height="${num(height)}" rx="12" fill="${p.bg}"/>${out.join("")}${legend.markup}${note ? `<text x="${gutter + 4}" y="${num(noteY + 10)}" font-size="11.5" fill="${p.muted}">${esc(note)}</text>` : ""}</svg>`;
  return { svg, width, height, shown: steps.length, participants: members.map((m) => ({ id: m.comp.id, x: xOf(m.comp.id) })), rows: rows.filter((r) => !r.ghost).map((r) => ({ n: r.s.n, y: r.y, h: r.h })) };
}

const FILL_BADGE = (theme) => (theme === "dark" ? "#0f141a" : "#ffffff");

/** The tag of a proposal: a square, not the circle a step number sits in, so it differs without colour. */
const badgeWidth = (tag) => Math.max(19, textWidth(tag, 10.5, { bold: true }) + 8);

function badge(tag, x, y, p, theme) {
  const w = badgeWidth(tag);
  return `<rect x="${num(x - w / 2)}" y="${num(y - 8.5)}" width="${num(w)}" height="17" rx="3" fill="${p.proposal}"/><text x="${num(x)}" y="${num(y + 3.8)}" text-anchor="middle" font-size="10.5" font-weight="700" fill="${FILL_BADGE(theme)}">${esc(tag)}</text>`;
}

/** A new interaction an alternative proposes: hatched band, double rail, square ends and a PROPOSED label. */
function drawProposedInteraction(r, { p, theme, gutter, width, markers }) {
  const { ghost, self, a, b, lines, y: y0, h } = r;
  const color = p.proposal;
  markers.add(markerKey("filled", color));
  const labelW = Math.max(0, ...lines.map((t) => textWidth(t, LABEL)));
  const arrowY = y0 + h - 8 - (self ? 8 : 0);
  const left = (self ? a + 54 + labelW / 2 : (a + b) / 2) - labelW / 2;
  const tag = badge(ghost.id, Math.max(gutter + 14, left - 16), y0 + 10 + LINE - 8, p, theme);
  const out = [`<g data-kind="proposal" data-id="${esc(ghost.id)}"><title>${esc(`${ghost.id} · PROPOSED (hypothetical, not in the model): ${ghost.text}`)}</title>`];
  out.push(`<rect x="${gutter - 6}" y="${num(y0 - 2)}" width="${num(width - gutter + 6)}" height="${num(h + 2)}" fill="url(#${HATCH_ID})"/><rect x="${gutter - 6}" y="${num(y0 - 2)}" width="3" height="${num(h + 2)}" fill="${color}"/>`);
  lines.forEach((t, k) => out.push(`<text x="${num(left)}" y="${num(y0 + 10 + LINE * (k + 1) - 4)}" font-size="${LABEL}" font-style="italic" font-weight="600" fill="${p.text}" stroke="${p.bg}" stroke-width="5" paint-order="stroke" stroke-linejoin="round">${esc(t)}</text>`));
  out.push(tag);
  if (self) {
    const d = `M${num(a)} ${num(arrowY - 12)} h22 q6 0 6 6 v0 q0 6 -6 6 h-20`;
    out.push(`<path d="${d}" fill="none" stroke="${color}" stroke-width="5" marker-end="${markerUrl("filled", color)}"/><path d="${d}" fill="none" stroke="${p.bg}" stroke-width="1.8"/>`);
  } else {
    // The head is drawn, not a marker: a marker is no taller than the two rails and would not read as an arrow head.
    const dir = b > a ? 1 : -1;
    const tip = b - dir * 3;
    const root = tip - dir * 13;
    out.push(`<line x1="${num(a + dir * 3)}" y1="${num(arrowY)}" x2="${num(root)}" y2="${num(arrowY)}" stroke="${color}" stroke-width="5"/><line x1="${num(a + dir * 3)}" y1="${num(arrowY)}" x2="${num(root)}" y2="${num(arrowY)}" stroke="${p.bg}" stroke-width="1.8"/>`);
    out.push(`<path d="M${num(tip)} ${num(arrowY)} L${num(root)} ${num(arrowY - 7.5)} L${num(root)} ${num(arrowY + 7.5)} Z" fill="${color}"/><rect x="${num(a - 3.5)}" y="${num(arrowY - 3.5)}" width="7" height="7" fill="${color}"/>`);
  }
  out.push("</g>");
  return out.join("");
}

/** A note under an existing step that an alternative would change: a hatched dashed chip, so the step itself still reads as observed. */
function drawProposedChange(r, { p, theme, gutter, width, window }) {
  const { mark, y: y0, h, b } = r;
  const tagW = badgeWidth(mark.id);
  const text = truncate(`PROPOSED CHANGE to this step · ${mark.text}`, width - gutter - tagW - 60, 11);
  const ny = y0 + h - MARK_H + 4;
  const w = tagW + 20 + textWidth(text, 11);
  const nx = Math.min(width - w - 10, Math.max(gutter + 6, b - w / 2));
  const placed = badge(mark.id, nx + 6 + tagW / 2, ny + 8.5, p, theme);
  return `<g data-kind="proposal" data-id="${esc(mark.id)}"><title>${esc(`${mark.id} · PROPOSED CHANGE (hypothetical, not in the model): ${mark.text}`)}</title><rect x="${num(nx)}" y="${num(ny)}" width="${num(w)}" height="17" rx="4" fill="url(#${HATCH_ID})"/><rect x="${num(nx)}" y="${num(ny)}" width="${num(w)}" height="17" rx="4" fill="none" stroke="${p.proposal}" stroke-width="1.3" stroke-dasharray="5 3"/>${placed}<text x="${num(nx + tagW + 14)}" y="${num(ny + 12.5)}" font-size="11" font-style="italic" fill="${p.text}">${esc(text)}</text></g>`;
}

function drawRuler(window, flow, x, y, maxW, p) {
  const all = window.all;
  const first = window.steps[0].n;
  const last = window.steps[window.steps.length - 1].n;
  const label = `Steps ${first === last ? first : `${first}–${last}`} of ${all.length}`;
  const labelW = textWidth(label, 11.5, { bold: true });
  const room = maxW - labelW - 16;
  const fit = Math.max(window.steps.length, Math.floor(room / 8));
  // A flow too long for one tick each shows the ticks around the window; the fold chips reach the rest.
  const from = all.length <= fit ? 0 : Math.max(0, Math.min(all.length - fit, all.findIndex((s) => s.n === first) - Math.floor((fit - window.steps.length) / 2)));
  const shown = all.slice(from, from + fit);
  const tick = Math.max(5, Math.min(13, Math.floor(room / shown.length) - 3));
  const inWindow = new Set(window.steps.map((s) => s.n));
  const out = [`<text x="${num(x)}" y="${num(y + 11)}" font-size="11.5" font-weight="700" fill="${p.muted}">${esc(label)}</text>`];
  shown.forEach((s, i) => {
    const tx = x + labelW + 14 + i * (tick + 3);
    const sel = s.n === window.selected;
    const fill = sel ? p.accent : inWindow.has(s.n) ? p.muted : "none";
    out.push(`<g data-kind="step" data-id="${esc(`${flow.id}#${s.n}`)}"><title>${esc(`${s.n}. ${s.action}`)}</title><rect x="${num(tx)}" y="${num(y + 1)}" width="${tick}" height="14" rx="2.5" fill="${fill}" stroke="${sel ? p.accent : inWindow.has(s.n) ? p.muted : p.faint}" stroke-width="1"/></g>`);
  });
  return `<g data-kind="ruler">${out.join("")}</g>`;
}

function drawFold(flow, hidden, where, x, y, p) {
  const a = hidden[0].n;
  const b = hidden[hidden.length - 1].n;
  const range = a === b ? `step ${a}` : `steps ${a}–${b}`;
  const text = `${where === "above" ? "▲" : "▼"} ${range} ${where}`;
  const target = where === "above" ? b : a;
  const w = textWidth(text, 11.5, { bold: true }) + 22;
  return `<g data-kind="step" data-id="${esc(`${flow.id}#${target}`)}"><title>${esc(`Go to step ${target}`)}</title><rect x="${num(x)}" y="${num(y)}" width="${num(w)}" height="18" rx="9" fill="${p.surface2}" stroke="${p.border}"/><text x="${num(x + w / 2)}" y="${num(y + 12.5)}" text-anchor="middle" font-size="11.5" font-weight="600" fill="${p.muted}">${esc(text)}</text></g>`;
}

function calloutFor(model, flow, step, resolved, innerW) {
  const rel = resolved.relationship;
  const from = byId(model.components, step.from);
  const to = byId(model.components, step.to);
  const lines = [];
  lines.push({ t: "action", text: step.action });
  const meta = [`${step.confidence}`];
  if (rel) meta.push(`${categoryInfo(rel.category).label}${rel.label ? `: ${rel.label}` : ` (${rel.kind})`}`);
  else if (from.id !== to.id) meta.push(resolved.ambiguous ? "relationship ambiguous in the model" : "no relationship recorded for this step");
  if (from.repo && to.repo && from.repo !== to.repo) meta.push(`crosses ${from.repo} → ${to.repo}`);
  lines.push({ t: "meta", text: meta.join("  ·  ") });
  if (step.stateChange) lines.push({ t: "state", text: `${step.stateChange.store}: ${step.stateChange.description}${step.stateChange.verified ? "" : " (unverified)"}` });
  const ev = step.evidence ?? [];
  if (!ev.length) lines.push({ t: "ev", text: "no evidence cited" });
  for (const e of ev.slice(0, 3)) lines.push({ t: "ev", text: evidenceLine(e, Boolean(e.repo)) });
  if (ev.length > 3) lines.push({ t: "ev", text: `+${ev.length - 3} more` });
  const wrapped = lines.map((l) => ({ ...l, rows: l.t === "action" ? wrap(l.text, innerW - 24, 13, 2, { bold: true }) : l.t === "meta" ? wrap(l.text, innerW - 24, 11.5, 2) : [l.t === "ev" ? truncateMiddle(l.text, innerW - 24, 11.5, { mono: true }) : truncate(l.text, innerW - 24, 11.5)] }));
  const h = 14 + wrapped.reduce((n, l) => n + l.rows.length * 17, 0) + 8;
  return { h, lines: wrapped, step };
}

function drawCallout(c, x, y, w, p, a, b) {
  const out = [`<g data-kind="callout"><path d="M${num((a + b) / 2 - 7)} ${num(y)} l7 -7 l7 7" fill="${p.surface}" stroke="${p.accent}" stroke-width="1.5" stroke-linejoin="round"/><rect x="${num(x)}" y="${num(y)}" width="${num(w)}" height="${num(c.h)}" rx="9" fill="${p.surface}" stroke="${p.accent}" stroke-width="1.5"/><path d="M${num((a + b) / 2 - 6)} ${num(y + 0.75)} h12" stroke="${p.surface}" stroke-width="3"/>`];
  let ty = y + 14;
  for (const l of c.lines) {
    for (const row of l.rows) {
      const common = `x="${num(x + 12)}" y="${num(ty + 5)}"`;
      if (l.t === "action") out.push(`<text ${common} font-size="13" font-weight="650" fill="${p.text}">${esc(row)}</text>`);
      else if (l.t === "meta") out.push(`<text ${common} font-size="11.5" fill="${p.muted}">${esc(row)}</text>`);
      else if (l.t === "state") out.push(`<rect x="${num(x + 12)}" y="${num(ty - 3)}" width="9" height="9" rx="1.5" fill="none" stroke="${p.text}" stroke-width="1.4"/><text x="${num(x + 27)}" y="${num(ty + 5)}" font-size="11.5" fill="${p.text}">${esc(row)}</text>`);
      else out.push(`<text ${common} font-size="11.5" fill="${p.muted}" font-family='ui-monospace, "SF Mono", Menlo, monospace'><tspan fill="${p.accent}">▸ </tspan>${esc(row)}</text>`);
      ty += 17;
    }
  }
  out.push("</g>");
  return out.join("");
}

