import { byId, categoryInfo } from "./model.mjs";
import { layerComponents } from "./layout.mjs";
import { placeRouteLabels, routeOrthogonal } from "./route.mjs";
import { catColor, confColor, dashFor, esc, headOf, legendItems, legendRow, markerDefs, markerKey, markerUrl, num, palette, svgOpen, textWidth, truncate, wrap } from "./svgkit.mjs";

export const NODE_PAD = 14;
const STRUCTURAL = new Set(["build", "package", "implementation", "deployment"]);
const MAX_PER_ROW = 3;
// What a 100-column, 40-row pane gives a picture in cell-width units (8 wide, about 16.4 tall), and room for the legend below it.
const TARGET_W = 800;
const TARGET_H = 656;
const FOOTER_ALLOWANCE = 70;
const GAP_Y = 40;
const GAP_X = 44;
const CLUSTER_PAD = 16;
const CLUSTER_HEAD = 38;
const CLUSTER_GAP = 64;
const CLUSTER_GAP_LABELLED = 184;

/** Size and label lines of a component card. */
export function measureNode(comp) {
  const nameW = textWidth(comp.name, 13, { bold: true });
  const w = Math.max(124, Math.min(188, Math.ceil(nameW + NODE_PAD * 2 + 6)));
  const lines = wrap(comp.name, w - NODE_PAD * 2, 13, 2, { bold: true });
  return { w, h: 22 + lines.length * 16 + 14, lines };
}

/**
 * Colour and style for a relationship. A model with a single relationship category (Valence) tells its relationships
 * apart by `kind`, so those are coloured from a fixed rotation; otherwise colour is the category.
 */
export function edgeStyler(model, p) {
  const cats = new Set(model.relationships.map((r) => r.category));
  const byKind = cats.size <= 1;
  const kinds = [...new Set(model.relationships.map((r) => r.kind))].sort();
  const rotation = [p.cat.runtime, p.cat.event, p.cat.build, p.cat.contract, p.cat.deployment, p.cat.other, p.cat.package, p.cat.implementation];
  return {
    byKind,
    color: (r) => (byKind ? rotation[kinds.indexOf(r.kind) % rotation.length] : catColor(p, r.category)),
    head: (r) => (byKind ? "filled" : headOf(r.category)),
    kinds: byKind ? kinds : [],
    kindColor: (k) => rotation[kinds.indexOf(k) % rotation.length],
  };
}

/** Routes over the grid with no frames: kept for callers that only have cards and a canvas. */
export const routeEdges = (nodes, edges, bounds) => routeOrthogonal(nodes, edges, { bounds });

export function drawNode(p, comp, n, { selected = false, dim = false, possible = false, repoTag = "" } = {}) {
  const stroke = selected ? p.accent : possible ? p.faint : p.border;
  const dash = comp.confidence === "observed" || possible ? "" : comp.confidence === "inferred" ? "6 4" : "2 4";
  const out = [`<g data-kind="component" data-id="${esc(comp.id)}"${selected ? ' data-selected="true"' : ""} opacity="${dim ? 0.32 : 1}"><title>${esc(`${comp.name} (${comp.kind}) · ${comp.confidence}${comp.repo ? ` · ${comp.repo}` : ""}`)}</title>`];
  if (selected) out.push(`<rect x="${num(n.x - 5)}" y="${num(n.y - 5)}" width="${num(n.w + 10)}" height="${num(n.h + 10)}" rx="14" fill="${p.accentSoft}" stroke="none"/>`);
  out.push(`<rect x="${num(n.x)}" y="${num(n.y)}" width="${num(n.w)}" height="${num(n.h)}" rx="10" fill="${p.surface}" stroke="${stroke}" stroke-width="${selected ? 2.4 : 1.3}"${dash || possible ? ` stroke-dasharray="${possible ? "3 4" : dash}"` : ""}/>`);
  out.push(`<circle cx="${num(n.x + n.w - 11)}" cy="${num(n.y + 11)}" r="3.8" fill="${confColor(p, comp.confidence)}"/>`);
  n.lines.forEach((t, i) => out.push(`<text x="${num(n.x + NODE_PAD)}" y="${num(n.y + 24 + i * 16)}" font-size="13" font-weight="650" fill="${p.text}">${esc(t)}</text>`));
  out.push(`<text x="${num(n.x + NODE_PAD)}" y="${num(n.y + n.h - 9)}" font-size="10.5" fill="${p.muted}">${esc(truncate(`${comp.kind}${repoTag}`, n.w - NODE_PAD * 2, 10.5))}</text>`);
  out.push("</g>");
  return out.join("");
}

/** The curve, its head and optional label chip for one edge; `e.state` is "hot", "normal" or "dim". */
export function drawEdge(p, e, geom, label, style, badge = null) {
  const color = style.color(e.rel);
  const head = style.head(e.rel);
  const hot = e.state === "hot";
  const dim = e.state === "dim";
  const quiet = e.state === "quiet";
  const dash = e.dashed ?? (e.carried ? "1.5 5" : dashFor(e.rel.confidence));
  const out = [`<g data-kind="relationship" data-id="${esc(e.rel.id)}"${hot ? ' data-selected="true"' : ""} opacity="${dim ? 0.16 : quiet ? 0.5 : 1}"><title>${esc(e.title)}</title>`];
  out.push(`<path d="${geom.d}" fill="none" stroke="transparent" stroke-width="12"/>`);
  if (hot) out.push(`<path d="${geom.d}" fill="none" stroke="${p.accent}" stroke-opacity="0.35" stroke-width="7" stroke-linecap="round"/>`);
  out.push(`<path d="${geom.d}" fill="none" stroke="${color}" stroke-width="${hot ? 2.6 : quiet || e.carried ? 1.2 : e.cross ? 2.2 : 1.7}"${dash ? ` stroke-dasharray="${dash}"` : ""} stroke-linecap="round" marker-end="${markerUrl(head, color)}"/>`);
  if (label) out.push(`<rect x="${num(label.x)}" y="${num(label.y)}" width="${num(label.w)}" height="${label.h}" rx="8.5" fill="${p.bg}" stroke="${color}" stroke-opacity="0.8"/><text x="${num(label.x + label.w / 2)}" y="${num(label.y + 12)}" text-anchor="middle" font-size="11" font-weight="600" fill="${color}">${esc(label.text)}</text>`);
  if (badge) out.push(`<circle cx="${num(badge.x)}" cy="${num(badge.y)}" r="${badge.r}" fill="${p.bg}" stroke="${color}"/><text x="${num(badge.x)}" y="${num(badge.y + 3.6)}" text-anchor="middle" font-size="${badge.n > 9 ? 8.5 : 10}" font-weight="700" fill="${color}">${badge.n}</text>`);
  out.push("</g>");
  return out.join("");
}

function rankOf(model, ids, rels) {
  const sub = { ...model, components: model.components.filter((c) => ids.includes(c.id)), relationships: rels };
  const rank = new Map();
  layerComponents(sub).forEach((row, i) => row.forEach((id) => rank.set(id, i)));
  for (const id of ids) if (!rank.has(id)) rank.set(id, 0);
  return rank;
}

/**
 * Component overview. Components sit in repository boxes (when the model declares repositories) with directed,
 * typed relationships between them. `focus` keeps one component and what it directly connects to; `categories`
 * limits relationships to those categories; `selected` highlights one relationship id.
 * Relationships that a transport component carries on their behalf (`via`) are left out unless they touch the focus.
 */
export function overviewSvg(model, { categories = [], focus = null, selectedRel = null, theme = "dark", showCarried = false, revealHint = "" } = {}) {
  const p = palette(theme);
  const style = edgeStyler(model, p);
  const keep = (r) => !categories.length || categories.includes(r.category);
  let rels = model.relationships.filter(keep);
  const carried = rels.filter((r) => r.via && model.relationships.some((t) => t.from === r.via && t.to === r.to && t.category === r.category && t.id !== r.id));
  const carriedIds = new Set(carried.map((r) => r.id));
  const pair = Array.isArray(focus) ? focus : null;
  const focusComp = !pair && focus ? byId(model.components, focus) : undefined;
  rels = rels.filter((r) => showCarried || !carriedIds.has(r.id) || (focusComp && (r.from === focusComp.id || r.to === focusComp.id)) || (pair && pair.includes(r.from) && pair.includes(r.to)));
  if (focusComp) rels = rels.filter((r) => r.from === focusComp.id || r.to === focusComp.id);
  if (pair) rels = rels.filter((r) => pair.includes(r.from) && pair.includes(r.to));

  let comps = model.components.filter((c) => (pair ? pair.includes(c.id) : focusComp ? c.id === focusComp.id || rels.some((r) => r.from === c.id || r.to === c.id) : !categories.length || rels.some((r) => r.from === c.id || r.to === c.id) || carried.some((r) => r.from === c.id || r.to === c.id)));
  if (!comps.length) comps = model.components.slice(0, 1);
  const ids = comps.map((c) => c.id);
  const inView = rels.filter((r) => ids.includes(r.from) && ids.includes(r.to));
  const primary = inView.filter((r) => !STRUCTURAL.has(r.category));
  const rank = rankOf(model, ids, primary.length >= 3 ? primary : inView);
  if (primary.length >= 3) {
    const all = rankOf(model, ids, inView);
    const top = Math.max(...[...rank.values()]);
    const touched = new Set(primary.flatMap((r) => [r.from, r.to]));
    for (const id of ids) if (!touched.has(id)) rank.set(id, Math.min(all.get(id), top));
  }
  const repos = model.project.repositories;
  const nodes = new Map();
  const meta = new Map(comps.map((c) => [c.id, measureNode(c)]));

  const groups = [];
  if (repos.length) {
    for (const r of repos) {
      const members = comps.filter((c) => c.repo === r.id);
      if (members.length) groups.push({ key: r.id, repo: r, members });
    }
    const rest = comps.filter((c) => !repos.some((r) => r.id === c.repo));
    if (rest.length) groups.push({ key: "", repo: null, members: rest });
  } else groups.push({ key: "", repo: null, members: comps, bare: true });
  const avgRank = (g) => g.members.reduce((n, c) => n + rank.get(c.id), 0) / g.members.length;
  groups.sort((a, b) => (a.key === "") - (b.key === "") || avgRank(a) - avgRank(b));

  let frames = [];
  let cursorX = 24;
  let tallest = 0;
  if (groups.length === 1 && groups[0].bare) {
    layoutColumns(groups[0].members, rank, rels, meta, nodes);
    let right = 0;
    let bottom = 0;
    for (const n of nodes.values()) {
      right = Math.max(right, n.x + n.w);
      bottom = Math.max(bottom, n.y + n.h);
    }
    cursorX = right + 24;
    tallest = bottom + 24;
  } else {
    const order = new Map(groups.map((g, i) => [g.key, i]));
    const groupOf = new Map(comps.map((c) => [c.id, repos.some((r) => r.id === c.repo) ? c.repo : ""]));
    const gap = rels.some((r) => groupOf.has(r.from) && groupOf.has(r.to) && groupOf.get(r.from) !== groupOf.get(r.to)) ? CLUSTER_GAP_LABELLED : CLUSTER_GAP;
    const place = (perRow) => {
      const placedNodes = new Map();
      const boxes = [];
      let x0 = 24;
      let bottomMost = 0;
      for (const g of groups) {
        const memberIds = g.members.map((c) => c.id);
        const intra = rels.filter((r) => memberIds.includes(r.from) && memberIds.includes(r.to));
        const local = rankOf(model, memberIds, intra);
        const bias = (id) => rels.reduce((n, r) => {
          const other = r.from === id ? r.to : r.to === id ? r.from : null;
          if (!other || !groupOf.has(other) || groupOf.get(other) === g.key) return n;
          return n + Math.sign(order.get(groupOf.get(other)) - order.get(g.key));
        }, 0);
        const rows = [];
        for (const c of g.members) (rows[local.get(c.id)] ??= []).push(c);
        const placed = new Map();
        const lines = rows.filter(Boolean).flatMap((row) => {
          const key = (c) => {
            const ns = intra.flatMap((r) => (r.to === c.id ? [r.from] : r.from === c.id ? [r.to] : [])).filter((n) => placed.has(n));
            const bary = ns.length ? ns.reduce((sum, n) => sum + placed.get(n), 0) / ns.length : 0;
            return bary + bias(c.id) * 40;
          };
          const sorted = [...row].sort((a, b) => key(a) - key(b));
          sorted.forEach((c, i) => placed.set(c.id, i * 100));
          const pieces = [];
          for (let i = 0; i < sorted.length; i += perRow) pieces.push(sorted.slice(i, i + perRow));
          return pieces;
        });
        const rowW = lines.map((row) => row.reduce((n, c) => n + meta.get(c.id).w, 0) + (row.length - 1) * GAP_X);
        const label = g.repo ? `${g.repo.name}${/^\S{1,16}$/.test(g.repo.version) ? ` · ${g.repo.version}` : g.repo.revision ? ` · ${g.repo.revision.slice(0, 7)}` : ""}` : "Not modeled";
        const frameW = Math.max(Math.max(...rowW) + CLUSTER_PAD * 2, textWidth(label.toUpperCase(), 11.5, { bold: true }) + 34);
        let y = 24 + CLUSTER_HEAD;
        for (const [i, row] of lines.entries()) {
          let x = x0 + (frameW - rowW[i]) / 2;
          const rowH = Math.max(...row.map((c) => meta.get(c.id).h));
          for (const c of row) {
            const m = meta.get(c.id);
            placedNodes.set(c.id, { x, y: y + (rowH - m.h) / 2, w: m.w, h: m.h, lines: m.lines });
            x += m.w + GAP_X;
          }
          y += rowH + GAP_Y + 8;
        }
        const bottom = y - GAP_Y - 8 + CLUSTER_PAD;
        boxes.push({ g, x: x0, y: 24, w: frameW, h: bottom - 24, label });
        bottomMost = Math.max(bottomMost, bottom);
        x0 += frameW + gap;
      }
      return { nodes: placedNodes, frames: boxes, cursorX: x0 - gap + 24, tallest: bottomMost };
    };
    // A terminal shows a picture about as tall as it is wide in pixels; of the ways to wrap rows inside the boxes, take the one that leaves the picture largest there.
    const score = (l) => Math.min(TARGET_W / l.cursorX, TARGET_H / (l.tallest + 24 + FOOTER_ALLOWANCE));
    const best = [MAX_PER_ROW, 2, 1].map(place).reduce((a, b) => (score(b) > score(a) * 1.04 ? b : a));
    for (const [id, n] of best.nodes) nodes.set(id, n);
    frames = best.frames;
    cursorX = best.cursorX;
    // Shorter boxes stretch to the tallest so boundaries read as columns.
    for (const f of frames) f.h = best.tallest - 24;
    tallest = best.tallest + 24;
  }

  const edgeList = rels.filter((r) => nodes.has(r.from) && nodes.has(r.to) && r.from !== r.to).map((r) => {
    const a = byId(model.components, r.from);
    const b = byId(model.components, r.to);
    const cross = Boolean(a.repo && b.repo && a.repo !== b.repo);
    const via = r.via ? ` · via ${byId(model.components, r.via)?.name ?? r.via}` : "";
    return {
      id: r.id, from: r.from, to: r.to, rel: r, cross,
      carried: carriedIds.has(r.id),
      state: selectedRel ? (selectedRel === r.id ? "hot" : "dim") : focusComp ? "hot" : STRUCTURAL.has(r.category) && !categories.length && inView.length > 14 ? "quiet" : "normal",
      labelText: undefined,
      title: `${a.name} → ${b.name}: ${r.label || r.kind} (${categoryInfo(r.category).label}, ${r.confidence}${r.evidence.length ? "" : ", no evidence cited"})${via}${cross ? ` · crosses ${a.repo} → ${b.repo}` : ""}${carriedIds.has(r.id) ? " · a logical call carried by the transport link, drawn thin and dotted" : ""}`,
    };
  });
  for (const e of edgeList) {
    if (e.state === "dim" || e.state === "quiet" || !(focusComp || selectedRel || edgeList.length <= 14 || e.cross)) continue;
    const base = e.rel.label || e.rel.kind;
    e.labelText = `${e.cross ? "⇄ " : ""}${base}`;
  }
  const boxes = frames.map((f) => ({ x: f.x, y: f.y, w: f.w, h: f.h, titleW: textWidth(f.label.toUpperCase(), 11.5, { bold: true }) }));
  const geoms = routeOrthogonal(nodes, edgeList, { bounds: { x0: 6, y0: 6, x1: cursorX, y1: tallest - 6 }, frames: boxes });
  const { labels, badges, unplaced } = placeRouteLabels(edgeList, geoms, nodes, { frames: boxes, bounds: { x0: 2, y0: 2, x1: Math.max(cursorX, 640) - 2, y1: tallest - 2 } });

  const used = new Set(edgeList.map((e) => markerKey(style.head(e.rel), style.color(e.rel))));
  const out = [];
  for (const f of frames) {
    out.push(`<rect x="${num(f.x)}" y="${num(f.y)}" width="${num(f.w)}" height="${num(f.h)}" rx="14" fill="${p.band}" stroke="${f.g.repo ? p.border : p.faint}"${f.g.repo ? "" : ' stroke-dasharray="4 4"'}/>`);
    out.push(`<text x="${num(f.x + 16)}" y="${num(f.y + 25)}" font-size="11.5" font-weight="700" letter-spacing="0.6" fill="${f.g.repo ? p.text : p.muted}">${esc(f.label.toUpperCase())}</text>`);
  }
  for (const e of edgeList) out.push(drawEdge(p, e, geoms.get(e.id), labels.get(e.id), style, badges.get(e.id)));
  for (const c of comps) {
    const n = nodes.get(c.id);
    const touchesSel = selectedRel && edgeList.some((e) => e.id === selectedRel && (e.from === c.id || e.to === c.id));
    out.push(drawNode(p, c, n, { selected: focusComp?.id === c.id || Boolean(touchesSel), dim: Boolean(selectedRel) && !touchesSel }));
  }

  const items = [];
  if (style.byKind) for (const k of style.kinds.filter((k) => edgeList.some((e) => e.rel.kind === k))) items.push({ kind: "cat", color: style.kindColor(k), label: k, head: "filled" });
  else items.push(...legendItems(p, { categories: [...new Set(edgeList.map((e) => e.rel.category))] }));
  items.push(...legendItems(p, { confidences: ["observed", "inferred", "unknown"].filter((c) => edgeList.some((e) => e.rel.confidence === c)) }));
  for (const it of items) if (it.kind === "cat") used.add(markerKey(it.head, it.color));
  const width = Math.max(cursorX, 640);
  const legend = legendRow(items, 24, tallest + 6, p, width - 48);
  const notes = [];
  if (focusComp) notes.push({ text: `Showing ${focusComp.name} and ${comps.length - 1} directly connected component${comps.length === 2 ? "" : "s"} (${model.components.length} in the model)` });
  else if (comps.length < model.components.length) notes.push({ text: `${model.components.length - comps.length} of ${model.components.length} components have no relationship of the chosen types` });
  if (unplaced.length) notes.push({ text: `${unplaced.length} relationship label${unplaced.length === 1 ? "" : "s"} left off for lack of clear space (hover an arrow, or focus a component, to read ${unplaced.length === 1 ? "it" : "them"})` });
  const hidden = carried.filter((r) => !showCarried && !focusComp && !pair);
  const banner = hidden.length ? `${hidden.length} logical call${hidden.length === 1 ? "" : "s"} carried by a transport link ${hidden.length === 1 ? "is" : "are"} not drawn.${revealHint ? ` ${revealHint}` : " Focus a component to see them."}` : "";
  if (showCarried && carried.length) notes.push({ text: `Dotted thin lines are the ${carried.length} logical call${carried.length === 1 ? "" : "s"} carried by a transport link; the transport link itself is drawn solid.` });
  const keyed = [...badges.entries()].sort((a, c) => a[1].n - c[1].n);
  const keyLines = [];
  if (keyed.length) {
    let line = "";
    for (const [, b] of keyed) {
      const item = `[${b.n}] ${b.text}`;
      if (line && textWidth(`${line}      ${item}`, 11.5) > width - 48) {
        keyLines.push(line);
        line = item;
      } else line = line ? `${line}      ${item}` : item;
    }
    keyLines.push(line);
  }
  let fy = tallest + 6 + legend.height + 14;
  const foot = [];
  if (banner) {
    const bw = Math.min(width - 48, textWidth(banner, 12, { bold: true }) + 28);
    foot.push(`<rect x="24" y="${num(fy - 12)}" width="${num(bw)}" height="24" rx="12" fill="${p.warnSoft}" stroke="${p.warn}"/><text x="38" y="${num(fy + 4)}" font-size="12" font-weight="650" fill="${p.warn}">${esc(truncate(banner, width - 80, 12, { bold: true }))}</text>`);
    fy += 28;
  }
  for (const line of keyLines) {
    foot.push(`<text x="24" y="${num(fy)}" font-size="11.5" fill="${p.muted}">${esc(truncate(line, width - 48, 11.5))}</text>`);
    fy += 16;
  }
  for (const n of notes) {
    foot.push(`<text x="24" y="${num(fy)}" font-size="11.5" fill="${p.muted}">${esc(truncate(n.text, width - 48, 11.5))}</text>`);
    fy += 16;
  }
  const height = fy - (foot.length ? 4 : 14) + 12;
  const svg = `${svgOpen(width, height, p, `role="img" aria-label="${esc(`Component overview of ${model.project.name}`)}"`)}<defs>${markerDefs(used)}</defs><rect width="${num(width)}" height="${num(height)}" rx="12" fill="${p.bg}"/>${out.join("")}${legend.markup}${foot.join("")}</svg>`;
  return { svg, width, height, shown: comps.length, hiddenCarried: hidden.length, carriedTotal: focusComp || pair ? 0 : carried.length, nodes: [...nodes].map(([id, n]) => ({ id, x: n.x, y: n.y, w: n.w, h: n.h })) };
}

/** Rank columns left to right, nodes ordered within a column by the mean position of their neighbours. */
function layoutColumns(members, rank, rels, meta, nodes) {
  const cols = [];
  for (const c of members) (cols[rank.get(c.id)] ??= []).push(c);
  const lists = cols.filter(Boolean);
  const pos = new Map();
  lists.forEach((col) => col.forEach((c, i) => pos.set(c.id, i)));
  const neighbours = (id) => rels.flatMap((r) => (r.from === id ? [r.to] : r.to === id ? [r.from] : [])).filter((n) => pos.has(n));
  for (let pass = 0; pass < 4; pass++) {
    const order = pass % 2 ? [...lists].reverse() : lists;
    for (const col of order) {
      const key = new Map(col.map((c) => {
        const ns = neighbours(c.id);
        return [c.id, ns.length ? ns.reduce((s, n) => s + pos.get(n), 0) / ns.length : pos.get(c.id)];
      }));
      col.sort((a, b) => key.get(a.id) - key.get(b.id) || pos.get(a.id) - pos.get(b.id));
      col.forEach((c, i) => pos.set(c.id, i));
    }
  }
  const tallest = Math.max(...lists.map((col) => col.reduce((s, c) => s + meta.get(c.id).h, 0) + (col.length - 1) * GAP_Y));
  let x = 24;
  for (const col of lists) {
    const w = Math.max(...col.map((c) => meta.get(c.id).w));
    const total = col.reduce((s, c) => s + meta.get(c.id).h, 0) + (col.length - 1) * GAP_Y;
    let y = 24 + (tallest - total) / 2;
    for (const c of col) {
      const m = meta.get(c.id);
      nodes.set(c.id, { x: x + (w - m.w) / 2, y, w: m.w, h: m.h, lines: m.lines });
      y += m.h + GAP_Y;
    }
    x += w + 96;
  }
}

