import { byId, categoryInfo } from "./model.mjs";
import { drawEdge, drawNode, edgeStyler, measureNode } from "./diagram-graph.mjs";
import { placeRouteLabels, routeOrthogonal } from "./route.mjs";
import { esc, legendItems, legendRow, markerDefs, markerKey, num, palette, svgOpen, textWidth, truncate } from "./svgkit.mjs";

const GAP_Y = 22;
const COL_GAP = 168;

/**
 * Impact picture for an `impactOf` result. Left to right: possible further effects (consumers of consumers, dotted),
 * consumers, the selection, what it depends on. Established relationships are solid; reach that is only
 * computed through them is dotted and labelled "possible". `badges` (component id -> [{ text, tone }]) carries
 * claims from a behavior document (early return, drop, hold) onto the components they describe.
 */
