import { confColor, esc, legendRow, num, palette, svgOpen, textWidth, truncate, wrap } from "./svgkit.mjs";

const CARD_X = 214;
const CARD_W = 420;
const CARD_H = 64;
const GAP = 48;
const TOP = 78;
const RAIL_X = 128;

const KIND = {
  origin: { label: "failure starts", tone: "bad" },
  returns: { label: "passes the error up", tone: "warn" },
  drops: { label: "error ends: data dropped", tone: "bad" },
  holds: { label: "error ends: data kept", tone: "info" },
  unresolved: { label: "the document is silent", tone: "muted" },
