    if (sel) out.push(`<rect x="${CARD_X - 5}" y="${y - 5}" width="${CARD_W + 10}" height="${CARD_H + 10}" rx="14" fill="${p.accentSoft}"/>`);
    out.push(`<rect x="${CARD_X}" y="${y}" width="${CARD_W}" height="${CARD_H}" rx="10" fill="${p.surface}" stroke="${sel ? p.accent : step ? tone(KIND[step.kind].tone) : p.border}" stroke-width="${sel || step ? 2 : 1.3}"/>`);
