    wrap(hop.role ?? "", CARD_W - 52, 11, 2).forEach((t, k) => out.push(`<text x="${CARD_X + 38}" y="${y + 43 + k * 13}" font-size="11" fill="${p.muted}">${esc(t)}</text>`));
    out.push("</g>");
    const chips = [];
    if (hop.holds) chips.push({ text: `holds data${hop.holds.store ? `: ${hop.holds.store}` : ""}`, tone: "info", c: hop.holds.confidence });
