    chips.slice(0, 2).forEach((c, k) => {
      const text = truncate(c.text, 214, 10.5, { bold: true });
      const w = textWidth(text, 10.5, { bold: true }) + 24;
      const cy = y + 10 + k * 24;
      const color = tone(c.tone);
      out.push(`<g opacity="${dim ? 0.5 : 1}"><rect x="${CARD_X + CARD_W + 14}" y="${cy}" width="${num(w)}" height="19" rx="9.5" fill="${p.surface}" stroke="${color}" stroke-opacity="0.8"${c.c === "observed" ? "" : ' stroke-dasharray="3 3"'}/><circle cx="${CARD_X + CARD_W + 25}" cy="${cy + 9.5}" r="3" fill="${confColor(p, c.c)}"/><text x="${CARD_X + CARD_W + 34}" y="${cy + 13}" font-size="10.5" font-weight="600" fill="${color}">${esc(text)}</text></g>`);
