      sub: `presents ${cred ? cred.name : "no credential"} · ${h.seenAs ? `seen as ${principalName(auth, h.seenAs)}` : "the receiver is not shown the caller"}`,
      confidence: h.confidence, selected: selectedHop === h.id, tone: AUTHORITY_TONE[h.authority],
