  const stores = [...new Set(data.entities.map((e) => e.store))];
  const ranked = (e) => (e.id === hub ? 1 : e.store === hubStore ? 0 : 2 + stores.filter((s) => s !== hubStore).indexOf(e.store));
  const order = [...data.entities].sort((a, b) => ranked(a) - ranked(b) || stores.indexOf(a.store) - stores.indexOf(b.store));
  const nodes = order.map((e) => ({ id: e.id, title: e.name, sub: `${e.kind}${e.store === hubStore ? "" : ` · ${storeName(model, e.store)}`}`, lines: e.key ? [e.key] : [], col: ranked(e), frame: storeName(model, e.store), confidence: e.confidence, hover: `${e.name} (${e.kind}, ${storeName(model, e.store)}) · ${e.confidence}${e.key ? ` · key: ${e.key}` : ""}` }));
  const style = { references: { tone: "runtime", head: "filled" }, "shared-key": { tone: "event", head: "open" }, "derived-from": { tone: "other", head: "square" } };
  const edges = data.relations.map((r) => ({ id: r.id, from: r.from, to: r.to, label: r.via ?? r.kind, tone: style[r.kind].tone, head: style[r.kind].head, confidence: r.confidence, title: `${r.kind}: ${r.text} (${r.confidence})` }));
