    ...(used.has("shared-key") ? [{ kind: "line", tone: "event", head: "open", label: "shared key: equal values, no constraint between stores" }] : []),
    ...(used.has("derived-from") ? [{ kind: "line", tone: "other", head: "square", label: "derived when written; not stored" }] : []),
