      edges.push({
        id: `${t.id}@${f ?? "created"}`, key: t.id, from: f === null ? "@created" : f === ANY_STATE ? "@any" : f, to: t.to,
        label: `${transitionName(t)}${t.guard ? ` · ${GLYPH[t.guard.kind]}` : ""}`,
        tone: onFlow ? "runtime" : "other", head: t.guard?.kind === "none" ? "open" : "filled", confidence: t.confidence,
        title: `${t.id}: ${t.text}${t.guard ? ` Guard: ${t.guard.text}` : " Guard: not examined."} (${t.confidence})`,
