    { kind: "line", tone: "runtime", head: "filled", label: "on the modeled workflow" },
    { kind: "line", tone: "other", head: "filled", label: "off the modeled workflow" },
    { kind: "line", tone: "muted", head: "open", label: "open head: the function has no state check" },
  ];
  return graphSvg({ nodes, edges, selectedNode: selectedState, selectedEdge: selectedTransition, nodeKind: "state", edgeKind: "transition", theme, legend, align: "top", label: `${lifecycle.states.length} states and ${lifecycle.transitions.length} transitions of ${lifecycle.entity}`, notes: ["Edge label: transition · kind of guard (check, lock, owner, idem, or no check)."] });
}

/** The writes of one sequence in the order its source runs them, with a selectable join between each pair. */
export function sequenceRowsSvg(model, data, sequence, { selectedStep = null, selectedCut = null, theme = "dark" } = {}) {
  const pf = partialFailures(model, data, sequence);
  const name = (id) => storeName(model, id);
  const rows = pf.units.map((u, i) => {
    const cut = pf.cuts[i];
    const conf = weakestOf(u.writes.map((w) => w.confidence));
    const from = name(u.step.from);
    const to = name(u.step.to);
