      id: u.ref, num: u.step.n, title: `${from} → ${to}: ${u.step.action}`,
      sub: u.writes.map((w) => `${w.op} ${w.entity ? data.entities.find((e) => e.id === w.entity)?.name ?? w.entity : `signal to ${name(w.system)}`}`).join(" · "),
