  });
  const legend = [
    { kind: "line", tone: "runtime", label: "writes a datastore" },
    { kind: "line", tone: "warn", label: "writes or signals an external system" },
    { kind: "conf", confidence: "inferred", label: "dashed: not observed" },
  ];
  return rowsSvg({ rows, rowKind: "write", joinKind: "cut", theme, legend, label: `Writes of ${sequence.name}`, banner: `${sequence.name}: ${rows.length} writes, in the order the cited code runs them`, notes: pf.broken.length ? [`Steps that do not resolve in the model are not drawn: ${pf.broken.join(", ")}`] : [] });
}

