// Estimated advance in em for a proportional sans; deliberately a little generous so labels never run past their boxes.
export function textWidth(text, size, { bold = false, mono = false } = {}) {
  if (mono) return String(text).length * size * 0.62;
  let w = 0;
  for (const ch of String(text)) {
    if (NARROW.has(ch)) w += 0.3;
    else if (WIDE.has(ch)) w += 0.88;
    else if (ch >= "A" && ch <= "Z") w += 0.68;
    else if (ch >= "0" && ch <= "9") w += 0.58;
    else if (ch.charCodeAt(0) > 0x2000) w += 0.95;
