export function truncateMiddle(text, maxWidth, size, opts, head = 14) {
  const s = String(text);
  if (textWidth(s, size, opts) <= maxWidth) return s;
  const start = s.slice(0, head);
  let tail = s.length - head;
  while (tail > 1 && textWidth(`${start}…${s.slice(-tail)}`, size, opts) > maxWidth) tail--;
