export const lineRange = (ev) => `${ev.lines[0]}${ev.lines[1] > ev.lines[0] ? `-${ev.lines[1]}` : ""}`;

export const note = (h, key, text, props = {}) => h.Text({ key, dimColor: true, wrap: "wrap", children: text, ...props });
