    const x0 = Math.min(...boxes.map((b) => b.x)) - 16;
    const y0 = Math.min(...boxes.map((b) => b.y)) - 36;
    frames.push({ name, x: x0, y: y0, w: Math.max(...boxes.map((b) => b.x + b.w)) + 16 - x0, h: Math.max(...boxes.map((b) => b.y + b.h)) + 14 - y0, titleW: textWidth(name.toUpperCase(), 11.5, { bold: true }) });
  }

  const edgeList = edges.filter((e) => placed.has(e.from) && placed.has(e.to) && e.from !== e.to).map((e) => ({ ...e, labelText: e.label }));
  const bounds = { x0: 4, y0: 4, x1: width - 4, y1: bottom };
  const geoms = routeOrthogonal(placed, edgeList, { bounds, frames });
  const { labels, badges, unplaced } = placeRouteLabels(edgeList, geoms, placed, { frames, bounds: { x0: 2, y0: 2, x1: width - 2, y1: bottom } });

  const used = new Set();
  const out = [];
  for (const f of frames) {
    out.push(`<rect x="${num(f.x)}" y="${num(f.y)}" width="${num(f.w)}" height="${num(f.h)}" rx="14" fill="${p.band}" stroke="${p.border}"/>`);
    out.push(`<text x="${num(f.x + 16)}" y="${num(f.y + 24)}" font-size="11.5" font-weight="700" letter-spacing="0.6" fill="${p.text}">${esc(f.name.toUpperCase())}</text>`);
  }
  for (const e of edgeList) {
    const g = geoms.get(e.id);
    if (!g) continue;
    const color = toneColor(p, e.tone);
    const head = e.head ?? "filled";
    used.add(markerKey(head, color));
    const key = e.key ?? e.id;
    const hot = selectedEdge === key;
    const dash = e.dashed ?? dashFor(e.confidence ?? "observed");
    const lab = labels.get(e.id);
    const bad = badges.get(e.id);
    out.push(`<g data-kind="${edgeKind}" data-id="${esc(key)}"${hot ? ' data-selected="true"' : ""}><title>${esc(e.title ?? e.label ?? e.id)}</title><path d="${g.d}" fill="none" stroke="transparent" stroke-width="12"/>`);
    if (hot) out.push(`<path d="${g.d}" fill="none" stroke="${p.accent}" stroke-opacity="0.35" stroke-width="7" stroke-linecap="round"/>`);
    out.push(`<path d="${g.d}" fill="none" stroke="${color}" stroke-width="${hot ? 2.6 : 1.8}"${dash ? ` stroke-dasharray="${dash}"` : ""} stroke-linecap="round" marker-end="${markerUrl(head, color)}"/>`);
    if (lab) out.push(`<rect x="${num(lab.x)}" y="${num(lab.y)}" width="${num(lab.w)}" height="${lab.h}" rx="8.5" fill="${p.bg}" stroke="${color}" stroke-opacity="0.8"/><text x="${num(lab.x + lab.w / 2)}" y="${num(lab.y + 12)}" text-anchor="middle" font-size="11" font-weight="650" fill="${p.text}">${esc(lab.text)}</text>`);
    if (bad) out.push(`<circle cx="${num(bad.x)}" cy="${num(bad.y)}" r="${bad.r}" fill="${p.bg}" stroke="${color}"/><text x="${num(bad.x)}" y="${num(bad.y + 3.6)}" text-anchor="middle" font-size="${bad.n > 9 ? 8.5 : 10}" font-weight="700" fill="${p.text}">${bad.n}</text>`);
    out.push("</g>");
  }
  for (const n of nodes) {
    const b = placed.get(n.id);
    const m = meta.get(n.id);
    if (n.pseudo) {
      out.push(`<rect x="${num(b.x)}" y="${num(b.y)}" width="${num(b.w)}" height="${b.h}" rx="15" fill="${p.bg}" stroke="${p.faint}" stroke-dasharray="4 4"/><text x="${num(b.x + b.w / 2)}" y="${num(b.y + 19)}" text-anchor="middle" font-size="11.5" font-weight="650" fill="${p.muted}">${esc(n.title)}</text>`);
      continue;
    }
    const sel = selectedNode === n.id;
    const stroke = sel ? p.accent : p.border;
    out.push(`<g data-kind="${nodeKind}" data-id="${esc(n.id)}"${sel ? ' data-selected="true"' : ""}><title>${esc(n.hover ?? `${n.title}${n.sub ? ` · ${n.sub}` : ""} · ${n.confidence ?? ""}`)}</title>`);
    if (sel) out.push(`<rect x="${num(b.x - 5)}" y="${num(b.y - 5)}" width="${num(b.w + 10)}" height="${num(b.h + 10)}" rx="14" fill="${p.accentSoft}"/>`);
    const dash = n.confidence && n.confidence !== "observed" ? ` stroke-dasharray="${dashFor(n.confidence)}"` : "";
    out.push(`<rect x="${num(b.x)}" y="${num(b.y)}" width="${num(b.w)}" height="${num(b.h)}" rx="10" fill="${p.surface}" stroke="${n.tone ? toneColor(p, n.tone) : stroke}" stroke-width="${sel ? 2.4 : n.tone ? 1.8 : 1.3}"${dash}/>`);
    if (n.terminal) out.push(`<rect x="${num(b.x + 3)}" y="${num(b.y + 3)}" width="${num(b.w - 6)}" height="${num(b.h - 6)}" rx="8" fill="none" stroke="${n.tone ? toneColor(p, n.tone) : stroke}" stroke-width="1"/>`);
    if (n.confidence) out.push(`<circle cx="${num(b.x + b.w - 12)}" cy="${num(b.y + 12)}" r="3.8" fill="${confColor(p, n.confidence)}"/>`);
    let ty = b.y + 22;
    for (const t of m.titleLines) {
      out.push(`<text x="${num(b.x + PAD)}" y="${num(ty)}" font-size="13" font-weight="650" fill="${p.text}">${esc(t)}</text>`);
      ty += 16;
    }
    if (n.sub) {
      out.push(`<text x="${num(b.x + PAD)}" y="${num(ty - 1)}" font-size="10.5" fill="${p.muted}">${esc(truncate(n.sub, b.w - PAD * 2, 10.5))}</text>`);
      ty += 15;
    }
    for (const t of m.extra) {
      out.push(`<text x="${num(b.x + PAD)}" y="${num(ty - 1)}" font-size="10.5" fill="${p.faint}">${esc(truncate(t, b.w - PAD * 2, 10.5))}</text>`);
      ty += 14;
    }
    out.push("</g>");
  }

  const items = legend.map((l) => (l.kind === "line" ? { kind: "cat", color: toneColor(p, l.tone), label: l.label, head: l.head ?? "filled" } : l));
  for (const it of items) if (it.kind === "cat") used.add(markerKey(it.head, it.color));
  const lg = legendRow(items, 24, bottom + 6, p, width - 48);
  let fy = bottom + 6 + lg.height + 14;
  const foot = [];
  const keyed = [...badges.entries()].sort((a, c) => a[1].n - c[1].n);
  for (const [, b] of keyed) {
    foot.push(`<text x="24" y="${num(fy)}" font-size="11.5" fill="${p.muted}">${esc(truncate(`[${b.n}] ${b.text}`, width - 48, 11.5))}</text>`);
    fy += 16;
  }
  if (unplaced.length) {
    foot.push(`<text x="24" y="${num(fy)}" font-size="11.5" fill="${p.muted}">${unplaced.length} label${unplaced.length === 1 ? "" : "s"} left off for lack of clear space (hover a line, or select it, to read it)</text>`);
    fy += 16;
  }
  for (const t of notes) {
    foot.push(`<text x="24" y="${num(fy)}" font-size="11.5" fill="${p.muted}">${esc(truncate(t, width - 48, 11.5))}</text>`);
    fy += 16;
  }
  const height = fy - (foot.length ? 4 : 14) + 12;
  const svg = `${svgOpen(width, height, p, `role="img" aria-label="${esc(label)}"`)}<defs>${markerDefs(used)}</defs><rect width="${num(width)}" height="${num(height)}" rx="12" fill="${p.bg}"/>${out.join("")}${lg.markup}${foot.join("")}</svg>`;
  return { svg, width, height };
}

const CARD_X = 70;
const CARD_W = 520;
const CARD_H = 66;

/**
 * Cards top to bottom with a join between neighbours. `rows`: { id, num, title, sub, confidence, tone, chips, selected, join }
 * where a `join` is { id, text, tone, dashed } drawn as a selectable pill on the line to the next card; chips sit right of the card.
 */
export function rowsSvg({ rows, rowKind, joinKind, theme = "dark", legend = [], notes = [], label = "List", banner = null, connect = true }) {
  const p = palette(theme);
  const width = 940;
  const top = banner ? 60 : 24;
  const yOf = (i) => top + rows.slice(0, i).reduce((n, r) => n + CARD_H + (r.join ? 62 : connect ? 30 : 16), 0);
  const out = [];
  if (banner) out.push(`<rect x="${CARD_X}" y="14" width="${width - CARD_X - 24}" height="30" rx="9" fill="${p.surface2}" stroke="${p.border}"/><text x="${CARD_X + 14}" y="34" font-size="12.5" font-weight="650" fill="${p.text}">${esc(truncate(banner, width - CARD_X - 60, 12.5, { bold: true }))}</text>`);
  rows.forEach((r, i) => {
    const y = yOf(i);
    const color = r.tone ? toneColor(p, r.tone) : p.border;
    out.push(`<g data-kind="${rowKind}" data-id="${esc(r.id)}"${r.selected ? ' data-selected="true"' : ""}><title>${esc(r.hover ?? r.title)}</title>`);
    if (r.selected) out.push(`<rect x="${CARD_X - 5}" y="${y - 5}" width="${CARD_W + 10}" height="${CARD_H + 10}" rx="14" fill="${p.accentSoft}"/>`);
    out.push(`<rect x="${CARD_X}" y="${y}" width="${CARD_W}" height="${CARD_H}" rx="10" fill="${p.surface}" stroke="${r.selected ? p.accent : color}" stroke-width="${r.selected || r.tone ? 2 : 1.3}"${r.confidence && r.confidence !== "observed" ? ` stroke-dasharray="${dashFor(r.confidence)}"` : ""}/>`);
    out.push(`<circle cx="${CARD_X + 20}" cy="${y + 22}" r="10" fill="${r.selected ? p.accent : p.surface2}" stroke="${p.border}"/><text x="${CARD_X + 20}" y="${y + 26}" text-anchor="middle" font-size="11.5" font-weight="700" fill="${r.selected ? "#0f141a" : p.text}">${esc(r.num)}</text>`);
    if (r.confidence) out.push(`<circle cx="${CARD_X + CARD_W - 14}" cy="${y + 14}" r="4" fill="${confColor(p, r.confidence)}"/>`);
    out.push(`<text x="${CARD_X + 38}" y="${y + 27}" font-size="13.5" font-weight="650" fill="${p.text}">${esc(truncate(r.title, CARD_W - 70, 13.5, { bold: true }))}</text>`);
    wrap(r.sub ?? "", CARD_W - 52, 11, 2).forEach((t, k) => out.push(`<text x="${CARD_X + 38}" y="${y + 43 + k * 13}" font-size="11" fill="${p.muted}">${esc(t)}</text>`));
    out.push("</g>");
    (r.chips ?? []).slice(0, 3).forEach((c, k) => {
      const text = truncate(c.text, 296, 10.5, { bold: true });
      const w = textWidth(text, 10.5, { bold: true }) + 24;
      const cy = y + 4 + k * 22;
      const col = toneColor(p, c.tone);
      out.push(`<g><title>${esc(c.title ?? c.text)}</title><rect x="${CARD_X + CARD_W + 14}" y="${cy}" width="${num(w)}" height="19" rx="9.5" fill="${p.surface}" stroke="${col}" stroke-opacity="0.85"${c.dashed ? ' stroke-dasharray="3 3"' : ""}/><circle cx="${CARD_X + CARD_W + 25}" cy="${cy + 9.5}" r="3" fill="${col}"/><text x="${CARD_X + CARD_W + 34}" y="${cy + 13}" font-size="10.5" font-weight="600" fill="${col}">${esc(text)}</text></g>`);
    });
    if (i < rows.length - 1 && (connect || r.join)) {
      const x = CARD_X + CARD_W / 2;
      const y1 = y + CARD_H;
      const y2 = yOf(i + 1);
      const j = r.join;
      const col = j ? toneColor(p, j.tone) : p.faint;
      out.push(`<line x1="${x}" y1="${y1 + 2}" x2="${x}" y2="${y2 - 3}" stroke="${col}" stroke-width="2"${j?.dashed || !j ? ' stroke-dasharray="5 5"' : ""} marker-end="url(#lens-arrow)"/>`);
      if (j) {
        const text = truncate(j.text, CARD_W - 40, 11, { bold: true });
        const w = textWidth(text, 11, { bold: true }) + 24;
        const my = (y1 + y2) / 2;
        out.push(`<g data-kind="${joinKind}" data-id="${esc(j.id)}"${j.selected ? ' data-selected="true"' : ""}><title>${esc(j.title ?? j.text)}</title><rect x="${num(x - w / 2)}" y="${num(my - 11)}" width="${num(w)}" height="22" rx="11" fill="${p.bg}" stroke="${j.selected ? p.accent : col}" stroke-width="${j.selected ? 2.2 : 1.2}"${j.dashed ? ' stroke-dasharray="3 3"' : ""}/><text x="${num(x)}" y="${num(my + 4)}" text-anchor="middle" font-size="11" font-weight="650" fill="${p.text}">${esc(text)}</text></g>`);
      }
    }
  });
  const bodyBottom = yOf(rows.length - 1) + CARD_H;
  const items = legend.map((l) => (l.kind === "line" ? { kind: "cat", color: toneColor(p, l.tone), label: l.label } : l));
  const lg = legendRow(items, 24, bodyBottom + 26, p, width - 48);
  let fy = bodyBottom + 26 + lg.height + 14;
  const foot = [];
  for (const t of notes) {
    wrap(t, width - 48, 11.5, 3).forEach((line) => {
      foot.push(`<text x="24" y="${num(fy)}" font-size="11.5" fill="${p.muted}">${esc(line)}</text>`);
      fy += 16;
    });
  }
  const height = fy - (foot.length ? 4 : 14) + 12;
  const arrow = `<marker id="lens-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse" markerUnits="userSpaceOnUse"><path d="M1 1 L9 5 L1 9 Z" fill="${p.faint}"/></marker>`;
  const svg = `${svgOpen(width, height, p, `role="img" aria-label="${esc(label)}"`)}<defs>${arrow}</defs><rect width="${width}" height="${num(height)}" rx="12" fill="${p.bg}"/>${out.join("")}${lg.markup}${foot.join("")}</svg>`;
  return { svg, width, height };
}

